def _oc_runtime_support_directory() -> _oc_boot_Path:
    candidates = []
    try:
        candidates.append(_oc_boot_Path(__file__).resolve().parent)
    except Exception as _oc_exc:
        logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
    candidates.append(_oc_boot_Path.cwd())
    for base in candidates:
        try:
            base.mkdir(parents=True, exist_ok=True)
            test = base / ".oc_write_test"
            test.write_text("ok", encoding="utf-8")
            test.unlink(missing_ok=True)
            return base
        except Exception:
            continue
    return _oc_boot_Path.cwd()


