    missing = [name for name in OC_REQUIRED_DISTRIBUTIONS if _oc_importlib_util.find_spec(name) is None]
    if missing:
        problems.append("Missing required packages: " + ", ".join(missing))
    if problems:
        print("=" * 72)
        print("OMNI-COMPASS RUNTIME PREFLIGHT FAILED")
        print("=" * 72)
        for item in problems:
            print(f"- {item}")
        print("")
        print(f"Installation files were written to: {support_dir}")
        print(f"Run: {_oc_boot_sys.executable} -m pip install -r \"{support_dir / 'requirements.txt'}\"")
        print("The engine has exited before simulation; no partial result is being represented as a completed run.")
        raise SystemExit(2)


