def _mpl_save_bar_chart(path, title, labels, values, figsize=(8.20,5.60), rotate=20):
    """Legacy API retained; rendered as a low-ink lollipop chart."""
    try:
        import matplotlib.pyplot as _plt
        import numpy as _np
        fig,ax=_plt.subplots(figsize=figsize)
        vals=_np.asarray(values,dtype=float)
        cols=[OC_SEMANTIC_COLORS["favorable"] if v>=0 else OC_SEMANTIC_COLORS["adverse"] for v in vals]
        horizontal=len(labels)>=6 or max([len(str(x)) for x in labels] or [0])>12
        _oc_lollipop(ax,[str(x) for x in labels],vals,horizontal=horizontal,colors_list=cols,value_format="{:.2f}")
        ax.set_title(title)
        ax.set_ylabel("Count" if not horizontal else "")
        ax.set_xlabel("Count" if horizontal else "")
        if not horizontal:
            ax.tick_params(axis="x",rotation=rotate)
        _oc_save_figure(fig,path,note=f"{OC_VISUAL_SYSTEM_ID}; values are generated directly from the current execution.",dpi=180)
        _plt.close(fig)
        return True
    except Exception:
        try: _plt.close("all")
        except Exception as _oc_exc: logging.getLogger(__name__).warning("Nonfatal fallback captured: %s", _oc_exc)
        return False



def _mpl_save_exec_m4_plate(path, rows, seed):
    """Four-panel execution dashboard with basin-aware summaries.

    The population is bimodal by construction, so trajectory summaries are
    separated by declared signed target. This prevents a cross-basin median from
    masquerading as a representative physical trajectory.
    """
    try:
        import ast as _ast
        import numpy as _np
        import matplotlib.pyplot as _plt
        confirmations=[]; efforts=[]; signs=[]; histories=[]
        for idx,r in enumerate(rows or []):
            st=r.get("conveyance_confirmed_step",r.get("stable_achieved_step"))
            try: confirmations.append(float(st))
            except Exception: confirmations.append(_np.nan)
            try: efforts.append(float(r.get("basin_regulation_abs_total",0.0)))
            except Exception: efforts.append(_np.nan)
            try: signs.append(int(float(r.get("initial_nearest_basin",r.get("final_basin_sign",0)))))
            except Exception: signs.append(0)
            uh=r.get("U_history")
            if isinstance(uh,str):
                try: uh=_ast.literal_eval(uh)
                except Exception as _oc_exc: logging.getLogger(__name__).warning("History parse fallback: %s", _oc_exc); uh=None
            if isinstance(uh,(list,tuple)) and len(uh)>=2:
                try: histories.append((idx,_np.asarray([float(v) for v in uh],dtype=float)))
                except Exception as _oc_exc: logging.getLogger(__name__).warning("Nonfatal fallback captured: %s", _oc_exc)
        confirmations=_np.asarray(confirmations,dtype=float); efforts=_np.asarray(efforts,dtype=float); signs=_np.asarray(signs,dtype=int)
        fig,axs=_plt.subplots(2,2,figsize=(10.80,9.40),dpi=170)
        fig.suptitle("Current Execution: Basin Capture, Occupancy, and Governing Effort",fontsize=15,fontweight="semibold")

        # A: event-time count plus ECDF, using exact discrete steps.
        ax=axs[0,0]; x=confirmations[_np.isfinite(confirmations)]
        if x.size:
            steps=_np.arange(int(_np.min(x)),int(_np.max(x))+1)
            counts=_np.array([int(_np.sum(x==st)) for st in steps])
            _oc_lollipop(ax,[str(st) for st in steps],counts,horizontal=False,
                         colors_list=[OC_VISUAL_PALETTE["blue"]]*len(steps),value_format="{:.0f}",zero_line=False)
            ax.set_xlabel("Confirmation macro step"); ax.set_ylabel("Run count")
            ax.set_title("A. CONVEY-5 confirmation timing")
        else: ax.text(.5,.5,"No confirmation data",ha="center",va="center",transform=ax.transAxes)

        # B: separate target-basin median and IQR.
        ax=axs[0,1]
        for sign,label,col,marker in [(1,"+1 target",OC_SEMANTIC_COLORS["positive_basin"],"o"),(-1,"-1 target",OC_SEMANTIC_COLORS["negative_basin"],"s")]:
            arr=[u for idx,u in histories if idx < len(signs) and signs[idx]==sign]
            if not arr: continue
            L=min(len(u) for u in arr); M=_np.vstack([u[:L] for u in arr]); t=_np.arange(L)
            q25=_np.nanpercentile(M,25,axis=0); med=_np.nanmedian(M,axis=0); q75=_np.nanpercentile(M,75,axis=0)
            ax.fill_between(t,q25,q75,color=col,alpha=.14,linewidth=0)
            ax.plot(t,med,color=col,marker=marker,markevery=max(1,L//7),label=f"{label} median")
        ax.axhspan(1-BASIN_TOL,1+BASIN_TOL,color=OC_SEMANTIC_COLORS["positive_basin"],alpha=.07)
        ax.axhspan(-1-BASIN_TOL,-1+BASIN_TOL,color=OC_SEMANTIC_COLORS["negative_basin"],alpha=.07)
        ax.set_xlabel("Recorded macro step"); ax.set_ylabel("U"); ax.set_title("B. Basin-separated trajectory summaries")
        _oc_style_axes(ax,grid="both"); ax.legend(loc="best")

        # C: stacked occupancy ribbon, fractions sum to one.
        ax=axs[1,0]
        valid=[u for _,u in histories]
        if valid:
            L=min(len(u) for u in valid); M=_np.vstack([u[:L] for u in valid]); t=_np.arange(L)
            pos=[]; neg=[]; outside=[]
            for j in range(L):
                bs=_np.array([basin_sign(float(v)) if _np.isfinite(v) else 0 for v in M[:,j]])
                pos.append(float(_np.mean(bs==1))); neg.append(float(_np.mean(bs==-1))); outside.append(float(_np.mean(bs==0)))
            ax.stackplot(t,pos,neg,outside,labels=["+1 basin","-1 basin","Outside"],
                         colors=[OC_SEMANTIC_COLORS["positive_basin"],OC_SEMANTIC_COLORS["negative_basin"],OC_SEMANTIC_COLORS["outside_basin"]],alpha=.78)
            ax.set_ylim(0,1); ax.set_xlabel("Recorded macro step"); ax.set_ylabel("Fraction of runs")
            ax.set_title("C. Signed-basin occupancy"); _oc_style_axes(ax,grid="y"); ax.legend(loc="upper right",ncol=3,fontsize=11.0)
        else: ax.text(.5,.5,"No history data",ha="center",va="center",transform=ax.transAxes)

        # D: effort distribution by signed target and confirmation step.
        ax=axs[1,1]
        mask=_np.isfinite(confirmations)&_np.isfinite(efforts)
        for sign,label,col,marker,offset in [(1,"+1 target",OC_SEMANTIC_COLORS["positive_basin"],"o",-.08),(-1,"-1 target",OC_SEMANTIC_COLORS["negative_basin"],"s",.08)]:
            m=mask&(signs==sign)
            if _np.any(m):
                ax.scatter(confirmations[m]+offset,efforts[m],s=25,color=col,marker=marker,alpha=.55,
                           edgecolors=OC_VISUAL_PALETTE["paper"],linewidths=.35,label=label)
                for st in sorted(set(confirmations[m])):
                    mm=m&(confirmations==st)
                    ax.scatter([st+offset],[_np.median(efforts[mm])],s=90,facecolors="none",edgecolors=col,linewidths=1.5)
        ax.set_xlabel("CONVEY-5 confirmation step"); ax.set_ylabel("Integrated basin regulation")
        ax.set_title("D. Governing effort by signed target"); _oc_style_axes(ax,grid="both"); ax.legend()

        note=(f"{OC_VISUAL_SYSTEM_ID}; execution seed={seed}. All panels use current-run records. "
              "Trajectory statistics are separated by signed basin to preserve bimodal interpretation.")
        _oc_save_figure(fig,path,note=note,dpi=180); _plt.close(fig); return True
    except Exception:
        try: _plt.close("all")
        except Exception as _oc_exc: logging.getLogger(__name__).warning("Nonfatal fallback captured: %s", _oc_exc)
        return False

def _mpl_save_hist(path, title, data, bins=30, figsize=(8.20,5.60)):
    try:
        import matplotlib.pyplot as _plt
        import numpy as _np
        vals=_np.asarray(list(data),dtype=float); vals=vals[_np.isfinite(vals)]
        fig,ax=_plt.subplots(figsize=figsize)
        ax.hist(vals,bins=bins,histtype="stepfilled",color=OC_VISUAL_PALETTE["sky"],
                edgecolor=OC_VISUAL_PALETTE["blue"],linewidth=1.0,alpha=.55)
        if vals.size:
            med=float(_np.median(vals)); ax.axvline(med,color=OC_VISUAL_PALETTE["vermillion"],linestyle="--",linewidth=1.5,label=f"Median {med:.3g}")
            ax.legend()
        ax.set_title(title); ax.set_ylabel("Count")
        _oc_style_axes(ax,grid="y")
        _oc_save_figure(fig,path,note=f"{OC_VISUAL_SYSTEM_ID}; current-run distribution.")
        _plt.close(fig); return True
    except Exception:
        return False

def _mpl_save_density_strip(path, title, values, bins=40, figsize=(8.20,5.60)):
    """Compact density-rug display with quartile and median marks."""
    try:
        import matplotlib.pyplot as _plt
        import numpy as _np
        vals=_np.asarray([float(v) for v in values if v is not None],dtype=float)
        vals=vals[_np.isfinite(vals)]
        if vals.size==0: return False
        counts,edges=_np.histogram(vals,bins=min(int(bins),max(3,int(_np.sqrt(vals.size))+1)),density=True)
        centers=.5*(edges[:-1]+edges[1:])
        fig,ax=_plt.subplots(figsize=figsize)
        ax.fill_between(centers,0,counts,color=OC_VISUAL_PALETTE["sky"],alpha=.38)
        ax.plot(centers,counts,color=OC_VISUAL_PALETTE["blue"],linewidth=2)
        # Deterministic rug, not randomized jitter.
        rug_h=(counts.max() if counts.size else 1.0)*.035
        ax.vlines(vals,0,rug_h,color=OC_VISUAL_PALETTE["slate"],alpha=.18,linewidth=.6)
        q25,q50,q75=_np.percentile(vals,[25,50,75])
        for q,ls,col,lab in [(q25,":",OC_VISUAL_PALETTE["slate"],"Q1"),(q50,"--",OC_VISUAL_PALETTE["vermillion"],"Median"),(q75,":",OC_VISUAL_PALETTE["slate"],"Q3")]:
            ax.axvline(q,color=col,linestyle=ls,linewidth=1.3,label=f"{lab} {q:.2f}")
        ax.set_title(title); ax.set_xlabel("Steps"); ax.set_ylabel("Density"); ax.legend(ncol=3,fontsize=11.0)
        _oc_style_axes(ax,grid="y")
        _oc_save_figure(fig,path,note=f"{OC_VISUAL_SYSTEM_ID}; density and rug derive from current-run values.")
        _plt.close(fig); return True
    except Exception:
        try: _plt.close("all")
        except Exception as _oc_exc: logging.getLogger(__name__).warning("Nonfatal fallback captured: %s", _oc_exc)
        return False


def _apply_perf_placeholders(report_text: str, results_dict: dict) -> str:
    """swap performance placeholders in report narrative with measured values (if available)."""
    perf = (results_dict or {}).get('perf', {}) if isinstance(results_dict, dict) else {}
    rt = perf.get('runtime_seconds', None)
    rss = perf.get('peak_rss_mb', None)
    plat = perf.get('platform', None)
    pyv = perf.get('python', None)
    def fmt(x):
        try:
            return f"{float(x):.3f}"
        except Exception:
            return "N/A"
    report_text = _sub_str(report_text, '<runtime_seconds>', fmt(rt))
    report_text = _sub_str(report_text, '<peak_rss_mb>', fmt(rss))
    report_text = _sub_str(report_text, '<platform>', str(plat) if plat else 'N/A')
    report_text = _sub_str(report_text, '<python_runtime>', str(pyv) if pyv else 'N/A')
    return report_text


