def _oc_canonical_sha256(path=None):
    """Canonical digest: every byte except the published-digest line."""
    try:
        target = path or __file__
        h = hashlib.sha256()
        with open(target, "rb") as f:
            for line in f:
                if line.startswith(b"OC_AUTHENTIC_SHA256"):
                    continue
                h.update(line)
        return h.hexdigest()
    except Exception:
        return "(unknown-sha256)"


def _oc_authenticity_status():
    """Development build: no authenticity seal is asserted or enforced."""
    actual = _oc_engine_sha256()
    if globals().get("OC_DEVELOPMENT_UNLOCKED", False):
        return None, "PENDING", actual
    expected = OC_AUTHENTIC_SHA256
    if expected in ("PENDING", "", None):
        return None, expected, actual
    return (actual == expected), expected, actual

def _oc_authenticity_verdict():
    if globals().get("OC_DEVELOPMENT_UNLOCKED", False):
        return "DEVELOPMENT_UNLOCKED"
    ok, _e, _a = _oc_authenticity_status()
    if ok is None:
        return "UNVERIFIED"
    return "VERIFIED" if ok else "MODIFIED"

