def _oc_emit_integrity_artifacts(outdir, batch_id, meta=None):
    """Write verifier, integrity record and legal disclosure into the output dir."""
    written = {}
    try:
        from pathlib import Path as _P
        d = _P(str(outdir))
        d.mkdir(parents=True, exist_ok=True)
        ok, expected, actual = _oc_authenticity_status()

        vsrc = OC_EXTERNAL_VERIFIER_SOURCE.replace("__OC_DIGEST__", str(expected))
        vsrc = vsrc.replace("__OC_SOURCE__", OC_ENGINE_OFFICIAL_SOURCE)
        vp = d / "verify_omni-compass.py"
        vp.write_text(vsrc, encoding="utf-8")
        written["external_verifier"] = str(vp)

        rec = {
            "batch_id": batch_id,
            "product": OC_ENGINE_PRODUCT_NAME,
            "owner_of_record": OC_ENGINE_OWNER_OF_RECORD,
            "creator_of_record": OC_ENGINE_CREATOR_OF_RECORD,
            "copyright": OC_ENGINE_COPYRIGHT,
            "governing_law": OC_ENGINE_GOVERNING_LAW,
            "contact_telephone": OC_ENGINE_CONTACT_TELEPHONE,
            "official_source": OC_ENGINE_OFFICIAL_SOURCE,
            "authenticity_verdict": _oc_authenticity_verdict(),
            "published_canonical_sha256": expected,
            "computed_canonical_sha256": actual,
            "whole_file_sha256": _oc_engine_sha256(),
            "integrity_scope": "All bytes of the engine source except the single line carrying the published digest.",
            "verification_instructions": [
                "python verify_omni-compass.py <engine.py>",
                "shasum -a 256 <engine.py>   (compare whole-file digest against the published value)",
                "Confirm the published digest independently at " + OC_ENGINE_OFFICIAL_SOURCE,
            ],
            "notices": {
                "integrity": OC_INTEGRITY_STATEMENT,
                "licence_and_rights": OC_LICENSE_GRANT_NOTICE,
                "rename_on_modification": OC_RENAME_ON_MODIFICATION_NOTICE,
                "modified_copy": OC_MODIFIED_COPY_NOTICE,
                "result_attribution": OC_RESULT_ATTRIBUTION_REQUIREMENT,
                "evidence_class": OC_EVIDENCE_CLASS_NOTICE,
                "proportionality_of_claim": OC_PROPORTIONALITY_OF_CLAIM_NOTICE,
                "no_legal_opinion": OC_NO_LEGAL_OPINION_NOTICE,
            },
        }
        rp = d / f"ENGINE_INTEGRITY_RECORD_{batch_id}.json"
        rp.write_text(json.dumps(rec, indent=2, default=str), encoding="utf-8")
        written["integrity_record"] = str(rp)

        lines = []
        lines.append("=" * 78)
        lines.append(f"  {OC_ENGINE_PRODUCT_NAME.upper()}")
        lines.append("  MASTER INTEGRITY, VERIFICATION AND LEGAL DISCLOSURE RECORD")
        lines.append("=" * 78)
        lines.append("")
        lines.append(f"Batch ID: {batch_id}")
        lines.append(f"Owner of record: {OC_ENGINE_OWNER_OF_RECORD}")
        lines.append(f"Creator / developer of record: {OC_ENGINE_CREATOR_OF_RECORD}")
        lines.append(f"{OC_ENGINE_COPYRIGHT}")
        lines.append(f"Governing law: {OC_ENGINE_GOVERNING_LAW}")
        lines.append(f"Commercial licensing contact: {OC_ENGINE_CREATOR_OF_RECORD}, telephone {OC_ENGINE_CONTACT_TELEPHONE}")
        lines.append(f"Official source: {OC_ENGINE_OFFICIAL_SOURCE}")
        lines.append(f"Authenticity verdict: {_oc_authenticity_verdict()}")
        lines.append(f"Published canonical digest: {expected}")
        lines.append(f"Computed canonical digest:  {actual}")
        lines.append(f"Whole-file digest:          {_oc_engine_sha256()}")
        lines.append("")
        lines.append("-" * 78)
        lines.append("HOW TO VERIFY THIS EXECUTION")
        lines.append("-" * 78)
        lines.append("")
        lines.append("1. VERIFY THE FILE. A standalone verifier has been written beside this")
        lines.append("   record. It reads bytes only and does not execute the engine:")
        lines.append("")
        lines.append("       python verify_omni-compass.py <engine.py>")
        lines.append("")
        lines.append("   Do not rely on the engine's self-report alone. Confirm the published")
        lines.append("   digest independently at the official source, and cross-check with any")
        lines.append("   standard utility: shasum -a 256 <engine.py>")
        lines.append("")
        lines.append("2. VERIFY THE ENVIRONMENT. An unmodified engine executed against")
        lines.append("   mismatched or corrupted libraries can produce incorrect output while")
        lines.append("   its digest still verifies. Use the pinned dependency set or the")
        lines.append("   published container image, and state which was used when publishing.")
        lines.append("")
        lines.append("3. VERIFY THE MATHEMATICS. Execute the engine with a fixed seed and")
        lines.append("   confirm that the deterministic fields reproduce:")
        lines.append("")
        lines.append("       python <engine.py> --seed 12345")
        lines.append("")
        lines.append("   Fields that legitimately differ between executions - batch identifier,")
        lines.append("   timestamps, wall-clock stage timings and output directory names - are")
        lines.append("   not part of any reference vector and prove nothing either way.")
        lines.append("")
        for block in (OC_INTEGRITY_STATEMENT, OC_LICENSE_GRANT_NOTICE,
                      OC_RENAME_ON_MODIFICATION_NOTICE, OC_MODIFIED_COPY_NOTICE,
                      OC_RESULT_ATTRIBUTION_REQUIREMENT, OC_EVIDENCE_CLASS_NOTICE,
                      OC_PROPORTIONALITY_OF_CLAIM_NOTICE, OC_NO_LEGAL_OPINION_NOTICE):
            lines.append("-" * 78)
            lines.append("")
            lines.append(block)
            lines.append("")
        lines.append("-" * 78)
        lines.append("IF YOU ARE SHOWN AN ADVERSE OMNI-COMPASS RESULT")
        lines.append("-" * 78)
        lines.append("")
        lines.append("Adverse and critical results are permitted and invited. Before giving any")
        lines.append("adverse result evidentiary weight, request the three disclosures required")
        lines.append("above: the canonical digest of the executed file, the environment, and the")
        lines.append("seed and arguments. An authentic engine reproduces its fixed-seed")
        lines.append("reference values. A file that cannot produce them, or whose digest does")
        lines.append("not match the published value, did not execute Omni-Compass.")
        lines.append("")
        lines.append("=" * 78)
        lp = d / f"MASTER_LEGAL_AND_INTEGRITY_DISCLOSURE_{batch_id}.txt"
        lp.write_text("\n".join(lines), encoding="utf-8")
        written["master_disclosure"] = str(lp)

        licp = d / "LICENSE.txt"
        licp.write_text(OC_FULL_LICENSE_TEXT, encoding="utf-8")
        written["license"] = str(licp)
    except Exception as exc:  # never allow disclosure emission to break a run
        written["error"] = f"{type(exc).__name__}: {exc}"
    return written
