def _public_equation_pdf_flowables(disclosure_style):
    """Render the complete equation inside one collision-safe outer cell.

    The prior implementation applied a border to each Paragraph because the
    disclosure style itself carried border attributes. Wrapped equation lines
    were therefore crossed by horizontal rules. This implementation uses
    border-free child paragraphs inside one auto-height Table cell, with a
    single outer border and no internal grid lines.
    """
    equation_style = ParagraphStyle(
        "CompleteEquationLineCell",
        parent=disclosure_style,
        fontName="OCMono",
        fontSize=11.0,
        leading=14.0,
        leftIndent=0,
        rightIndent=0,
        firstLineIndent=0,
        spaceBefore=0,
        spaceAfter=4,
        borderWidth=0,
        borderPadding=0,
        backColor=None,
        splitLongWords=False,
        wordWrap="LTR",
        allowWidows=0,
        allowOrphans=0,
    )
    operator_heading_style = ParagraphStyle(
        "EquationOperatorHeadingCell",
        parent=disclosure_style,
        fontName="OCSans-Bold",
        fontSize=11.0,
        leading=13.5,
        spaceBefore=5,
        spaceAfter=3,
        borderWidth=0,
        borderPadding=0,
        backColor=None,
    )
    operator_style = ParagraphStyle(
        "EquationOperatorCell",
        parent=disclosure_style,
        fontName="OCSans",
        fontSize=11.0,
        leading=13.5,
        spaceBefore=0,
        spaceAfter=0,
        borderWidth=0,
        borderPadding=0,
        backColor=None,
        splitLongWords=False,
        wordWrap="LTR",
    )
    disclosure_heading_style = ParagraphStyle(
        "EquationDisclosureHeadingClean",
        parent=disclosure_style,
        fontName="OCSans-Bold",
        fontSize=11.0,
        leading=13.5,
        spaceBefore=8,
        spaceAfter=4,
        borderWidth=0,
        borderPadding=0,
        backColor=None,
    )
    disclosure_body_style = ParagraphStyle(
        "EquationDisclosureBodyClean",
        parent=disclosure_style,
        fontName="OCSans",
        fontSize=11.0,
        leading=13.5,
        spaceBefore=0,
        spaceAfter=0,
        borderWidth=0,
        borderPadding=0,
        backColor=None,
        allowWidows=0,
        allowOrphans=0,
    )

    equation_contents = []
    for line in PUBLIC_EQUATION_TEXT_LINES:
        equation_contents.append(Paragraph(_html.escape(line), equation_style))
    equation_contents.append(Spacer(1, 3))
    equation_contents.append(Paragraph("Executed hybrid microstep operator", operator_heading_style))
    equation_contents.append(Paragraph(_html.escape(HYBRID_OPERATOR_ASCII), operator_style))

    equation_cell = Table(
        [[equation_contents]],
        colWidths=[500],
        hAlign="LEFT",
        splitByRow=1,
    )
