# ---------------------------------------------------------------------
# CANONICAL EXPERIMENTAL SPINOR-CLOSURE EXTENSION
# ---------------------------------------------------------------------
SPINOR_CLOSURE_ENABLED: bool = True
SPINOR_PHASE_GAIN: float = 1.0

def spinor_phase_angle(t: float, p: OCParameters) -> float:
    """Compass phase theta(t), one 360-degree circuit per bath period."""
    return float(p.omega_B * t)

def spinor_closure_factor(t: float, p: OCParameters) -> float:
    """720-degree spinor factor: +1 at 0, -1 at 360°, +1 at 720°."""
    if not SPINOR_CLOSURE_ENABLED:
        return 1.0
    return float(np.cos(0.5 * spinor_phase_angle(t, p)))

@dataclass
class OCState:
    E: float
    U: float
    I_U: float
    S: float
    B: float
    B_dot: float

def sample_initial_state(rng: np.random.Generator) -> OCState:
    return OCState(
        E=float(rng.uniform(0.0, 1.0)),
        U=float(rng.uniform(-1.0, 1.0)),
        I_U=float(rng.uniform(0.0, 1.0)),
        S=float(rng.uniform(-1.0, 1.0)),
        B=float(rng.uniform(-1.0, 1.0)),
        B_dot=float(rng.uniform(-1.0, 1.0)),
    )

def sample_parameters(rng: np.random.Generator) -> OCParameters:
    p = {k: float(rng.uniform(lo, hi)) for k, (lo, hi) in PARAMETER_RANGES.items()}
    return OCParameters(**p)

def v_eff(state: OCState, p: OCParameters, t: float = 0.0) -> float:
    """Piece I line (4), with optional CANONICAL 720-degree spinor closure."""
    U_t = 0.5
    z = p.lambda_0 + p.lambda_1 * (state.U - U_t) + p.lambda_2 * state.S
    saturated_drive = float(p.c * np.tanh(z))
    return float(SPINOR_PHASE_GAIN * spinor_closure_factor(t, p) * saturated_drive)

def phi_state(S: float, p: OCParameters) -> float:
    """Piece I line (5): canonical coherence-state potential Phi(S)."""
    return float(0.5 * p.alpha_s * (S ** 2) + 0.25 * p.beta_s * (S ** 3) - p.delta * S)

def F_state(S: float, p: OCParameters) -> float:
    """Piece I line (6): canonical S-state flow, -dPhi/dS."""
    return float(p.delta - p.alpha_s * S - 0.75 * p.beta_s * (S ** 2))


def W_potential(U: float, p: OCParameters) -> float:
    """Signed-basin double-well potential; minima occur at U=+1 and U=-1."""
    return float(0.25 * float(p.mu) * (float(U) * float(U) - 1.0) ** 2)

def W_gradient_flow(U: float, p: OCParameters) -> float:
    """-dW/dU = mu*U*(1-U^2); stable at +/-1 and unstable at 0 for mu>0."""
    U = float(U)
    return float(float(p.mu) * U * (1.0 - U * U))

def W_curvature(U: float, p: OCParameters) -> float:
    """Derivative of the U gradient flow; equals -2*mu at either basin center."""
    U = float(U)
    return float(float(p.mu) * (1.0 - 3.0 * U * U))


_OC_BATH_LYAP_CACHE: Dict[Tuple[float,float], np.ndarray] = {}
_OC_COMPOSITE_WEIGHT_CACHE: Dict[Tuple[float,...], Dict[str,float]] = {}

def spinor_residual_bounds(p: OCParameters) -> Dict[str, float]:
    """Explicit conservative spinor residual coefficients for the recorded parameter row."""
    c=abs(float(p.c))
    lsum=abs(float(p.lambda_1))+abs(float(p.lambda_2))
    emax=max(abs(float(p.E_max)),EPS)
    omega=max(abs(float(p.omega_B)),EPS)
    R1=float(2.0*c*lsum)
    R2=float(2.0*c*c*lsum*(1.0+1.0/emax))
    scaled=float(R1/omega + R2/(omega*omega))
    return {
        "R1":R1,"R2":R2,"omega_B":omega,
        "R1_over_omega":float(R1/omega),
        "R2_over_omega_sq":float(R2/(omega*omega)),
        "averaging_residual_bound":scaled,
        "ordinary_bounded_input_bound":c,
        "frequency_regime_high":float(omega>=1.0),
    }


# =============================================================================
# EXPLICIT PRACTICAL-STABILITY RESIDUAL CERTIFICATE (H13/H14)
# =============================================================================
# These constants do not alter the canonical ODE or controller.  They freeze the
# lower-bound coefficient and dissipation floor already used by the H12 storage
# argument so the residual comparison is reproducible and falsifiable.
OC_PRACTICAL_A_U: float = 1.0
OC_PRACTICAL_ETA_FLOOR: float = 0.25
OC_PRACTICAL_BASIN_RADIUS_TARGET: float = 0.10
OC_PRACTICAL_D_BAR_UNFORCED: float = 0.0

def practical_stability_residual_radius(
    R1: float,
    R2: float,
    omega_B: float,
    *,
    D_bar: float = OC_PRACTICAL_D_BAR_UNFORCED,
    a_U: float = OC_PRACTICAL_A_U,
    eta: float = OC_PRACTICAL_ETA_FLOOR,
) -> float:
    """Return rho_U from the explicit comparison inequality.

    If V >= (a_U/2)(U-sigma)^2 and
        dV/dt <= -eta V + R1/omega_B + R2/omega_B^2 + D_bar,
    then
        limsup |U-sigma| <= rho_U
    with the returned radius.  This function evaluates the theorem formula;
    it does not claim that its hypotheses hold outside the separately recorded
    H12 local region or under undeclared disturbance bounds.
    """
    w=max(abs(float(omega_B)), EPS)
    a=max(float(a_U), EPS)
    e=max(float(eta), EPS)
    d=max(float(D_bar), 0.0)
    residual=max(0.0, float(R1)/w + float(R2)/(w*w) + d)
    return float(math.sqrt(2.0*residual/(a*e)))

def practical_stability_required_omega(
    R1: float,
    R2: float,
    *,
    D_bar: float = OC_PRACTICAL_D_BAR_UNFORCED,
    a_U: float = OC_PRACTICAL_A_U,
    eta: float = OC_PRACTICAL_ETA_FLOOR,
    basin_tolerance: float = OC_PRACTICAL_BASIN_RADIUS_TARGET,
) -> float:
    """Smallest omega satisfying rho_U < basin_tolerance under the formula.

    Returns +inf if the disturbance floor alone already makes the target
    impossible.  Strict inequality is interpreted as omega greater than the
    returned positive root.
    """
    a=max(float(a_U),EPS); e=max(float(eta),EPS)
    tol=max(float(basin_tolerance),EPS)
    d=max(float(D_bar),0.0)
    # rho^2 < tol^2 => R1/w + R2/w^2 + D_bar < (a*eta*tol^2)/2
    allowance=0.5*a*e*tol*tol-d
    if allowance <= 0.0:
        return float("inf")
    r1=max(float(R1),0.0); r2=max(float(R2),0.0)
    disc=r1*r1+4.0*allowance*r2
    return float((r1+math.sqrt(max(0.0,disc)))/(2.0*allowance))

def practical_stability_parameter_box_certificate() -> Dict[str, Any]:
    """Conservative H13/H14 audit against the declared parameter box.

    The theorem is intentionally evaluated first in the unforced D_bar=0
    regime because the current engine has not proved a scalar mapping from the
    full beta_int/beta_ext forcing box into the simplified D_bar term used by
    this comparison formula.  Current Monte-Carlo forcing is therefore NOT
    promoted into this theorem.
    """
    c_max=float(PARAMETER_RANGES["c"][1])
    l1_max=float(PARAMETER_RANGES["lambda_1"][1])
    l2_max=float(PARAMETER_RANGES["lambda_2"][1])
    emax_min=max(float(PARAMETER_RANGES["E_max"][0]),EPS)
    omega_lo=float(PARAMETER_RANGES["omega_B"][0])
    omega_hi=float(PARAMETER_RANGES["omega_B"][1])
    R1_max=float(2.0*c_max*(l1_max+l2_max))
    R2_max=float(2.0*c_max*c_max*(l1_max+l2_max)*(1.0+1.0/emax_min))
    omega_required=practical_stability_required_omega(
        R1_max,R2_max,D_bar=OC_PRACTICAL_D_BAR_UNFORCED)
    rho_at_box_max=practical_stability_residual_radius(
        R1_max,R2_max,omega_hi,D_bar=OC_PRACTICAL_D_BAR_UNFORCED)
    overlaps=bool(math.isfinite(omega_required) and omega_hi>omega_required)
    _omega_root = float(omega_required)
    _omega_nextafter = math.nextafter(_omega_root, math.inf) if math.isfinite(_omega_root) else _omega_root
    _omega_relative = _omega_root * (1.0 + 1.0e-12) if math.isfinite(_omega_root) else _omega_root
    # Use the stronger of one-ULP advancement and a transparent relative margin.
    # This avoids making the theorem's strictness depend only on binary64 spacing.
    _omega_safe = max(_omega_nextafter, _omega_relative) if math.isfinite(_omega_root) else _omega_root
    _rho_at_safe = practical_stability_residual_radius(
        R1_max, R2_max, _omega_safe,
        D_bar=OC_PRACTICAL_D_BAR_UNFORCED,
        a_U=OC_PRACTICAL_A_U,
        eta=OC_PRACTICAL_ETA_FLOOR,
    ) if math.isfinite(_omega_safe) else float("inf")
    return {
        "schema_id":"OC-PRACTICAL-STABILITY-H13-H14-v2-RESTRICTED-REGIME",
        "a_U":OC_PRACTICAL_A_U,
        "eta_floor":OC_PRACTICAL_ETA_FLOOR,
        "D_bar":OC_PRACTICAL_D_BAR_UNFORCED,
        "D_bar_scope":"UNFORCED THEOREM ONLY; no scalar full-beta-box D_bar proof is asserted.",
        "basin_tolerance":OC_PRACTICAL_BASIN_RADIUS_TARGET,
        "R1_box_max":R1_max,
        "R2_box_max":R2_max,
        "omega_B_box":[omega_lo,omega_hi],
        "omega_required_strictly_greater_than":_omega_root,
        "omega_boundary_root_rho_equals_tolerance":_omega_root,
        "omega_nextafter_strict_candidate":_omega_nextafter,
        "omega_relative_margin_candidate":_omega_relative,
        "omega_strict_margin_relative":1.0e-12,
        "omega_min_strict_safe":_omega_safe,
        "rho_U_at_omega_min_strict_safe":_rho_at_safe,
        "restricted_theorem_domain":f"omega_B >= {_omega_safe:.17g}",
        "restricted_theorem_machine_check_pass":bool(_rho_at_safe < OC_PRACTICAL_BASIN_RADIUS_TARGET),
        "rho_U_at_declared_omega_max":rho_at_box_max,
        "current_parameter_box_satisfies_rho_lt_tolerance":overlaps,
        "theorem_status":"PROVED_RESTRICTED_DOMAIN_ONLY_DISJOINT_FROM_EXECUTED_BOX" if (_rho_at_safe < OC_PRACTICAL_BASIN_RADIUS_TARGET and not overlaps) else ("PROVED_RESTRICTED_DOMAIN_WITH_BOX_OVERLAP" if _rho_at_safe < OC_PRACTICAL_BASIN_RADIUS_TARGET else "RESTRICTED_SET_MACHINE_CHECK_FAILED"),
        "full_declared_box_status":"OUTSIDE_RESTRICTED_THEOREM_DOMAIN" if not overlaps else "OVERLAPS_RESTRICTED_THEOREM_DOMAIN",
        "supports_executed_500_campaign":bool(overlaps),
        "claim_matrix_reading_rule":"This theorem is mathematically valid on its stated restricted unforced frequency domain. When that domain is disjoint from the executed omega_B sampling box it must not be cited as proof of the 500-run campaign.",
        "formula":"rho_U=sqrt(2*(R1/omega_B+R2/omega_B^2+D_bar)/(a_U*eta))",
        "condition":"rho_U < basin_tolerance",
        "proof_statement":"For fixed conservative R1_max, R2_max, a_U, eta and D_bar=0, rho_U is strictly decreasing for omega_B>0. Therefore every omega_B >= omega_min_strict_safe satisfies rho_U < basin_tolerance.",
        "excluded_inference":"This proves only the stated unforced restricted-frequency sufficient condition. It does not prove the current forced Monte-Carlo campaign, the original omega_B in [0.1,5] box, global H12 region entry, or a full-beta-box D_bar bound.",
    }

# =============================================================================
# AUDIT FIX S1 - CERT-10 CONTRACTION COROLLARY
# =============================================================================
# The strongest unused asset in the package.  The canonical controller is exact
# feedback linearization on the U channel:
#
#       u = -f_U(x,t) + KP*(sigma - U)     =>     dU/dt = KP*(sigma - U)
#
# The feedforward term cancels the ENTIRE U-channel drift at every RK4 stage, so
# the sampled-data error recurrence already computed in H11 is
#
#       e_{k+1} = (1 - KP*h)*e_k + h*d
#
# with |d| bounded by the intra-hold variation of the U field.  This makes basin
# entry DETERMINISTIC for every parameter draw in the declared box, not merely
# observed in 500 samples.  Prior builds reported CERT-10 only as a row-checked
# empirical fraction (500/500) and attached a Clopper-Pearson upper bound on the
# unobserved failure rate.  That understated the available claim: for THIS
# predicate the failure region is provably empty over the box.
#
# The corollary is emitted as its own artifact and is cross-checked against the
# executed campaign, so it is falsifiable rather than merely asserted.
# =============================================================================

def cert10_contraction_corollary(
    kp: float = None,
    macro_dt: float = None,
    micro_steps: int = None,
    basin_tol: float = None,
    residual_radius: float = None,
    max_initial_error: float = 1.0,
    certification_steps: int = None,
    horizon_steps: int = None,
) -> Dict[str, Any]:
    """Conditional sampled-data CERT-10 bound using the H11 residual envelope.

    The feedforward command cancels the U-channel drift at the BEGINNING of each
    microstep and is then held ZOH across the four RK4 stages.  Therefore the
    exact closed-loop RK4 map is not the pure scalar ODE dU/dt=KP*(sigma-U).
    H11 reconstructs the actual map as

        e[k+1] = (1-KP*h)e[k] + h*d[k] + eps[k]

    where d[k] is the intra-hold drift/saturation residual and eps[k] is the
    RK4 reconstruction error.  The bound below is analytic CONDITIONAL ON the
    declared numerical envelope for |d| (with its Lipschitz margin), plus no
    actuator saturation.  It is stronger than a row-only Monte-Carlo statement,
    but it is not mislabeled as a formal interval proof over the entire box.
    """
    kp=float(KP if kp is None else kp)
    macro_dt=float(MACRO_DT if macro_dt is None else macro_dt)
    micro_steps=int(MICRO_STEPS_PER_STEP if micro_steps is None else micro_steps)
    basin_tol=float(BASIN_TOL if basin_tol is None else basin_tol)
    certification_steps=int(CERTIFICATION_STEPS if certification_steps is None else certification_steps)
    horizon_steps=int(MAX_STEPS if horizon_steps is None else horizon_steps)
    if residual_radius is None:
        residual_radius=(float(OC_CERTIFIED_LIPSCHITZ_MARGIN)*float(OC_CERTIFIED_SUP_INTRA_HOLD_D)/kp) if kp else float("inf")
    h=macro_dt/float(micro_steps)
    q_signed=1.0-kp*h
    q_micro=abs(q_signed)
    contractive=bool(q_micro<1.0)
    q_macro=q_micro**micro_steps
    rho=float(residual_radius)
    trajectory=[]; entry_step=None
    for step in range(1,horizon_steps+1):
        # Standard affine-contraction envelope after step*micro_steps updates:
        # |e_N| <= q^N |e_0| + rho(1-q^N), where rho is the ultimate radius.
        qn=q_macro**step
        bound=float(qn*float(max_initial_error)+rho*(1.0-qn))
        inside=bool(bound<=basin_tol)
        trajectory.append({"macro_step":step,"worst_case_total_error_bound":bound,
                           "homogeneous_error_term":float(qn*float(max_initial_error)),
                           "residual_accumulation_term":float(rho*(1.0-qn)),
                           "inside_basin_tolerance":inside})
        if inside and entry_step is None: entry_step=step
        if step>=8 and entry_step is not None: break
    # If entry_step is observation one, ten consecutive observations finish at +9.
    cert_step=(entry_step+certification_steps-1) if entry_step is not None else None
    return {
        "hypotheses":[
            "sample-time feedforward cancellation with bounded FF+P command held ZOH across each RK4 microstep",
            "the declared 3x-margined intra-hold residual envelope bounds every canonical microstep residual",
            "no actuator saturation over the claimed execution class",
            "KP*h is in (0,2), so the scalar homogeneous recurrence is contractive",
            "Step-0 nearest-basin target lock gives worst-case initial |U-sigma|<=1 for U0 in [-1,1]",
        ],
        "KP":kp,"macro_dt":macro_dt,"micro_steps_per_macro_step":micro_steps,"micro_dt":h,
        "kp_times_h":kp*h,"per_microstep_contraction_factor":q_micro,
        "per_macro_step_contraction_factor":q_macro,"recurrence_is_contractive":contractive,
        "basin_tolerance":basin_tol,"certified_residual_radius":rho,
        "residual_envelope_basis":"NUMERICAL_PARAMETER_BOX_SWEEP_WITH_3X_MARGIN; NOT AN INTERVAL-ARITHMETIC PROOF",
        "worst_case_initial_error":float(max_initial_error),"worst_case_trajectory":trajectory,
        "guaranteed_basin_entry_macro_step":entry_step,"certification_steps_required":certification_steps,
        "guaranteed_cert10_completion_macro_step":cert_step,"horizon_macro_steps":horizon_steps,
        "horizon_slack_macro_steps":(horizon_steps-cert_step) if cert_step is not None else None,
        "status":"CONDITIONAL_ANALYTIC_GIVEN_NUMERIC_RESIDUAL_ENVELOPE" if (contractive and entry_step is not None) else "NOT_ESTABLISHED",
        "reading_rule":(
            "If the stated intra-hold residual envelope is valid for the whole declared box and no saturation occurs, "
            "the affine sampled-data bound guarantees basin entry and hence CERT-10 by the reported step. The 500-run "
            "campaign cross-checks that sufficient bound; it does not convert the numerical residual envelope into a formal "
            "interval proof. Clopper-Pearson remains the finite-sample statement for claims not covered by this conditional bound."),
        "falsifier":(
            "FALSIFIER: any non-saturated canonical row whose H11 residual exceeds the declared margined envelope, whose basin "
            "entry is later than the bound, or whose CERT-10 completion is later than the bound invalidates this certificate."),
    }


# =============================================================================
# AUDIT FIX A1 - CERT-10 MEASUREMENT-NOISE BUDGET
# =============================================================================
# The most deployment-relevant result this package produces was buried in an
# n=30 auxiliary CSV: certification collapses under persistent channel noise
# long before basin capture does.  In batch e706d5a8-8, sigma=0.05 gave
# conveyance 24/30 = 0.800 but certification 4/30 = 0.133, while a 0.25 IMPULSE
# left both at 30/30.  That non-monotonicity is not noise in the data - it is
# the correct behaviour of a DWELL predicate, and it is exactly what an operator
# must know before deploying against real sensors.
#
# CERT-10 requires ten CONSECUTIVE in-basin observations.  With basin tolerance
# T and certified ultimate residual radius rho, the usable noise headroom is
# T - rho.  For zero-mean channel noise of scale sigma the per-observation
# admission probability is 2*Phi((T-rho)/sigma) - 1 and certification requires
# ten in a row.  This yields a hard, quotable sensor specification that the
# package previously did not state at all.
# =============================================================================

# -----------------------------------------------------------------------------
# EMPIRICALLY GOVERNING CONSTANTS - SET FROM EXECUTED ARMS, NOT FROM THE MODEL
# -----------------------------------------------------------------------------
# The executed disturbance grid certified at 1.0000 at sigma=0.020 and at
# 0.4333 at sigma=0.030, so the knee lies between them. The governing budget is
# set at the last sigma that certified cleanly. It is DELIBERATELY tighter than
# the independent-observation closed form, which execution showed to be
# optimistic. If a future campaign refines the grid between 0.020 and 0.030,
# this constant is to be updated FROM THAT CAMPAIGN, not from the model.
OC_CERT10_EMPIRICAL_NOISE_BUDGET_SIGMA: float = 0.020
OC_CERT10_NOISE_BUDGET_BASIS: str = (
    "Set from executed disturbance arms (n=30 per arm): certification held at 1.0000 through "
    "sigma=0.020 and fell to 0.4333 at sigma=0.030. The budget is the last cleanly certifying "
    "sigma. Re-derive from any campaign that refines the 0.020-0.030 interval or raises n.")

# -----------------------------------------------------------------------------
# EXECUTED FINDING - THE RESIDUAL-RADIUS CERTIFICATE IS CONSERVATIVE
# -----------------------------------------------------------------------------
# The extended threshold sweep (AUDIT FIX A3) ran tolerances down to 0.002 -
# well below the un-margined predicted edge of sup|d|/KP = 0.008396 - and
# certification remained at 1.0000 at every tolerance tested. No boundary was
# located. The correct reading is NOT that the sweep failed: it is that the
# ACTUAL ultimate U-error is substantially smaller than the certified radius,
# i.e. the certificate is conservative by at least a factor of four on executed
# trajectories. The certificate remains valid - it is an upper bound and upper
# bounds are allowed to be loose - but it must not be presented as tight, and
# the sweep must not be presented as having located an empirical edge.
OC_RESIDUAL_CERTIFICATE_CONSERVATISM_NOTE: str = (
    "EXECUTED FINDING: the extended basin-tolerance sweep reached 0.002, below the un-margined "
    "predicted degradation edge of sup|d|/KP = 0.008396, and certification remained at 1.0000 "
    "throughout. No empirical boundary was located in the swept range. This indicates the "
    "residual-radius certificate is CONSERVATIVE on executed trajectories by at least a factor of "
    "four, not that the sweep is uninformative. The certificate is an upper bound and remains "
    "valid; it is not tight, it is not presented as tight, and the sweep is not presented as "
    "having located an edge. A tighter certificate would require re-deriving sup|d| from executed "
    "intra-hold variation rather than from the parameter-box corner sweep.")


def _bernoulli_run_probability(success_probability: float, run_length: int, observations: int) -> float:
    """Probability of at least one run of `run_length` successes in N iid Bernoulli trials."""
    p=max(0.0,min(1.0,float(success_probability))); k=max(1,int(run_length)); n=max(0,int(observations))
    if n<k: return 0.0
    transient=[0.0]*k; transient[0]=1.0; absorbed=0.0
    for _ in range(n):
        nxt=[0.0]*k
        alive=sum(transient)
        nxt[0]+=alive*(1.0-p)
        for r,mass in enumerate(transient):
            if r==k-1: absorbed+=mass*p
            else: nxt[r+1]+=mass*p
        transient=nxt
    return max(0.0,min(1.0,absorbed))


def cert10_noise_budget(
    basin_tol: float = None,
    residual_radius: float = None,
    certification_steps: int = None,
    sigmas: Tuple[float, ...] = (0.001,0.005,0.010,0.015,0.020,0.025,0.030,0.040,0.050,0.060,0.080),
    target_cert_probability: float = 0.95,
) -> Dict[str, Any]:
    """Independent Gaussian MEASUREMENT-noise qualification model.

    This is deliberately distinct from DISTURBANCE_ROBUSTNESS.csv, where noise
    is injected into the U STATE after every microstep and therefore changes the
    subsequent dynamics.  Here noise corrupts observations only.  Given the
    conditional residual radius rho, every true observation is assumed no worse
    than rho from its target; Gaussian measurement noise must fit inside the
    remaining headroom T-rho.  The finite-horizon CERT-10 probability is the
    probability of at least one run of ten admissible observations, not merely p^10.
    """
    basin_tol=float(BASIN_TOL if basin_tol is None else basin_tol)
    certification_steps=int(CERTIFICATION_STEPS if certification_steps is None else certification_steps)
    if residual_radius is None:
        residual_radius=float(OC_CERTIFIED_LIPSCHITZ_MARGIN)*float(OC_CERTIFIED_SUP_INTRA_HOLD_D)/float(KP)
    headroom=float(basin_tol)-float(residual_radius)
    cor=cert10_contraction_corollary(basin_tol=basin_tol,residual_radius=residual_radius,certification_steps=certification_steps)
    entry=int(cor.get("guaranteed_basin_entry_macro_step") or 0)
    available=max(0,int(MAX_STEPS)-entry+1)
    def _phi(z): return 0.5*(1.0+math.erf(z/math.sqrt(2.0)))
    def _prob(sigma):
        if sigma<=0: return 1.0,1.0
        if headroom<=0: return 0.0,0.0
        p1=max(0.0,min(1.0,2.0*_phi(headroom/float(sigma))-1.0))
        return p1,_bernoulli_run_probability(p1,certification_steps,available)
    curve=[]
    for sigma in sigmas:
        p1,pk=_prob(float(sigma))
        curve.append({"sigma":float(sigma),"single_observation_admission_probability_worst_case":p1,
                      "finite_horizon_cert10_probability_iid_measurement_model":pk,
                      "available_post_entry_observations":available})
    budget=None
    if headroom>0:
        lo,hi=1e-8,max(headroom*8.0,1e-4)
        for _ in range(220):
            mid=.5*(lo+hi); _,pk=_prob(mid)
            if pk>=float(target_cert_probability): lo=mid
            else: hi=mid
        budget=lo
    return {
        "model_scope":"INDEPENDENT_GAUSSIAN_MEASUREMENT_NOISE_ONLY",
        "basin_tolerance":basin_tol,"conditional_residual_radius":float(residual_radius),
        "usable_measurement_noise_headroom":headroom,"certification_steps_required":certification_steps,
        "guaranteed_entry_step_used":entry,"available_post_entry_observations":available,
        "target_cert_probability":float(target_cert_probability),"measurement_noise_sigma_budget_model":budget,
        "curve":curve,
        "reading_rule":(
            "This model does not describe process/state noise. It assumes independent zero-mean Gaussian measurement error "
            "applied only to qualification observations after the controller has entered its conditional residual set. "
            "Process-noise limits are empirical and are reported separately from executed disturbance arms."),
        "falsifier":(
            "FALSIFIER: a measurement-only Monte-Carlo arm generated from clean trajectories and independent Gaussian observation "
            "noise must agree with this finite-horizon run-probability model within its sampling interval."),
    }


def cert10_process_noise_empirical_budget(noise_rows: List[Dict[str,Any]], target_probability: float=0.95) -> Dict[str,Any]:
    """Derive a process/state-noise budget from executed Gaussian arms, with uncertainty."""
    rows=[]
    for r in noise_rows or []:
        name=str(r.get("scenario",""))
        if not name.startswith("gaussian_"): continue
        try: sigma=float(name.split("_",1)[1])
        except Exception: continue
        n=int(r.get("n",r.get("count",0)) or 0)
        rate=float(r.get("certified_rate",0.0) or 0.0)
        k=int(round(rate*n)) if n else 0
        lo,hi=_ev_wilson_interval(k,n) if n else (0.0,1.0)
        rows.append({"sigma":sigma,"n":n,"certified":k,"certified_rate":rate,"wilson95_low":lo,"wilson95_high":hi,
                     "qualifies_target_with_95pct_lower_bound":bool(lo>=float(target_probability))})
    rows.sort(key=lambda x:x["sigma"])
    qualifying=[r for r in rows if r["qualifies_target_with_95pct_lower_bound"]]
    budget=max((r["sigma"] for r in qualifying),default=None)
    return {"model_scope":"EXECUTED_U_STATE_PROCESS_NOISE_AFTER_EACH_MICROSTEP",
            "target_cert_probability":float(target_probability),"empirical_sigma_budget_95pct_lower_bound":budget,
            "rows":rows,
            "reading_rule":"This is an empirical process/state-noise envelope, not a sensor-noise theorem. The budget is the largest tested sigma whose 95% Wilson lower bound remains at or above the target certification probability."}


def cert10_corollary_row_audit(rows: List[Dict[str, Any]], corollary: Dict[str, Any] = None) -> Dict[str, Any]:
    """Check every executed row against the analytic bound. This is the falsifier test."""
    cor = corollary or cert10_contraction_corollary()
    bound_entry = cor.get("guaranteed_basin_entry_macro_step")
    bound_cert = cor.get("guaranteed_cert10_completion_macro_step")
    checked = violations = saturated_excluded = 0
    worst_entry = worst_cert = -1
    for r in (rows or []):
        try:
            if int(r.get("actuator_saturated_periods", 0) or 0) > 0:
                saturated_excluded += 1
                continue
            entry = r.get("first_basin_entry_step")
            cert = r.get("certified_step")
            if entry is None:
                continue
            checked += 1
            entry = int(entry)
            worst_entry = max(worst_entry, entry)
            bad = bound_entry is not None and entry > int(bound_entry)
            if cert is not None:
                cert = int(cert)
                worst_cert = max(worst_cert, cert)
                if bound_cert is not None and cert > int(bound_cert):
                    bad = True
            if bad:
                violations += 1
        except Exception:
            continue
    return {
        "rows_checked": checked,
        "rows_excluded_for_actuator_saturation": saturated_excluded,
        "analytic_basin_entry_bound": bound_entry,
        "observed_worst_basin_entry": (worst_entry if worst_entry >= 0 else None),
        "analytic_cert10_completion_bound": bound_cert,
        "observed_worst_cert10_completion": (worst_cert if worst_cert >= 0 else None),
        "violations": violations,
        "status": "PASS" if violations == 0 else "FAIL",
        "interpretation": (
            "PASS means every executed row respected the closed-form bound, so the analytic corollary "
            "and the executed campaign agree. A single FAIL row falsifies the corollary and must be "
            "published as a defect, not explained away."),
    }


def cert10_corollary_lines(rows: List[Dict[str, Any]] = None) -> List[str]:
    """Human-readable corollary block for the report."""
    c = cert10_contraction_corollary()
    out = ["CERT-10 CONTRACTION COROLLARY - CONDITIONAL SAMPLED-DATA CERTIFICATE", ""]
    out.append("The canonical controller performs sample-time feedforward cancellation plus proportional correction:")
    out.append("    u_k = sat(-f_U(x_k,t_k) + KP*(sigma-U_k)); u_k is held ZOH across RK4 stages")
    out.append("H11 reconstructs the sampled-data error as e_(k+1)=(1-KP*h)e_k+h*d_k+eps_k.")
    out.append("")
    out.append(f"KP = {c['KP']:.4g}   macro_dt = {c['macro_dt']:.4g}   micro-steps/macro = {c['micro_steps_per_macro_step']}")
    out.append(f"micro h = {c['micro_dt']:.4g}   KP*h = {c['kp_times_h']:.4g}   contractive: {c['recurrence_is_contractive']}")
    out.append(f"per-microstep contraction |1 - KP*h| = {c['per_microstep_contraction_factor']:.6f}")
    out.append(f"per-macro-step contraction           = {c['per_macro_step_contraction_factor']:.6f}")
    out.append(f"basin tolerance = {c['basin_tolerance']:.4g}   certified residual radius = {c['certified_residual_radius']:.6f}")
    out.append(f"residual envelope basis             = {c['residual_envelope_basis']}")
    out.append("")
    out.append("Worst-case error trajectory from the maximal initial error of 1.0:")
    for t in c["worst_case_trajectory"]:
        out.append(f"   after macro step {t['macro_step']}: |U - sigma| <= {t['worst_case_total_error_bound']:.6f}"
                   + ("   INSIDE BASIN TOLERANCE" if t["inside_basin_tolerance"] else ""))
    out.append("")
    out.append(f"CONDITIONAL basin entry bound by macro step {c['guaranteed_basin_entry_macro_step']} for EVERY parameter draw in the declared box.")
    out.append(f"CONDITIONAL CERT-10 completion bound by macro step {c['guaranteed_cert10_completion_macro_step']}; horizon is {c['horizon_macro_steps']}, slack {c['horizon_slack_macro_steps']} macro steps.")
    out.append(f"STATUS: {c['status']}")
    out.append("")
    for h_ in c["hypotheses"]:
        out.append(f"   HYPOTHESIS: {h_}")
    out.append("")
    if rows:
        a = cert10_corollary_row_audit(rows, c)
        out.append("EXECUTED-ROW CROSS-CHECK (this is the falsifier test, not a restatement)")
        out.append(f"   rows checked: {a['rows_checked']}   violations: {a['violations']}   status: {a['status']}")
        out.append(f"   analytic basin-entry bound {a['analytic_basin_entry_bound']} vs observed worst {a['observed_worst_basin_entry']}")
        out.append(f"   analytic CERT-10 bound {a['analytic_cert10_completion_bound']} vs observed worst {a['observed_worst_cert10_completion']}")
        out.append("")
    out.append(c["reading_rule"])
    out.append("")
    out.append(c["falsifier"])
    out.append("")
    out.append("CLAIM-STRENGTH NOTE - READ BEFORE CITING THE 500/500 FIGURE")
    out.append(
        "Because capture is guaranteed by construction under the hypotheses above, the 500/500 CERT-10 "
        "figure is a DESIGN GUARANTEE CONFIRMED BY EXECUTION, not an empirical discovery. A controller "
        "that cancels known plant dynamics and closes a proportional loop will reach its setpoint; that "
        "is textbook and this package does not present it as novel. The results that carry engineering "
        "information are the residual radius against tolerance, the command envelope against authority, "
        "the zero-saturation record, and the measurement-noise envelope in the CERT-10 NOISE BUDGET.")
    return out


def practical_stability_row_audit(rows: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Evaluate the explicit unforced residual formula on recorded row coefficients."""
    audits=[]
    for r in rows:
        R1=float(r.get("spinor_R1",0.0) or 0.0)
        R2=float(r.get("spinor_R2",0.0) or 0.0)
        # omega_B is retained inside sampled_parameters in canonical rows.
        sp=r.get("sampled_parameters") or {}
        try:
            omega=float(sp.get("omega_B"))
        except Exception:
            omega=float("nan")
        if not math.isfinite(omega) or omega<=0:
            continue
        rho=practical_stability_residual_radius(R1,R2,omega,D_bar=0.0)
        audits.append({"run_id":r.get("run_id"),"R1":R1,"R2":R2,"omega_B":omega,
                       "rho_U_unforced_formula":rho,
                       "rho_lt_basin_tolerance":bool(rho < OC_PRACTICAL_BASIN_RADIUS_TARGET)})
    passed=sum(1 for x in audits if x["rho_lt_basin_tolerance"])
    return {
        "rows_evaluated":len(audits),
        "rows_satisfying_unforced_rho_lt_tolerance":passed,
        "all_rows_satisfy":bool(audits and passed==len(audits)),
        "maximum_rho_U":max([x["rho_U_unforced_formula"] for x in audits] or [float("nan")]),
        "minimum_rho_U":min([x["rho_U_unforced_formula"] for x in audits] or [float("nan")]),
        "rows":audits,
        "claim_boundary":"Diagnostic application of the unforced residual formula to recorded coefficients; not a proof that current forced trajectories satisfy D_bar=0.",
    }
# =============================================================================
# END EXPLICIT PRACTICAL-STABILITY RESIDUAL CERTIFICATE
# =============================================================================

def stable_S_equilibrium(p: OCParameters) -> float:
    a=0.75*float(p.beta_s); b=float(p.alpha_s); c=-float(p.delta)
    if abs(a)<=EPS:
        return float(p.delta/max(p.alpha_s,EPS))
    disc=max(0.0,b*b-4.0*a*c)
    roots=[(-b+math.sqrt(disc))/(2.0*a),(-b-math.sqrt(disc))/(2.0*a)]
    stable=[r for r in roots if (-float(p.alpha_s)-1.5*float(p.beta_s)*r)<0.0]
    if not stable:
        raise RuntimeError("No stable S critical point available for composite storage")
    return float(stable[0])

def bath_lyapunov_matrix(p: OCParameters) -> np.ndarray:
    """Positive-definite P solving A_B^T P + P A_B = -I."""
    w=max(abs(float(p.omega_B)),EPS)
    damp=max(w/max(abs(float(p.Q_B)),EPS),EPS)
    key=(round(w,14),round(damp,14))
    if key in _OC_BATH_LYAP_CACHE:
        return _OC_BATH_LYAP_CACHE[key]
    p12=1.0/(2.0*w*w)
    p22=(p12+0.5)/damp
    p11=damp*p12+w*w*p22
    P=np.array([[p11,p12],[p12,p22]],dtype=float)
    if float(np.min(np.linalg.eigvalsh(P)))<=0.0:
        raise RuntimeError("Bath Lyapunov matrix is not positive definite")
    _OC_BATH_LYAP_CACHE[key]=P
    return P

def composite_practical_lyapunov_weights(p: OCParameters) -> Dict[str,float]:
    alpha_s=max(float(p.alpha_s),EPS)
    beta_s=max(float(p.beta_s),EPS)
    mu=max(float(p.mu),EPS)
    alpha_E=max(float(p.alpha_E if p.alpha_E is not None else p.alpha),EPS)
    lambda_I=max(float(p.lambda_I),EPS)
    key=tuple(round(float(x),14) for x in (
        p.omega_B,p.Q_B,p.gamma_c,p.delta,p.alpha_s,p.beta_s,p.mu,alpha_E,lambda_I
    ))
    if key in _OC_COMPOSITE_WEIGHT_CACHE:
        return _OC_COMPOSITE_WEIGHT_CACHE[key]
    P=bath_lyapunov_matrix(p)
    G=np.array([0.0,float(p.gamma_c)*float(p.delta)],dtype=float)
    pg2=float((P@G)@(P@G))
    S_floor=float(-alpha_s/(3.0*beta_s))
    m_floor=float(alpha_s/2.0)
    eta_S_target=0.25
    wS=float((pg2+eta_S_target)/(m_floor*m_floor))
    out={
        "a_U":1.0,"b_W":1.0/(2.0*mu),"c_E":1.0/alpha_E,
        "w_I":1.0/lambda_I,"w_S":wS,"d_B":1.0,
        "S_floor":S_floor,"m_floor":m_floor,"eta_S_target":eta_S_target,
        "bath_PG_norm_sq":pg2,
    }
    _OC_COMPOSITE_WEIGHT_CACHE[key]=out
    return out

def composite_practical_lyapunov_value(state: OCState, p: OCParameters, target_sign: int) -> Dict[str,float]:
    sigma=float(+1 if int(target_sign)>=0 else -1)
    S_star=stable_S_equilibrium(p)
    B_star=float((float(p.gamma_c)*float(p.delta)/(max(abs(float(p.omega_B)),EPS)**2))*S_star)
    P=bath_lyapunov_matrix(p)
    w=composite_practical_lyapunov_weights(p)
    z=np.array([float(state.B)-B_star,float(state.B_dot)],dtype=float)
    e=float(state.U)-sigma
    V_U=0.5*w["a_U"]*e*e
    V_W=w["b_W"]*W_potential(state.U,p)
    V_E=0.5*w["c_E"]*float(state.E)**2
    V_S=w["w_S"]*(phi_state(float(state.S),p)-phi_state(S_star,p))
    V_I=0.5*w["w_I"]*float(state.I_U)**2
    V_B=0.5*w["d_B"]*float(z@P@z)
    return {
        "V":float(V_U+V_W+V_E+V_S+V_I+V_B),
        "V_U":float(V_U),"V_W":float(V_W),"V_E":float(V_E),
        "V_S":float(V_S),"V_I":float(V_I),"V_B":float(V_B),
        "sigma":sigma,"S_star":S_star,"B_star":B_star,
        "local_S_region":float(float(state.S)>=w["S_floor"]-1e-12),
        "S_floor":w["S_floor"],"S_weight":w["w_S"],
    }

def composite_practical_lyapunov_certificate(state: OCState, p: OCParameters, t: float,
                                             u_ctrl: float, target_sign: int) -> Dict[str,float]:
    """Exact dV plus a conservative Young/ISS upper bound on the declared local S region."""
    parts=composite_practical_lyapunov_value(state,p,target_sign)
    w=composite_practical_lyapunov_weights(p)
    sigma=parts["sigma"]; S_star=parts["S_star"]; B_star=parts["B_star"]
    P=bath_lyapunov_matrix(p)
    d=oc_derivatives(state,p,t,u_ctrl)
    e=float(state.U)-sigma
    sdev=float(state.S)-S_star
    z=np.array([float(state.B)-B_star,float(state.B_dot)],dtype=float)
    g=W_gradient_flow(state.U,p)
    W_prime=-g
    phi_prime=-F_state(state.S,p)
    dV_exact=float(
        w["a_U"]*e*float(d.U)
        +w["b_W"]*W_prime*float(d.U)
        +w["c_E"]*float(state.E)*float(d.E)
        +w["w_S"]*phi_prime*float(d.S)
        +w["w_I"]*float(state.I_U)*float(d.I_U)
        +w["d_B"]*float(z@P@np.array([float(d.B),float(d.B_dot)],dtype=float))
    )
    alpha_E=max(float(p.alpha_E if p.alpha_E is not None else p.alpha),EPS)
    lambda_I=max(float(p.lambda_I),EPS)
    r_U=float(d.U)+KP*e
    E_drive=float(p.beta_int)+float(p.beta_ext)+v_eff(state,p,t)
    I_drive=1.0-float(state.U)-float(p.sigma_1)*float(state.E)-float(p.delta)*float(state.S)
    h_U=float(d.U)-g
    gamma_U=(r_U*r_U)/(2.0*max(KP,EPS))
    gamma_E=(E_drive*E_drive)/(2.0*alpha_E*alpha_E)
    gamma_I=(I_drive*I_drive)/(2.0*lambda_I*lambda_I)
    gamma_W=0.5*w["b_W"]*(h_U*h_U)
    spin=spinor_residual_bounds(p)
    # H12 differentiates the exact chi(t)-driven vector field, so v_eff is
    # already present in E_drive. Do not count the averaging residual twice.
    gamma_avg_exact_field=0.0
    if spin["frequency_regime_high"]>0.5:
        _avg_effect=float(spin["averaging_residual_bound"])
        _avg_regime="omega_B>=1: explicit averaging envelope reported"
    else:
        _avg_effect=float(spin["ordinary_bounded_input_bound"])
        _avg_regime="omega_B<1: ordinary |v_eff|<=c input envelope reported"
    averaged_model_gamma=float((_avg_effect**2)/(2.0*alpha_E*alpha_E))
    Gamma=float(gamma_U+gamma_E+gamma_I+gamma_W+gamma_avg_exact_field)
    eta_S=float(w["w_S"]*(w["m_floor"]**2)-w["bath_PG_norm_sq"])
    negative=float(
        -(KP/2.0)*e*e
        -0.5*float(state.E)**2
        -0.5*float(state.I_U)**2
        -eta_S*sdev*sdev
        -0.25*float(z@z)
        -0.5*w["b_W"]*g*g
    )
    upper=float(negative+Gamma)
    local=bool(parts["local_S_region"]>0.5 and eta_S>0.0)
    inequality_observed=bool(local and upper+1e-10>=dV_exact)
    eta=float(min(KP/2.0,0.5,0.5,eta_S,0.25)) if local else float("nan")
    radius=float(math.sqrt(max(Gamma,0.0)/eta)) if local and eta>0.0 else float("nan")
    return {
        **parts,"dV_exact":dV_exact,"dV_upper_bound":upper,
        "bound_slack":float(upper-dV_exact),"inequality_observed":float(inequality_observed),
        "eta_S":eta_S,"eta":eta,"Gamma":Gamma,
        "instantaneous_composite_radius":radius,
        "r_U":r_U,"E_drive":E_drive,"I_drive":I_drive,"h_U":h_U,
        "gamma_U":gamma_U,"gamma_E":gamma_E,"gamma_I":gamma_I,
        "gamma_W":gamma_W,"gamma_avg_exact_field":gamma_avg_exact_field,
        "averaged_model_gamma":averaged_model_gamma,
        "averaging_regime":_avg_regime,
        **{f"spinor_{k}":float(v) for k,v in spin.items()},
    }

def rk4_step_with_u_error_audit(state: OCState, p: OCParameters, t: float, dt: float,
                                 u_hold: float, target_sign: int,
                                 raw_command: float) -> Tuple[OCState, Dict[str,float]]:
    """Exact sampled-data U-error recurrence reconstructed from the four RK4 stages."""
    sigma=float(+1 if int(target_sign)>=0 else -1)
    h=float(dt)
    y0=state_to_vec(state)
    s1=vec_to_state(y0); k1s=oc_derivatives(s1,p,t,u_hold); k1=state_to_vec(k1s)
    s2=vec_to_state(y0+0.5*h*k1); k2s=oc_derivatives(s2,p,t+0.5*h,u_hold); k2=state_to_vec(k2s)
    s3=vec_to_state(y0+0.5*h*k2); k3s=oc_derivatives(s3,p,t+0.5*h,u_hold); k3=state_to_vec(k3s)
    s4=vec_to_state(y0+h*k3); k4s=oc_derivatives(s4,p,t+h,u_hold); k4=state_to_vec(k4s)
    y1=y0+(h/6.0)*(k1+2.0*k2+2.0*k3+k4)
    nxt=vec_to_state(y1)
    f1=raw_drift_U(s1,p,t); f2=raw_drift_U(s2,p,t+0.5*h)
    f3=raw_drift_U(s3,p,t+0.5*h); f4=raw_drift_U(s4,p,t+h)
    fbar=float((f1+2.0*f2+2.0*f3+f4)/6.0)
    e0=float(state.U-sigma); e1=float(nxt.U-sigma)
    q_signed=float(1.0-KP*h); q=abs(q_signed)
    saturation_residual=float(u_hold-raw_command)
    drift_residual=float(fbar-f1)
    residual=float(drift_residual+saturation_residual)
    eps=float(e1-(q_signed*e0+h*residual))
    radius=float((h*abs(residual)+abs(eps))/max(1.0-q,EPS)) if q<1.0 else float("inf")
    return nxt,{
        "h11_q":float(q),"h11_residual":float(residual),
        "h11_residual_abs":float(abs(residual)),
        "h11_reconstruction_error":float(eps),
        "h11_reconstruction_error_abs":float(abs(eps)),
        "h11_u_radius":float(radius),"h11_error_pre":e0,"h11_error_post":e1,
    }


def oc_derivatives(state: OCState, p: OCParameters, t: float, u_ctrl: float = 0.0) -> OCState:
    """Grandmaster six-state derivative with bounded exogenous U actuation."""
    v_t = v_eff(state, p, t)
    alpha_E = float(p.alpha_E if p.alpha_E is not None else p.alpha)
    dE = (-alpha_E * state.E) + p.beta_int + p.beta_ext + v_t
    safe_Emax = max(p.E_max, 1e-6)

    if GRANDMASTER_SYMMETRIC_CORE:
        dU = W_gradient_flow(state.U, p) - (dE / safe_Emax) - (float(p.lambda_U) * state.U)
    else:
        alpha_U = float(p.alpha_U if p.alpha_U is not None else p.alpha)
        dU = (alpha_U * (1.0 - state.U)) - (dE / safe_Emax) - (p.k * state.U * (1.0 - state.U))
    dU += float(u_ctrl)

    dI_U = ((1.0 - state.U) - (p.sigma_1 * state.E) - (p.delta * state.S)
            - (float(p.lambda_I) * state.I_U))
    dS = F_state(state.S, p)
    dB = state.B_dot
    dB_dot = (
        (p.gamma_c * p.delta * state.S)
        - (p.omega_B / max(p.Q_B, EPS)) * state.B_dot
        - ((p.omega_B ** 2) * state.B)
    )
    return OCState(E=dE, U=dU, I_U=dI_U, S=dS, B=dB, B_dot=dB_dot)

def raw_drift_U(state: OCState, p: OCParameters, t: float) -> float:
    """Uncontrolled U drift used by the bounded feedforward controller."""
    return float(oc_derivatives(state, p, t, 0.0).U)

def state_to_vec(s: OCState) -> np.ndarray:
    return np.array([s.E, s.U, s.I_U, s.S, s.B, s.B_dot], dtype=float)

def vec_to_state(v: np.ndarray) -> OCState:
    return OCState(E=float(v[0]), U=float(v[1]), I_U=float(v[2]), S=float(v[3]), B=float(v[4]), B_dot=float(v[5]))


def rk4_step(state: OCState, p: OCParameters, t: float, dt: float, u_hold: float = 0.0) -> OCState:
    """Classical RK4 with one exogenous control command held across all four stages."""
    y0 = state_to_vec(state)
    k1 = state_to_vec(oc_derivatives(vec_to_state(y0), p, t, u_hold))
    k2 = state_to_vec(oc_derivatives(vec_to_state(y0 + 0.5 * dt * k1), p, t + 0.5 * dt, u_hold))
    k3 = state_to_vec(oc_derivatives(vec_to_state(y0 + 0.5 * dt * k2), p, t + 0.5 * dt, u_hold))
    k4 = state_to_vec(oc_derivatives(vec_to_state(y0 + dt * k3), p, t + dt, u_hold))
    y1 = y0 + (dt / 6.0) * (k1 + 2.0 * k2 + 2.0 * k3 + k4)
    return vec_to_state(y1)

def bath_discrete_residual(previous: OCState, current: OCState, following: OCState, p: OCParameters, h: float) -> float:
    """Execute Piece I line (8) as a finite-difference companion audit.

    Line (7) remains the bath evolution law. This function evaluates the
    backward-damped second-difference residual on the generated trajectory:

        D2_h B[n] + (omega_B/Q_B) Dm_h B[n] + omega_B^2 B[n]
        - gamma_c*delta*S[n].

    A small residual supports numerical consistency. It does not create a
    second bath state and therefore cannot overwrite the RK4 bath evolution.
    """
    h = float(h)
    if h <= 0.0:
        raise ValueError("bath residual step h must be positive")
    d2 = (float(following.B) - 2.0 * float(current.B) + float(previous.B)) / (h * h)
    dm = (float(current.B) - float(previous.B)) / h
    return float(
        d2
        + (float(p.omega_B) / max(float(p.Q_B), EPS)) * dm
        + (float(p.omega_B) ** 2) * float(current.B)
        - float(p.gamma_c) * float(p.delta) * float(current.S)
    )



def hybrid_microstep_operator(
    state: OCState,
    p: OCParameters,
    t: float,
    dt: float,
    *,
    regulation_enabled: bool,
    locked_basin_sign: int,
    regulation_gain: float,
) -> Tuple[OCState, int, Dict[str, float]]:
    """One canonical sampled-data step with bounded derivative-level FF+P actuation.

    No canonical path assigns U after integration. The same pre-state is also
    advanced once with u=0 to expose the actuator contribution in the evidence.
    """
    sign = int(locked_basin_sign)
    if sign not in (-1, +1):
        sign = nearest_basin_sign(float(state.U))
    target = float(sign)

    uncontrolled = rk4_step(state, p, t, dt, 0.0)
    if not regulation_enabled:
        return uncontrolled, sign, {
            "continuous_U": float(uncontrolled.U),
            "projected_U": float(uncontrolled.U),
            "controlled_U": float(uncontrolled.U),
            "regulation_delta": 0.0,
            "regulation_gain": 0.0,
            "actuator_command": 0.0,
            "actuator_saturated": 0.0,
            "invariance_intervention": 0.0,
            "control_mode": GRANDMASTER_CONTROL_MODE,
        }

    drift_u = raw_drift_U(state, p, t)
    error = target - float(state.U)
    raw_command = (-drift_u) + KP * error
    u_cmd = float(max(-U_AUTHORITY, min(U_AUTHORITY, raw_command)))
    composite_audit = composite_practical_lyapunov_certificate(state,p,t,u_cmd,sign)
    controlled, h11_audit = rk4_step_with_u_error_audit(state,p,t,dt,u_cmd,sign,raw_command)
    composite_post = composite_practical_lyapunov_value(controlled,p,sign)
    composite_audit["V_post"] = float(composite_post["V"])
    composite_audit["delta_V_rk4"] = float(composite_post["V"]-composite_audit["V"])
    delta_u = float(controlled.U - uncontrolled.U)
    saturated = float(abs(raw_command) > U_AUTHORITY + EPS)

    return controlled, sign, {
        "continuous_U": float(uncontrolled.U),
        "projected_U": float(controlled.U),
        "controlled_U": float(controlled.U),
        "regulation_delta": delta_u,
        "regulation_gain": float(abs(u_cmd) / max(U_AUTHORITY, EPS)),
        "actuator_command": float(u_cmd),
        "actuator_saturated": saturated,
        "invariance_intervention": saturated,
        "control_mode": GRANDMASTER_CONTROL_MODE,
        **h11_audit,
        **{f"h12_{k}":v for k,v in composite_audit.items()},
    }

class OCOperatorStop(RuntimeError):
    """Raised when the authenticated operator kill switch is active."""


_OC_KILL_SWITCH_FILE = ""


def _oc_runtime_stop_requested() -> bool:
    """Return True when the environment or configured sentinel requests stop.

    Supported operator controls:
      * OC_KILL_SWITCH=1|true|yes|on|stop
      * --kill-switch-file PATH (or OC_KILL_SWITCH_FILE) when PATH exists

    The check is evaluated before each Monte Carlo trajectory and each RK4
    microstep. Normal mathematical behavior is unchanged while the switch is off.
    """
    flag = str(os.environ.get("OC_KILL_SWITCH", "")).strip().lower()
    if flag in {"1", "true", "yes", "on", "stop", "halt", "kill"}:
        return True
    path_text = str(_OC_KILL_SWITCH_FILE or os.environ.get("OC_KILL_SWITCH_FILE", "")).strip()
    if path_text:
        try:
            return Path(path_text).expanduser().exists()
        except Exception:
            return False
    return False


def _oc_assert_runtime_enabled() -> None:
    if _oc_runtime_stop_requested():
        raise OCOperatorStop(
            "Authenticated operator kill switch is active; execution stopped before further commands were computed."
        )


def macro_step(
    state: OCState,
    p: OCParameters,
    t0: float,
    regulation_enabled: bool = True,
    locked_basin_sign: int = 0,
    *,
    micro_steps: int = MICRO_STEPS_PER_STEP,
    macro_dt: float = MACRO_DT,
    macro_regulation_gain: float = MACRO_BASIN_REGULATION_GAIN,
) -> Tuple[OCState, float, Dict[str, float], int]:
    """Execute one macro interval through the explicit hybrid operator.

    RuntimeConfig values are passed into this function by the canonical Monte
    Carlo path, making microstep count, macro duration, and regulation gain
    authoritative instead of merely serialized metadata.
    """
    micro_steps = int(micro_steps)
    if micro_steps <= 0:
        raise ValueError("micro_steps must be positive")
    macro_dt = float(macro_dt)
    if macro_dt <= 0.0:
        raise ValueError("macro_dt must be positive")
    micro_dt = macro_dt / micro_steps
    macro_regulation_gain = float(macro_regulation_gain)
    if not (0.0 <= macro_regulation_gain <= 1.0):
        raise ValueError("macro_regulation_gain must lie in [0,1]")
    micro_gain = 1.0 - (1.0 - macro_regulation_gain) ** (1.0 / micro_steps)

    t = float(t0)
    s = state
    force_abs_integral = 0.0
    force_sq_integral = 0.0
    force_peak = 0.0
    regulation_abs_total = 0.0
    regulation_peak = 0.0
    regulation_gain_peak = 0.0
    invariance_interventions = 0
    actuator_abs_integral = 0.0
    actuator_sq_integral = 0.0
    actuator_peak = 0.0
    actuator_saturated_periods = 0
    h11_residual_peak = 0.0
    h11_reconstruction_error_peak = 0.0
    h11_u_radius_peak = 0.0
    h12_controlled_microsteps = 0
    h12_local_region_microsteps = 0
    h12_inequality_observed_microsteps = 0
    h12_gamma_peak = 0.0
    h12_eta_min = None
    h12_radius_peak = 0.0
    h12_slack_min = None
    h12_delta_V_peak = 0.0
    spinor_R1_peak = 0.0
    spinor_R2_peak = 0.0
    spinor_residual_bound_peak = 0.0
    bath_residual_abs_total = 0.0
    bath_residual_sq_total = 0.0
    bath_residual_peak = 0.0
    bath_residual_count = 0
    lock_sign = int(locked_basin_sign)
    previous_bath_state: Optional[OCState] = None

    for _ in range(micro_steps):
        _oc_assert_runtime_enabled()
        force_now = float(v_eff(s, p, t))
        force_abs_integral += abs(force_now) * micro_dt
        force_sq_integral += (force_now ** 2) * micro_dt
        force_peak = max(force_peak, abs(force_now))

        current_before = s
        s, lock_sign, operator_metrics = hybrid_microstep_operator(
            current_before, p, t, micro_dt,
            regulation_enabled=bool(regulation_enabled),
            locked_basin_sign=lock_sign,
            regulation_gain=micro_gain,
        )

        regulation_delta = float(operator_metrics["regulation_delta"])
        regulation_abs_total += abs(regulation_delta)
        regulation_peak = max(regulation_peak, abs(regulation_delta))
        regulation_gain_peak = max(regulation_gain_peak, float(operator_metrics["regulation_gain"]))
        invariance_interventions += int(operator_metrics["invariance_intervention"])
        _u_cmd = float(operator_metrics.get("actuator_command", 0.0))
        actuator_abs_integral += abs(_u_cmd) * micro_dt
        actuator_sq_integral += (_u_cmd ** 2) * micro_dt
        actuator_peak = max(actuator_peak, abs(_u_cmd))
        actuator_saturated_periods += int(bool(operator_metrics.get("actuator_saturated", 0.0)))
        h11_residual_peak=max(h11_residual_peak,float(operator_metrics.get("h11_residual_abs",0.0)))
        h11_reconstruction_error_peak=max(h11_reconstruction_error_peak,float(operator_metrics.get("h11_reconstruction_error_abs",0.0)))
        h11_u_radius_peak=max(h11_u_radius_peak,float(operator_metrics.get("h11_u_radius",0.0)))
        if regulation_enabled:
            h12_controlled_microsteps += 1
            _local=bool(float(operator_metrics.get("h12_local_S_region",0.0))>0.5)
            _ineq=bool(float(operator_metrics.get("h12_inequality_observed",0.0))>0.5)
            h12_local_region_microsteps += int(_local)
            h12_inequality_observed_microsteps += int(_ineq)
            h12_gamma_peak=max(h12_gamma_peak,float(operator_metrics.get("h12_Gamma",0.0)))
            _eta=float(operator_metrics.get("h12_eta",float("nan")))
            if math.isfinite(_eta) and _eta>0:
                h12_eta_min=_eta if h12_eta_min is None else min(h12_eta_min,_eta)
            _rad=float(operator_metrics.get("h12_instantaneous_composite_radius",float("nan")))
            if math.isfinite(_rad):
                h12_radius_peak=max(h12_radius_peak,_rad)
            _sl=float(operator_metrics.get("h12_bound_slack",float("nan")))
            if math.isfinite(_sl):
                h12_slack_min=_sl if h12_slack_min is None else min(h12_slack_min,_sl)
            h12_delta_V_peak=max(h12_delta_V_peak,abs(float(operator_metrics.get("h12_delta_V_rk4",0.0))))
            spinor_R1_peak=max(spinor_R1_peak,float(operator_metrics.get("h12_spinor_R1",0.0)))
            spinor_R2_peak=max(spinor_R2_peak,float(operator_metrics.get("h12_spinor_R2",0.0)))
            spinor_residual_bound_peak=max(spinor_residual_bound_peak,float(operator_metrics.get("h12_spinor_averaging_residual_bound",0.0)))

        if previous_bath_state is not None:
            residual = bath_discrete_residual(previous_bath_state, current_before, s, p, micro_dt)
            bath_residual_abs_total += abs(residual)
            bath_residual_sq_total += residual * residual
            bath_residual_peak = max(bath_residual_peak, abs(residual))
            bath_residual_count += 1
        previous_bath_state = current_before
        t += micro_dt

    return s, t, {
        "v_eff_abs_integral": float(force_abs_integral),
        "v_eff_sq_integral": float(force_sq_integral),
        "v_eff_peak": float(force_peak),
        "basin_regulation_abs_total": float(regulation_abs_total),
        "basin_regulation_peak": float(regulation_peak),
        "basin_regulation_gain_peak": float(regulation_gain_peak),
        "basin_invariance_interventions": int(invariance_interventions),
        "bath_discrete_residual_abs_total": float(bath_residual_abs_total),
        "bath_discrete_residual_sq_total": float(bath_residual_sq_total),
        "bath_discrete_residual_peak": float(bath_residual_peak),
        "bath_discrete_residual_count": int(bath_residual_count),
        "actuator_abs_integral": float(actuator_abs_integral),
        "actuator_sq_integral": float(actuator_sq_integral),
        "actuator_peak": float(actuator_peak),
        "actuator_saturated_periods": int(actuator_saturated_periods),
        "h11_residual_peak": float(h11_residual_peak),
        "h11_reconstruction_error_peak": float(h11_reconstruction_error_peak),
        "h11_u_radius_peak": float(h11_u_radius_peak),
        "h12_controlled_microsteps": int(h12_controlled_microsteps),
        "h12_local_region_microsteps": int(h12_local_region_microsteps),
        "h12_inequality_observed_microsteps": int(h12_inequality_observed_microsteps),
        "h12_gamma_peak": float(h12_gamma_peak),
        "h12_eta_min": h12_eta_min,
        "h12_radius_peak": float(h12_radius_peak),
        "h12_slack_min": h12_slack_min,
        "h12_delta_V_peak": float(h12_delta_V_peak),
        "spinor_R1_peak": float(spinor_R1_peak),
        "spinor_R2_peak": float(spinor_R2_peak),
        "spinor_residual_bound_peak": float(spinor_residual_bound_peak),
        "control_mode": GRANDMASTER_CONTROL_MODE,
        "symmetric_bistable_core": bool(GRANDMASTER_SYMMETRIC_CORE),
        "micro_steps_executed": int(micro_steps),
        "micro_dt_executed": float(micro_dt),
        "micro_regulation_gain_executed": float(micro_gain),
    }, int(lock_sign)

BASIN_CENTERS: Tuple[float, float] = (+1.0, -1.0)
BASIN_TOL: float = 0.10

# ==========================================================================
# RESEARCH SWITCHES - ALL DEFAULT OFF
# --------------------------------------------------------------------------
# The canonical eight-line Omni-Compass form and every declared constant are
# UNCHANGED and are what execute by default. Nothing below alters the canonical
# mechanism unless the operator sets the corresponding environment variable.
# These exist so the owner can run the diagnostic experiments personally rather
# than take anyone's word for the result.
#
#   OC_RESEARCH_BISTABLE=1
#       Line (2) only. Substitutes a Z2-symmetric pitchfork coherence law,
#       dU = (kappa + k)(U - U^3) - (Edot/E_max)*U, in place of the canonical
#       line (2). Purpose: test whether a second basin exists in the field
#       itself. Canonical line (2) is restored the moment this is unset.
#
#   OC_RESEARCH_ACCEPT_TOL=0.05
#       Scoring only. Judges basin membership at a tolerance strictly tighter
#       than the 0.10 control band that R_basin defends, so a state parked at
#       the band edge does not score as in-basin. Unset => scoring at 0.10,
#       exactly as declared in the symbol chart.
#
#   OC_RESEARCH_CBF=1
#       Operator R_basin only. Substitutes a minimum-norm Control Barrier
#       Function filter with hard authority bound U_MAX_STEP. Purpose: measure
#       what the canonical adaptive regulator achieves when its gain is capped.
#       Canonical R_basin is restored the moment this is unset.
#
#   OC_CORE_LOCK_STRICT=1
#       Restores hard-fail on canonical core hash mismatch.
# ==========================================================================
import os as _oc_os
OC_RESEARCH_BISTABLE: bool = str(_oc_os.environ.get("OC_RESEARCH_BISTABLE", "")).strip().lower() in ("1", "true", "yes", "on")
OC_RESEARCH_CBF: bool = str(_oc_os.environ.get("OC_RESEARCH_CBF", "")).strip().lower() in ("1", "true", "yes", "on")
try:
    ACCEPT_TOL: float = float(_oc_os.environ.get("OC_RESEARCH_ACCEPT_TOL", BASIN_TOL))
except (TypeError, ValueError):
    ACCEPT_TOL = BASIN_TOL
if not (0.0 < ACCEPT_TOL <= BASIN_TOL):
    ACCEPT_TOL = BASIN_TOL
KAPPA_U: float = 1.0
U_MAX_STEP: float = 0.25
GAMMA_CBF: float = 5.0
OC_RESEARCH_MODE_ACTIVE: bool = bool(OC_RESEARCH_BISTABLE or OC_RESEARCH_CBF or (ACCEPT_TOL != BASIN_TOL))
OC_RESEARCH_FLAGS_SUMMARY: str = (
    "CANONICAL (eight-line form and all declared constants as published)"
    if not OC_RESEARCH_MODE_ACTIVE else
    "RESEARCH: " + ", ".join(filter(None, [
        "bistable-line2" if OC_RESEARCH_BISTABLE else "",
        "cbf-Rbasin" if OC_RESEARCH_CBF else "",
        f"accept_tol={ACCEPT_TOL}" if ACCEPT_TOL != BASIN_TOL else "",
    ]))
)
STABILITY_WINDOW: int = 5
CERTIFICATION_STEPS: int = 10

# Streak-start limits and completion limits are deliberately distinct.
# With macro observations available through Step 20:
#   CONVEY-5 may start at Step 16 and confirm at Step 20.
#   CERT-10 may start at Step 11 and complete at Step 20.
LATEST_CONVEYANCE_STREAK_START_STEP: int = MAX_STEPS - STABILITY_WINDOW + 1  # Step 16
LATEST_CERTIFICATION_STREAK_START_STEP: int = MAX_STEPS - CERTIFICATION_STEPS + 1  # Step 11
LATEST_CONVEYANCE_CONFIRMATION_STEP: int = MAX_STEPS  # Step 20
LATEST_CERTIFICATION_COMPLETION_STEP: int = MAX_STEPS  # Step 20

# Compatibility aliases retained for existing report and evidence surfaces.
LATEST_CONVEYABLE_ENTRY_STEP: int = LATEST_CONVEYANCE_STREAK_START_STEP
LATEST_CERTIFIABLE_ENTRY_STEP: int = LATEST_CERTIFICATION_STREAK_START_STEP

# Fail-fast protocol assertions. These execute before Monte Carlo integration.
assert MAX_STEPS == 20, 'Canonical macro-step horizon must remain Step 20.'
assert STABILITY_WINDOW == 5, 'Primary conveyance must remain CONVEY-5.'
assert CERTIFICATION_STEPS == 10, 'Primary certification must be CERT-10.'
assert LATEST_CONVEYANCE_STREAK_START_STEP == 16, 'CONVEY-5 latest streak start must be Step 16.'
assert LATEST_CERTIFICATION_STREAK_START_STEP == 11, 'CERT-10 latest streak start must be Step 11.'
assert LATEST_CONVEYANCE_CONFIRMATION_STEP == 20, 'CONVEY-5 may confirm through Step 20.'
assert LATEST_CERTIFICATION_COMPLETION_STEP == 20, 'CERT-10 may complete through Step 20.'
assert LATEST_CONVEYANCE_STREAK_START_STEP + STABILITY_WINDOW - 1 == LATEST_CONVEYANCE_CONFIRMATION_STEP
assert LATEST_CERTIFICATION_STREAK_START_STEP + CERTIFICATION_STEPS - 1 == LATEST_CERTIFICATION_COMPLETION_STEP

# Five non-overlapping accounting bands spanning the original engine's
# actual Step-0 nearest-basin distance range [0, 1] under symmetric U(0) in [-1, 1].
# These accounting bands do not change equations, parameters, or trajectories.
DISTANCE_BANDS: Tuple[Tuple[float, float, str], ...] = (
    (0.00, 0.10, "Band 1: Born in basin [0.00, 0.10]"),
    (0.10, 0.25, "Band 2: Very near (0.10, 0.25]"),
    (0.25, 0.50, "Band 3: Near-to-middle (0.25, 0.50]"),
    (0.50, 0.75, "Band 4: Far (0.50, 0.75]"),
    (0.75, 1.00, "Band 5: Farthest original starts (0.75, 1.00]"),
)

def basin_sign(U: float) -> int:
    # ACCEPT_TOL == BASIN_TOL unless the operator sets OC_RESEARCH_ACCEPT_TOL.
    if abs(U - BASIN_CENTERS[0]) <= ACCEPT_TOL:
        return +1
    if abs(U - BASIN_CENTERS[1]) <= ACCEPT_TOL:
        return -1
    return 0

def is_in_basin(U: float) -> bool:
    return basin_sign(U) != 0

def initial_distance_to_nearest_basin(U: float) -> float:
    return float(min(abs(U - center) for center in BASIN_CENTERS))

def nearest_basin_sign(U: float) -> int:
    return +1 if abs(U - BASIN_CENTERS[0]) <= abs(U - BASIN_CENTERS[1]) else -1

def distance_band_label(distance: float) -> str:
    d = float(max(0.0, distance))
    for index, (lo, hi, label) in enumerate(DISTANCE_BANDS):
        if index == 0:
            if lo <= d <= hi + EPS:
                return label
        elif lo < d <= hi + EPS:
            return label
    return DISTANCE_BANDS[-1][2]

def _oc_canonical_basin_regulation(U: float, locked_basin_sign: int, nominal_gain: float) -> Tuple[float, int, float]:
    """Drive toward and preserve the declared signed basin.

    ``locked_basin_sign`` is the supervisory target sign. In the canonical
    signed-basin run it is assigned from the Step-0 nearest basin before the
    first integration microstep. The adaptive law uses the nominal gain when
    sufficient and raises only the gain required to place or retain the state
    inside the declared basin boundary. This is a runtime control calculation,
    not a change to the eight-line Piece I differential equation or parameters.
    Returns (regulated_U, target_sign, gain_used).
    """
    sign = int(locked_basin_sign)
    if sign not in (-1, +1):
        sign = nearest_basin_sign(U)
        target = float(sign)
        gain = float(max(0.0, min(1.0, nominal_gain)))
        regulated = float(U + gain * (target - U))
        acquired = basin_sign(regulated)
        return regulated, int(acquired if acquired != 0 else 0), gain

    target = float(sign)
    lo = target - BASIN_TOL
    hi = target + BASIN_TOL
    gain = float(max(0.0, min(1.0, nominal_gain)))
    regulated = float(U + gain * (target - U))

    # If the nominal law would permit an exit, solve for the minimum gain that
    # places the state just inside the same basin boundary.
    margin = max(EPS, BASIN_TOL * 1e-9)
    if regulated > hi:
        desired = hi - margin
        denom = target - U
        if abs(denom) > EPS:
            required = (desired - U) / denom
            gain = float(max(gain, min(1.0, required)))
            regulated = float(U + gain * (target - U))
    elif regulated < lo:
        desired = lo + margin
        denom = target - U
        if abs(denom) > EPS:
            required = (desired - U) / denom
            gain = float(max(gain, min(1.0, required)))
            regulated = float(U + gain * (target - U))

    # Numerical guard only; the adaptive gain above is the governing calculation.
    regulated = float(min(hi - margin, max(lo + margin, regulated)))
    return regulated, sign, gain

MATERIAL_REGULATION_EPS: float = 1e-12

def _oc_cbf_basin_regulation(U: float, locked_basin_sign: int, nominal_gain: float) -> Tuple[float, int, float]:
    """OPT-IN DIAGNOSTIC. Bounded minimum-norm Control Barrier Function filter.

    Not the canonical R_basin. Active solely when OC_RESEARCH_CBF=1.
    Safe set h(U) = BASIN_TOL^2 - (U - sigma)^2 >= 0; minimum-norm correction,
    hard-saturated at U_MAX_STEP; zero action while the constraint holds.
    Same signature and return contract as the canonical regulator.
    """
    sign = int(locked_basin_sign)
    if sign not in (-1, +1):
        sign = nearest_basin_sign(U)
        if sign == 0:
            return float(U), 0, 0.0
        target = float(sign)
        delta = float(max(-U_MAX_STEP, min(U_MAX_STEP,
                     max(0.0, min(1.0, nominal_gain)) * (target - U))))
        regulated = float(U + delta)
        return regulated, int(basin_sign(regulated)), float(min(1.0, abs(delta) / max(abs(target - U), EPS)))
    target = float(sign)
    h = (BASIN_TOL * BASIN_TOL) - ((U - target) ** 2)
    if h >= 0.0:
        return float(U), int(sign), 0.0
    nearest = target + math.copysign(BASIN_TOL, U - target)
    delta = float(max(-U_MAX_STEP, min(U_MAX_STEP, (nearest - U) * min(1.0, GAMMA_CBF * 0.1))))
    regulated = float(U + delta)
    return regulated, int(sign), float(min(1.0, abs(delta) / max(abs(target - U), EPS)))


OC_SUPERSEDED_PROJECTION_LAW_NOTICE = (
    "SUPERSEDED PROJECTION LAW. apply_invariant_basin_regulation and the two regulators it "
    "dispatches to (_oc_canonical_basin_regulation, _oc_cbf_basin_regulation) are NOT on the "
    "canonical execution path and are called by nothing in this engine. They assign U directly "
    "after integration. That behaviour was superseded by derivative-level bounded FF+P "
    "zero-order-hold actuation in hybrid_microstep_operator, which is what actually executes and "
    "which never writes U after integration. These functions are retained for historical diff "
    "against prior releases only. They are excluded from OC_CORE_ISOLATION_SURFACES and from every "
    "claim binding. If any future edit calls them from macro_step or hybrid_microstep_operator, "
    "the report's 'no post-RK4 state overwrite' statement becomes false and must be withdrawn."
)


def apply_invariant_basin_regulation(U: float, locked_basin_sign: int, nominal_gain: float) -> Tuple[float, int, float]:
    """NOT ON THE CANONICAL PATH. Superseded projection law. Never called.

    ###################################################################
    #  AUDIT FIX M2b - QUARANTINED                                    #
    #  This function ASSIGNS U AFTER INTEGRATION.  The canonical       #
    #  executed path does not, and does not call this.  See            #
    #  OC_SUPERSEDED_PROJECTION_LAW_NOTICE above.  Retained for        #
    #  historical diff only.  Do not wire this back in without         #
    #  withdrawing the 'no post-RK4 state overwrite' claim.            #
    ###################################################################
    """
    if OC_RESEARCH_CBF:
        return _oc_cbf_basin_regulation(U, locked_basin_sign, nominal_gain)
    return _oc_canonical_basin_regulation(U, locked_basin_sign, nominal_gain)


@dataclass
class RuntimeConfig:
    mc_runs: int = MONTE_CARLO_RUNS
    macro_steps: int = MAX_STEPS
    micro_steps: int = MICRO_STEPS_PER_STEP
    dt: float = MACRO_DT

    basin_centers: Tuple[float, float] = BASIN_CENTERS
    basin_tol: float = BASIN_TOL
    stability_window: int = STABILITY_WINDOW
    conveyance_cutoff_step: int = 20

    divergence_abs_limit: float = 1e6
    nonfinite_is_divergence: bool = True

    self_tuning_enabled: bool = True
    self_tune_gain: float = MACRO_BASIN_REGULATION_GAIN
    universal_basin_regulation_enabled: bool = True

    # Deployment-authority wrapper. These fields do not modify the canonical
    # differential equations. They define whether computed directives are
    # advisory, operator-supervised, autonomously authorized, or disabled.
    operation_mode: str = "autopilot"
    kill_switch_enabled: bool = True
    kill_switch_file: str = ""

    output_dir: str = "./omni-compass_outputs"

    @property
    def micro_basin_regulation_gain(self) -> float:
        if int(self.micro_steps) <= 0:
            raise ValueError("micro_steps must be positive")
        gain = float(self.self_tune_gain)
        if not (0.0 <= gain <= 1.0):
            raise ValueError("self_tune_gain must lie in [0,1]")
        return float(1.0 - (1.0 - gain) ** (1.0 / int(self.micro_steps)))

    def to_dict(self) -> Dict[str, Any]:
        return {
            "mc_runs": self.mc_runs,
            "macro_steps": self.macro_steps,
            "micro_steps": self.micro_steps,
            "dt": self.dt,
            "basin_centers": list(self.basin_centers),
            "basin_tol": self.basin_tol,
            "stability_window": self.stability_window,
            "conveyance_cutoff_step": self.conveyance_cutoff_step,
            "divergence_abs_limit": self.divergence_abs_limit,
            "nonfinite_is_divergence": self.nonfinite_is_divergence,
            "self_tuning_enabled": self.self_tuning_enabled,
            "self_tune_gain": self.self_tune_gain,
            "universal_basin_regulation_enabled": self.universal_basin_regulation_enabled,
            "micro_basin_regulation_gain": self.micro_basin_regulation_gain,
            "initial_U_distribution": "Uniform[-1, 1] (symmetric canonical basin challenge)",
            "closed_feedback_core": ["E", "U", "S"],
            "driven_observer_channels": ["I_U", "B", "B_dot"],
            "gamma_1_status": "reserved compatibility parameter; inactive in Piece I-S derivatives",
            "canonical_U_field": "mu*U*(1-U^2) - (dE/dt)/E_max - lambda_U*U",
            "canonical_control_entry": "dU/dt += sat(-raw_drift_U + KP*(sigma-U), +/- U_AUTHORITY), zero-order held",
            "canonical_control_mode": GRANDMASTER_CONTROL_MODE,
            "symmetric_bistable_core": GRANDMASTER_SYMMETRIC_CORE,
            "state_assignment_after_rk4": False,
            "u_authority": U_AUTHORITY,
            "kp": KP,
            "operation_mode": self.operation_mode,
            "kill_switch_enabled": self.kill_switch_enabled,
            "kill_switch_file": self.kill_switch_file,
            "output_dir": self.output_dir,
            "certification_steps": CERTIFICATION_STEPS,
            "latest_certifiable_entry_step": LATEST_CERTIFIABLE_ENTRY_STEP,
            "latest_certification_streak_start_step": LATEST_CERTIFICATION_STREAK_START_STEP,
            "latest_certification_completion_step": LATEST_CERTIFICATION_COMPLETION_STEP,
            "latest_conveyance_streak_start_step": LATEST_CONVEYANCE_STREAK_START_STEP,
            "latest_conveyance_confirmation_step": LATEST_CONVEYANCE_CONFIRMATION_STEP,
            "latest_conveyable_entry_step": LATEST_CONVEYABLE_ENTRY_STEP,
            "distance_band_accounting": [
                {"min": lo, "max": hi, "label": label} for lo, hi, label in DISTANCE_BANDS
            ],
        }

@dataclass
class RunResult:
    run_id: int

    # Step-0 and five-band accounting fields.
