def _is_divergent(state: OCState, cfg: RuntimeConfig) -> bool:
    vals = [state.E, state.U, state.I_U, state.S, state.B, state.B_dot]
    if cfg.nonfinite_is_divergence and (not all(math.isfinite(v) for v in vals)):
        return True
    return any(abs(v) > cfg.divergence_abs_limit for v in vals)

def _classify_regime(U_hist: List[float]) -> str:
    if len(U_hist) < 3:
        return "stalled"
    dU = [U_hist[i] - U_hist[i - 1] for i in range(1, len(U_hist))]
    flips = 0
    for i in range(1, len(dU)):
        if dU[i - 1] == 0.0:
            continue
        if (dU[i - 1] > 0 and dU[i] < 0) or (dU[i - 1] < 0 and dU[i] > 0):
            flips += 1
    spread = float(np.std(U_hist)) if len(U_hist) > 1 else 0.0
    if flips <= 1 and spread < 0.15:
        return "monotone"
    if flips <= 6 and spread < 0.35:
        return "oscillatory"
    return "chaotic"

def _basin_label(sign: int) -> str:
    return {+1: "+1", -1: "-1", 0: "none"}.get(sign, "none")

def _pct(n: int, d: int) -> float:
    return (100.0 * n / d) if d else 0.0

def _safe_mean(xs: List[float]) -> float:
    return float(sum(xs) / len(xs)) if xs else 0.0

def _safe_stdev(xs: List[float]) -> float:
    if len(xs) < 2:
        return 0.0
    m = _safe_mean(xs)
    return float(math.sqrt(sum((x - m) ** 2 for x in xs) / (len(xs) - 1)))

def _init_param_stats() -> Dict[str, Dict[str, float]]:
    stats: Dict[str, Dict[str, float]] = {}
    for k in PARAMETER_RANGES.keys():
        stats[k] = {"min": float("inf"), "max": float("-inf"), "sum": 0.0, "sum_sq": 0.0, "n": 0.0}
    return stats

def _update_param_stats(stats: Dict[str, Dict[str, float]], p: OCParameters) -> None:
    pd = p.__dict__
    for k, v in pd.items():
        s = stats[k]
        s["min"] = min(s["min"], v)
        s["max"] = max(s["max"], v)
        s["sum"] += v
        s["sum_sq"] += (v * v)
        s["n"] += 1.0

def _finalize_param_stats(stats: Dict[str, Dict[str, float]]) -> Dict[str, Dict[str, float]]:
    out: Dict[str, Dict[str, float]] = {}
    for k, s in stats.items():
        n = s["n"]
        if n <= 0:
            out[k] = {"min": None, "mean": None, "stdev": None, "max": None}
            continue
        mean = s["sum"] / n
        var = max(0.0, (s["sum_sq"] / n) - (mean * mean))
        out[k] = {"min": float(s["min"]), "mean": float(mean), "stdev": float(math.sqrt(var)), "max": float(s["max"])}
    return out

# ---------------------------
# DUAL REPORTING (PRIMARY + RMS)
# ---------------------------

RMS_WINDOW = 12
RMS_EPSILON = 0.25
def _min_dist_to_basin(u: float) -> float:
    return float(min(abs(u - BASIN_CENTERS[0]), abs(u - BASIN_CENTERS[1])))

def _rms_last_window(u_hist: List[float]) -> Optional[float]:
    if not u_hist or len(u_hist) < RMS_WINDOW:
        return None
    d = [_min_dist_to_basin(u) for u in u_hist[-RMS_WINDOW:]]
    return float(math.sqrt(sum(x * x for x in d) / float(RMS_WINDOW)))

def _dwell_last_k(u_hist: List[float], k: int) -> bool:
    if not u_hist or len(u_hist) < k:
        return False
    signs = [basin_sign(float(u)) for u in u_hist[-k:]]
    return bool(signs and signs[0] != 0 and all(s == signs[0] for s in signs))

def apply_dual_metrics(results: List[RunResult]) -> None:
    for r in results:
        r.conveyed_primary = bool(r.conveyed)
        # CERT-10 is recorded during execution at the first qualifying same-basin streak.
        r.certified_primary = bool(r.certified_primary)

        rms = _rms_last_window(r.U_history)
        r.rms_metric = None if rms is None else float(rms)
        r.conveyed_rms = bool((rms is not None) and (rms < RMS_EPSILON))
        r.certified_rms = bool(r.conveyed_rms and _dwell_last_k(r.U_history, CERTIFICATION_STEPS))

def dual_counts(results: List[RunResult]) -> Dict[str, Any]:
    total = len(results)
    def pct(x): return (100.0 * x / total) if total else 0.0

    cp  = sum(1 for r in results if r.conveyed_primary)
    ctp = sum(1 for r in results if r.certified_primary)
    cr  = sum(1 for r in results if r.conveyed_rms)
    ctr = sum(1 for r in results if r.certified_rms)

    both = sum(1 for r in results if r.conveyed_primary and r.conveyed_rms)
    p_only = sum(1 for r in results if r.conveyed_primary and not r.conveyed_rms)
    r_only = sum(1 for r in results if (not r.conveyed_primary) and r.conveyed_rms)

    return {
        "total": total,
        "primary": {"conveyed": cp, "certified": ctp, "conveyed_pct": pct(cp), "certified_pct": pct(ctp)},
        "rms":     {"conveyed": cr, "certified": ctr, "conveyed_pct": pct(cr), "certified_pct": pct(ctr)},
        "overlap": {"both": both, "primary_only": p_only, "rms_only": r_only,
                    "both_pct": pct(both), "primary_only_pct": pct(p_only), "rms_only_pct": pct(r_only)},
        "params": {"stability_window": STABILITY_WINDOW, "rms_window": RMS_WINDOW, "rms_epsilon": RMS_EPSILON, "cert_steps": CERTIFICATION_STEPS},
    }

