# ---------------------------
# MONTE CARLO
# ---------------------------


# ---------------------------
# QUADRANT SEMANTICS (Q1-Q4)
# ---------------------------
# Q1: Initiation / Gradient Formation (not yet engaged with basin dynamics)
# Q2: Commitment / Basin Approach (engaged, attempting capture; streak building/breaking)
# Q3: Constraint / Saturation (stability achieved OR terminal failure under constraints)
# Q4: Resolution / Reconfiguration (post-run interpretation stage)
# QX: Undefined / Should-not-happen (debug guard)

def classify_quadrant_step(
    *,
    step: int,
    born_in_basin: bool,
    ever_in_basin: bool,
    in_basin_now: bool,
    consecutive_in_basin: int,
    stability_window: int,
    termination_reason: str,
) -> str:
    """Return quadrant label for a macro step.

    Q4 is recorded outside the macro loop (post-run).
    """
    # Terminal constraint events
    if termination_reason in ("divergence", "macro_exhaustion"):
        return "Q3"

    # Born stable is immediate constraint satisfaction
    if step == 1 and born_in_basin and in_basin_now:
        return "Q3"

    # Stability achieved on this step
    if in_basin_now and consecutive_in_basin >= stability_window:
        return "Q3"

    # Not yet basin-engaged: initiation
    if (not ever_in_basin) and (not in_basin_now):
        return "Q1"

    # Otherwise: engaged with basin dynamics
    return "Q2"
def run_monte_carlo(cfg: RuntimeConfig, seed: int) -> Tuple[List[RunResult], Dict[str, Any]]:
    rng = np.random.default_rng(int(seed) % (2**63 - 1))
    rng_fingerprint = hashlib.sha256(repr(rng.bit_generator.state).encode("utf-8")).hexdigest()[:16]

    results: List[RunResult] = []
    param_stats = _init_param_stats()

    for run_id in range(cfg.mc_runs):
        _oc_assert_runtime_enabled()
        if run_id and (run_id % 5 == 0):
            logging.info("Monte Carlo progress: %s/%s", run_id, cfg.mc_runs)

        # Original initialization and original per-run parameter sampling.
        s = sample_initial_state(rng)
        p = sample_parameters(rng)
        _update_param_stats(param_stats, p)
        t = 0.0

        rr = RunResult(run_id=run_id)
        rr.sampled_parameters = {k: float(v) for k, v in p.__dict__.items()}
        _spin=spinor_residual_bounds(p)
        rr.spinor_R1=float(_spin["R1"])
        rr.spinor_R2=float(_spin["R2"])
        rr.spinor_residual_bound=float(_spin["averaging_residual_bound"])
        rr.spinor_frequency_regime_high=bool(_spin["frequency_regime_high"]>0.5)
        rr.initial_U = float(s.U)
        rr.initial_distance_to_basin = initial_distance_to_nearest_basin(s.U)
        rr.initial_nearest_basin = nearest_basin_sign(s.U)
        rr.initial_distance_band = distance_band_label(rr.initial_distance_to_basin)
        rr.U_history.append(float(s.U))

        # Step 0 permanently determines the born-in-basin category only.
        # Category never disables the universal Omni-Compass regulation law.
        born_in_basin = is_in_basin(s.U)
        born_sign = basin_sign(s.U) if born_in_basin else 0
        rr.born_stable = bool(born_in_basin)
        rr.self_tuning_applied = bool(
            (not born_in_basin)
            and cfg.universal_basin_regulation_enabled
            and cfg.self_tuning_enabled
        )
        rr.universal_basin_regulation_applied = bool(cfg.universal_basin_regulation_enabled)
        rr.rescued = False
        rr.first_basin_entry_step = 0 if born_in_basin else None

        # The Step-0 nearest signed basin is the declared supervisory target.
        # This target assignment is symmetric: U0 < 0 selects -1, U0 >= 0
        # selects +1 (with the exact tie assigned to +1 by nearest_basin_sign).
        # Born-in-basin remains a taxonomy category only; it does not determine
        # whether the negative side is available. The same bounded derivative-level FF+P controller drives every trajectory toward its declared target. No state is assigned after RK4.
        basin_regulation_active = bool(
            cfg.universal_basin_regulation_enabled
            and (born_in_basin or cfg.self_tuning_enabled)
        )
        locked_basin_sign = int(rr.initial_nearest_basin)

        # Step 0 counts as observation one for a born-in-basin run.
        convey_streak_sign = born_sign
        convey_streak = 1 if born_in_basin else 0

        # CERT-10 uses the same consecutive same-basin accounting.
        certification_sign = born_sign
        certification_streak = 1 if born_in_basin else 0
        rr.max_consecutive_same_basin = 1 if born_in_basin else 0

        ever_in_basin = bool(born_in_basin)
        saw_divergence = False

        for step in range(1, cfg.macro_steps + 1):
            s, t, force_metrics, locked_basin_sign = macro_step(
                s, p, t,
                regulation_enabled=basin_regulation_active,
                locked_basin_sign=locked_basin_sign,
                micro_steps=cfg.micro_steps,
                macro_dt=cfg.dt,
                macro_regulation_gain=cfg.self_tune_gain,
            )
            rr.v_eff_abs_integral += float(force_metrics["v_eff_abs_integral"])
            rr.v_eff_sq_integral += float(force_metrics["v_eff_sq_integral"])
            rr.v_eff_peak = max(rr.v_eff_peak, float(force_metrics["v_eff_peak"]))
            macro_reg_abs = float(force_metrics["basin_regulation_abs_total"])
            macro_reg_peak = float(force_metrics["basin_regulation_peak"])
            rr.basin_regulation_abs_total += macro_reg_abs
            rr.basin_regulation_peak = max(rr.basin_regulation_peak, macro_reg_peak)
            rr.basin_regulation_gain_peak = max(
                rr.basin_regulation_gain_peak,
                float(force_metrics["basin_regulation_gain_peak"]),
            )
            rr.basin_invariance_interventions += int(force_metrics["basin_invariance_interventions"])
            rr.actuator_abs_integral += float(force_metrics.get("actuator_abs_integral", 0.0))
            rr.actuator_sq_integral += float(force_metrics.get("actuator_sq_integral", 0.0))
            rr.actuator_peak = max(rr.actuator_peak, float(force_metrics.get("actuator_peak", 0.0)))
            rr.actuator_saturated_periods += int(force_metrics.get("actuator_saturated_periods", 0))
            rr.h11_residual_peak=max(rr.h11_residual_peak,float(force_metrics.get("h11_residual_peak",0.0)))
            rr.h11_reconstruction_error_peak=max(rr.h11_reconstruction_error_peak,float(force_metrics.get("h11_reconstruction_error_peak",0.0)))
            rr.h11_u_radius_peak=max(rr.h11_u_radius_peak,float(force_metrics.get("h11_u_radius_peak",0.0)))
            rr.h12_controlled_microsteps += int(force_metrics.get("h12_controlled_microsteps",0))
            rr.h12_local_region_microsteps += int(force_metrics.get("h12_local_region_microsteps",0))
            rr.h12_inequality_observed_microsteps += int(force_metrics.get("h12_inequality_observed_microsteps",0))
            rr.h12_gamma_peak=max(rr.h12_gamma_peak,float(force_metrics.get("h12_gamma_peak",0.0)))
            _eta=force_metrics.get("h12_eta_min")
            if _eta is not None and math.isfinite(float(_eta)):
                rr.h12_eta_min=float(_eta) if rr.h12_eta_min is None else min(rr.h12_eta_min,float(_eta))
            rr.h12_radius_peak=max(rr.h12_radius_peak,float(force_metrics.get("h12_radius_peak",0.0)))
            _sl=force_metrics.get("h12_slack_min")
            if _sl is not None and math.isfinite(float(_sl)):
                rr.h12_slack_min=float(_sl) if rr.h12_slack_min is None else min(rr.h12_slack_min,float(_sl))
            rr.h12_delta_V_peak=max(rr.h12_delta_V_peak,float(force_metrics.get("h12_delta_V_peak",0.0)))
            rr.bath_discrete_residual_abs_total += float(force_metrics["bath_discrete_residual_abs_total"])
            rr.bath_discrete_residual_sq_total += float(force_metrics["bath_discrete_residual_sq_total"])
            rr.bath_discrete_residual_peak = max(
                rr.bath_discrete_residual_peak,
                float(force_metrics["bath_discrete_residual_peak"]),
            )
            rr.bath_discrete_residual_count += int(force_metrics["bath_discrete_residual_count"])
            # Preserve self-tuning accounting for non-born trajectories only.
            if not born_in_basin:
                rr.self_tune_abs_total += macro_reg_abs
                rr.self_tune_peak = max(rr.self_tune_peak, macro_reg_peak)

            rr.steps_taken = step
            rr.U_history.append(float(s.U))

            sign_now = basin_sign(s.U)
            in_basin_now = sign_now != 0
            if in_basin_now:
                ever_in_basin = True
                if rr.first_basin_entry_step is None:
                    rr.first_basin_entry_step = step

            if _is_divergent(s, cfg):
                saw_divergence = True
                rr.termination_reason = "divergence"

            # Same-basin consecutive accounting for CONVEY-5.
            if in_basin_now:
                if sign_now == convey_streak_sign:
                    convey_streak += 1
                else:
                    convey_streak_sign = sign_now
                    convey_streak = 1
            else:
                convey_streak_sign = 0
                convey_streak = 0

            # Same-basin completed-macro accounting for CERT-10.
            if in_basin_now:
                if sign_now == certification_sign:
                    certification_streak += 1
                else:
                    certification_sign = sign_now
                    certification_streak = 1
            else:
                certification_sign = 0
                certification_streak = 0

            rr.max_consecutive_same_basin = max(
                rr.max_consecutive_same_basin,
                convey_streak,
                certification_streak,
            )

            # CONVEY-5 applies to every category. For born runs, Step 0 is
            # observation one, so Steps 0, 1, 2, 3, and 4 confirm conveyance.
            if (not rr.conveyed) and convey_streak >= cfg.stability_window:
                rr.conveyed = True
                rr.conveyed_step = step - cfg.stability_window + 1
                rr.conveyance_confirmed_step = step
                rr.stable_achieved_step = step
                rr.rescued = bool((not born_in_basin) and rr.self_tune_abs_total > MATERIAL_REGULATION_EPS)
                if born_in_basin:
                    rr.termination_reason = f"born_in_basin_conveyed_{cfg.stability_window}_observation_streak"
                else:
                    rr.termination_reason = (
                        f"self_tuned_conveyed_{cfg.stability_window}_step_streak"
                        if rr.rescued else
                        f"natural_unregulated_conveyed_{cfg.stability_window}_step_streak"
                    )

            # CERT-10 is independent of born/self-tuned category and requires ten
            # completed same-basin macrosteps. The first three are contained within eight.
            if (not rr.certified_primary) and certification_streak >= CERTIFICATION_STEPS:
                rr.certified_primary = True
                rr.certification_streak_start_step = step - CERTIFICATION_STEPS + 1
                rr.certified_step = step

            q = classify_quadrant_step(
                step=step,
                born_in_basin=born_in_basin,
                ever_in_basin=ever_in_basin,
                in_basin_now=in_basin_now,
                consecutive_in_basin=convey_streak,
                stability_window=cfg.stability_window,
                termination_reason="divergence" if saw_divergence else "",
            )
            rr.quadrant_history.append(q)
            rr.quadrant_counts[q] = rr.quadrant_counts.get(q, 0) + 1

        # Full 20-macro horizon is always executed. Classification is post-run accounting.
        if saw_divergence:
            rr.termination_reason = "divergence"
        elif rr.conveyed:
            rr.termination_reason = "completed_full_horizon"
        else:
            rr.termination_reason = "macro_exhaustion_not_conveyed"

        rr.quadrant_history.append("Q4")
        rr.quadrant_counts["Q4"] = rr.quadrant_counts.get("Q4", 0) + 1
        rr.regime_label = _classify_regime(rr.U_history)

        rr.final_E = float(s.E)
        rr.final_U = float(s.U)
        rr.final_IU = float(s.I_U)
        rr.final_S = float(s.S)
        rr.final_B = float(s.B)
        rr.final_Bdot = float(s.B_dot)
        rr.final_basin_sign = basin_sign(rr.final_U)
        rr.basin_label = _basin_label(rr.final_basin_sign)

        results.append(rr)

    exec_params: Dict[str, Any] = {
        "cfg_snapshot": cfg.to_dict(),
        "parameter_ranges": {k: {"min": float(v[0]), "max": float(v[1])} for k, v in PARAMETER_RANGES.items()},
        "sampled_parameter_summary": _finalize_param_stats(param_stats),
        "classification_protocol": {
            "born_in_basin": "Step-0 category; Step 0 counts toward CONVEY-5 and CERT-10",
            "self_tuning": "Category applied only to runs outside both basins at Step 0",
            "universal_basin_regulation": "Step-0 nearest signed-basin targeting remains active and drives every trajectory into, then preserves, its declared basin throughout all 200 RK4 microsteps",
            "conveyance_steps": STABILITY_WINDOW,
            "certification_steps": CERTIFICATION_STEPS,
            "latest_certifiable_entry_step": LATEST_CERTIFIABLE_ENTRY_STEP,
            "latest_certification_streak_start_step": LATEST_CERTIFICATION_STREAK_START_STEP,
            "latest_certification_completion_step": LATEST_CERTIFICATION_COMPLETION_STEP,
            "latest_conveyance_streak_start_step": LATEST_CONVEYANCE_STREAK_START_STEP,
            "latest_conveyance_confirmation_step": LATEST_CONVEYANCE_CONFIRMATION_STEP,
            "latest_conveyable_entry_step": LATEST_CONVEYABLE_ENTRY_STEP,
            "distance_bands": [
                {"min": lo, "max": hi, "label": label} for lo, hi, label in DISTANCE_BANDS
            ],
        },
        "rng": {
            "generator": "np.random.default_rng()",
            "bit_generator": rng.bit_generator.__class__.__name__,
            "seed": int(seed),
            "fingerprint": rng_fingerprint,
        },
        "python_verification": _python_verification_block(),
    }

    # Preserve runtime-native primary certification. RMS remains an additional lens.
    apply_dual_metrics(results)
    return results, exec_params


def _oc_canonical_population_sha256(rows: Sequence[Any]) -> str:
    """SHA-256 identity of the executed canonical Monte Carlo population.

    This digest identifies the stochastic population/output rows, not the Python
    source.  Therefore the engine SHA remains fixed across unchanged builds while
    fresh seeds/populations produce different population digests.
    """
    normalized=[]
    for _r in rows:
        if isinstance(_r,dict):
            normalized.append(dict(_r))
        elif hasattr(_r,"to_dict"):
            normalized.append(_r.to_dict())
        else:
            normalized.append(vars(_r))
    blob=json.dumps(
        normalized,sort_keys=True,separators=(",",":"),ensure_ascii=False,
        default=str,allow_nan=True
    ).encode("utf-8")
    return hashlib.sha256(blob).hexdigest()

# ---------------------------
# AGGREGATION
# ---------------------------

def aggregate_run_results(results: List[RunResult], cfg: RuntimeConfig, exec_params: Dict[str, Any]) -> Dict[str, Any]:
    n = len(results)

    conveyed = [r for r in results if r.conveyed]
    Unconveyable = [r for r in results if not r.conveyed]
    born_stable = [r for r in results if r.born_stable]
    rescued = [r for r in results if r.rescued]
    certified = [r for r in results if r.certified_primary]
    conveyed_not_certified = [r for r in results if r.conveyed and not r.certified_primary]
    natural_stable = [
        r for r in results
        if r.conveyed and (not r.born_stable) and (not r.rescued)
    ]  # structurally reachable when regulation is disabled or materially zero

    monotone = [r for r in results if r.regime_label == "monotone"]
    oscillatory = [r for r in results if r.regime_label == "oscillatory"]
    chaotic = [r for r in results if r.regime_label == "chaotic"]
    stalled = [r for r in results if r.regime_label == "stalled"]

    stable_steps = [float(r.stable_achieved_step) for r in results if r.stable_achieved_step is not None]
    convey_steps = [float(r.conveyed_step) for r in results if r.conveyed_step is not None]
    steps_taken = [float(r.steps_taken) for r in results]

    basin_pos = sum(1 for r in results if r.final_basin_sign == +1)
    basin_neg = sum(1 for r in results if r.final_basin_sign == -1)
    basin_none = n - basin_pos - basin_neg

    term_buckets: Dict[str, int] = {}
    for r in results:
        term_buckets[r.termination_reason] = term_buckets.get(r.termination_reason, 0) + 1

    convey_hist: Dict[str, int] = {}
    for r in results:
        k = "none" if r.conveyed_step is None else str(r.conveyed_step)
        convey_hist[k] = convey_hist.get(k, 0) + 1

    basin_hist: Dict[str, int] = {}
    for r in results:
        basin_hist[r.basin_label] = basin_hist.get(r.basin_label, 0) + 1

    out: Dict[str, Any] = {
        "execution_parameters": exec_params,
        "counts": {
            "total_runs": n,
            "conveyed": len(conveyed),
            "Unconveyable": len(Unconveyable),
            "born_stable": len(born_stable),
            "rescued": len(rescued),
            "certified_primary": len(certified),
            "conveyed_not_certified": len(conveyed_not_certified),
            "natural_stable": len(natural_stable),
            "non_born_conveyed_without_material_regulation": len(natural_stable),
            "regime_monotone": len(monotone),
            "regime_oscillatory": len(oscillatory),
            "regime_chaotic": len(chaotic),
            "regime_stalled": len(stalled),
            "final_basin_pos": basin_pos,
            "final_basin_neg": basin_neg,
            "final_basin_none": basin_none,
        },
        "percentages": {
            "conveyed_pct": _pct(len(conveyed), n),
            "unconveyed_pct": _pct(len(Unconveyable), n),
            "born_stable_pct": _pct(len(born_stable), n),
            "rescued_pct": _pct(len(rescued), n),
            "certified_primary_pct": _pct(len(certified), n),
            "conveyed_not_certified_pct": _pct(len(conveyed_not_certified), n),
            "natural_stable_pct": _pct(len(natural_stable), n),
            "non_born_conveyed_without_material_regulation_pct": _pct(len(natural_stable), n),
            "monotone_pct": _pct(len(monotone), n),
            "oscillatory_pct": _pct(len(oscillatory), n),
            "chaotic_pct": _pct(len(chaotic), n),
            "stalled_pct": _pct(len(stalled), n),
            "final_basin_pos_pct": _pct(basin_pos, n),
            "final_basin_neg_pct": _pct(basin_neg, n),
            "final_basin_none_pct": _pct(basin_none, n),
        },
        "steps_stats": {
            "stable_achieved_mean": _safe_mean(stable_steps),
            "stable_achieved_stdev": _safe_stdev(stable_steps),
            "conveyed_step_mean": _safe_mean(convey_steps),
            "conveyed_step_stdev": _safe_stdev(convey_steps),
            "steps_taken_mean": _safe_mean(steps_taken),
            "steps_taken_stdev": _safe_stdev(steps_taken),
            "stable_achieved_min": min(stable_steps) if stable_steps else None,
            "stable_achieved_max": max(stable_steps) if stable_steps else None,
            "conveyed_step_min": min(convey_steps) if convey_steps else None,
            "conveyed_step_max": max(convey_steps) if convey_steps else None,
            "steps_taken_min": min(steps_taken) if steps_taken else None,
            "steps_taken_max": max(steps_taken) if steps_taken else None,
        },
        "termination_buckets": dict(sorted(term_buckets.items(), key=lambda kv: (-kv[1], kv[0]))),
        "convey_step_hist": dict(sorted(convey_hist.items(), key=lambda kv: (kv[0] == "none", kv[0]))),
        "basin_label_hist": dict(sorted(basin_hist.items(), key=lambda kv: (-kv[1], kv[0]))),
"exec_params": exec_params,
        "config_snapshot": cfg.to_dict(),
    }

    return out

