def write_jsonl_dump(path: Path, results: List[RunResult], meta: Dict[str, Any], exec_params: Dict[str, Any]) -> None:
    with path.open("w", encoding="utf-8") as f:
        header = {
            "availability_id": meta.get("availability_id"),
            "batch_id": meta.get("batch_id"),
            "timestamp_utc": meta.get("timestamp_utc"),
            "timestamp_local": meta.get("timestamp_local"),
            "owner": meta.get("owner_name"),
            "company": meta.get("company_name"),
            "execution_parameters": exec_params,
            "execution_contract_text": meta.get("execution_contract_text", EXECUTION_CONTRACT_TEXT),
            "declaration_header_text": meta.get("declaration_header_text", DECLARATION_HEADER_TEXT),
        }
        f.write(json.dumps({"type": "header", "meta": header}) + "\n")
        for r in results:
            f.write(json.dumps({"type": "run", "data": r.to_dict()}) + "\n")

def _pdf_paragraphs_from_dict(d: Dict[str, Any], indent: int = 0) -> List[str]:
    out: List[str] = []
    pad = "  " * indent
    for k, v in d.items():
        if isinstance(v, dict):
            out.append(f"{pad}{k}:")
            out.extend(_pdf_paragraphs_from_dict(v, indent + 1))
        else:
            out.append(f"{pad}{k}: {v}")
    return out

def _pdf_lines_from_text_block(text: str) -> List[str]:
    return [line.rstrip("\n") for line in (text or "").splitlines()]



