def _even_col_widths(n_cols: int, pagesize, left_margin: float = 36.0, right_margin: float = 36.0) -> list:
    """Evenly distribute column widths across the usable page width."""
    if n_cols <= 0:
        return []
    page_w = pagesize[0]
    usable = max(1.0, page_w - left_margin - right_margin)
    return [usable / n_cols] * n_cols

