# CANONICAL universal ReportLab table typography and embedded-font contract. Many legacy tables supplied
# plain strings and therefore inherited ReportLab's 10 pt default even after
# paragraph styles were raised. This wrapper applies the 11 pt publication
# floor to every table before section-specific styling is added.
if HAVE_REPORTLAB:
    _OC_BASE_TABLE_CLASS = Table
    class _OC11PointTable(_OC_BASE_TABLE_CLASS):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            try:
                self.setStyle(TableStyle([
                    ("FONTNAME", (0,0), (-1,-1), "OCSans"),
                    ("FONTSIZE", (0,0), (-1,-1), 11.0),
                    ("LEADING", (0,0), (-1,-1), 13.2),
                ]))
            except Exception as _oc_exc:
                logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
    Table = _OC11PointTable


def add_pdf_engine_cover_page(story, styles, mc_runs: int, doc_height: float = 720.0, meta_ts: str = '', batch_id: str = '', rng_seed: str = '', meta: Optional[Dict[str, Any]] = None):
    """Create one compact cover page with a complete current-run identity register.

    The cover is a code-generated execution artifact. Nothing is stamped onto the
    finished PDF afterward. The entire block is deliberately shifted upward 18 pt
    and compacted so the timestamp, batch ID, RNG jump identity and hashes remain
    on page 1 for every run.
    """
    if not HAVE_REPORTLAB:
        raise ModuleNotFoundError("ReportLab is required for PDF generation (HAVE_REPORTLAB=False).")

    m = dict(meta or {})
    # The former 18 pt top spacer is removed. This moves the complete cover block
    # upward by 18 pt while leaving the document-wide frame and later pages alone.
    story.append(Spacer(1, 0))

    # Cover hierarchy is deliberate: the Omni-Compass brand is the largest
    # typographic element; the formal engine name is second; evidence and
    # descriptor lines follow without displacing the execution-identity grid.
    the_style = ParagraphStyle(
        "CoverTheV250R6", parent=styles["Title"], fontName="OCSans-Bold",
        fontSize=13.5, leading=14.5, alignment=1, spaceAfter=0,
    )
    brand_style = ParagraphStyle(
        "CoverBrandV250R6", parent=styles["Title"], fontName="OCSans-Bold",
        fontSize=30.0, leading=31.0, alignment=1, spaceAfter=2,
    )
    engine_title_style = ParagraphStyle(
        "CoverEngineTitleV250R2", parent=styles["Title"], fontName="OCSans-Bold",
        fontSize=19.0, leading=21.5, alignment=1, spaceAfter=7,
    )
    subtitle_style = ParagraphStyle(
        "CoverSubV250R2", parent=styles["Normal"], fontName="OCSans",
        fontSize=13.0, leading=15.0, alignment=1, spaceAfter=7,
    )
    execution_style = ParagraphStyle(
        "CoverExecutionV234", parent=styles["Normal"], fontName="OCSans-Bold",
        fontSize=12.0, leading=15.0, alignment=1, spaceAfter=7,
    )
    scope_style = ParagraphStyle(
        "CoverScopeV250R4", parent=styles["Normal"], fontName="OCSans",
        fontSize=11.0, leading=13.2, alignment=1, spaceAfter=5,
    )
    descriptor_style = ParagraphStyle(
        "CoverDescriptorV250R4", parent=styles["Normal"], fontName="OCSans-Bold",
        fontSize=11.0, leading=13.2, alignment=1, spaceAfter=5,
    )
    attest_style = ParagraphStyle(
        "CoverAttestV234", parent=styles["Normal"], fontName="OCSans",
        fontSize=11.0, leading=13.2, alignment=1, spaceAfter=5,
    )
    register_label = ParagraphStyle(
        "CoverRegisterLabelV234", parent=styles["Normal"], fontName="OCSans-Bold",
        fontSize=11.0, leading=13.2, alignment=0,
    )
    register_value = ParagraphStyle(
        "CoverRegisterValueV234", parent=styles["Normal"], fontName="OCSans",
        fontSize=11.0, leading=13.2, alignment=0, wordWrap="CJK",
    )

    story.append(Paragraph("THE", the_style))
    story.append(Paragraph("OMNI-COMPASS", brand_style))
    story.append(Paragraph(
        "UNIFIED GOVERNING CONVERGENCE<br/>CONTROL CORE ENGINE",
        engine_title_style,
    ))
    story.append(Paragraph("UNIFIED EXECUTIVE EXECUTION REPORT", subtitle_style))
    story.append(Paragraph(
        f"{int(mc_runs):,}-RUN MONTE CARLO / RUNGE-KUTTA (RK4) INTEGRATED EXECUTION",
        execution_style,
    ))
    story.append(Paragraph(COVER_BENCHMARK_SCOPE_PDF, scope_style))
    story.append(Paragraph(COVER_MANAGER_SCOPE_PDF, scope_style))
    story.append(Spacer(1, 5))
    story.append(Paragraph(
        COVER_SYSTEM_DESCRIPTOR_PDF + ".",
        descriptor_style,
    ))
    story.append(Spacer(1, 5))
    story.append(Paragraph(COVER_ATTESTATION_PDF, attest_style))
    story.append(Spacer(1, 8))
    story.append(Paragraph("<b>CURRENT-RUN EXECUTION IDENTITY</b>", execution_style))

    ts_et = str(m.get("timestamp_eastern") or meta_ts or m.get("timestamp_local") or "").strip()
    ts_utc = str(m.get("timestamp_utc") or run_started_at_iso).strip()
    bid = str(m.get("batch_id") or batch_id or "").strip()
    jump_seed = str(m.get("rng_jump_seed") or m.get("random_seed") or rng_seed or "").strip()
    jump_mode = str(m.get("rng_seed_mode") or "JUMP-GENERATED").strip()
    generator = str(m.get("rng_generator") or "numpy.random.default_rng / Python random").strip()
    bit_generator = str(m.get("rng_bit_generator") or "PCG64").strip()
    fingerprint = str(m.get("rng_fingerprint") or "").strip().upper()
    jump_id = str(m.get("rng_jump_id") or "").strip().upper()
    run_hash_show = str(m.get("run_hash") or run_hash or "").strip().upper()
    engine_hash = str(m.get("engine_sha256") or _oc_engine_sha256() or "").strip().upper()
    population_hash = str(m.get("canonical_population_sha256") or "").strip().upper()

    identity_rows = [
        [Paragraph("EXECUTION TIMESTAMP - ET", register_label), Paragraph(ts_et, register_value)],
        [Paragraph("EXECUTION TIMESTAMP - UTC", register_label), Paragraph(ts_utc, register_value)],
        [Paragraph("BATCH ID", register_label), Paragraph(bid, register_value)],
        [Paragraph("RNG JUMP SEED", register_label), Paragraph(f"{jump_seed} ({jump_mode})", register_value)],
        [Paragraph("RNG GENERATOR", register_label), Paragraph(f"{generator} / {bit_generator}", register_value)],
        [Paragraph("RNG JUMP ID", register_label), Paragraph(jump_id, register_value)],
        [Paragraph("RNG STATE FINGERPRINT", register_label), Paragraph(fingerprint, register_value)],
        [Paragraph("RUN HASH", register_label), Paragraph(run_hash_show, register_value)],
        [Paragraph("POPULATION SHA-256", register_label), Paragraph(population_hash, register_value)],
        [Paragraph("ENGINE SHA-256", register_label), Paragraph(engine_hash, register_value)],
    ]
    identity_table = Table(identity_rows, colWidths=[1.65 * inch, 4.55 * inch], hAlign="CENTER")
    identity_table.setStyle(TableStyle([
        ("BOX", (0, 0), (-1, -1), 0.8, colors.HexColor(OC_VISUAL_PALETTE["blue"])),
        ("INNERGRID", (0, 0), (-1, -1), 0.35, colors.HexColor(OC_VISUAL_PALETTE["grid"])),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("LEFTPADDING", (0, 0), (-1, -1), 5),
        ("RIGHTPADDING", (0, 0), (-1, -1), 5),
        ("TOPPADDING", (0, 0), (-1, -1), 3),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
    ]))
    story.append(identity_table)
    story.append(PageBreak())

def add_pdf_engine_header_first_page(story, styles, mc_runs: int):
    """Add centered engine header to the FIRST PAGE of a PDF artifact."""
    from reportlab.platypus import Spacer, Paragraph

    story.append(Spacer(1, 48))
    for line in ENGINE_HEADER_TEXT.format(mc_runs=mc_runs).split("\n"):
        story.append(
            Paragraph(
                f"<para alignment='center'><b>{line}</b></para>",
                styles["Title"]
            )
        )
    story.append(Spacer(1, 72))

from reportlab.lib.units import inch

def _draw_oc_header_footer(canvas, doc):
    """Repeating unified-report header, website footer, and page numbers."""
    try:
        w, h = doc.pagesize
    except Exception:
        return

    try:
        canvas.saveState()
        canvas.setFont("OCSans-Bold", 11)
        canvas.drawCentredString(w / 2.0, h - 20, "OMNI-COMPASS UNIFIED GOVERNING CONVERGENCE CONTROL CORE ENGINE")
        canvas.setLineWidth(0.5)
        canvas.line(OC_HEADER_RULE_LEFT_PT, h - 27, w - OC_PAGE_RIGHT_MARGIN_PT, h - 27)
        canvas.restoreState()
    except Exception as _oc_exc:
        logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)

    try:
        canvas.saveState()
        canvas.setFont("OCSans", 9)
        canvas.drawCentredString(w / 2.0, 14, "www.omni-compass.com")
        canvas.restoreState()
    except Exception as _oc_exc:
        logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)

    try:
        from reportlab.lib.units import inch
        canvas.saveState()
        canvas.setFont("OCSans-BoldOblique", 10)
        pn = int(getattr(canvas, "getPageNumber", lambda: (getattr(doc, "page", 0) or 0))())
        xL = OC_PAGE_LEFT_MARGIN_PT
        y = 28
        page_text = f"{pn}"
        # Canonical footer contract: bold-italic page number mirrored left/right,
        # with the website centered.
        canvas.drawString(xL, y, page_text)
        canvas.drawRightString(w - OC_PAGE_RIGHT_MARGIN_PT, y, page_text)
        canvas.restoreState()
    except Exception as _oc_exc:
        logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)


def _cover_first_page(canvas, doc):
    """Cover page callback: draw cover box + website footer."""
    _draw_draw_cover_box(canvas, doc)
    _draw_oc_header_footer(canvas, doc)


def _draw_draw_cover_box(canvas, doc):
    """Draw a bold border box around the cover page content area (cover page only)."""
    canvas.saveState()
    w, h = doc.pagesize
    margin_x = 24
    margin_y = 24
    try:
        canvas.setStrokeColor(colors.HexColor(OC_VISUAL_PALETTE["blue"]))
    except Exception as _oc_exc:
        logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
    canvas.setLineWidth(2.2)
    canvas.rect(margin_x, margin_y, w - 2*margin_x, h - 2*margin_y, stroke=1, fill=0)
    canvas.restoreState()


try:
    from reportlab.platypus import Flowable as _OCFlowable
except Exception:
    _OCFlowable = object


OC_TOC_TITLE = "TABLE OF CONTENTS"


class _OCTOCMarker(_OCFlowable):
    """Zero-height marker used to register page-level front matter in the TOC."""
    def __init__(self, title: str, level: int = 0):
        if _OCFlowable is not object:
            super().__init__()
        self.title = str(title)
        self.level = int(level)
        self.width = 0
        self.height = 0

    def wrap(self, availWidth, availHeight):
        return (0, 0)

    def draw(self):
        return None


class _OCPageBreakUnlessTop(_OCFlowable):
    """Start a major section on a new page without emitting a blank page.

    A normal PageBreak placed after content that has already flowed exactly to the
    next frame can create a dead page. This flowable forces a break only when
    meaningful vertical space has already been consumed on the current page.
    """
    def __init__(self, top_tolerance: float = 18.0):
        if _OCFlowable is not object:
            super().__init__()
        self.top_tolerance = float(top_tolerance)
        self.width = 0
        self.height = 0

    def wrap(self, availWidth, availHeight):
        frame = getattr(getattr(self, '_doctemplate', None), 'frame', None)
        full_height = float(getattr(frame, '_aH', availHeight) or availHeight)
        at_top = float(availHeight) >= full_height - self.top_tolerance
        if at_top:
            return (0, 0)
        return (0, float(availHeight) + 1.0)

    def draw(self):
        return None


