def _coerce_results_to_dicts(results):
    if not results:
        return []
    if isinstance(results[0], dict):
        return list(results)
    out=[]
    for r in results:
        if hasattr(r, "to_dict") and callable(getattr(r, "to_dict")):
            out.append(r.to_dict())
        elif is_dataclass(r):
            out.append(asdict(r))
        elif hasattr(r,'__dict__'):
            out.append(dict(r.__dict__))
        else:
            out.append({'value': str(r)})
    return out





# ---------------------------
# CANONICAL RAW TABLE SCHEMA
# ---------------------------
def _canonical_cols(rows: List[Dict[str, Any]], max_pdf_cols: int = 18) -> Dict[str, List[str]]:
    """
    Produce a single canonical column ordering used across:
      • RAW_DATA CSV header
      • RAW_DATA standalone PDF table
      • Executive report RAW appendix table

    This prevents the 'blank first column' / shifted-header confusion that happens
    when one renderer adds an implicit index while another uses explicit keys.
    """
    if not rows:
        return {"all": [], "pdf": []}

    keys = list(rows[0].keys())

    preferred = [
        "run_id",
        "engine_equation_form",
        "engine_equation_lines",
        "initial_U",
        "initial_distance_to_basin",
        "initial_nearest_basin",
        "initial_distance_band",
        "born_stable",
        "self_tuning_applied",
        "conveyed",
        "conveyed_step",
        "conveyance_confirmed_step",
        "certified_primary",
        "certification_streak_start_step",
        "certified_step",
        "first_basin_entry_step",
        "max_consecutive_same_basin",
        "v_eff_abs_integral",
        "v_eff_sq_integral",
        "v_eff_peak",
        "self_tune_abs_total",
        "self_tune_peak",
        "rescued",
        "stable_achieved_step",
        "steps_taken",
        "termination_reason",
        "regime_label",
        "basin_label",
        "final_basin_sign",
        "quadrant_final_label",
        "quadrant_final_id",
        "q1_steps",
        "q2_steps",
        "q3_steps",
        "q4_steps",
        "rms_metric",
        "final_U",
        "final_E",
        "final_IU",
        "final_S",
        "final_B",
        "final_Bdot",
    ]
    cols_all = [k for k in preferred if k in keys] + [k for k in keys if k not in preferred]

    # Safety: ensure run_id is first if present
    if "run_id" in cols_all:
        cols_all = ["run_id"] + [c for c in cols_all if c != "run_id"]

    cols_pdf = cols_all[:max_pdf_cols]
    return {"all": cols_all, "pdf": cols_pdf}

# ---------------------------
# QUADRANT FIELDS (RAW ROW AUGMENTATION)
# ---------------------------
def _augment_row_with_quadrants(row: Dict[str, Any]) -> Dict[str, Any]:
    """Attach equation identity and quadrant fields in a consistent, reader-visible way."""
    row["engine_equation_form"] = ENGINE_EQUATION_FORM
    row["engine_equation_lines"] = EQUATION_LINE_COUNT
    try:
        hist = row.get("quadrant_history") or []
        if isinstance(hist, str):
            hist = [hist]
        q_final = hist[-1] if hist else "QX"
    except Exception:
        q_final = "QX"

    qid_map = {"Q1": 1, "Q2": 2, "Q3": 3, "Q4": 4, "QX": 0}
    row["quadrant_final_label"] = q_final
    row["quadrant_final_id"] = int(qid_map.get(str(q_final), 0))

    counts = row.get("quadrant_counts") or {}
    try:
        row["q1_steps"] = int(counts.get("Q1", 0))
        row["q2_steps"] = int(counts.get("Q2", 0))
        row["q3_steps"] = int(counts.get("Q3", 0))
        row["q4_steps"] = int(counts.get("Q4", 0))
    except Exception:
        row["q1_steps"] = row["q2_steps"] = row["q3_steps"] = row["q4_steps"] = 0

    return row


def _compute_rms_from_history(rows: List[Dict[str, Any]], cfg_snapshot: Dict[str, Any]) -> Tuple[float, np.ndarray]:
    target = 1.0
    bc = cfg_snapshot.get("basin_centers", None)
    bcl = _parse_list_maybe(bc)
    if isinstance(bcl, list) and len(bcl) > 0:
        try:
            target = float(bcl[0])
        except Exception:
            target = 1.0

    rms_vals: List[float] = []
    for r in rows:
        uh = _extract_u_history(r)
        if not uh:
            rms_vals.append(float("nan"))
            continue
        arr = np.array(uh, dtype=float)
        rms_vals.append(float(np.sqrt(np.mean((arr - target) ** 2))))
    return target, np.array(rms_vals, dtype=float)


def _safe_numeric_values(items: List[Any]) -> List[float]:
    out: List[float] = []
    for item in items:
        try:
            value = float(item)
            if math.isfinite(value):
                out.append(value)
        except Exception as _oc_exc:
            logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
    return out


def _metric_stats(items: List[Any]) -> Dict[str, Optional[float]]:
    vals = sorted(_safe_numeric_values(items))
    if not vals:
        return {"mean": None, "median": None, "p95": None, "min": None, "max": None}
    idx95 = max(0, min(len(vals) - 1, int(math.ceil(0.95 * len(vals))) - 1))
    return {
        "mean": float(sum(vals) / len(vals)),
        "median": float(np.median(np.asarray(vals, dtype=float))),
        "p95": float(vals[idx95]),
        "min": float(vals[0]),
        "max": float(vals[-1]),
    }


def summarize_distance_bands(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Group the single executed population into five reporting bands.

    This is post-run accounting only. It never resamples, moves, or reruns a trajectory.
    """
    summaries: List[Dict[str, Any]] = []
    for index, (lo, hi, label) in enumerate(DISTANCE_BANDS, start=1):
        band_rows = [r for r in rows if str(r.get("initial_distance_band", "")) == label]
        count = len(band_rows)
        conveyed_rows = [r for r in band_rows if _safe_bool(r.get("conveyed", False))]
        certified_rows = [r for r in band_rows if _safe_bool(r.get("certified_primary", False))]
        born_rows = [r for r in band_rows if _safe_bool(r.get("born_stable", False))]
        tuned_rows = [r for r in band_rows if _safe_bool(r.get("self_tuning_applied", False))]
        conveyed_not_certified = [r for r in conveyed_rows if not _safe_bool(r.get("certified_primary", False))]

        summary = {
            "band_index": index,
            "label": label,
            "distance_min_bound": lo,
            "distance_max_bound": hi,
            "runs": count,
            "distance": _metric_stats([r.get("initial_distance_to_basin") for r in band_rows]),
            "born_in_basin": len(born_rows),
            "self_tuning_applied": len(tuned_rows),
            "conveyed": len(conveyed_rows),
            "conveyed_pct": (100.0 * len(conveyed_rows) / count) if count else 0.0,
            "certified": len(certified_rows),
            "certified_pct": (100.0 * len(certified_rows) / count) if count else 0.0,
            "conveyed_not_certified": len(conveyed_not_certified),
            "not_conveyed": count - len(conveyed_rows),
            "first_entry_step": _metric_stats([r.get("first_basin_entry_step") for r in band_rows]),
            "conveyance_entry_step": _metric_stats([r.get("conveyed_step") for r in conveyed_rows]),
            "conveyance_confirmed_step": _metric_stats([r.get("conveyance_confirmed_step") for r in conveyed_rows]),
            "certified_step": _metric_stats([r.get("certified_step") for r in certified_rows]),
            "v_eff_abs_integral": _metric_stats([r.get("v_eff_abs_integral") for r in band_rows]),
            "v_eff_sq_integral": _metric_stats([r.get("v_eff_sq_integral") for r in band_rows]),
            "v_eff_peak": _metric_stats([r.get("v_eff_peak") for r in band_rows]),
            "self_tune_abs_total": _metric_stats([r.get("self_tune_abs_total") for r in band_rows]),
            "self_tune_peak": _metric_stats([r.get("self_tune_peak") for r in band_rows]),
            "basin_regulation_abs_total": _metric_stats([r.get("basin_regulation_abs_total") for r in band_rows]),
            "basin_regulation_peak": _metric_stats([r.get("basin_regulation_peak") for r in band_rows]),
            "basin_regulation_gain_peak": _metric_stats([r.get("basin_regulation_gain_peak") for r in band_rows]),
            "basin_invariance_interventions": _metric_stats([r.get("basin_invariance_interventions") for r in band_rows]),
        }
        summaries.append(summary)
    return summaries


def _fmt_metric(value: Any, digits: int = 3) -> str:
    try:
        if value is None:
            return "-"
        return f"{float(value):.{digits}f}"
    except Exception:
        return "-"


def write_distance_band_artifacts(outdir: Path, batch_id: str, rows: List[Dict[str, Any]]) -> Dict[str, Path]:
    """Write five-band accounting plus low-ink, fixed-format referee figures."""
    summaries=summarize_distance_bands(rows); json_path=outdir/f"DISTANCE_BAND_SUMMARY_{batch_id}.json"; csv_path=outdir/f"DISTANCE_BAND_SUMMARY_{batch_id}.csv"
    outcomes_png=outdir/f"DISTANCE_BAND_OUTCOMES_{batch_id}.png"; timing_png=outdir/f"DISTANCE_BAND_TIMING_{batch_id}.png"; force_png=outdir/f"DISTANCE_BAND_FORCE_{batch_id}.png"
    json_path.write_text(json.dumps({"basis":"Post-run accounting of the actual single execution","distance_definition":"min(abs(U0-1), abs(U0+1))","visual_system":OC_VISUAL_SYSTEM_ID,"bands":summaries},indent=2),encoding="utf-8")
    csv_fields=["band_index","label","distance_min_bound","distance_max_bound","runs","born_in_basin","self_tuning_applied","conveyed","conveyed_pct","certified","certified_pct","conveyed_not_certified","not_conveyed","distance_mean","distance_min","distance_max","first_entry_mean","conveyance_entry_mean","conveyance_confirmed_mean","certified_step_mean","v_eff_abs_integral_mean","v_eff_peak_mean","self_tune_abs_total_mean","self_tune_peak_mean"]
    with csv_path.open("w",encoding="utf-8",newline="") as f:
        writer=csv.DictWriter(f,fieldnames=csv_fields); writer.writeheader()
        for q in summaries:
            writer.writerow({"band_index":q["band_index"],"label":q["label"],"distance_min_bound":q["distance_min_bound"],"distance_max_bound":q["distance_max_bound"],"runs":q["runs"],"born_in_basin":q["born_in_basin"],"self_tuning_applied":q["self_tuning_applied"],"conveyed":q["conveyed"],"conveyed_pct":q["conveyed_pct"],"certified":q["certified"],"certified_pct":q["certified_pct"],"conveyed_not_certified":q["conveyed_not_certified"],"not_conveyed":q["not_conveyed"],"distance_mean":q["distance"]["mean"],"distance_min":q["distance"]["min"],"distance_max":q["distance"]["max"],"first_entry_mean":q["first_entry_step"]["mean"],"conveyance_entry_mean":q["conveyance_entry_step"]["mean"],"conveyance_confirmed_mean":q["conveyance_confirmed_step"]["mean"],"certified_step_mean":q["certified_step"]["mean"],"v_eff_abs_integral_mean":q["v_eff_abs_integral"]["mean"],"v_eff_peak_mean":q["v_eff_peak"]["mean"],"self_tune_abs_total_mean":q["self_tune_abs_total"]["mean"],"self_tune_peak_mean":q["self_tune_peak"]["mean"]})
    import matplotlib.pyplot as _plt
    labels=[f"B{q['band_index']}\nn={q['runs']}" for q in summaries]; note=f"{OC_VISUAL_SYSTEM_ID}; five bands are computed from actual Step-0 distance in the current execution."
    # Two explicit vertical lanes prevent coincident 100% values from hiding a
    # series. The values are unchanged; only presentation geometry is separated.
    fig,ax=_plt.subplots(figsize=(8.40,6.82))
    y=np.arange(len(labels),dtype=float)
    conveyed_vals=np.asarray([q["conveyed_pct"] for q in summaries],dtype=float)
    cert_vals=np.asarray([q["certified_pct"] for q in summaries],dtype=float)
    lane=0.14
    ax.scatter(conveyed_vals,y-lane,s=76,marker="s",color=OC_VISUAL_PALETTE["blue"],
               edgecolors=OC_VISUAL_PALETTE["paper"],linewidths=0.9,label="CONVEY-5",zorder=3)
    ax.scatter(cert_vals,y+lane,s=82,marker="^",color=OC_VISUAL_PALETTE["teal"],
               edgecolors=OC_VISUAL_PALETTE["paper"],linewidths=0.9,label="Canonical M2 CERT-10",zorder=4)
    for yi,value in zip(y-lane,conveyed_vals):
        ax.annotate(f"{value:.1f}%",(value,yi),xytext=(-7,0),textcoords="offset points",
                    ha="right",va="center",fontsize=11.0,color=OC_VISUAL_PALETTE["blue"])
    for yi,value in zip(y+lane,cert_vals):
        ax.annotate(f"{value:.1f}%",(value,yi),xytext=(-7,0),textcoords="offset points",
                    ha="right",va="center",fontsize=11.0,color=OC_VISUAL_PALETTE["teal"])
    ax.set_yticks(y); ax.set_yticklabels(labels); ax.invert_yaxis()
    ax.set_xlim(0,105); ax.set_xlabel("Percent of runs in band")
    ax.set_title("Five-band initial-distance outcomes")
    _oc_style_axes(ax,grid="x"); ax.legend(loc="lower left", bbox_to_anchor=(0.02, 0.02))
    _oc_save_figure(fig,outcomes_png,note=note+" Coincident percentages are displayed on separate lanes so both executed series remain visible.")
    _plt.close(fig)
    # Ordered timing lines are meaningful because band order is meaningful.
    fig,ax=_plt.subplots(figsize=(8.40,6.82)); series=[("First basin entry","first_entry_step",OC_VISUAL_PALETTE["sky"],"o","-"),("CONVEY-5 confirmed","conveyance_confirmed_step",OC_VISUAL_PALETTE["blue"],"s","--"),("CERT-10 completed","certified_step",OC_VISUAL_PALETTE["teal"],"^","-.")]
    x=np.arange(len(labels))
