def _oc_top10_engineering_financial_outcomes(
    rows: Sequence[Any],
    summary: Dict[str, Any],
    meta: Dict[str, Any],
) -> Dict[str, Any]:
    """Authoritative current-run synthesis for CTO/CFO review.

    Authority:
      governing mathematics -> executed payloads -> Top-10 object -> report/Q&A.

    Missing source data remains NOT AVAILABLE; the publication layer may not
    manufacture a substitute number.
    """
    def _pct(d: Optional[Dict[str,Any]]) -> Optional[float]:
        try:
            v=float((d or {}).get("mean_percent_change"))
            return v if math.isfinite(v) else None
        except Exception:
            return None

    def _mean(d: Optional[Dict[str,Any]], key: str) -> Optional[float]:
        try:
            v=float((d or {}).get(key))
            return v if math.isfinite(v) else None
        except Exception:
            return None

    def _fmt_pct(v: Optional[float]) -> str:
        return "NOT AVAILABLE" if v is None else f"{v:+.2f}%"

    compute=meta.get("compute_payload") if isinstance(meta.get("compute_payload"),dict) else {}
    manager=meta.get("manager_payload") if isinstance(meta.get("manager_payload"),dict) else {}
    megastack=meta.get("global_stack_payload") if isinstance(meta.get("global_stack_payload"),dict) else {}

    mgr=(manager.get("omni_vs_broker",{}) or {})
    cb=mgr.get("control_burden_events",{}) or {}
    rec=mgr.get("mean_recovery_minutes",{}) or {}
    adm=mgr.get("time_admissible_fraction",{}) or {}
    sla=mgr.get("sla_violation_rate",{}) or {}

    comp={}
    for _mode in ("cpu","gpu","mixed"):
        comp[_mode]=(((compute.get("summaries",{}) or {}).get(_mode,{}) or {}).get("omni_vs_binpack",{}) or {})

    cpu_power=(comp.get("cpu",{}) or {}).get("powered_cpu_core_hours",{}) or {}
    gpu_power=(comp.get("gpu",{}) or {}).get("powered_gpu_hours",{}) or {}
    mixed_cpu=(comp.get("mixed",{}) or {}).get("powered_cpu_core_hours",{}) or {}
    mixed_gpu=(comp.get("mixed",{}) or {}).get("powered_gpu_hours",{}) or {}
    mixed_energy=(comp.get("mixed",{}) or {}).get("facility_energy_kwh",{}) or {}

    thermal_rows=[]
    for _mode in ("cpu","gpu","mixed"):
        _d=(comp.get(_mode,{}) or {}).get("thermal_excursion_hours",{}) or {}
        thermal_rows.append((_mode,_pct(_d),_mean(_d,"baseline_mean"),_mean(_d,"contender_mean")))

    finance={}
    try:
        primary=_ms_primary_financial_table(megastack.get("summary_rows",[]) or [])
        unit={x.get("mode"):x for x in primary if int(x.get("stack_count",0) or 0)==1}
        overlay=unit.get("kubernetes_plus_omnicompass",{}) or {}
        direct=unit.get("omnicompass_direct",{}) or {}
        _vals={
            "kubernetes_annual_cost_per_stack_usd":(unit.get("kubernetes",{}) or {}).get("annual_operating_cost_usd"),
            "overlay_savings_per_stack_usd":overlay.get("incremental_financial_impact_vs_kubernetes_usd"),
            "overlay_savings_pct":overlay.get("incremental_financial_impact_vs_kubernetes_pct"),
            "direct_savings_per_stack_usd":direct.get("incremental_financial_impact_vs_kubernetes_usd"),
            "direct_savings_pct":direct.get("incremental_financial_impact_vs_kubernetes_pct"),
        }
        for _k,_v in _vals.items():
            try:
                _fv=float(_v)
                finance[_k]=_fv if math.isfinite(_fv) else None
            except Exception:
                finance[_k]=None
    except Exception as _exc:
        logging.getLogger(__name__).warning("Top-10 financial translation unavailable: %s",_exc)

    total=int(summary.get("total_runs",len(rows)) or len(rows))
    conveyed=int(summary.get("conveyed",0) or 0)
    certified=int(summary.get("certified_primary",summary.get("certified_primary", summary.get("certified",0))) or 0)

    _thermal_text="; ".join(f"{m.upper()} {_fmt_pct(v)}" for m,v,_,_ in thermal_rows)
    if finance.get("overlay_savings_per_stack_usd") is not None and finance.get("direct_savings_per_stack_usd") is not None:
        _finance_text=(
            f"K8s+OC {_fmt_pct(finance.get('overlay_savings_pct'))} = "
            f"${finance.get('overlay_savings_per_stack_usd'):,.0f}/stack-year; "
            f"OC direct {_fmt_pct(finance.get('direct_savings_pct'))} = "
            f"${finance.get('direct_savings_per_stack_usd'):,.0f}/stack-year"
        )
    else:
        _finance_text="Financial translation NOT AVAILABLE"

    metrics=[
        {
            "rank":1,"metric":"Canonical control qualification",
            "executed_value":f"CONVEY-5 {conveyed}/{total}; CERT-10 {certified}/{total}",
            "direction":"qualification",
            "interpretation":"Repeatable finite-horizon signed-basin capture and dwell qualification under the executed contract.",
            "financial_translation":"Foundation for downstream benefit accounting; it is not itself a dollar saving."
        },
        {
            "rank":2,"metric":"Control burden events",
            "baseline":_mean(cb,"baseline_mean"),"omni":_mean(cb,"contender_mean"),"change_pct":_pct(cb),
            "executed_value":_fmt_pct(_pct(cb)),"direction":"lower is favorable",
            "interpretation":"Less repeated supervisory/governance activity.",
            "financial_translation":"May reduce control-plane work, reconciliation, incident handling, and associated resource burden when independently costed."
        },
        {
            "rank":3,"metric":"Mean recovery time",
            "baseline":_mean(rec,"baseline_mean"),"omni":_mean(rec,"contender_mean"),"change_pct":_pct(rec),
            "executed_value":_fmt_pct(_pct(rec)),"direction":"lower is favorable",
            "interpretation":"Less time spent in degraded or corrective operation.",
            "financial_translation":"Maps to avoided recovery labor, service loss, excess powered operation, and risk-adjusted outage cost when validated."
        },
        {
            "rank":4,"metric":"Time admissible",
            "baseline":_mean(adm,"baseline_mean"),"omni":_mean(adm,"contender_mean"),"change_pct":_pct(adm),
            "executed_value":_fmt_pct(_pct(adm)),"direction":"higher is favorable",
            "interpretation":"A larger operating fraction remains inside the declared admissible governance condition.",
            "financial_translation":"Supports more usable operating time and less deviation/recovery burden."
        },
        {
            "rank":5,"metric":"SLA violation rate",
            "baseline":_mean(sla,"baseline_mean"),"omni":_mean(sla,"contender_mean"),"change_pct":_pct(sla),
            "executed_value":_fmt_pct(_pct(sla)),"direction":"lower is favorable",
            "interpretation":"Lower modeled service-level violation frequency in matched manager scenarios.",
            "financial_translation":"Maps to avoided SLA/customer impact and incident loss only through customer-specific records."
        },
        {
            "rank":6,"metric":"CPU powered core-hours",
            "baseline":_mean(cpu_power,"baseline_mean"),"omni":_mean(cpu_power,"contender_mean"),"change_pct":_pct(cpu_power),
            "executed_value":_fmt_pct(_pct(cpu_power)),"direction":"lower is favorable",
            "interpretation":"Equal completed CPU workload with fewer powered core-hours against the strong bin-pack comparator.",
            "financial_translation":"Lower powered time can reduce electrical work and capacity cost per completed workload."
        },
        {
            "rank":7,"metric":"GPU powered hours",
            "baseline":_mean(gpu_power,"baseline_mean"),"omni":_mean(gpu_power,"contender_mean"),"change_pct":_pct(gpu_power),
            "executed_value":_fmt_pct(_pct(gpu_power)),"direction":"lower is favorable",
            "interpretation":"Equal completed GPU workload with fewer powered GPU-hours against the strong bin-pack comparator.",
            "financial_translation":"Lower accelerator powered time can reduce energy/capacity cost and preserve more fixed power or battery budget for useful work."
        },
        {
            "rank":8,"metric":"Mixed CPU/GPU powered hours",
            "baseline_cpu":_mean(mixed_cpu,"baseline_mean"),"omni_cpu":_mean(mixed_cpu,"contender_mean"),
            "baseline_gpu":_mean(mixed_gpu,"baseline_mean"),"omni_gpu":_mean(mixed_gpu,"contender_mean"),
            "change_cpu_pct":_pct(mixed_cpu),"change_gpu_pct":_pct(mixed_gpu),
            "executed_value":f"CPU {_fmt_pct(_pct(mixed_cpu))}; GPU {_fmt_pct(_pct(mixed_gpu))}",
            "direction":"lower is favorable",
            "interpretation":"Heterogeneous workload retains completed work while reducing powered resource-hours.",
            "financial_translation":"Supports lower resource/energy consumption per useful workload and more useful-work capacity inside a fixed resource budget."
        },
        {
            "rank":9,"metric":"Mixed-mode facility energy",
            "baseline":_mean(mixed_energy,"baseline_mean"),"omni":_mean(mixed_energy,"contender_mean"),"change_pct":_pct(mixed_energy),
            "executed_value":_fmt_pct(_pct(mixed_energy)),"direction":"lower is favorable",
            "interpretation":"Facility electrical energy for the matched mixed workload.",
            "financial_translation":"Convert kWh reduction with site tariffs, demand charges, PUE/cooling architecture, and workload equivalence."
        },
        {
            "rank":10,"metric":"Thermal truth + modeled one-stack financial translation",
            "executed_value":f"{_thermal_text}; {_finance_text}",
            "thermal":thermal_rows,"finance":finance,
            "direction":"thermal lower is favorable; financial impact higher is favorable",
            "interpretation":"Thermal exposure is shown even when neutral. Financial translation uses the complete non-duplicated normalized stack ledger, not CPU/GPU energy alone.",
            "financial_translation":"Synthetic normalized model only; customer pricing must use independently verified realized benefit and the adopter's complete cost ledger."
        },
    ]

    equations={
        "energy_efficiency":"UsefulWorkEfficiency = CompletedUsefulWork / EnergyOrPoweredResourceBudget; at equal completed work, lower energy/powered-hours increases efficiency.",
        "technical_to_stack_tax":"VerifiedStackBenefit = Compute + Accelerator + MemoryNetworkStorage + EnergyCooling + ReliabilityRecovery + Maintenance + ToolingIntegration + OtherAcceptedBenefits - CausalOverlap",
        "gross_to_net":"NetAnnualBenefit = VerifiedGrossBenefit - Implementation - Integration - Migration - Training - SecurityCompliance - ResidualLicenses - OngoingOperation - QuantifiedRisk",
        "one_stack_scaling":"C_m(N)=N*C_m(1); Delta_m(N)=N*[C_Kubernetes(1)-C_m(1)]",
        "pricing_basis":"ContractPrice is a negotiated commercial term applied only to contractually accepted value; RK4/Monte-Carlo execution does not infer a mandatory license percentage.",
    }

    return {
        "schema_id":"OC-TOP10-ENGINEERING-FINANCIAL-OUTCOMES-v1",
        "batch_id":meta.get("batch_id"),
        "engine_sha256":meta.get("engine_sha256") or _oc_engine_sha256().upper(),
        "canonical_population_sha256":meta.get("canonical_population_sha256"),
        "random_seed":meta.get("random_seed"),
        "rng_fingerprint":meta.get("rng_fingerprint"),
        "authority_chain":"GOVERNING_MATH -> EXECUTED COMPUTATION -> TOP-10 OUTCOMES -> FINANCIAL TRANSLATION -> PUBLICATION",
        "source_surfaces":["canonical_rows","manager_payload.omni_vs_broker","compute_payload.summaries.*.omni_vs_binpack","global_stack_payload.summary_rows"],
        "metrics":metrics,
        "equations":equations,
        "claim_boundary":"Current-run synthesis of executed synthetic/digital-twin evidence. It does not convert modeled engineering changes into measured customer savings, hardware lifetime, battery endurance, or production superiority without target-environment validation.",
    }


def _oc_write_top10_outcomes_artifacts(outdir: Path, batch_id: str, payload: Dict[str,Any]) -> Dict[str,str]:
    outdir=Path(outdir)
    j=outdir/f"TOP10_ENGINEERING_FINANCIAL_OUTCOMES_{batch_id}.json"
    c=outdir/f"TOP10_ENGINEERING_FINANCIAL_OUTCOMES_{batch_id}.csv"
    t=outdir/f"TOP10_ENGINEERING_FINANCIAL_OUTCOMES_{batch_id}.txt"
    j.write_text(json.dumps(payload,indent=2,default=str),encoding="utf-8")
    _oc_write_csv_records(c,[{
        "rank":m.get("rank"),"metric":m.get("metric"),"executed_value":m.get("executed_value"),
        "direction":m.get("direction"),"interpretation":m.get("interpretation"),
        "financial_translation":m.get("financial_translation"),
    } for m in payload.get("metrics",[])])
    lines=[
        "OMNI-COMPASS TOP 10 ENGINEERING & FINANCIAL OUTCOMES",
        "===================================================",
        f"Batch ID: {payload.get('batch_id')}",
        f"Seed: {payload.get('random_seed')}",
        f"Population SHA-256: {payload.get('canonical_population_sha256')}",
        f"Engine SHA-256: {payload.get('engine_sha256')}",
        f"Authority: {payload.get('authority_chain')}",
        "",
    ]
    for m in payload.get("metrics",[]):
        lines += [
            f"{m.get('rank')}. {m.get('metric')}: {m.get('executed_value')}",
            f"   Engineering: {m.get('interpretation')}",
            f"   Financial translation: {m.get('financial_translation')}",
        ]
    lines += ["","ACCOUNTING EQUATIONS"]
    for k,v in (payload.get("equations",{}) or {}).items():
        lines.append(f"{k}: {v}")
    lines += ["",str(payload.get("claim_boundary",""))]
    t.write_text("\n".join(lines)+"\n",encoding="utf-8")
    return {"top10_json":str(j),"top10_csv":str(c),"top10_txt":str(t)}


def _oc_top10_pdf_flowables(payload: Dict[str,Any], styles, body, compact_body) -> List[Any]:
    flows=[
        Paragraph(
            "<b>0E.1. TOP 10 ENGINEERING &amp; FINANCIAL OUTCOMES - CONTROL -> RESOURCE -> ENERGY -> STACK TAX</b>",
            ParagraphStyle("OCTop10DecisionHeading", parent=styles["Heading2"], fontName="OCSans-Bold", fontSize=max(11.0, styles["Heading2"].fontSize), leading=max(13.2, styles["Heading2"].leading))
        ),
        Spacer(1,6),
        Paragraph(
            "<b>CONTROLLING INTERPRETATION:</b> The 500/500 result establishes repeatable finite-horizon control qualification. "
            "The engineering value is measured downstream as reduced control burden and recovery, more admissible operating time, "
            "service behavior, fewer powered CPU/GPU resource-hours at equal completed work, energy/thermal behavior, and the "
            "non-duplicated translation of those technical surfaces into the normalized STACKS / CLUSTERS cost ledger.",
            body),
        Spacer(1,6),
    ]
    data=[["#","Outcome","Current executed result","Why a CTO/CFO cares"]]
    for m in payload.get("metrics",[]):
        data.append([str(m.get("rank","")),str(m.get("metric","")),str(m.get("executed_value","")),str(m.get("financial_translation",""))])
    flows.append(_oc_ev_make_table(data,[22,118,145,225],font_size=11.0))
    flows += [Spacer(1,7),Paragraph("<b>BUSINESS-101 STACK-TAX EQUATIONS</b>",compact_body)]
    for _k in ("energy_efficiency","technical_to_stack_tax","gross_to_net","one_stack_scaling","pricing_basis"):
        flows.append(Paragraph(_html.escape(str((payload.get("equations",{}) or {}).get(_k,""))),compact_body))
        flows.append(Spacer(1,2))
    flows += [Spacer(1,4),Paragraph("<b>EVIDENCE BOUNDARY:</b> "+_html.escape(str(payload.get("claim_boundary",""))),compact_body)]
    return flows


def _oc_economic_benefit_formula_rows(meta: Optional[Dict[str, Any]] = None) -> List[List[str]]:
    snap = _oc_economic_benefit_model_snapshot(meta)
    rows = [
        ["Economic quantity", "Controlling calculation and interpretation"],
        ["Verified STACKS / CLUSTERS operating benefit", "Verified compute + accelerator + memory/network/storage + energy/cooling + reliability/recovery + maintenance + software/tooling + integration + other accepted technical benefits, with causal overlap counted once"],
        ["Verified product / hardware benefit", "Accepted asset-preservation, maintenance, battery/endurance, component-life, thermal, or replacement-deferral value only when platform-specific evidence establishes it"],
        ["Verified operating-cost benefit", "Translate accepted technical effects into actual or avoided expenditure using authenticated customer cost records; include labor only where the customer proves a cost conversion"],
        ["Aggregate gross annual benefit", "Verified non-duplicative STACKS / CLUSTERS + product/hardware + operating-cost benefits"],
        ["Aggregate net annual benefit", "Verified gross annual benefit - implementation - integration - training - transition - residual licenses - security/compliance - ongoing Omni-Compass operation - quantified risk cost"],
        ["ROI", "(Verified annual benefit - all-in evaluated cost) / all-in evaluated cost; identify whether benefit is gross or net and whether the period is annual"],
        ["Introductory 10% licensing benchmark", "Illustrative license consideration = contractually accepted value captured x 10%; the benchmark is introductory, nonbinding, company-specific in dollar amount, subject to change or withdrawal, expected to increase with validation and demand, and controlled only by a definitive written agreement"],
        ["Customer-retained value", "Accepted value captured - license consideration - integration - migration - security/compliance - training/transition - support - ongoing operation - residual systems - quantified risk and other agreed attributable costs"],
        ["Benefit-cost ratio", "Verified gross or net benefit / total evaluated cost, clearly labeled and calculated from the same accepted benefit basis and complete all-in cost ledger"],
        ["Simple payback months", "12 x total evaluated investment / verified annual net benefit"],
        ["Share of stack tax removed", "Total-cost reduction percentage / independently established baseline stack-tax percentage"],
        ["Authority-adjusted benefit", "Benefit measured only over authorized and instrumented layers; no benefit is assigned to an unobserved or unauthorized surface"],
        ["Cash versus capacity", "Cash savings require actual or avoided expenditure; released engineering capacity remains separate unless finance approves conversion"],
    ]
    if snap.get("status") == "executed synthetic model":
        rows.append(["Current model status", f"Executed synthetic Megastack view; {snap.get('canonical_run_count')} canonical variables; maximum declared normalized scale {int(snap.get('scale',0)):,}; production calibration required"])
    else:
        rows.append(["Current model status", str(snap.get("status", "not available"))])
    return rows



