def _oc_market_domain_benefit_rows() -> List[List[str]]:
    """Evidence-bound market map derived from the engine's declared muscle catalog."""
    rows = [["Domain family", "Declared / representative surfaces", "Market benefit emphasis", "Evidence boundary"]]
    benefit_map = {
        "compute": "CPU/GPU utilization, powered-hours, useful work, scheduling, energy/thermal efficiency",
        "containers": "placement, scaling, lifecycle coordination, reduced reconciliation and churn",
        "network": "routing/mesh/load-balancing coordination, latency, transfer burden, recovery",
        "storage": "I/O, replication, backup/recovery, write amplification, data movement",
        "data": "database/stream/cache coordination, throughput, latency, replay and recovery",
        "observability": "shared telemetry state, duplicate-alert reduction, diagnosis and audit",
        "security": "policy/identity/secrets/threat coordination, least privilege, containment and recovery",
        "automation": "infrastructure/workflow coordination, drift and handoff reduction",
        "ai": "accelerator/resource coordination, inference/training scheduling, optimizer governance",
        "hpc": "scientific workload scheduling, accelerator efficiency, queue/makespan, reproducibility",
        "robotics": "bounded command arbitration, motion/perception/safety coordination, recovery and hardware stress",
        "automotive": "perception/planning/control coordination, compute/energy/thermal and fault recovery",
        "aerospace": "guidance/navigation/control, propulsion/thermal, telemetry/mission coordination and resilience",
        "enterprise": "transaction/search/workflow coordination, availability, latency, integration and recovery",
        "logistics": "routing/fulfillment/fleet coordination, throughput, latency, resource efficiency",
        "edge": "intermittent-link/remote coordination, bounded local authority, energy budget and recovery",
        "resilience": "fault injection, failover, restart, disaster recovery, containment and availability",
        "governance": "telemetry consensus, decision replay, provenance, cross-manager arbitration and audit",
    }
    fam = {}
    for f, n, d in MS_MUSCLE_CATALOG:
        fam.setdefault(str(f), []).append((str(n), str(d)))
    for f in sorted(fam):
        names = [n for n,_ in fam[f]]
        reps = ", ".join(names[:5]) + (" ..." if len(names) > 5 else "")
        boundary = "Executed/mapped synthetic surface; production benefit requires domain-specific adapters, telemetry, safety and validation."
        rows.append([f.upper(), reps, benefit_map.get(f, "Shared-state governance, bounded correction, recovery and resource coordination"), boundary])
    rows.append(["BIOLOGY / LIFE SCIENCE", "Not a declared executable family in the current muscle catalog", "Potential future state/constraint/telemetry governance extension", "No current biological performance or physical-life-science claim is established by this execution."])
    return rows


