def _oc_rights_usage_sections(meta: Optional[Dict[str, Any]] = None, base_number: int = 16) -> List[Tuple[str, List[str]]]:
    controls = _oc_rights_usage_control_paragraphs(meta)
    use_lines = controls[:]
    use_lines.extend([""] + [" | ".join(row) for row in _oc_rights_usage_level_rows()])
    claim_lines = [OC_CLAIM_BOUNDARY_COMPACT_NOTICE, ""] + [" | ".join(row) for row in _oc_claim_boundary_rows()]
    claim_lines.extend([
        "",
        "COMMERCIAL TRANSITION: Production, enterprise, customer-facing, embedded, hosted, paid-service, monetized, or sustained operational use begins only after an executed written license defines scope, environment, term, authority, modification, redistribution, security, audit, support, economics, and termination conditions.",
        "PRICING BOUNDARY: The introductory 10% value-captured benchmark is nonbinding planning arithmetic, not a permanent public price, binding quote, offer, guarantee, royalty commitment, subscription price, or final implementation fee. The percentage, value basis, scope, and all commercial terms may change, be withdrawn, or be negotiated; only a definitive executed agreement creates an obligation.",
    ])
    return [
        (f"{base_number}. EXECUTIVE RELIANCE, NO-WARRANTY & ORDER-OF-CONTROL CONTRACT", controls),
        (f"{base_number}A. RIGHTS, AUTHORIZED EVALUATION & ALL USE LEVELS", use_lines),
        (f"{base_number}B. CLAIM BOUNDARIES, LICENSING & DEPLOYMENT TRANSITION", claim_lines),
    ]


def _oc_rights_usage_text(meta: Optional[Dict[str, Any]] = None, section_numbers: Tuple[int, int, int] = (17, 18, 19)) -> str:
    a, b, c = section_numbers
    controls = _oc_rights_usage_control_paragraphs(meta)
    lines: List[str] = [
        f"{a}. EXECUTIVE RELIANCE, NO-WARRANTY & ORDER-OF-CONTROL CONTRACT",
        "---------------------------------------------------------------",
        "",
        *controls,
        "",
        f"{b}. RIGHTS, AUTHORIZED EVALUATION & ALL USE LEVELS",
        "----------------------------------------------------",
        "",
    ]
    for row in _oc_rights_usage_level_rows()[1:]:
        lines.extend([row[0].upper(), row[1], ""])
    lines.extend([
        f"{c}. CLAIM BOUNDARIES, LICENSING & DEPLOYMENT TRANSITION",
        "---------------------------------------------------------",
        "",
        OC_CLAIM_BOUNDARY_COMPACT_NOTICE,
        "",
    ])
    for row in _oc_claim_boundary_rows()[1:]:
        lines.extend([row[0].upper(), "May establish: " + row[1], "Does not establish: " + row[2], ""])
    lines.extend([
        "COMMERCIAL TRANSITION",
        "Production, enterprise, customer-facing, embedded, hosted, paid-service, monetized, or sustained operational use begins only after an executed written license defines scope, environment, term, authority, modification, redistribution, security, audit, support, economics, and termination conditions.",
        "",
        "PRICING BOUNDARY",
        "The introductory 10% value-captured benchmark is nonbinding planning arithmetic, not a permanent public price, binding quote, offer, guarantee, royalty commitment, subscription price, or final implementation fee. The percentage, value basis, scope, and all commercial terms may change, be withdrawn, or be negotiated; only a definitive executed agreement creates an obligation.",
    ])
    return "\n".join(lines)


def _oc_rights_usage_pdf_flowables(title_style, body_style, width: float = 500.0, meta: Optional[Dict[str, Any]] = None) -> List[Any]:
    """Return a complete, reusable ReportLab disclosure block."""
    if Paragraph is None or Table is None or TableStyle is None:
        return []
    width = float(max(360.0, width))
    head_style = ParagraphStyle(
        "OCRightsTableHead", parent=body_style, fontName="OCSans-Bold",
        fontSize=max(11.0, float(getattr(body_style, "fontSize", 11.0))),
        leading=max(13.2, float(getattr(body_style, "leading", 13.2))), spaceAfter=0,
    )
    cell_style = ParagraphStyle(
        "OCRightsTableCell", parent=body_style, fontName="OCSans",
        fontSize=max(11.0, float(getattr(body_style, "fontSize", 11.0))),
        leading=max(13.2, float(getattr(body_style, "leading", 13.2))), spaceAfter=0,
        splitLongWords=False, wordWrap="LTR",
    )
    flows: List[Any] = [Paragraph(f"<b>{_html.escape(OC_RIGHTS_USAGE_TITLE)}</b>", title_style), Spacer(1, 8)]
    for p in _oc_rights_usage_control_paragraphs(meta):
        flows.append(Paragraph(_html.escape(p), body_style))
    usage_data = []
    for ridx, row in enumerate(_oc_rights_usage_level_rows()):
        style = head_style if ridx == 0 else cell_style
        usage_data.append([Paragraph(_html.escape(str(c)), style) for c in row])
    usage_table = Table(usage_data, colWidths=[width * 0.34, width * 0.66], repeatRows=1, hAlign="LEFT", splitByRow=1)
    usage_table.setStyle(TableStyle([
        ("BACKGROUND", (0,0), (-1,0), colors.lightgrey), ("GRID", (0,0), (-1,-1), 0.35, colors.grey),
        ("VALIGN", (0,0), (-1,-1), "TOP"), ("LEFTPADDING", (0,0), (-1,-1), 5),
        ("RIGHTPADDING", (0,0), (-1,-1), 5), ("TOPPADDING", (0,0), (-1,-1), 5),
        ("BOTTOMPADDING", (0,0), (-1,-1), 5),
    ]))
    flows.extend([Spacer(1, 6), usage_table, Spacer(1, 10), Paragraph("<b>CLAIM BOUNDARY MATRIX</b>", title_style), Spacer(1, 6)])
    claim_data = []
    for ridx, row in enumerate(_oc_claim_boundary_rows()):
        style = head_style if ridx == 0 else cell_style
        claim_data.append([Paragraph(_html.escape(str(c)), style) for c in row])
    claim_table = Table(claim_data, colWidths=[width * 0.23, width * 0.385, width * 0.385], repeatRows=1, hAlign="LEFT", splitByRow=1)
    claim_table.setStyle(TableStyle([
        ("BACKGROUND", (0,0), (-1,0), colors.lightgrey), ("GRID", (0,0), (-1,-1), 0.35, colors.grey),
        ("VALIGN", (0,0), (-1,-1), "TOP"), ("LEFTPADDING", (0,0), (-1,-1), 4),
        ("RIGHTPADDING", (0,0), (-1,-1), 4), ("TOPPADDING", (0,0), (-1,-1), 4),
        ("BOTTOMPADDING", (0,0), (-1,-1), 4),
    ]))
    flows.extend([claim_table, Spacer(1, 8)])
    return flows


def _oc_write_rights_usage_artifacts(outdir: Path, batch_id: str, meta: Optional[Dict[str, Any]] = None) -> Dict[str, str]:
    """Emit human- and machine-readable copies of the exact embedded disclosure."""
    outdir = Path(outdir)
    outdir.mkdir(parents=True, exist_ok=True)
    stem = f"OMNI-COMPASS_RIGHTS_USAGE_DISCLOSURE_{batch_id}"
    txt_path = outdir / f"{stem}.txt"
    json_path = outdir / f"{stem}.json"
    txt_path.write_text(_oc_rights_usage_text(meta, (1, 2, 3)) + "\n", encoding="utf-8")
    payload = {
        "disclosure_id": OC_RIGHTS_USAGE_DISCLOSURE_ID,
        "title": OC_RIGHTS_USAGE_TITLE,
        "compact_rights_notice": OC_RIGHTS_USAGE_COMPACT_NOTICE,
        "compact_claim_boundary": OC_CLAIM_BOUNDARY_COMPACT_NOTICE,
        "control_paragraphs": _oc_rights_usage_control_paragraphs(meta),
        "use_levels": [dict(zip(_oc_rights_usage_level_rows()[0], row)) for row in _oc_rights_usage_level_rows()[1:]],
        "claim_boundaries": [dict(zip(_oc_claim_boundary_rows()[0], row)) for row in _oc_claim_boundary_rows()[1:]],
    }
    json_path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")
    return {"rights_usage_txt": str(txt_path), "rights_usage_json": str(json_path)}


def _oc_validate_rights_usage_module() -> None:
    required = (
        "all rights are reserved", "no implied license", "production", "commercial", "redistribution",
        "sublicensing", "derivative", "independent validation", "claim", "price",
    )
    corpus_parts = _oc_rights_usage_control_paragraphs({}) + [OC_RIGHTS_USAGE_COMPACT_NOTICE, OC_CLAIM_BOUNDARY_COMPACT_NOTICE]
    corpus_parts.extend(" ".join(row) for row in _oc_rights_usage_level_rows())
    corpus_parts.extend(" ".join(row) for row in _oc_claim_boundary_rows())
    corpus_parts.append("The introductory 10% benchmark is not a permanent public price, binding quote, offer, guarantee, royalty commitment, subscription price, or final implementation fee.")
    corpus = " ".join(corpus_parts).lower()
    missing = [token for token in required if token not in corpus]
    if missing:
        raise RuntimeError("Canonical rights/usage disclosure is incomplete: " + ", ".join(missing))


_oc_validate_rights_usage_module()
