def write_full_report_txt_html(sections: List[Tuple[str, List[str]]], txt_path: Path, html_path: Path) -> None:
    cover_bytes = _oc_static_identity_cover_bytes()
    with txt_path.open("w", encoding="utf-8") as f:
        f.write("OFFICIAL STATIC IDENTITY COVER\n")
        f.write("------------------------------\n")
        f.write(f"Identity: {STATIC_IDENTITY_COVER_NAME}\n")
        f.write(f"Embedded cover SHA-256: {STATIC_IDENTITY_COVER_SHA256}\n")
        f.write("The complete welcome page follows on physical page 2, and the live Table of Contents begins on physical page 3.\n\n")
        for title, lines in sections:
            f.write(title + "\n")
            f.write("-"*len(title) + "\n")
            for ln in lines:
                f.write(str(ln) + "\n")
            f.write("\n")

    with html_path.open("w", encoding="utf-8") as f:
        f.write("<html><head><meta charset='utf-8'><title>Omni-Compass Execution Report</title></head><body>\n")
        f.write("<section id='official-static-identity-cover' style='text-align:center;page-break-after:always;'>\n")
        f.write(f"<img alt='{_html.escape(STATIC_IDENTITY_COVER_NAME)}' src='{_oc_static_identity_cover_data_uri()}' style='max-width:100%;height:auto;'/>\n")
        f.write(f"<p><b>Embedded cover SHA-256:</b> {_html.escape(STATIC_IDENTITY_COVER_SHA256)}</p></section>\n")
        for title, lines in sections:
            f.write(f"<h2>{_html.escape(title)}</h2>\n<pre>\n")
            for ln in lines:
                f.write(_html.escape(str(ln)) + "\n")
            f.write("</pre>\n")
        f.write("</body></html>\n")



def _oc_stiffness_threshold_phrase(stress: Any) -> str:
    """State the acceptance criterion that produced the stiffness warning count.

    A maximum eigenvalue condition-number ratio in the thousands is not by itself
    a defect, and reporting it next to 'warnings 0' without the criterion invites
    the reasonable objection that the threshold was never disclosed. The criterion
    is the classical RK4 absolute-stability limit on the dimensionless product
    |h*lambda|, not the condition-number ratio, and it is stated explicitly here.
    """
    try:
        st = (stress or {}).get("stiffness_summary", {}) or {}
        thr = st.get("acceptance_threshold_h_lambda")
        obs = st.get("max_observed_h_lambda")
        if thr is None:
            return ("acceptance criterion: classical RK4 absolute-stability limit |h*lambda| <= 2.785; "
                    "the condition-number ratio is a conditioning diagnostic and is not the criterion")
        if obs is None:
            return (f"acceptance criterion: |h*lambda| <= {float(thr):.3f} (classical RK4 absolute-stability "
                    "limit); the condition-number ratio is a conditioning diagnostic, not the criterion")
        margin = float(thr) - float(obs)
        return (f"acceptance criterion: |h*lambda| <= {float(thr):.3f} (classical RK4 absolute-stability limit); "
                f"maximum observed |h*lambda| = {float(obs):.4f}, margin {margin:.4f}; the condition-number "
                "ratio is a conditioning diagnostic and is NOT the acceptance criterion")
    except Exception:
        return ("acceptance criterion: classical RK4 absolute-stability limit |h*lambda| <= 2.785; "
                "the condition-number ratio is a conditioning diagnostic, not the criterion")


def _oc_zero_failure_upper_bound(n: Any, confidence: float = 0.95) -> Any:
    """Exact one-sided upper confidence bound on the failure rate given 0 observed failures.

    STATISTICAL BASIS
    -----------------
    With k = 0 failures observed in n independent trials, the Clopper-Pearson
    (exact binomial) one-sided upper bound at confidence level C reduces to the
    closed form:

        p_upper = 1 - (1 - C)**(1/n)

    This is the classical "rule of three" in exact form: at C = 0.95 it is very
    close to 3/n for moderate n.

    WHY THIS IS REPORTED
    --------------------
    A campaign reporting a 100% success fraction has NOT demonstrated that the
    failure region is empty. It has demonstrated that the executed sample did not
    encounter one. The exact upper bound is the honest statement of what a
    zero-failure sample of size n can support, and it is reported alongside every
    perfect score so that a reader is not invited to over-read the result.
    """
    try:
        n_int = int(n)
        if n_int <= 0:
            return None
        return 1.0 - (1.0 - float(confidence)) ** (1.0 / n_int)
    except Exception:
        return None


def _oc_zero_failure_bound_phrase(fraction: Any, n: Any, confidence: float = 0.95) -> str:
    """Human-readable bound phrase; only asserts a zero-failure bound when the sample was perfect."""
    try:
        n_int = int(n)
    except Exception:
        return "exact upper confidence bound unavailable (sample size not recorded)"
    try:
        frac = float(fraction)
    except Exception:
        return "exact upper confidence bound unavailable (success fraction not recorded)"
    pct = int(round(float(confidence) * 100))
    if frac >= 1.0 - 1e-12:
        ub = _oc_zero_failure_upper_bound(n_int, confidence)
        if ub is None:
            return "exact upper confidence bound unavailable"
        return (
            f"zero failures observed, so the exact (Clopper-Pearson) one-sided {pct}% upper bound on the "
            f"underlying failure rate is {ub*100:.2f}%, NOT zero - a perfect sample bounds the failure "
            f"rate, it does not prove the failure region is empty"
        )
    observed_failures = max(0, int(round((1.0 - frac) * n_int)))
    return (
        f"{observed_failures} failure(s) observed in n={n_int}; the sampled fraction bounds behavior over "
        "the executed vectors only and does not extend to the continuous domain"
    )


def _oc_disp(value: Any, digits: int = 4) -> str:
    """Publication-safe numeric display.

    Binary floating point produces artifacts such as 89.60000000000001 and
    4897.335282941602 when a computed value is interpolated directly into report
    text. The underlying numbers are correct; the DISPLAY is not publication
    grade, and in a document arguing for referee-level rigor an artifact of this
    kind appearing inside a claim ledger undermines the surrounding argument.

    This formatter rounds for display only. It never alters a stored value, a
    computed result, a digest input, a raw data row, or any acceptance decision.
    Integral values render without a decimal tail; everything else renders at the
    requested precision with trailing zeros removed.
    """
    if value is None:
        return "n/a"
    if isinstance(value, bool):
        return str(value)
    try:
        f = float(value)
    except (TypeError, ValueError):
        return str(value)
    if f != f or f in (float("inf"), float("-inf")):
        return str(value)
    if abs(f) != 0.0 and (abs(f) < 1e-4 or abs(f) >= 1e12):
        return f"{f:.{max(1, digits)}e}"
    if abs(f - round(f)) < 1e-9:
        return str(int(round(f)))
    out = f"{f:.{max(0, digits)}f}"
    # Strip trailing zeros ONLY after a decimal point. Stripping them from a
    # whole number removes significant digits (121504130 -> 12150413).
    if "." in out:
        out = out.rstrip("0").rstrip(".")
    return out if out not in ("", "-") else "0"


def _oc_ev_num(value: Any, digits: int = 4, pct: bool = False) -> str:
    try:
        x = float(value)
        if not math.isfinite(x):
            return "n/a"
        if pct:
            return f"{100.0*x:.2f}%"
        ax = abs(x)
        if ax != 0.0 and (ax < 1e-3 or ax >= 1e4):
            return f"{x:.3e}"
        return f"{x:.{digits}f}"
    except Exception:
        return "n/a"


def _oc_ev_read_csv(path: Path) -> List[Dict[str, Any]]:
    try:
        with path.open("r", encoding="utf-8-sig", newline="") as f:
            return [dict(r) for r in csv.DictReader(f)]
    except Exception:
        return []


def _oc_ev_status_rows(payload: Dict[str, Any]) -> List[List[str]]:
    self_tests = payload.get("self_tests", {}) or {}
    step = payload.get("step_size", {}) or {}
    cross = (payload.get("cross_solver", {}) or {}).get("summary", {}) or {}
    _seed_payload = payload.get("seed_replication", {}) or {}
    seed = (_seed_payload.get("summary", {}) or {}) if isinstance(_seed_payload, dict) and "summary" in _seed_payload else _seed_payload
    sample_rows = (payload.get("sample_size", {}) or {}).get("rows", []) or []
    ablation_rows = (payload.get("ablation", {}) or {}).get("summary_rows", []) or []
    sens = (payload.get("sensitivity", {}) or {}).get("lhs_summary", {}) or {}
    stress = payload.get("stress", {}) or {}
    disturbance = stress.get("disturbance_rows", []) or []
    orders = [float(r.get("observed_refinement_order", 0)) for r in step.get("rows", []) if r.get("record_type") == "observed_order"]
    observed_order = max(orders) if orders else 0.0
    adaptive = next((r for r in ablation_rows if str(r.get("mode")) == "adaptive"), {})
    off = next((r for r in ablation_rows if str(r.get("mode")) == "off"), {})
    reg_status = "NOT RUN"
    regulation_reading = "Ablation payload unavailable"
    if adaptive and off:
        a = float(adaptive.get("mean_conveyance_confirmation_step", 0))
        o = float(off.get("mean_conveyance_confirmation_step", 0))
        delta = o - a
        pct = (delta / o * 100.0) if abs(o) > EPS else 0.0
        regulation_reading = f"Adaptive mean confirmation {a:.2f} vs regulation-off {o:.2f}; acceleration {delta:.2f} steps ({pct:.2f}%)"
        reg_status = "PASS" if a <= o else "REVIEW"
    lhs_n = int(sens.get("n", 0) or 0)
    lhs_fraction = float(sens.get("successful_parameter_space_fraction", 0) or 0)
    lhs_status = "PASS" if lhs_n > 0 and lhs_fraction >= 1.0 - 1e-12 else ("REVIEW" if lhs_n > 0 else "NOT RUN")
    return [
        ["Implementation integrity", f"{self_tests.get('passed',0)}/{self_tests.get('passed',0)+self_tests.get('failed',0)} automated tests passed", "PASS" if self_tests.get("failed", 1) == 0 else "REVIEW"],
        ["RK4 refinement behavior", f"Observed order {observed_order:.3f}; classification agreement reported across tested refinements", "PASS" if observed_order >= 3.5 else "REVIEW"],
        ["Independent solver concordance", f"DOP853 comparison: mean L2 {_oc_ev_num(cross.get('mean_l2'))}; basin agreement {_oc_ev_num(cross.get('basin_agreement'), pct=True)}", "PASS" if float(cross.get("basin_agreement",0)) == 1.0 else "REVIEW"],
        ["Repeated-seed stability", f"{seed.get('batches','n/a')} batches x {seed.get('runs_per_batch','n/a')} runs; conveyed mean {_oc_ev_num(seed.get('conveyed_rate_mean'), pct=True)}", "PASS" if float(seed.get("conveyed_rate_mean",0)) >= .95 else "REVIEW"],
        ["Sample-size stabilization", f"Largest executed ensemble: {sample_rows[-1].get('sample_size','n/a') if sample_rows else 'n/a'}; Wilson interval disclosed", "PASS" if sample_rows else "NOT RUN"],
        ["Regulation acceleration and capture-control benefit", regulation_reading, reg_status],
        ["Threshold robustness", "80 threshold combinations in quick profile; full grid exported and summarized", "PASS" if (payload.get("threshold_survival",{}) or {}).get("threshold_grid_rows",0) else "NOT RUN"],
        ["Disturbance robustness", f"{len(disturbance)} declared disturbance scenarios executed; acceptance is bounded to the tested magnitudes", "PASS" if disturbance else "NOT RUN"],
        ["Finite declared parameter-space robustness campaign", f"Latin-hypercube success fraction {_oc_ev_num(lhs_fraction, pct=True)} over n={lhs_n or 'n/a'}; {_oc_zero_failure_bound_phrase(lhs_fraction, lhs_n)}; criterion: complete success over the executed vectors", lhs_status],
        ["Continuous-domain mechanism-dominance position", "Declared in Sections 0A and 7; separate from the finite campaign", "DECLARED POSITION"],
        ["Operational authority and kill-switch contract", "Autopilot, supervised, observe-only, off, environment stop, and sentinel-file stop are wired into the execution wrapper", "WIRED"],
        ["20-25% addressable stack-tax reduction", "Owner commercial target; not measured by the current synthetic campaign", "COMMERCIAL TARGET"],
        ["Stiffness screening", f"Maximum reported ratio {_oc_ev_num((stress.get('stiffness_summary',{}) or {}).get('max_ratio'))}; warnings {(stress.get('stiffness_summary',{}) or {}).get('warnings','n/a')}; {_oc_stiffness_threshold_phrase(stress)}", "PASS" if (stress.get("stiffness_summary",{}) or {}).get("warnings",1) == 0 else "REVIEW"],
        ["Differential residual audit", f"Mean L2 {_oc_ev_num((stress.get('residual_summary',{}) or {}).get('mean_l2'))}; max Linf {_oc_ev_num((stress.get('residual_summary',{}) or {}).get('max_linf'))}", "DISCLOSED"],
        ["External empirical validation", "No independent physical experiment or third-party replication is contained in this execution", "NOT ESTABLISHED"],
    ]


def _oc_ev_generate_integrated_figures(payload: Dict[str, Any], evidence_dir: Path, outdir: Path, batch_id: str) -> Dict[str, Path]:
    """Generate the fixed numerical-evidence visual suite.

    Each chart type is chosen by evidentiary function: ordered numerical
    progression uses lines, categorical comparisons use low-ink lollipops,
    uncertainty uses bands, and two-parameter robustness uses an annotated
    heatmap. The mapping is invariant across runs.
    """
    figs: Dict[str, Path] = {}
    fig_dir = outdir / "_oc_evidence_figs"; fig_dir.mkdir(parents=True, exist_ok=True)
    def finish(fig,name,note):
        pp=fig_dir/f"{name}_{batch_id}.png"; _oc_save_figure(fig,pp,note=note,dpi=180); plt.close(fig); figs[name]=pp
    base_note=f"{OC_VISUAL_SYSTEM_ID}; current-run numerical evidence; no synthetic decorative series."

    try:
        rows=[r for r in (payload.get("step_size",{}) or {}).get("rows",[]) if r.get("record_type")!="observed_order"]
        if rows:
            fig,ax=plt.subplots(figsize=(8.20,6.52))
            for i,mode in enumerate(sorted(set(str(r.get("mode")) for r in rows))):
                rr=sorted([r for r in rows if str(r.get("mode"))==mode],key=lambda x:int(x.get("micro_steps",0)))
                ax.plot([int(r.get("micro_steps",0)) for r in rr],[float(r.get("mean_final_state_l2",0)) for r in rr],
                        marker=OC_VISUAL_MARKERS[i%len(OC_VISUAL_MARKERS)],linestyle=OC_VISUAL_LINESTYLES[i%len(OC_VISUAL_LINESTYLES)],label=mode)
            ax.set_yscale("log"); ax.set_xlabel("RK4 microsteps per macro step"); ax.set_ylabel("Mean final-state L2 difference vs reference")
            ax.set_title("RK4 step-size refinement"); _oc_style_axes(ax,grid="both"); ax.legend()
            finish(fig,"EVIDENCE_RK4_REFINEMENT",base_note+" Log scale is used because solver error spans orders of magnitude.")
    except Exception: plt.close("all")

    try:
        rows=(payload.get("sample_size",{}) or {}).get("rows",[]) or []
        if rows:
            x=[int(r["sample_size"]) for r in rows]; y=[float(r["conveyed_rate"]) for r in rows]
            lo=[float(r["conveyed_ci_low"]) for r in rows]; hi=[float(r["conveyed_ci_high"]) for r in rows]
            fig,ax=plt.subplots(figsize=(8.20,6.52)); ax.fill_between(x,lo,hi,color=OC_SEMANTIC_COLORS["uncertainty"],alpha=.22,label="95% Wilson interval")
            ax.plot(x,y,marker="o",color=OC_SEMANTIC_COLORS["candidate"],label="Observed conveyed rate")
            ax.set_xlabel("Monte Carlo sample size"); ax.set_ylabel("Conveyed proportion"); ax.set_ylim(0,1.02); ax.set_title("Monte Carlo sample-size stabilization")
            _oc_style_axes(ax,grid="both"); ax.legend(); finish(fig,"EVIDENCE_SAMPLE_SIZE",base_note)
    except Exception: plt.close("all")

    try:
        rows=(payload.get("seed_replication",{}) or {}).get("rows",[]) or []
        if rows:
            fig,ax=plt.subplots(figsize=(8.20,6.23)); xx=[int(r["batch"])+1 for r in rows]; yy=[float(r["mean_conveyance_confirmation_step"]) for r in rows]
            ax.plot(xx,yy,marker="o",color=OC_SEMANTIC_COLORS["candidate"]); ax.fill_between(xx,yy,yy,color=OC_VISUAL_PALETTE["sky"],alpha=.10)
            ax.set_xlabel("Independent seed batch"); ax.set_ylabel("Mean confirmation step"); ax.set_title("Repeated-seed timing stability")
            _oc_style_axes(ax,grid="both"); finish(fig,"EVIDENCE_SEED_REPLICATION",base_note)
    except Exception: plt.close("all")

    try:
        rows=(payload.get("ablation",{}) or {}).get("summary_rows",[]) or []
        if rows:
            modes=[str(r.get("mode")).replace("_"," ") for r in rows]; steps=[float(r.get("mean_conveyance_confirmation_step",0)) for r in rows]
            fig,ax=plt.subplots(figsize=(8.20,6.38)); _oc_lollipop(ax,modes,steps,horizontal=True,
                colors_list=[OC_VISUAL_SERIES[i%len(OC_VISUAL_SERIES)] for i in range(len(modes))],value_format="{:.3f}",zero_line=False)
            ax.set_xlabel("Mean conveyance confirmation step"); ax.set_title("Regulation ablation: timing comparison")
            finish(fig,"EVIDENCE_ABLATION",base_note+" Lower values indicate earlier confirmation.")
    except Exception: plt.close("all")

    try:
        rows=(payload.get("stress",{}) or {}).get("disturbance_rows",[]) or []
        if rows:
            names=[str(r.get("scenario")).replace("_"," ") for r in rows]; vals=[float(r.get("mean_conveyance_confirmation_step",0)) for r in rows]
            fig,ax=plt.subplots(figsize=(8.0,max(4.5,.36*len(names)+1.4))); _oc_lollipop(ax,names,vals,horizontal=True,
                colors_list=[OC_SEMANTIC_COLORS["candidate"]]*len(names),value_format="{:.3f}",zero_line=False)
            ax.set_xlabel("Mean conveyance confirmation step"); ax.set_title("Disturbance robustness across declared scenarios")
            finish(fig,"EVIDENCE_DISTURBANCE",base_note)
    except Exception: plt.close("all")

    try:
        rows=(payload.get("sensitivity",{}) or {}).get("sensitivity_rows",[]) or []
        ranked=sorted(rows,key=lambda r:abs(float(r.get("prcc_with_final_distance",0))),reverse=True)[:10]
        if ranked:
            labels=[str(r.get("parameter")) for r in ranked]; vals=[float(r.get("prcc_with_final_distance",0)) for r in ranked]
            cols=[OC_SEMANTIC_COLORS["adverse"] if v>0 else OC_SEMANTIC_COLORS["favorable"] for v in vals]
            fig,ax=plt.subplots(figsize=(8.20,7.25)); _oc_lollipop(ax,labels,vals,horizontal=True,colors_list=cols,value_format="{:+.3f}")
            ax.set_xlim(-1.05,1.05); ax.set_xlabel("PRCC with final basin distance"); ax.set_title("Global parameter sensitivity ranking")
            finish(fig,"EVIDENCE_SENSITIVITY",base_note+" Sign indicates direction; magnitude indicates ranked association.")
    except Exception: plt.close("all")

    try:
        rows=_oc_ev_read_csv(evidence_dir/"THRESHOLD_ROBUSTNESS.csv"); rows=[r for r in rows if int(float(r.get("certification_window",0)))==CERTIFICATION_STEPS]
        if rows:
            tols=sorted(set(float(r["basin_tolerance"]) for r in rows)); wins=sorted(set(int(float(r["conveyance_window"])) for r in rows))
            grid=np.full((len(wins),len(tols)),np.nan)
            for r in rows: grid[wins.index(int(float(r["conveyance_window"]))),tols.index(float(r["basin_tolerance"]))]=float(r["baseline_certification_agreement"])
            fig,ax=plt.subplots(figsize=(8.20,6.52)); im=_oc_annotated_heatmap(ax,grid,[str(x) for x in wins],[f"{x:.2f}" for x in tols],
                title=f"Threshold robustness matrix (CERT-{CERTIFICATION_STEPS} agreement)",vmin=0,vmax=1,fmt="{:.2f}")
            ax.set_xlabel("Basin tolerance"); ax.set_ylabel("Conveyance window"); fig.colorbar(im,ax=ax,label="Agreement with canonical classification")
            finish(fig,"EVIDENCE_THRESHOLD_MATRIX",base_note+" Cell values are exact classification agreement rates.")
    except Exception: plt.close("all")

    try:
        rows=(payload.get("threshold_survival",{}) or {}).get("survival_rows",[]) or []
        if rows:
            xx=[int(r["step"]) for r in rows]; yy=[float(r["cumulative_conveyed"]) for r in rows]
            lo=[1-float(r["ci_high"]) for r in rows]; hi=[1-float(r["ci_low"]) for r in rows]
            fig,ax=plt.subplots(figsize=(8.20,6.38)); ax.fill_between(xx,lo,hi,step="post",color=OC_SEMANTIC_COLORS["uncertainty"],alpha=.22,label="95% interval")
            ax.step(xx,yy,where="post",color=OC_SEMANTIC_COLORS["candidate"],linewidth=2.2,label="Cumulative conveyed")
            ax.set_xlabel("Macro step"); ax.set_ylabel("Cumulative conveyed probability"); ax.set_ylim(0,1.02); ax.set_title("Event-time conveyance curve")
            _oc_style_axes(ax,grid="both"); ax.legend(); finish(fig,"EVIDENCE_SURVIVAL",base_note)
    except Exception: plt.close("all")
    return figs



def _oc_soft_break_html(value: Any) -> str:
    """Publication-safe token wrapping without corrupting mathematics.

    Ordinary prose and short mathematical identifiers remain intact. Long file names,
    JSON keys, paths, URLs and digests receive explicit break opportunities. Long
    formula tokens break only at semantic operators, never inside alpha_s/beta_s-like
    subscripts. This keeps referee tables inside the page while preserving notation.
    """
    raw = "" if value is None else str(value)

    def _break_formula(token: str) -> str:
        out=[]; seg=0
        for ch in token:
            out.append(_html.escape(ch)); seg += 1
            if ch == "=":
                out.append("<br/>"); seg=0
            elif ch in "+-;," and seg >= 9:
                out.append("<br/>"); seg=0
            elif seg >= 16 and ch in "/.)":
                out.append("<br/>"); seg=0
        return "".join(out)

    def _break_machine(token: str) -> str:
        out=[]; seg=0
        for ch in token:
            out.append(_html.escape(ch)); seg += 1
            if ch in "_-/\\:.;" and seg >= 4:
                out.append("<br/>"); seg=0
            elif seg >= 12:
                out.append("<br/>"); seg=0
        return "".join(out)

    def _break_token(token: str) -> str:
        if re.fullmatch(r"[0-9A-Fa-f]{20,}", token):
            return "<br/>".join(_html.escape(token[i:i+12]) for i in range(0,len(token),12))
        # Formula detection precedes machine/path detection because dS/dt and
        # h_sigma(U) contain characters that otherwise resemble identifiers.
        is_formula = any(ch in token for ch in "()^=*+") or bool(re.search(r"(?:alpha|beta|sigma|delta|gamma|BASIN_TOL|dS/dt|W\(|h_sigma)", token))
        if is_formula:
            return _break_formula(token)
        # Machine identifiers must be classified BEFORE the short-token exemption.
        # IDs such as CFG-CERT-SPAN and OBSERVE-ONLY are short enough to evade the
        # old breaker but still too wide for narrow 11 pt referee-table cells.
        if any(ch in token for ch in "_/\\:.;-"):
            return _break_machine(token)
        if len(token) <= 16:
            return _html.escape(token)
        return _html.escape(token)

    pieces = re.split(r"(\s+)", raw)
    return "".join(_html.escape(x) if x.isspace() else _break_token(x) for x in pieces)



def _oc_pdffonts_embedding_audit(pdf_path: str) -> Dict[str, Any]:
    """Audit embedded-font status with Poppler when available.

    Font embedding is necessary for the engine's archival/diligence publication contract,
    although this check alone does not assert full PDF/A conformance.
    """
    import shutil as _shutil, subprocess as _subprocess
    exe=_shutil.which("pdffonts")
    if not exe:
        return {"status":"SKIPPED","reason":"pdffonts unavailable","unembedded":[]}
    cp=_subprocess.run([exe,str(pdf_path)],capture_output=True,text=True,timeout=30)
    rows=[]
    for line in cp.stdout.splitlines()[2:]:
        parts=line.split()
        if len(parts) >= 6:
            # Poppler columns include name/type/encoding/emb/sub/uni/object. Find emb token robustly.
            emb_idx = next((i for i,x in enumerate(parts) if x in ("yes","no") and i>=3), None)
            if emb_idx is not None and parts[emb_idx]=="no": rows.append(line.strip())
    return {"status":"PASS" if not rows else "FAIL","unembedded":rows,"raw_returncode":cp.returncode}

def _oc_cell_paragraph(value: Any, style: ParagraphStyle) -> Paragraph:
    return Paragraph(_oc_soft_break_html(value), style)


def _oc_scale_widths(widths: List[float], maximum: float = OC_SAFE_BODY_WIDTH_PT) -> List[float]:
    vals=[max(12.0,float(x)) for x in widths]
    total=sum(vals)
    if total <= maximum + 1e-9:
        return vals
    factor=maximum/total
    return [x*factor for x in vals]

def _oc_ev_make_table(data: List[List[Any]], widths: List[float], font_size: float = 11.0, header_rows: int = 1) -> Table:
    """Build a margin-safe table whose every textual cell wraps at 11 pt or larger."""
    font_size=max(11.0,float(font_size)); widths=_oc_scale_widths(widths)
    cell_style=ParagraphStyle("EvidenceCell",fontName="OCSans",fontSize=font_size,
        leading=max(13.4,font_size+2.4),splitLongWords=False,wordWrap="LTR",
        allowWidows=0,allowOrphans=0,spaceAfter=0,spaceBefore=0)
    head_style=ParagraphStyle("EvidenceHead",fontName="OCSans-Bold",fontSize=font_size,
        leading=max(13.4,font_size+2.4),alignment=1,splitLongWords=False,wordWrap="LTR",
        allowWidows=0,allowOrphans=0,spaceAfter=0,spaceBefore=0)
    cooked=[]
    for ri,row in enumerate(data):
        style=head_style if ri<header_rows else cell_style
        cooked.append([v if isinstance(v,(Paragraph,Table,Image)) else _oc_cell_paragraph(v,style) for v in row])
    t=Table(cooked,repeatRows=header_rows,colWidths=widths,hAlign="LEFT",splitByRow=1,splitInRow=1)
    t.setStyle(TableStyle([
        ("BACKGROUND",(0,0),(-1,header_rows-1),colors.lightgrey),
        ("GRID",(0,0),(-1,-1),0.40,colors.grey),("VALIGN",(0,0),(-1,-1),"TOP"),
        ("LEFTPADDING",(0,0),(-1,-1),6),("RIGHTPADDING",(0,0),(-1,-1),6),
        ("TOPPADDING",(0,0),(-1,-1),5),("BOTTOMPADDING",(0,0),(-1,-1),5),
    ]))
    return t

def _oc_pdf_evidence_summary(value: Any, max_chars: int = 220) -> str:
    """Publication-safe evidence synopsis; full evidence remains in JSON/CSV/TXT artifacts."""
    if value is None: return ""
    if isinstance(value, dict):
        status=str(value.get("status", "")).strip()
        kind_raw=str(value.get("kind", "")).strip()
        kind_map={
            "portable_source_identity_plus_environment_ast_diagnostic":"portable source identity",
            "authoritative_equation_text":"canonical equation text",
            "public_equation_plate":"public equation plate",
            "canonical_runtime_constant":"runtime constant",
        }
        kind=kind_map.get(kind_raw, kind_raw.replace("_", " "))
        exp=str(value.get("expected_source_sha256", value.get("expected_sha256", ""))).strip()
        obs=str(value.get("observed_source_sha256", value.get("observed_sha256", ""))).strip()
        if exp or obs:
            short=lambda x: x if len(x)<=12 else f"{x[:6]}..{x[-4:]}"
            match=(exp and obs and exp==obs)
            parts=[]
            if match: parts.append("digest match=YES")
            elif status: parts.append(f"status={status.replace('_',' ')}")
            if kind: parts.append(f"class={kind}")
            if exp: parts.append(f"exp {short(exp)}")
            if obs and obs!=exp: parts.append(f"obs {short(obs)}")
            return "; ".join(parts)
        if "expected_value" in value or "observed_value" in value:
            ev=value.get("expected_value"); ov=value.get("observed_value")
            return f"expected={ev}; observed={ov}; status={status.replace('_',' ') or ('PASS' if ev==ov else 'REVIEW')}"
        compact={k:value[k] for k in list(value)[:5]}
        # Human-facing PDF synopsis uses readable keys; exact machine keys remain in JSON/CSV/TXT.
        compact={str(k).replace("_", " "):v for k,v in compact.items()}
        text=json.dumps(compact,ensure_ascii=False,default=str,separators=(", ",": "))
        # Long cryptographic digests remain complete in machine artifacts; the PDF uses
        # a stable prefix/suffix synopsis so hashes cannot overrun table geometry.
        text=__import__("re").sub(r"(?i)(?<![0-9a-f])[0-9a-f]{32,}(?![0-9a-f])", lambda m: m.group(0)[:8]+"..."+m.group(0)[-6:], text)
        if len(value)>len(compact): text+=f"; +{len(value)-len(compact)} additional fields"
    elif isinstance(value,(list,tuple)):
        preview=list(value[:4]); text=json.dumps(preview,ensure_ascii=False,default=str)
        if len(value)>len(preview): text+=f"; +{len(value)-len(preview)} additional items"
    else: text=str(value)
    text=" ".join(text.split())
    return text if len(text)<=max_chars else text[:max_chars-3]+"..."

def _oc_pdf_validation_message(record: Dict[str, Any]) -> str:
    msg=" ".join(str(record.get("message","")).split()); code=str(record.get("code","")); sev=str(record.get("severity",""))
    if code.startswith("CORE-LOCK-") and sev.upper()=="INFO" and "PORTABILITY DIAGNOSTIC" in msg.upper():
        surface=code[len("CORE-LOCK-"):] or str(record.get("surface","canonical core"))
        return f"Authoritative source identity for {surface} is VERIFIED. Environment-specific AST digest variance is informational only; no mathematical, source, or behavioral change is inferred."
    return msg



def _oc_compact_report_pagebreaks(flowables, preserve_hard_breaks: int = 3, reserve_height: float = 180.0):
    """Convert body-only hard page breaks to conditional breaks.

    The first three hard breaks preserve the full-bleed cover, complete page-two
    invitation, and page-three Table of Contents. Later section boundaries start
    a new page only when the remaining frame cannot hold a useful opening block.
    This prevents a trailing paragraph or short table continuation from creating
    a mostly empty page immediately before another forced page break.
    """
    if PageBreak is None or CondPageBreak is None:
        return list(flowables)
    compacted = []
    hard_seen = 0
    for item in flowables:
        if isinstance(item, PageBreak):
            hard_seen += 1
            if hard_seen <= int(preserve_hard_breaks):
                compacted.append(item)
            else:
                compacted.append(CondPageBreak(float(reserve_height)))
        else:
            compacted.append(item)
    return compacted



def _oc_seeded_subset(rows: List[Dict[str, Any]], seed: int, count: int = 100) -> Tuple[List[Dict[str, Any]], List[int]]:
    """Return a reproducible strict subset and its parent indices."""
    parent = list(rows)
    n = min(max(0, int(count)), len(parent))
    if n >= len(parent):
        return parent, list(range(len(parent)))
    rng = random.Random(int(seed))
    indices = list(range(len(parent)))
    rng.shuffle(indices)
    picked = sorted(indices[:n])
    return [parent[i] for i in picked], picked


def _oc_companion_classification_rows() -> List[List[str]]:
    return [
        ["Content class", "Report treatment", "Controlling limitation"],
        ["Owner / historical statement", "Preserved as the owner's account", "Not mathematical proof, novelty adjudication, or empirical validation"],
        ["Originality / significance position", "Owner-asserted position", "Independent prior-art, patent, scientific, and market review remain separate"],
        ["Introductory 10% benchmark", "Nonbinding commercial-planning arithmetic", "Not a permanent public price, quote, offer, guarantee, or final transaction term"],
        ["Modeled economic output", "Executed synthetic model under declared assumptions", "Not customer production truth, audited savings, or guaranteed return"],
        ["Rights / IP statement", "Owner representation and public-record route", "Official records and definitive agreements control"],
        ["Forward-looking statement", "Expectation concerning demand, pricing, adoption, or value", "May differ materially because of technical, legal, market, competitive, and execution outcomes"],
        ["Deployment / workforce discussion", "Planning and diligence material", "Not employment, legal, safety, regulatory, or production advice"],
    ]


