def _oc_write_companion_report(outdir: Path, batch_id: str, summary: Dict[str, Any], cfg_snapshot: Dict[str, Any], meta: Dict[str, Any]) -> Dict[str, str]:
    """Emit the standalone owner/executive/commercial/legal companion family."""
    outdir = Path(outdir)
    stem = f"OMNI-COMPASS_OWNER_EXECUTIVE_COMMERCIAL_LEGAL_COMPANION_{batch_id}"
    pdf_path = outdir / f"{stem}.pdf"
    txt_path = outdir / f"{stem}.txt"
    html_path = outdir / f"{stem}.html"
    json_path = outdir / f"{stem}.json"
    jsonl_path = outdir / f"{stem}.jsonl"
    csv_path = outdir / f"{stem}.csv"
    sections = _oc_companion_sections(summary, cfg_snapshot, meta)

    # Machine-readable mirrors.
    payload = {
        "report_profile": OC_REPORT_PROFILE_COMPANION,
        "title": OC_COMPANION_TITLE,
        "batch_id": batch_id,
        "engine_sha256": meta.get("engine_sha256", meta.get("source_sha256")),
        "run_hash": meta.get("run_hash"),
        "timestamp_eastern": meta.get("timestamp_eastern"),
        "introductory_license_rate": OC_INTRODUCTORY_LICENSE_RATE,
        "official_route": OC_LICENSE_PRICING_ROUTE,
        "sections": [{"title": title, "lines": lines} for title, lines in sections],
        "classification_register": [dict(zip(_oc_companion_classification_rows()[0], row)) for row in _oc_companion_classification_rows()[1:]],
    }
    json_path.write_text(json.dumps(payload, indent=2, ensure_ascii=False, default=str), encoding="utf-8")
    with jsonl_path.open("w", encoding="utf-8") as f:
        for idx, (title, lines) in enumerate(sections, 1):
            f.write(json.dumps({"section_index": idx, "title": title, "lines": lines, "batch_id": batch_id}, ensure_ascii=False, default=str) + "\n")
    with csv_path.open("w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["section_index", "section_title", "line_index", "content", "content_class"])
        for sidx, (title, lines) in enumerate(sections, 1):
            for lidx, line in enumerate(lines, 1):
                content_class = "companion_declaration"
                low = str(line).lower()
                if "10%" in low or "license" in low or "pricing" in low:
                    content_class = "commercial_licensing"
                elif "patent" in low or "copyright" in low or "trademark" in low or "rights" in low:
                    content_class = "legal_ip_notice"
                elif "modeled" in low or "executed" in low or "benchmark" in low:
                    content_class = "evidence_or_model_boundary"
                writer.writerow([sidx, title, lidx, line, content_class])

    with txt_path.open("w", encoding="utf-8") as f:
        f.write(OC_COMPANION_TITLE + "\n")
        f.write("=" * len(OC_COMPANION_TITLE) + "\n")
        f.write(f"Batch ID: {batch_id}\nOfficial route: www.omni-compass.com\n\n")
        for title, lines in sections:
            f.write(title + "\n" + "-" * len(title) + "\n")
            for line in lines:
                f.write(str(line) + "\n")
            f.write("\n")

    with html_path.open("w", encoding="utf-8") as f:
        f.write("<html><head><meta charset='utf-8'><title>" + _html.escape(OC_COMPANION_TITLE) + "</title></head><body>")
        f.write("<h1>" + _html.escape(OC_COMPANION_TITLE) + "</h1>")
        f.write(f"<p><b>Batch ID:</b> {_html.escape(batch_id)}<br/><b>Official route:</b> www.omni-compass.com</p>")
        for title, lines in sections:
            f.write("<h2>" + _html.escape(title) + "</h2>")
            for line in lines:
                f.write("<p>" + _html.escape(str(line)) + "</p>")
        f.write("</body></html>")

    styles = getSampleStyleSheet()
    for style in styles.byName.values():
        try:
            style.fontName = "OCSans-Bold" if "Heading" in str(getattr(style, "name", "")) or getattr(style, "name", "") == "Title" else "OCSans"
            style.fontSize = max(11.0, float(getattr(style, "fontSize", 11.0) or 11.0))
            style.leading = max(13.2, float(getattr(style, "leading", 13.2) or 13.2))
        except Exception as _oc_exc:
            logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
    body = ParagraphStyle("OCCompanionBody", parent=styles["Normal"], fontName="OCSans", fontSize=11.0, leading=13.4, spaceAfter=5)
    small = ParagraphStyle("OCCompanionSmall", parent=body, fontSize=11.0, leading=13.2, spaceAfter=3)
    toc = TableOfContents(dotsMinLevel=0)
    toc.levelStyles = [
        ParagraphStyle("OCCompanionTOC0", fontName="OCSans-Bold", fontSize=11.0, leading=13.4, leftIndent=0, spaceAfter=1),
        ParagraphStyle("OCCompanionTOC1", fontName="OCSans", fontSize=11.0, leading=13.2, leftIndent=14, spaceAfter=0.4),
    ]
    story: List[Any] = [_OCTOCMarker("OFFICIAL COMPANION COVER", 0), PageBreak()]
    story.append(_OCTOCMarker("REPORT CLASSIFICATION & PURPOSE", 0))
    story.append(Paragraph("<b>REPORT CLASSIFICATION &amp; PURPOSE</b>", styles["Heading1"]))
    story.append(Spacer(1, 8))
    story.append(Paragraph(_html.escape("This is a standalone companion report generated as part of the authenticated execution package. Its owner, historical, executive, commercial, legal, IP, workforce, valuation, and forward-looking content is not numerical evidence unless a specific item is expressly identified as an executed model output."), body))
    story.append(Paragraph(_html.escape(OC_LICENSE_PRICING_NOTICE), body))
    story.append(Paragraph(_html.escape(OC_IP_RECORDS_AND_DILIGENCE_NOTICE), body))
    story.append(PageBreak())
    story.append(_OCTOCMarker(OC_TOC_TITLE, 0))
    story.append(Paragraph(f"<b>{OC_TOC_TITLE}</b>", styles["Heading1"]))
    story.append(Spacer(1, 10))
    story.append(toc)
    story.append(PageBreak())
    # Charts belong WITH the text they support, not bulk-dumped at the back.
    # Each companion section receives only the figures that evidence that
    # section's own subject matter, placed immediately after its text.
    _cmp_charts = _oc_companion_chart_map(meta, Path(str(pdf_path)).parent)
    _cmp_embedded = 0

    for idx, (title, lines) in enumerate(sections):
        level = 1 if title.startswith("APPENDIX") else 0
        story.append(_OCTOCMarker(title, level))
        story.append(Paragraph(f"<b>{_html.escape(title)}</b>", styles["Heading1"] if level == 0 else styles["Heading2"]))
        story.append(Spacer(1, 8))
        for line in lines:
            story.append(Paragraph(_sub_str(_html.escape(str(line)), "\n", "<br/>"), small))

        _figs = _oc_charts_for_section(title, _cmp_charts)
        if _figs:
            story.append(Spacer(1, 12))
            story.append(Paragraph(
                f"<b>{_html.escape('SUPPORTING FIGURES FOR THIS SECTION')}</b>", small))
            story.append(Paragraph(_html.escape(
                f"Figures: {len(_figs)}. Execution batch: {meta.get('batch_id','current')}. Each figure "
                "is an unaltered artifact of this execution, identified by its generating filename. "
                "Modelled economic figures are public-source model outputs and are not vendor quotes, "
                "contracts, invoices, appraisals, or measured customer results."), small))
            story.append(Spacer(1, 8))
            for _p in _figs:
                _pth = Path(str(_p))
                try:
                    story.append(Paragraph(f"<b>{_html.escape(_oc_chart_caption(_pth.name))}</b>", small))
                    story.append(Spacer(1, 3))
                    story.append(Image(str(_pth), width=498, height=300, kind="proportional"))
                    story.append(Spacer(1, 3))
                    story.append(Paragraph(_html.escape(f"Source artifact: {_pth.name}"), small))
                    story.append(Spacer(1, 10))
                    _cmp_embedded += 1
                except Exception:
                    continue
        if idx < len(sections) - 1:
            story.append(PageBreak())

    meta["companion_chart_images_embedded"] = int(_cmp_embedded)


    _companion_outline_counter = {"value": 0}

    def after_flowable(flowable):
        if isinstance(flowable, _OCTOCMarker):
            _companion_outline_counter["value"] += 1
            _bookmark = f"oc_companion_{_companion_outline_counter['value']}"
            try:
                doc.canv.bookmarkPage(_bookmark)
                doc.canv.addOutlineEntry(
                    flowable.title, _bookmark, level=max(0, int(flowable.level)), closed=False
                )
            except Exception as _oc_exc:
                logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
            toc.addEntry(flowable.level, flowable.title, doc.page)

    def companion_cover(canvas, doc):
        canvas.setProducer(OC_PDF_PRODUCER)
        canvas.setCreator("Omni-Compass Python Report Engine")
        canvas.setAuthor("The Omni-Compass LLC")
        w, h = doc.pagesize
        canvas.saveState()
        canvas.setFillColor(colors.HexColor(OC_VISUAL_PALETTE["ink"]))
        canvas.rect(0, 0, w, h, stroke=0, fill=1)
        canvas.setStrokeColor(colors.HexColor(OC_VISUAL_PALETTE["sky"]))
        canvas.setLineWidth(2.2)
        canvas.rect(28, 28, w - 56, h - 56, stroke=1, fill=0)
        canvas.setFillColor(colors.white)
        canvas.setFont("OCSans-Bold", 17)
        canvas.drawCentredString(w / 2, h - 92, "THE OMNI-COMPASS")
        canvas.setFont("OCSans-Bold", 21)
        for y, line in [(h - 205, "OWNER, EXECUTIVE, COMMERCIAL,"), (h - 237, "LEGAL & HISTORICAL COMPANION")]:
            canvas.drawCentredString(w / 2, y, line)
        canvas.setFont("OCSans", 12)
        canvas.drawCentredString(w / 2, h - 286, "Companion to the Integrated 500-Run and Technical 100-Run Reports")
        canvas.drawCentredString(w / 2, h - 337, f"Batch ID: {batch_id}")
        canvas.drawCentredString(w / 2, h - 360, str(meta.get("timestamp_eastern", meta.get("timestamp_utc", ""))))
        canvas.setFont("OCSans-Bold", 12)
        canvas.drawCentredString(w / 2, 108, "The Omni-Compass LLC")
        canvas.setFont("OCSans", 11)
        canvas.drawCentredString(w / 2, 84, "www.omni-compass.com")
        canvas.restoreState()

    doc = SimpleDocTemplate(
        str(pdf_path), pagesize=LETTER,
        leftMargin=OC_PAGE_LEFT_MARGIN_PT, rightMargin=OC_PAGE_RIGHT_MARGIN_PT,
        topMargin=OC_PAGE_TOP_MARGIN_PT, bottomMargin=OC_PAGE_BOTTOM_MARGIN_PT,
        title=OC_COMPANION_TITLE, author="The Omni-Compass LLC",
        subject="Owner, executive, commercial, licensing, legal, historical, IP, valuation, workforce, deployment, and diligence companion",
        creator="Omni-Compass Python Report Engine", lang="en-US",
    )
    doc.afterFlowable = after_flowable

    # Page order: page 1 = the companion's own title/cover page so a reader
    # identifies the document immediately; page 2 = the verified embedded
    # identity cover sheet; page 3 = content. Two leading page breaks reserve
    # pages 1 and 2 for the canvas-drawn covers.
    # The companion story opens as [cover TOC marker, PageBreak, content...].
    # The identity cover sheet is placed on page 2 by inserting AFTER that
    # existing break (index 2), with its own TOC marker so the page is indexed.
    story.insert(2, PageBreak())
    story.insert(2, _OCTOCMarker("OFFICIAL FULL-BLEED IDENTITY COVER", 0))

    def _oc_companion_cover_or_report_page(canvas, doc):
        canvas.setProducer(OC_PDF_PRODUCER)
        canvas.setCreator("Omni-Compass Python Report Engine")
        canvas.setAuthor("The Omni-Compass LLC")
        if int(getattr(doc, "page", 0)) == 2:
            _oc_draw_static_identity_cover(canvas, doc)
            return
        _draw_oc_header_footer(canvas, doc)

    # Normalize section boundaries before the terminal plate. Forced body PageBreaks
    # become conditional breaks, preventing header/footer-only separator pages when
    # a preceding chart/table has already ended exactly at a frame boundary.
    story = _oc_compact_report_pagebreaks(story, preserve_hard_breaks=3, reserve_height=180.0)
    _oc_append_closing_plate(story)

    doc.multiBuild(story, maxPasses=7, onFirstPage=companion_cover,
                   onLaterPages=_oc_companion_cover_or_report_page)
    return {
        "companion_pdf": str(pdf_path), "companion_txt": str(txt_path), "companion_html": str(html_path),
        "companion_json": str(json_path), "companion_jsonl": str(jsonl_path), "companion_csv": str(csv_path),
    }

def _oc_discover_run_charts(meta, outdir):
    """Discover every chart PNG this execution actually wrote to disk.

    NOTHING IS FABRICATED. This locates only image files the engine itself
    produced during the current run. If a suite did not execute, its group is
    simply absent. Groups are returned in a fixed, declared order so the appendix
    sequence, the table of contents, and page numbering are stable and
    reproducible across runs and across ReportLab multiBuild passes.

    Returns [(appendix_letter, group_title, [Path, ...]), ...]
    """
    from pathlib import Path as _P
    try:
        base = _P(str(outdir))
    except Exception:
        return []
    batch = str(meta.get("batch_id", "") or "")

    def _dir(key, fallback):
        raw = meta.get(key)
        if raw:
            p = _P(str(raw))
            if p.is_dir():
                return p
        p = base / fallback
        return p if p.is_dir() else None

    def _pngs(d):
        if d is None:
            return []
        try:
            return sorted([f for f in _P(str(d)).glob("*.png") if f.is_file()], key=lambda x: x.name)
        except Exception:
            return []

    groups = []
    ms = _dir("global_stack_output_dir", "GLOBAL_MEGASTACK_ARTIFACTS_" + batch)
    if ms is not None:
        a = _pngs(_P(str(ms)) / "CHARTS_500_RUN")
        if a:
            groups.append(("AV", "GLOBAL MEGASTACK CHART SET - FULL CANONICAL POPULATION", a))
        b = _pngs(_P(str(ms)) / "CHARTS_100_SAMPLE")
        if b:
            groups.append(("AW", "GLOBAL MEGASTACK CHART SET - DETERMINISTIC SEEDED SAMPLE", b))
        pm = _P(str(ms)) / "PUBLIC_ENTERPRISE_MANAGER_BENCHMARK"
        c = _pngs(pm / "CHARTS_500_RUN")
        d = _pngs(pm / "CHARTS_100_SAMPLE")
        if c or d:
            groups.append(("AX", "PUBLIC ENTERPRISE MANAGER MECHANISM BENCHMARK CHART SET", list(c) + list(d)))

    comp = _pngs(_dir("compute_output_dir", "COMPUTE_INFRASTRUCTURE_ARTIFACTS_" + batch))
    mgr = _pngs(_dir("manager_output_dir", "FRAGMENTED_STACK_GOVERNANCE_ARTIFACTS_" + batch))
    if comp or mgr:
        groups.append(("AY", "COMPUTE INFRASTRUCTURE & FRAGMENTED-STACK GOVERNANCE CHART SET", list(comp) + list(mgr)))

    eve = _pngs(_dir("evidence_output_dir", "NUMERICAL_EVIDENCE_ARTIFACTS_" + batch))
    figs = _pngs(base / "_oc_evidence_figs")
    seen, merged = set(), []
    for f in list(eve) + list(figs):
        if f.name not in seen:
            seen.add(f.name)
            merged.append(f)
    if merged:
        groups.append(("AZ", "NUMERICAL EVIDENCE FIGURE SET", merged))
    return groups


