def _oc_figures_for_principal_section(title, chart_index):
    """Figures evidencing this principal-report section, in declared order."""
    if not chart_index:
        return []
    t = str(title or "").upper()
    for prefix, patterns in OC_PRINCIPAL_SECTION_FIGURES:
        if not t.startswith(prefix.upper()):
            continue
        out, seen = [], set()
        for pat in patterns:
            for name, path in chart_index.items():
                if pat.upper() in name and name not in seen:
                    seen.add(name)
                    out.append(path)
        return out
    return []


def _oc_companion_chart_map(meta, outdir):
    """Flat name->path index of every chart this execution produced."""
    idx = {}
    try:
        for _letter, _title, paths in _oc_discover_run_charts(meta, outdir):
            for p in paths:
                idx[str(getattr(p, "name", p)).upper()] = p
    except Exception:
        return {}
    return idx


