        # Fill Section 22 placeholders using the same executed identifiers/timestamps as Section 1.
        def _fill_section22_placeholders(text_in: str) -> str:
            try:
                ts_e = str(meta.get("timestamp_eastern", "")).strip()
            except Exception:
                ts_e = ""
            date_line = ""
            time_line = ""
            m_ts = re.match(r"^(\d{2}/\d{2}/\d{4})\s+(\d{2}:\d{2}:\d{2}\s+[AP]M)", ts_e)
            if m_ts:
                date_line = m_ts.group(1)
                time_line = m_ts.group(2)
            else:
                date_line = ts_e or "(unknown)"
                time_line = ""

            pr_local = meta.get("parameter_ranges", {})
            try:
                cfg_hash_src = json.dumps({"cfg_snapshot": cfg_snapshot, "parameter_ranges": pr_local}, sort_keys=True, default=str)
            except Exception:
                cfg_hash_src = repr({"cfg_snapshot": cfg_snapshot, "parameter_ranges": pr_local})
            cfg_hash_local = hashlib.sha256(cfg_hash_src.encode("utf-8")).hexdigest()[:16]

            try:
                with open(__file__, "rb") as f:
                    code_fp = hashlib.sha256(f.read()).hexdigest()[:16]
            except Exception:
                code_fp = "(unavailable)"

            out = text_in
            out = _sub_str(out, "<YYYY-MM-DD>", date_line)
            out = _sub_str(out, "<HH:MM:SS>", time_line if time_line else "(unknown)")
            out = _sub_str(out, "<UTC offset>", "Eastern United States ")
            out = _sub_str(out, "<UUID or hash>", f"MC_BATCH_{meta.get('batch_id','(unknown)')}")
            out = _sub_str(out, "<hash of parameters/config>", cfg_hash_local)
            out = _sub_str(out, "<source fingerprint>", code_fp)
            return out

