def _oc_make_fig_failure_case(path, title, rows):
    import statistics,hashlib,json
    best_series=None; best_score=-1.0; best_meta=None
    for r in rows or []:
        series=_parse_list_maybe(r.get("U_history"))
        if not isinstance(series,list) or len(series)<12: continue
        diffs=[series[i]-series[i-1] for i in range(1,len(series))]; score=statistics.pstdev(diffs) if len(diffs)>2 else 0.0
        regime=str(r.get("regime_label","")).lower(); term=str(r.get("terminal_reason","")).lower()
        if any(k in regime or k in term for k in ("osc","edge")): score+=1.0
        if score>best_score: best_score=score; best_series=series; best_meta=(r.get("run_id"),r.get("seed"))
    if best_series is None: raise RuntimeError("Appendix I requires real trajectory data (U_history missing)")
    mu=sum(best_series)/len(best_series); ys=[u-mu for u in best_series]; xs=list(range(len(ys))); digest=hashlib.sha256(json.dumps([round(v,10) for v in best_series]).encode("utf-8")).hexdigest()[:16]; run_id,seed=best_meta
    fig,ax=plt.subplots(figsize=(8.20,5.60)); ax.plot(xs,ys,color=OC_VISUAL_PALETTE["vermillion"],marker="o",markevery=max(1,len(xs)//8)); ax.axhline(0,color=OC_VISUAL_PALETTE["slate"],linestyle="--")
    ax.set_title(title); ax.set_xlabel("Step"); ax.set_ylabel("U - mean(U)"); _oc_style_axes(ax,grid="both"); _oc_save_figure(fig,path,note=f"Appendix I source: run_id={run_id} seed={seed} sha256[:16]={digest}; {OC_VISUAL_SYSTEM_ID}",dpi=170); plt.close(fig)


