# =============================================================================
# OMNI-COMPASS NUMERICAL EVIDENCE, ROBUSTNESS, AND VERIFICATION SUITE
# =============================================================================
# This layer does not alter the canonical equations, RK4 function, canonical
# Monte Carlo sampler, conveyance logic, certification logic, or default run.
# It executes separately declared verification and benchmark modes around the
# canonical engine and writes independent evidence artifacts.
# =============================================================================

@dataclass
class EvidenceCase:
    case_id: int
    state0: OCState
    params: OCParameters


@dataclass
class EvidenceTrajectory:
    case_id: int
    mode: str
    micro_steps: int
    state_history: List[OCState]
    U_history: List[float]
    conveyed: bool
    certified: bool
    born_in_basin: bool
    first_basin_entry_step: Optional[int]
    conveyed_entry_step: Optional[int]
    conveyance_confirmed_step: Optional[int]
    certification_start_step: Optional[int]
    certified_step: Optional[int]
    final_basin_sign: int
    basin_switches: int
    max_same_basin_streak: int
    regulation_abs_total: float
    regulation_sq_total: float
    regulation_peak: float
    invariance_interventions: int
    attempted_exits: int
    divergence: bool
    candidate_energy: List[float]
    basin_margin_history: List[float]
    contraction_ratios: List[float]

    def final_state(self) -> OCState:
        return self.state_history[-1]

    def to_dict(self) -> Dict[str, Any]:
        fs = self.final_state()
        return {
            "case_id": self.case_id,
            "mode": self.mode,
            "micro_steps": self.micro_steps,
            "conveyed": self.conveyed,
            "certified": self.certified,
            "born_in_basin": self.born_in_basin,
            "first_basin_entry_step": self.first_basin_entry_step,
            "conveyed_entry_step": self.conveyed_entry_step,
            "conveyance_confirmed_step": self.conveyance_confirmed_step,
            "certification_start_step": self.certification_start_step,
            "certified_step": self.certified_step,
            "final_basin_sign": self.final_basin_sign,
            "basin_switches": self.basin_switches,
            "max_same_basin_streak": self.max_same_basin_streak,
            "regulation_abs_total": self.regulation_abs_total,
            "regulation_sq_total": self.regulation_sq_total,
            "regulation_peak": self.regulation_peak,
            "invariance_interventions": self.invariance_interventions,
            "attempted_exits": self.attempted_exits,
            "divergence": self.divergence,
            "final_E": fs.E,
            "final_U": fs.U,
            "final_I_U": fs.I_U,
            "final_S": fs.S,
            "final_B": fs.B,
            "final_B_dot": fs.B_dot,
            "minimum_basin_margin": min(self.basin_margin_history) if self.basin_margin_history else None,
            "median_contraction_ratio": float(np.median(self.contraction_ratios)) if self.contraction_ratios else None,
            "candidate_energy_decrease_fraction": (
                float(np.mean(np.diff(self.candidate_energy) <= 0.0))
                if len(self.candidate_energy) >= 2 else None
            ),
        }


@dataclass
class EvidenceSuiteConfig:
    profile: str = "quick"
    seed: int = 20260719
    output_dir: str = "./omni-compass_evidence"
    step_size_cases: int = 12
    cross_solver_cases: int = 6
    ablation_cases: int = 40
    repeated_seed_batches: int = 4
    repeated_seed_runs: int = 100
    max_sample_size: int = 500
    threshold_cases: int = 80
    sensitivity_samples: int = 48
    robustness_cases: int = 40
    noise_cases: int = 30
    adversarial_repeats: int = 1
    bootstrap_resamples: int = 250

    @classmethod
    def from_profile(cls, profile: str, seed: int, output_dir: str) -> "EvidenceSuiteConfig":
        p = str(profile or "quick").lower()
        if p == "full":
            return cls(
                profile="full", seed=seed, output_dir=output_dir,
                # Full-referee auxiliary suite. The canonical master population remains 500.
                step_size_cases=16, cross_solver_cases=10, ablation_cases=80,
                repeated_seed_batches=4, repeated_seed_runs=125,
                max_sample_size=500, threshold_cases=100,
                sensitivity_samples=32, robustness_cases=48, noise_cases=500,
                adversarial_repeats=2, bootstrap_resamples=400,
            )
        return cls(profile="quick", seed=seed, output_dir=output_dir)


def _ev_state_copy(s: OCState) -> OCState:
    return OCState(E=float(s.E), U=float(s.U), I_U=float(s.I_U), S=float(s.S), B=float(s.B), B_dot=float(s.B_dot))


def _ev_param_copy(p: OCParameters) -> OCParameters:
    return OCParameters(**{k: float(v) for k, v in p.__dict__.items()})


def _ev_draw_cases(seed: int, n: int) -> List[EvidenceCase]:
    rng = np.random.default_rng(int(seed) % (2**63 - 1))
    cases: List[EvidenceCase] = []
    for i in range(int(n)):
        cases.append(EvidenceCase(i, sample_initial_state(rng), sample_parameters(rng)))
    return cases


def _ev_basin_sign(U: float, tol: float = BASIN_TOL) -> int:
    if abs(float(U) - 1.0) <= float(tol):
        return +1
    if abs(float(U) + 1.0) <= float(tol):
        return -1
    return 0


def _ev_nearest_basin(U: float) -> int:
    return +1 if abs(float(U) - 1.0) <= abs(float(U) + 1.0) else -1


def _ev_basin_margin(U: float, tol: float = BASIN_TOL) -> float:
    sign = _ev_nearest_basin(U)
    center = float(sign)
    return float(tol - abs(float(U) - center))


def _ev_classify_history(
    U_history: List[float], tol: float = BASIN_TOL,
    convey_window: int = STABILITY_WINDOW, cert_steps: int = CERTIFICATION_STEPS,
) -> Dict[str, Any]:
    signs = [_ev_basin_sign(u, tol) for u in U_history]
    born = bool(signs and signs[0] != 0)
    first_entry = next((i for i, s in enumerate(signs) if s != 0), None)
    convey_sign = signs[0] if born else 0
    convey_streak = 1 if born else 0
    cert_sign = signs[0] if born else 0
    cert_streak = 1 if born else 0
    max_streak = max(convey_streak, cert_streak)
    conveyed_entry = None
    conveyed_confirm = None
    cert_start = None
    certified_step = None
    prior_nonzero = signs[0] if signs else 0
    switches = 0
    for step in range(1, len(signs)):
        s = signs[step]
        if s != 0 and prior_nonzero != 0 and s != prior_nonzero:
            switches += 1
        if s != 0:
            prior_nonzero = s
        if s != 0:
            if s == convey_sign:
                convey_streak += 1
            else:
                convey_sign = s
                convey_streak = 1
            if s == cert_sign:
                cert_streak += 1
            else:
                cert_sign = s
                cert_streak = 1
        else:
            convey_sign = 0
            convey_streak = 0
            cert_sign = 0
            cert_streak = 0
        max_streak = max(max_streak, convey_streak, cert_streak)
        if conveyed_confirm is None and convey_streak >= convey_window:
            conveyed_entry = step - convey_window + 1
            conveyed_confirm = step
        if certified_step is None and cert_streak >= cert_steps:
            cert_start = step - cert_steps + 1
            certified_step = step
    return {
        "born": born,
        "first_entry": first_entry,
        "conveyed": conveyed_confirm is not None,
        "conveyed_entry": conveyed_entry,
        "conveyed_confirm": conveyed_confirm,
        "certified": certified_step is not None,
        "cert_start": cert_start,
        "certified_step": certified_step,
        "final_sign": signs[-1] if signs else 0,
        "switches": switches,
        "max_streak": max_streak,
    }


def _ev_regulate(U: float, lock_sign: int, gain: float, mode: str, tol: float) -> Tuple[float, int, float, bool, bool]:
    mode = str(mode).lower()
    if mode == "off":
        return float(U), int(lock_sign), 0.0, False, False

    nominal = float(max(0.0, min(1.0, gain)))
    sign = int(lock_sign)

    # Match the canonical pre-acquisition rule exactly: move toward the nearest
    # center, but do not create a lock until the regulated state actually enters
    # a declared basin.
    if sign not in (-1, +1):
        target_sign = _ev_nearest_basin(U)
        target = float(target_sign)
        regulated = float(U + nominal * (target - U))
        acquired = _ev_basin_sign(regulated, tol)
        return regulated, int(acquired if acquired != 0 else 0), nominal, False, False

    target = float(sign)
    lo = target - float(tol)
    hi = target + float(tol)
    regulated = float(U + nominal * (target - U))
    attempted_exit = bool(regulated > hi or regulated < lo)

    if mode == "fixed":
        return regulated, sign, nominal, False, attempted_exit

    used = nominal
    margin = max(EPS, float(tol) * 1e-9)
    if regulated > hi:
        desired = hi - margin
        denom = target - U
        if abs(denom) > EPS:
            required = (desired - U) / denom
            used = float(max(used, min(1.0, required)))
            regulated = float(U + used * (target - U))
    elif regulated < lo:
        desired = lo + margin
        denom = target - U
        if abs(denom) > EPS:
            required = (desired - U) / denom
            used = float(max(used, min(1.0, required)))
            regulated = float(U + used * (target - U))

    regulated = float(min(hi - margin, max(lo + margin, regulated)))
    return regulated, sign, used, bool(used > nominal + EPS), attempted_exit


def _ev_s_equilibrium(p: OCParameters) -> float:
    # Solve 0.75*beta_s*S^2 + alpha_s*S - delta = 0; positive root.
    a = 0.75 * float(p.beta_s)
    b = float(p.alpha_s)
    c0 = -float(p.delta)
    if abs(a) <= EPS:
        return float(-c0 / b) if abs(b) > EPS else 0.0
    disc = max(0.0, b*b - 4.0*a*c0)
    return float((-b + math.sqrt(disc)) / (2.0*a))


def _ev_candidate_energy(state: OCState, p: OCParameters, basin_target: float) -> float:
    s_star = _ev_s_equilibrium(p)
    vals = np.asarray([state.E, state.U-basin_target, 0.5*state.I_U, state.S-s_star, state.B, state.B_dot], dtype=float)
    if not np.all(np.isfinite(vals)):
        return float("inf")
    vals = np.clip(vals, -1e150, 1e150)
    with np.errstate(over="ignore", invalid="ignore"):
        total = float(np.dot(vals, vals))
    return total if math.isfinite(total) else float("inf")


def _ev_simulate_case(
    case: EvidenceCase, *, micro_steps: int = MICRO_STEPS_PER_STEP,
    macro_steps: int = MAX_STEPS, macro_dt: float = MACRO_DT,
    regulation_mode: str = "adaptive", tol: float = BASIN_TOL,
    convey_window: int = STABILITY_WINDOW, cert_steps: int = CERTIFICATION_STEPS,
    noise_std: float = 0.0, impulse: float = 0.0, dropout_prob: float = 0.0,
    regulation_delay_microsteps: int = 0, parameter_drift: float = 0.0,
    rng: Optional[np.random.Generator] = None,
) -> EvidenceTrajectory:
    if micro_steps <= 0:
        raise ValueError("micro_steps must be positive")
    r = rng if rng is not None else np.random.default_rng(0)
    s = _ev_state_copy(case.state0)
    p0 = _ev_param_copy(case.params)
    dt = float(macro_dt) / int(micro_steps)
    micro_gain = 1.0 - (1.0 - MACRO_BASIN_REGULATION_GAIN) ** (1.0 / int(micro_steps))
    lock_sign = _ev_nearest_basin(s.U)
    state_history = [_ev_state_copy(s)]
    U_history = [float(s.U)]
    reg_abs = reg_sq = reg_peak = 0.0
    interventions = attempted_exits = 0
    divergence = False
    elapsed_micro = 0
    t = 0.0
    total_micro = int(macro_steps) * int(micro_steps)
    impulse_index = total_micro // 2
    for macro in range(1, int(macro_steps)+1):
        for _ in range(int(micro_steps)):
            frac = elapsed_micro / max(1, total_micro-1)
            if parameter_drift:
                pd = dict(p0.__dict__)
                pd["beta_ext"] = float(pd["beta_ext"] * (1.0 + parameter_drift * frac))
                p = OCParameters(**pd)
            else:
                p = p0
            # ----------------------------------------------------------
            # CANONICAL-MECHANISM PARITY.
            #
            # This verifier previously integrated the UNCONTROLLED field
            # with rk4_step(s,p,t,dt) and then OVERWROTE s.U with
            # _ev_regulate(...) after the step -- the superseded v1
            # projection method. The canonical engine was upgraded to a
            # bounded zero-order-held actuator entering dU/dt, and the
            # verifier was not. The two therefore integrated DIFFERENT
            # SYSTEMS, which is why the equivalence self-test reported a
            # 1.33e-01 disagreement while the independent SciPy DOP853
            # cross-solver agreed with the canonical engine to 1e-8.
            #
            # The verifier now forms the same bounded command, holds it
            # across all four RK4 stages, and accepts the controlled RK4
            # state itself. No post-integration U overwrite participates.
            # ----------------------------------------------------------
            do_reg = regulation_mode != "off" and elapsed_micro >= int(regulation_delay_microsteps)
            _apply = do_reg and (dropout_prob <= 0.0 or float(r.random()) >= dropout_prob)
            u_cmd = 0.0
            if _apply:
                if lock_sign not in (-1, +1):
                    lock_sign = +1 if abs(float(s.U) - 1.0) <= abs(float(s.U) + 1.0) else -1
                _ff = -raw_drift_U(s, p, t)
                _raw = _ff + KP * (float(lock_sign) - float(s.U))
                u_cmd = float(max(-U_AUTHORITY, min(U_AUTHORITY, _raw)))
                reg_abs += abs(u_cmd) * dt
                reg_sq += (u_cmd * u_cmd) * dt
                reg_peak = max(reg_peak, abs(u_cmd))
                interventions += int(abs(_raw) > U_AUTHORITY)
                attempted_exits += int(abs(float(s.U) - float(lock_sign)) > tol)
            try:
                s = rk4_step(s, p, t, dt, u_cmd)
            except Exception:
                divergence = True
                break
            if noise_std > 0.0:
                s = OCState(s.E, float(s.U + r.normal(0.0, noise_std)), s.I_U, s.S, s.B, s.B_dot)
            if impulse and elapsed_micro == impulse_index:
                s = OCState(s.E, float(s.U + impulse), s.I_U, s.S, s.B, s.B_dot)
            t += dt
            elapsed_micro += 1
            vals = state_to_vec(s)
            if not np.all(np.isfinite(vals)) or np.any(np.abs(vals) > 1e6):
                divergence = True
                break
        state_history.append(_ev_state_copy(s))
        U_history.append(float(s.U))
        if divergence:
            break
    cls = _ev_classify_history(U_history, tol, convey_window, cert_steps)
    target_sign = cls["final_sign"] if cls["final_sign"] in (-1,+1) else _ev_nearest_basin(U_history[-1])
    energies = [_ev_candidate_energy(st, p0, float(target_sign)) for st in state_history]
    margins = [_ev_basin_margin(u, tol) for u in U_history]
    ratios: List[float] = []
    for a, b in zip(U_history[:-1], U_history[1:]):
        da = abs(float(a)-float(target_sign))
        db = abs(float(b)-float(target_sign))
        if da > EPS:
            ratios.append(float(db/da))
    return EvidenceTrajectory(
        case_id=case.case_id, mode=regulation_mode, micro_steps=micro_steps,
        state_history=state_history, U_history=U_history,
        conveyed=bool(cls["conveyed"]), certified=bool(cls["certified"]),
        born_in_basin=bool(cls["born"]), first_basin_entry_step=cls["first_entry"],
        conveyed_entry_step=cls["conveyed_entry"], conveyance_confirmed_step=cls["conveyed_confirm"],
        certification_start_step=cls["cert_start"], certified_step=cls["certified_step"],
        final_basin_sign=int(cls["final_sign"]), basin_switches=int(cls["switches"]),
        max_same_basin_streak=int(cls["max_streak"]), regulation_abs_total=float(reg_abs),
        regulation_sq_total=float(reg_sq), regulation_peak=float(reg_peak),
        invariance_interventions=int(interventions), attempted_exits=int(attempted_exits),
        divergence=bool(divergence), candidate_energy=energies,
        basin_margin_history=margins, contraction_ratios=ratios,
    )


def _ev_simulate_scipy_regulated(case: EvidenceCase, micro_steps: int = 10, mode: str = "adaptive") -> Optional[EvidenceTrajectory]:
    try:
        from scipy.integrate import solve_ivp
    except Exception:
        return None
    s = _ev_state_copy(case.state0)
    p = _ev_param_copy(case.params)
    dt = MACRO_DT / int(micro_steps)
    gain = 1.0 - (1.0 - MACRO_BASIN_REGULATION_GAIN) ** (1.0/int(micro_steps))
    # Match the canonical Step-0 supervisory target exactly. The prior use
    # of basin_sign returned zero for non-born cases and allowed the two
    # solvers to choose different basins after their first continuous step.
    lock = _ev_nearest_basin(s.U)
    hist = [_ev_state_copy(s)]
    uh = [float(s.U)]
    reg_abs = reg_sq = reg_peak = 0.0
    interventions = attempted = 0
    t = 0.0
    for _macro in range(MAX_STEPS):
        for _ in range(int(micro_steps)):
            y0 = state_to_vec(s)
            def fun(tt, yy):
                return state_to_vec(oc_derivatives(vec_to_state(np.asarray(yy, dtype=float)), p, float(tt)))
            # CANONICAL PARITY: the independent DOP853 reference must
            # integrate the SAME system as the canonical engine -- the
            # bounded zero-order-held command inside the vector field, not
            # an uncontrolled field followed by a state overwrite.
            if lock not in (-1, +1):
                lock = _ev_nearest_basin(float(s.U))
            _ff = -raw_drift_U(s, p, t)
            _raw_cmd = _ff + KP * (float(lock) - float(s.U))
            u_cmd = float(max(-U_AUTHORITY, min(U_AUTHORITY, _raw_cmd)))

            def fun_u(tt, yy, _u=u_cmd):
                return state_to_vec(oc_derivatives(
                    vec_to_state(np.asarray(yy, dtype=float)), p, float(tt), _u))

            sol = solve_ivp(fun_u, (t, t+dt), y0, method="DOP853", rtol=1e-10, atol=1e-12)
            s = vec_to_state(np.asarray(sol.y[:, -1], dtype=float))
            reg_abs += abs(u_cmd)*dt; reg_sq += (u_cmd*u_cmd)*dt
            reg_peak = max(reg_peak, abs(u_cmd))
            interventions += int(abs(_raw_cmd) > U_AUTHORITY)
            attempted += int(abs(float(s.U)-float(lock)) > BASIN_TOL)
            t += dt
        hist.append(_ev_state_copy(s)); uh.append(float(s.U))
    cls = _ev_classify_history(uh)
    target = cls["final_sign"] if cls["final_sign"] in (-1,+1) else _ev_nearest_basin(uh[-1])
    energies=[_ev_candidate_energy(st,p,float(target)) for st in hist]
    ratios=[]
    for a,b in zip(uh[:-1],uh[1:]):
        da=abs(a-target)
        if da>EPS: ratios.append(abs(b-target)/da)
    return EvidenceTrajectory(
        case.case_id, f"scipy-{mode}", micro_steps, hist, uh,
        bool(cls["conveyed"]), bool(cls["certified"]), bool(cls["born"]), cls["first_entry"],
        cls["conveyed_entry"], cls["conveyed_confirm"], cls["cert_start"], cls["certified_step"],
        int(cls["final_sign"]), int(cls["switches"]), int(cls["max_streak"]),
        reg_abs, reg_sq, reg_peak, interventions, attempted, False, energies,
        [_ev_basin_margin(u) for u in uh], ratios,
    )


def _ev_final_vector(tr: EvidenceTrajectory) -> np.ndarray:
    return state_to_vec(tr.final_state())


def _ev_wilson_interval(k: int, n: int, z: float = 1.959963984540054) -> Tuple[float, float]:
    if n <= 0:
        return (float("nan"), float("nan"))
    p = k/n
    d = 1.0 + z*z/n
    c = (p + z*z/(2*n))/d
    h = z*math.sqrt((p*(1-p)/n)+(z*z/(4*n*n)))/d
    lo, hi = max(0.0, c-h), min(1.0, c+h)
    # AUDIT FIX A8: floating-point residue previously made the same saturated
    # bound print as 1.0 at one n and 0.9999999999999998 at another, in adjacent
    # rows of a published table. Snap bounds that are within 1e-12 of the unit
    # endpoints. This changes display only; no acceptance decision reads these.
    if abs(hi - 1.0) < 1e-12: hi = 1.0
    if abs(lo) < 1e-12: lo = 0.0
    return lo, hi


def _ev_bootstrap_ci(values: List[float], rng: np.random.Generator, resamples: int = 500) -> Tuple[float, float]:
    vals=np.asarray([v for v in values if v is not None and np.isfinite(v)],dtype=float)
    if vals.size == 0: return (float("nan"),float("nan"))
    means=[]
    for _ in range(max(50,int(resamples))):
        means.append(float(np.mean(rng.choice(vals,size=vals.size,replace=True))))
    return float(np.percentile(means,2.5)), float(np.percentile(means,97.5))


def _ev_rankdata(x: np.ndarray) -> np.ndarray:
    x=np.asarray(x,dtype=float)
    order=np.argsort(x,kind="mergesort")
    ranks=np.empty(len(x),dtype=float)
    i=0
    while i<len(x):
        j=i+1
        while j<len(x) and x[order[j]]==x[order[i]]: j+=1
        rank=0.5*(i+j-1)+1.0
        ranks[order[i:j]]=rank
        i=j
    return ranks


def _ev_spearman(x: List[float], y: List[float]) -> float:
    xa=np.asarray(x,dtype=float); ya=np.asarray(y,dtype=float)
    mask=np.isfinite(xa)&np.isfinite(ya)
    if np.sum(mask)<3:return float("nan")
    rx=_ev_rankdata(xa[mask]); ry=_ev_rankdata(ya[mask])
    if np.std(rx)<=EPS or np.std(ry)<=EPS:return 0.0
    return _oc_safe_corrcoef(rx, ry)


def _ev_prcc(X: np.ndarray, y: np.ndarray) -> np.ndarray:
    X=np.asarray(X,dtype=float); y=np.asarray(y,dtype=float)
    RX=np.column_stack([_ev_rankdata(X[:,j]) for j in range(X.shape[1])])
    Ry=_ev_rankdata(y)
    out=[]
    for j in range(X.shape[1]):
        others=np.delete(RX,j,axis=1)
        A=np.column_stack([np.ones(len(RX)),others])
        bx=np.linalg.lstsq(A,RX[:,j],rcond=None)[0]
        by=np.linalg.lstsq(A,Ry,rcond=None)[0]
        ex=RX[:,j]-A@bx; ey=Ry-A@by
        out.append(_oc_safe_corrcoef(ex, ey) if np.std(ex)>EPS and np.std(ey)>EPS else 0.0)
    return np.asarray(out,dtype=float)


def _ev_lhs(rng: np.random.Generator, n: int, d: int) -> np.ndarray:
    H=np.zeros((n,d),dtype=float)
    for j in range(d):
        pts=(np.arange(n)+rng.random(n))/n
        rng.shuffle(pts); H[:,j]=pts
    return H


def _ev_variable_parameter_names() -> List[str]:
    return [k for k,(lo,hi) in PARAMETER_RANGES.items() if abs(hi-lo)>EPS]


def _ev_params_from_unit(row: np.ndarray, names: List[str]) -> OCParameters:
    vals={}
    idx=0
    for k,(lo,hi) in PARAMETER_RANGES.items():
        if k in names:
            vals[k]=float(lo+(hi-lo)*float(row[idx])); idx+=1
        else: vals[k]=float(lo)
    return OCParameters(**vals)


def _ev_trajectory_summary(trs: List[EvidenceTrajectory]) -> Dict[str, Any]:
    n=len(trs); conv=sum(t.conveyed for t in trs); cert=sum(t.certified for t in trs); div=sum(t.divergence for t in trs)
    ci_conv=_ev_wilson_interval(conv,n); ci_cert=_ev_wilson_interval(cert,n)
    times=[t.conveyance_confirmed_step for t in trs if t.conveyance_confirmed_step is not None]
    return {
        "n":n,"conveyed":conv,"conveyed_rate":conv/n if n else 0.0,"conveyed_ci95":ci_conv,
        "certified":cert,"certified_rate":cert/n if n else 0.0,"certified_ci95":ci_cert,
        "divergent":div,"divergence_rate":div/n if n else 0.0,
        "mean_conveyance_confirmation_step":float(np.mean(times)) if times else None,
        "p95_conveyance_confirmation_step":float(np.percentile(times,95)) if times else None,
        "mean_regulation_abs_total":float(np.mean([t.regulation_abs_total for t in trs])) if trs else None,
        "mean_regulation_sq_total":float(np.mean([t.regulation_sq_total for t in trs])) if trs else None,
        "mean_regulation_peak":float(np.mean([t.regulation_peak for t in trs])) if trs else None,
        "mean_attempted_exits":float(np.mean([t.attempted_exits for t in trs])) if trs else None,
        "mean_invariance_interventions":float(np.mean([t.invariance_interventions for t in trs])) if trs else None,
        "mean_minimum_basin_margin":float(np.mean([min(t.basin_margin_history) for t in trs])) if trs else None,
        "median_contraction_ratio":float(np.median([r for t in trs for r in t.contraction_ratios])) if trs else None,
        "candidate_energy_decrease_fraction":float(np.mean([np.mean(np.diff(t.candidate_energy)<=0) for t in trs if len(t.candidate_energy)>1])) if trs else None,
    }


def _ev_write_csv(path: Path, rows: List[Dict[str, Any]]) -> None:
    if not rows:
        path.write_text("",encoding="utf-8"); return
    keys=[]
    for r in rows:
        for k in r.keys():
            if k not in keys: keys.append(k)
    with path.open("w",newline="",encoding="utf-8") as f:
        w=csv.DictWriter(f,fieldnames=keys); w.writeheader()
        for r in rows:
            w.writerow({k:(json.dumps(v,sort_keys=True) if isinstance(v,(dict,list,tuple)) else v) for k,v in r.items()})


def _ev_step_size_suite(cfg: EvidenceSuiteConfig, out: Path) -> Dict[str, Any]:
    cases=_ev_draw_cases(cfg.seed+101,cfg.step_size_cases); levels=[10,20,40,80] if cfg.profile=="full" else [10,20,40]; modes=["off","adaptive"]; rows=[]
    for mode in modes:
        sims={m:[_ev_simulate_case(c,micro_steps=m,regulation_mode=mode) for c in cases] for m in levels}; ref=sims[levels[-1]]
        for m in levels[:-1]:
            errs=[]; agree_conv=agree_cert=agree_basin=0; event_err=[]
            for a,b in zip(sims[m],ref):
                errs.append(float(np.linalg.norm(_ev_final_vector(a)-_ev_final_vector(b),ord=2))); agree_conv+=int(a.conveyed==b.conveyed); agree_cert+=int(a.certified==b.certified); agree_basin+=int(a.final_basin_sign==b.final_basin_sign)
                if a.conveyance_confirmed_step is not None and b.conveyance_confirmed_step is not None: event_err.append(abs(a.conveyance_confirmed_step-b.conveyance_confirmed_step))
            rows.append({"mode":mode,"micro_steps":m,"reference_micro_steps":levels[-1],"mean_final_state_l2":float(np.mean(errs)),"max_final_state_l2":float(np.max(errs)),"p95_final_state_l2":float(np.percentile(errs,95)),"conveyance_agreement":agree_conv/len(cases),"certification_agreement":agree_cert/len(cases),"basin_agreement":agree_basin/len(cases),"mean_event_step_difference":float(np.mean(event_err)) if event_err else None})
        if len(levels)>=3:
            for i in range(len(levels)-2):
                m1,m2=levels[i],levels[i+1]; e1=np.mean([np.linalg.norm(_ev_final_vector(a)-_ev_final_vector(b)) for a,b in zip(sims[m1],ref)]); e2=np.mean([np.linalg.norm(_ev_final_vector(a)-_ev_final_vector(b)) for a,b in zip(sims[m2],ref)]); order=math.log(e1/e2,2.0) if e1>EPS and e2>EPS else None
                rows.append({"mode":mode,"micro_steps":m1,"reference_micro_steps":m2,"observed_refinement_order":order,"record_type":"observed_order"})
    _ev_write_csv(out/"RK4_STEP_SIZE_CONVERGENCE.csv",rows)
    try:
        plot=[r for r in rows if r.get("mean_final_state_l2") is not None]; fig,ax=plt.subplots(figsize=(8.20,6.38))
        for i,mode in enumerate(modes):
            rr=[r for r in plot if r["mode"]==mode]; ax.plot([r["micro_steps"] for r in rr],[max(r["mean_final_state_l2"],1e-18) for r in rr],marker=OC_VISUAL_MARKERS[i],linestyle=OC_VISUAL_LINESTYLES[i],label=mode)
        ax.set_yscale("log"); ax.set_xlabel("RK4 microsteps per macro step"); ax.set_ylabel("Mean final-state L2 error vs finest"); ax.set_title("RK4 step-size convergence"); _oc_style_axes(ax,grid="both"); ax.legend(); _oc_save_figure(fig,out/"RK4_STEP_SIZE_CONVERGENCE.png",note=f"{OC_VISUAL_SYSTEM_ID}; ordered solver-refinement evidence."); plt.close(fig)
    except Exception: plt.close("all")
    return {"levels":levels,"rows":rows}


def _ev_cross_solver_suite(cfg: EvidenceSuiteConfig, out: Path) -> Dict[str, Any]:
    cases=_ev_draw_cases(cfg.seed+202,cfg.cross_solver_cases)
    rows=[]; scipy_available=True
    for c in cases:
        rk=_ev_simulate_case(c,micro_steps=10,regulation_mode="adaptive")
        ref=_ev_simulate_scipy_regulated(c,10,"adaptive")
        if ref is None:
            scipy_available=False; ref=_ev_simulate_case(c,micro_steps=160,regulation_mode="adaptive")
        err=np.abs(_ev_final_vector(rk)-_ev_final_vector(ref))
        rows.append({"case_id":c.case_id,"reference":"SciPy DOP853 + identical discrete regulation" if scipy_available else "RK4 160-microstep reference","state_l2":float(np.linalg.norm(err)),"state_linf":float(np.max(err)),"conveyance_agreement":rk.conveyed==ref.conveyed,"certification_agreement":rk.certified==ref.certified,"basin_agreement":rk.final_basin_sign==ref.final_basin_sign,"event_step_difference":None if rk.conveyance_confirmed_step is None or ref.conveyance_confirmed_step is None else abs(rk.conveyance_confirmed_step-ref.conveyance_confirmed_step)})
    _ev_write_csv(out/"CROSS_SOLVER_VALIDATION.csv",rows)
    return {"scipy_available":scipy_available,"summary":{"mean_l2":float(np.mean([r["state_l2"] for r in rows])),"max_linf":float(np.max([r["state_linf"] for r in rows])),"conveyance_agreement":float(np.mean([r["conveyance_agreement"] for r in rows])),"certification_agreement":float(np.mean([r["certification_agreement"] for r in rows])),"basin_agreement":float(np.mean([r["basin_agreement"] for r in rows]))},"rows":rows}




def _ev_run_canonical_silent(cfg: RuntimeConfig, seed: int):
    root = logging.getLogger()
    old_level = root.level
    try:
        root.setLevel(logging.WARNING)
        return run_monte_carlo(cfg, seed)
    finally:
        root.setLevel(old_level)

def _ev_seed_batch_summary(seed: int, runs: int, batch_index: int = 0) -> Dict[str, Any]:
    """Return one independent canonical seed-batch summary."""
    rcfg=RuntimeConfig(mc_runs=int(runs))
    results,_=_ev_run_canonical_silent(rcfg,int(seed))
    conv=sum(r.conveyed for r in results)
    cert=sum(r.certified_primary for r in results)
    n=len(results)
    times=[r.conveyance_confirmed_step for r in results if r.conveyance_confirmed_step is not None]
    return {
        "batch":int(batch_index),"seed":int(seed),"runs":n,"conveyed":conv,"conveyed_rate":conv/n,
        "certified":cert,"certified_rate":cert/n,
        "mean_conveyance_confirmation_step":float(np.mean(times)) if times else None,
        "p95_conveyance_confirmation_step":float(np.percentile(times,95)) if times else None,
        "mean_regulation_abs_total":float(np.mean([r.basin_regulation_abs_total for r in results])),
    }


def _ev_repeated_seed_suite(cfg: EvidenceSuiteConfig, out: Path) -> Dict[str, Any]:
    """Run declared independent-seed canonical batches with fresh-process isolation.

    The seed set, run count, equations, classifier, thresholds, and summary statistics
    are unchanged. Workers execute the existing internal seed-summary path in isolated
    interpreters, eliminating cumulative process-state interference between batches.
    """
    import gc, subprocess as _oc_subprocess, sys as _oc_sys, concurrent.futures as _oc_futures
    marker="__OC_SEED_BATCH_SUMMARY__="
    def _worker(i):
        seed_i=int(cfg.seed+1000+i)
        cmd=[_oc_sys.executable, str(Path(__file__).resolve()), "--_internal-seed-summary", str(seed_i), str(int(cfg.repeated_seed_runs)), str(i)]
        cp=_oc_subprocess.run(cmd, stdout=_oc_subprocess.PIPE, stderr=_oc_subprocess.STDOUT, text=True, check=True, timeout=1500)
        line=next((ln for ln in cp.stdout.splitlines() if ln.startswith(marker)), None)
        if line is None:
            raise RuntimeError(f"Seed replication worker {i} returned no machine-readable summary")
        return json.loads(line[len(marker):])
    rows=[]
    max_workers=max(1,min(int(cfg.repeated_seed_batches),10))
    with _oc_futures.ThreadPoolExecutor(max_workers=max_workers) as ex:
        futures=[ex.submit(_worker,i) for i in range(int(cfg.repeated_seed_batches))]
        for fut in _oc_futures.as_completed(futures):
            rows.append(fut.result())
    rows=sorted(rows,key=lambda r:int(r.get("batch",0)))
    gc.collect()
    _ev_write_csv(out/"MONTE_CARLO_SEED_REPLICATION.csv",rows)
    rates=[r["conveyed_rate"] for r in rows]; certs=[r["certified_rate"] for r in rows]
    try:
        fig,ax=plt.subplots(figsize=(8.20,6.38)); xx=np.arange(1,len(rows)+1)
        ax.plot(xx,rates,marker="o",label="CONVEY-5",color=OC_VISUAL_PALETTE["blue"])
        ax.plot(xx,certs,marker="s",linestyle="--",label="CERT-10",color=OC_VISUAL_PALETTE["teal"])
        ax.set_xlabel("Independent seed batch"); ax.set_ylabel("Rate"); ax.set_ylim(0,1.02)
        ax.set_title("Monte Carlo seed replication"); _oc_style_axes(ax,grid="both"); ax.legend()
        _oc_save_figure(fig,out/"MONTE_CARLO_SEED_REPLICATION.png",note=f"{OC_VISUAL_SYSTEM_ID}; isolated deterministic seed batches.")
        plt.close(fig)
    except Exception:
        plt.close("all")
    return {"batches":len(rows),"runs_per_batch":cfg.repeated_seed_runs,
        "conveyed_rate_mean":float(np.mean(rates)),"conveyed_rate_sd":float(np.std(rates,ddof=1)) if len(rates)>1 else 0.0,
        "conveyed_rate_range":[float(np.min(rates)),float(np.max(rates))],"certified_rate_mean":float(np.mean(certs)),
        "certified_rate_sd":float(np.std(certs,ddof=1)) if len(certs)>1 else 0.0,
        "worker_isolation":"fresh interpreter per canonical seed batch; same canonical execution path; concurrent collection only","rows":rows}

def _ev_sample_size_suite(cfg: EvidenceSuiteConfig, out: Path) -> Dict[str, Any]:
    sizes=[s for s in [100,250,500,1000,2500,5000] if s<=cfg.max_sample_size]
    if cfg.max_sample_size not in sizes: sizes.append(cfg.max_sample_size)
    rcfg=RuntimeConfig(mc_runs=max(sizes)); results,_=_ev_run_canonical_silent(rcfg,cfg.seed+3000); rows=[]
    for n in sizes:
        sub=results[:n]; conv=sum(r.conveyed for r in sub); cert=sum(r.certified_primary for r in sub); ci=_ev_wilson_interval(conv,n); times=[r.conveyance_confirmed_step for r in sub if r.conveyance_confirmed_step is not None]
        rows.append({"sample_size":n,"conveyed_rate":conv/n,"conveyed_ci_low":ci[0],"conveyed_ci_high":ci[1],"certified_rate":cert/n,"mean_conveyance_confirmation_step":float(np.mean(times)) if times else None,"mean_regulation_abs_total":float(np.mean([r.basin_regulation_abs_total for r in sub]))})
    _ev_write_csv(out/"MONTE_CARLO_SAMPLE_SIZE_CONVERGENCE.csv",rows)
    try:
        x=[r["sample_size"] for r in rows]; y=[r["conveyed_rate"] for r in rows]; lo=[r["conveyed_ci_low"] for r in rows]; hi=[r["conveyed_ci_high"] for r in rows]; fig,ax=plt.subplots(figsize=(8.20,6.38)); ax.fill_between(x,lo,hi,color=OC_VISUAL_PALETTE["sky"],alpha=.24,label="95% Wilson interval"); ax.plot(x,y,marker="o",color=OC_VISUAL_PALETTE["blue"],label="Observed rate"); ax.set_xscale("log"); ax.set_xlabel("Monte Carlo sample size (log scale)"); ax.set_ylabel("Conveyance estimate"); ax.set_ylim(0,1.02); ax.set_title("Monte Carlo estimate stabilization"); _oc_style_axes(ax,grid="both"); ax.legend(); _oc_save_figure(fig,out/"MONTE_CARLO_SAMPLE_SIZE_CONVERGENCE.png",note=f"{OC_VISUAL_SYSTEM_ID}; nested prefixes of one declared execution batch."); plt.close(fig)
    except Exception: plt.close("all")
    return {"rows":rows}


def _oc_render_regulation_ablation_figure(rows: List[Dict[str, Any]], path: Path) -> Path:
    """Render the completed ablation rows without rerunning any trajectory.

    M0/M1 use the same ten-observation counter as a diagnostic. Only M2 is
    labeled canonical CERT-10. Distinct lanes and markers prevent coincident
    values from concealing a series.
    """
    import numpy as _np
    import matplotlib.pyplot as _plt

    by_mode = {str(r.get("mode", "")).lower(): r for r in rows if isinstance(r, dict)}
    ordered = [
        ("off", "M0 off\nautonomous ablation"),
        ("fixed", "M1 fixed\nbounded ablation"),
        ("adaptive", "M2 adaptive\ncanonical"),
    ]
    if not all(key in by_mode for key, _ in ordered):
        raise ValueError("Regulation ablation rows must include off, fixed, and adaptive modes.")

    labels = [label for _, label in ordered]
    convey = _np.asarray([100.0 * float(by_mode[key].get("conveyed_rate", 0.0)) for key, _ in ordered])
    dwell = _np.asarray([100.0 * float(by_mode[key].get("certified_rate", 0.0)) for key, _ in ordered])
    y = _np.arange(len(labels), dtype=float)
    lane = 0.14

    fig, ax = _plt.subplots(figsize=(8.40, 6.82))
    ax.scatter(convey, y-lane, s=78, marker="s", color=OC_VISUAL_PALETTE["blue"],
               edgecolors=OC_VISUAL_PALETTE["paper"], linewidths=0.9,
               label="CONVEY-5", zorder=3)
    ax.scatter(dwell, y+lane, s=84, marker="^", color=OC_VISUAL_PALETTE["teal"],
               edgecolors=OC_VISUAL_PALETTE["paper"], linewidths=0.9,
               label="10-observation dwell", zorder=4)
    for yi, value in zip(y-lane, convey):
        ax.annotate(f"{value:.1f}%", (value, yi), xytext=(-7, 0), textcoords="offset points",
                    ha="right", va="center", fontsize=11.0,
                    color=OC_VISUAL_PALETTE["blue"])
    for yi, value in zip(y+lane, dwell):
        ax.annotate(f"{value:.1f}%", (value, yi), xytext=(-7, 0), textcoords="offset points",
                    ha="right", va="center", fontsize=11.0,
                    color=OC_VISUAL_PALETTE["teal"])
    ax.set_yticks(y); ax.set_yticklabels(labels); ax.invert_yaxis()
    ax.set_xlim(0, 105); ax.set_xlabel("Percent of matched ablation cases")
    ax.set_title("Regulation ablation: counterfactual arms versus canonical M2")
    _oc_style_axes(ax, grid="x"); ax.legend(loc="upper left", bbox_to_anchor=(0.02, 0.98))
    note = (
        f"{OC_VISUAL_SYSTEM_ID}; same matched cases, regulation mode varied. "
        "M0/M1 ten-observation dwell values are counterfactual diagnostics. "
        "Only M2 adaptive is the canonical CERT-10 result."
    )
    _oc_save_figure(fig, path, note=note)
    _plt.close(fig)
    return Path(path)


def _ev_ablation_suite(cfg: EvidenceSuiteConfig, out: Path) -> Dict[str, Any]:
    cases=_ev_draw_cases(cfg.seed+404,cfg.ablation_cases); modes=["adaptive","fixed","off"]; all_tr={m:[_ev_simulate_case(c,regulation_mode=m) for c in cases] for m in modes}; rows=[]
    for m in modes:
        q=_ev_trajectory_summary(all_tr[m]); q["mode"]=m; rows.append(q)
    _ev_write_csv(out/"REGULATION_ABLATION.csv",rows)
    try:
        _oc_render_regulation_ablation_figure(rows, out/"REGULATION_ABLATION.png")
    except Exception:
        plt.close("all")
    detail=[t.to_dict() for m in modes for t in all_tr[m]]; _ev_write_csv(out/"REGULATION_EFFORT_AND_INVARIANCE.csv",detail); return {"summary_rows":rows}


def _ev_survival_table(trs: List[EvidenceTrajectory], horizon: int = MAX_STEPS) -> List[Dict[str,Any]]:
    at_risk=len(trs); survival=1.0; rows=[]
    events={s:0 for s in range(horizon+1)}
    for t in trs:
        if t.conveyance_confirmed_step is not None: events[int(t.conveyance_confirmed_step)]+=1
    green=0.0
    for step in range(horizon+1):
        d=events.get(step,0)
        if at_risk>0:
            if d>0:
                survival*=1.0-d/at_risk
                if at_risk-d>0: green+=d/(at_risk*(at_risk-d))
            se=survival*math.sqrt(green) if green>0 else 0.0
            rows.append({"step":step,"at_risk":at_risk,"events":d,"survival_unconveyed":survival,"cumulative_conveyed":1-survival,"greenwood_se":se,"ci_low":max(0.0,survival-1.96*se),"ci_high":min(1.0,survival+1.96*se)})
            at_risk-=d
    return rows


def _ev_threshold_survival_suite(cfg: EvidenceSuiteConfig, out: Path) -> Dict[str,Any]:
    cases=_ev_draw_cases(cfg.seed+505,cfg.threshold_cases); trs=[_ev_simulate_case(c,regulation_mode="adaptive") for c in cases]; base=[(t.conveyed,t.certified) for t in trs]; rows=[]
    # -------------------------------------------------------------------------
    # AUDIT FIX A3 - THE SWEEP NEVER BROKE, SO IT LOCATED NO BOUNDARY
    # -------------------------------------------------------------------------
    # DEFECT (prior builds): tolerances {0.01, 0.02, 0.05, 0.10, 0.15} produced
    # 80 rows every one of which reported conveyed_rate = certified_rate = 1.0.
    # A robustness sweep that never fails confirms a design margin; it does not
    # establish a robustness boundary.  The certificate already predicts where
    # the edge should be: the un-margined residual radius is
    # sup|d|/KP = 0.100756/12 = 0.008396, so certification should begin to
    # degrade as the tolerance approaches ~0.008 and fail below it.  The old
    # sweep stopped at 0.01 - just ABOVE the predicted edge - so it never tested
    # its own prediction.
    #
    # The sweep now extends through the predicted edge.  If degradation appears
    # where the certificate says it should, the practical-stability certificate
    # is upgraded from asserted to VALIDATED, which is a materially stronger
    # claim than eighty rows of 1.0.  If it appears somewhere else, that is a
    # real defect and is published as one.
    # -------------------------------------------------------------------------
    for tol in [1e-6,1e-5,1e-4,0.0005,0.001,0.002,0.004,0.006,0.008,0.01,0.02,0.05,0.10,0.15]:
        for cw in [2,3,4,5]:
            for cert in [5,8,10,12]:
                cls=[_ev_classify_history(t.U_history,tol,cw,cert) for t in trs]; rows.append({"basin_tolerance":tol,"conveyance_window":cw,"certification_window":cert,"conveyed_rate":float(np.mean([c["conveyed"] for c in cls])),"certified_rate":float(np.mean([c["certified"] for c in cls])),"baseline_conveyance_agreement":float(np.mean([c["conveyed"]==base[i][0] for i,c in enumerate(cls)])),"baseline_certification_agreement":float(np.mean([c["certified"]==base[i][1] for i,c in enumerate(cls)]))})
    _ev_write_csv(out/"THRESHOLD_ROBUSTNESS.csv",rows)
    # AUDIT FIX A3b: state the predicted edge and adjudicate the sweep against it.
    try:
        _unmargined=float(OC_CERTIFIED_SUP_INTRA_HOLD_D)/float(KP)
        _margined=float(OC_CERTIFIED_LIPSCHITZ_MARGIN)*_unmargined
        _at_cert=[r for r in rows if int(r["certification_window"])==CERTIFICATION_STEPS]
        _degraded=sorted({float(r["basin_tolerance"]) for r in _at_cert if float(r["certified_rate"])<1.0})
        (out/"THRESHOLD_BOUNDARY_ADJUDICATION.json").write_text(json.dumps({
            "certified_sup_intra_hold_d":float(OC_CERTIFIED_SUP_INTRA_HOLD_D),
            "KP":float(KP),
            "unmargined_residual_radius":_unmargined,
            "margined_residual_radius":_margined,
            "predicted_degradation_edge_basin_tolerance":_unmargined,
            "tolerances_swept":sorted({float(r["basin_tolerance"]) for r in rows}),
            "tolerances_with_degraded_certification":_degraded,
            "sweep_reached_below_predicted_edge":bool(
                min({float(r["basin_tolerance"]) for r in rows}) < _unmargined),
            "status":("BOUNDARY_LOCATED" if _degraded else "NO_BOUNDARY_LOCATED_IN_SWEPT_RANGE"),
            "interpretation":(
                "The practical-stability certificate predicts that certification degrades as the basin "
                "tolerance approaches the un-margined residual radius sup|d|/KP. If the degraded "
                "tolerances listed above bracket that value, the certificate is VALIDATED by execution "
                "rather than merely asserted. If certification degrades at a tolerance materially above "
                "the predicted edge, the certificate is optimistic and must be re-derived. If no "
                "degradation appears anywhere in the swept range, the sweep still has not located a "
                "boundary and must be extended further."),
            "falsifier":(
                "FALSIFIER: the residual-radius certificate is falsified if certification degrades at a "
                "basin tolerance materially LARGER than the margined residual radius, since the "
                "certificate asserts the ultimate error stays inside that radius."),
        },indent=2,default=str),encoding="utf-8")
    except Exception as _thr_err:
        print(f"[WARN] threshold boundary adjudication failed: {_thr_err}")
    surv=_ev_survival_table(trs); _ev_write_csv(out/"CONVEYANCE_SURVIVAL_ANALYSIS.csv",surv)
    try:
        x=[r["step"] for r in surv]; y=[r["cumulative_conveyed"] for r in surv]; lo=[1-r["ci_high"] for r in surv]; hi=[1-r["ci_low"] for r in surv]; fig,ax=plt.subplots(figsize=(8.20,6.38)); ax.fill_between(x,lo,hi,step="post",color=OC_VISUAL_PALETTE["sky"],alpha=.24,label="95% interval"); ax.step(x,y,where="post",color=OC_VISUAL_PALETTE["blue"],linewidth=2.2,label="Cumulative conveyed"); ax.set_xlabel("Macro step"); ax.set_ylabel("Cumulative probability conveyed"); ax.set_ylim(0,1.02); ax.set_title("Event-time conveyance analysis"); _oc_style_axes(ax,grid="both"); ax.legend(); _oc_save_figure(fig,out/"CONVEYANCE_SURVIVAL_ANALYSIS.png",note=f"{OC_VISUAL_SYSTEM_ID}; event-time calculation from current evidence trajectories."); plt.close(fig)
    except Exception: plt.close("all")
    return {"threshold_grid_rows":len(rows),"survival_rows":surv}


def _ev_sensitivity_suite(cfg: EvidenceSuiteConfig, out: Path) -> Dict[str,Any]:
    rng=np.random.default_rng(cfg.seed+606); names=_ev_variable_parameter_names(); n=cfg.sensitivity_samples; H=_ev_lhs(rng,n,len(names)); X=[]; outcomes=[]; trs=[]
    for i in range(n):
        p=_ev_params_from_unit(H[i],names); s=sample_initial_state(rng); c=EvidenceCase(i,s,p); tr=_ev_simulate_case(c,regulation_mode="adaptive"); trs.append(tr); X.append([getattr(p,k) for k in names]); outcomes.append(1.0 if tr.conveyed else 0.0)
    Xn=np.asarray(X); y=np.asarray(outcomes); final_dist=np.asarray([min(abs(t.final_state().U-1),abs(t.final_state().U+1)) for t in trs]); effort=np.asarray([t.regulation_abs_total for t in trs]); prcc_dist=_ev_prcc(Xn,final_dist); prcc_eff=_ev_prcc(Xn,effort)
    rows=[]
    for j,k in enumerate(names): rows.append({"parameter":k,"spearman_with_conveyed":_ev_spearman(Xn[:,j].tolist(),y.tolist()),"prcc_with_final_distance":float(prcc_dist[j]),"prcc_with_regulation_effort":float(prcc_eff[j])})
    _ev_write_csv(out/"GLOBAL_PARAMETER_SENSITIVITY.csv",rows)
    # Morris elementary effects around random base points.
    morris=[]; delta=0.1; bases=max(8,min(32,n//8))
    for b in range(bases):
        x=rng.uniform(delta,1-delta,size=len(names)); p0=_ev_params_from_unit(x,names); s0=sample_initial_state(rng); base=_ev_simulate_case(EvidenceCase(b,s0,p0)); y0=min(abs(base.final_state().U-1),abs(base.final_state().U+1))
        for j,k in enumerate(names):
            x2=x.copy(); x2[j]=min(1.0,x2[j]+delta); p2=_ev_params_from_unit(x2,names); t2=_ev_simulate_case(EvidenceCase(b,s0,p2)); y2=min(abs(t2.final_state().U-1),abs(t2.final_state().U+1)); morris.append({"parameter":k,"elementary_effect":float((y2-y0)/delta)})
    msum=[]
    for k in names:
        vals=[r["elementary_effect"] for r in morris if r["parameter"]==k]; msum.append({"parameter":k,"mu":float(np.mean(vals)),"mu_star":float(np.mean(np.abs(vals))),"sigma":float(np.std(vals,ddof=1)) if len(vals)>1 else 0.0})
    _ev_write_csv(out/"MORRIS_SCREENING.csv",msum)
    # Pick-freeze first-order Sobol estimate on final distance.
    ns=max(24,min(96,n//4)); A=_ev_lhs(rng,ns,len(names)); B=_ev_lhs(rng,ns,len(names))
    fixed_states=[sample_initial_state(rng) for _ in range(ns)]
    def eval_matrix(M):
        return np.asarray([min(abs(_ev_simulate_case(EvidenceCase(i,fixed_states[i],_ev_params_from_unit(M[i],names))).final_state().U-1),abs(_ev_simulate_case(EvidenceCase(i,fixed_states[i],_ev_params_from_unit(M[i],names))).final_state().U+1)) for i in range(ns)])
    # Avoid duplicate simulation in the expression above.
    def eval_matrix_once(M):
        vals=[]
        for i in range(ns):
            tr=_ev_simulate_case(EvidenceCase(i,fixed_states[i],_ev_params_from_unit(M[i],names)))
            vals.append(min(abs(tr.final_state().U-1),abs(tr.final_state().U+1)))
        return np.asarray(vals)
    fA=eval_matrix_once(A); fB=eval_matrix_once(B); var=float(np.var(np.concatenate([fA,fB]),ddof=1)); sob=[]
    for j,k in enumerate(names):
        # ---------------------------------------------------------------------
        # AUDIT FIX A2 - NEGATIVE SOBOL INDICES WERE PUBLISHED UNQUALIFIED
        # ---------------------------------------------------------------------
        # A first-order Sobol index is Var(E[Y|X_i])/Var(Y) and is constrained to
        # [0,1], with the first-order set summing to <= 1.  Prior builds emitted
        # a bare point estimate per parameter; in batch e706d5a8-8 that produced
        # 8 negative values out of 15 (min -0.1454) summing to 0.338.  Negative
        # variance fractions are not sensitivities - they are estimator noise
        # around a true index of approximately zero.
        #
        # The cause is structural, not a bug: the feedforward term cancels the
        # U-channel drift exactly, so the controlled quantity of interest is
        # parameter-invariant by construction and there is no variance left to
        # decompose.  MORRIS_SCREENING confirms this independently - every
        # mu_star lands between 1e-7 and 2e-4.
        #
        # Each estimate now carries its own standard error and an explicit
        # significance flag, so a reader can see the indices are statistically
        # indistinguishable from zero rather than reading a negative number as
        # a negative sensitivity.
        # ---------------------------------------------------------------------
        AB=A.copy(); AB[:,j]=B[:,j]; fAB=eval_matrix_once(AB)
        _contrib=fB*(fAB-fA)
        Si=float(np.mean(_contrib)/var) if var>EPS else 0.0
        _se=float(np.std(_contrib,ddof=1)/math.sqrt(max(1,_contrib.size))/var) if (var>EPS and _contrib.size>1) else float("nan")
        _significant=bool(math.isfinite(_se) and abs(Si)>1.96*_se)
        sob.append({
            "parameter":k,
            "sobol_first_order_estimate":Si,
            "standard_error":_se,
            "estimate_over_se":(Si/_se if (math.isfinite(_se) and _se>0) else float("nan")),
            "statistically_distinguishable_from_zero_95pct":_significant,
            "admissible_range_note":("estimate lies outside the admissible [0,1] range for a variance fraction; "
                                     "this is estimator noise about a true index of approximately zero, not a "
                                     "negative sensitivity" if (Si<0.0 or Si>1.0) else ""),
        })
    _ev_write_csv(out/"SOBOL_FIRST_ORDER_ESTIMATES.csv",sob)
    try:
        _n_out=sum(1 for r in sob if (r["sobol_first_order_estimate"]<0.0 or r["sobol_first_order_estimate"]>1.0))
        _n_sig=sum(1 for r in sob if r["statistically_distinguishable_from_zero_95pct"])
        (out/"SOBOL_INTERPRETATION.json").write_text(json.dumps({
            "parameters":len(sob),
            "estimates_outside_admissible_0_1_range":_n_out,
            "estimates_distinguishable_from_zero_at_95pct":_n_sig,
            "sum_of_first_order_estimates":float(sum(r["sobol_first_order_estimate"] for r in sob)),
            "interpretation":(
                "First-order Sobol indices are variance fractions confined to [0,1]. Estimates outside that "
                "range are estimator noise about a true index of approximately zero and are reported "
                "UNCLAMPED so the noise floor is visible. The controlled quantity of interest is "
                "parameter-invariant by construction because the feedforward term cancels the U-channel "
                "drift exactly, so there is little variance to decompose. MORRIS_SCREENING confirms this "
                "independently with every mu_star at or below 2e-4."),
            "positive_reading":(
                "Read this table as EVIDENCE THAT THE FEEDFORWARD CANCELLATION WORKS, not as a failed "
                "sensitivity analysis. Global sensitivity of the controlled output to the declared "
                "parameter box is at the numerical noise floor, which is the intended consequence of exact "
                "drift cancellation."),
            "recommended_companion_analysis":(
                "For a sensitivity result with actual signal, run this same suite against the UNCONTROLLED "
                "arm (regulation_mode='off'), where the parameters do move the output. That also quantifies "
                "how much variance the controller is removing."),
        },indent=2,default=str),encoding="utf-8")
    except Exception as _oc_exc:
        logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
    robust=_ev_trajectory_summary(trs); robust["declared_parameter_space_sample_method"]="Latin hypercube"; robust["successful_parameter_space_fraction"]=robust["conveyed_rate"]
    (out/"PARAMETER_SPACE_ROBUSTNESS.json").write_text(json.dumps(robust,indent=2,default=str),encoding="utf-8")
    return {"lhs_summary":robust,"sensitivity_rows":rows,"morris":msum,"sobol":sob}


def _ev_adversarial_cases() -> List[EvidenceCase]:
    mid={k:(lo+hi)/2 for k,(lo,hi) in PARAMETER_RANGES.items()}; p=OCParameters(**mid)
    specs=[
        ("plus_center",OCState(.5,1.0,.5,0,0,0)),("minus_center",OCState(.5,-1.0,.5,0,0,0)),
        ("plus_upper_boundary",OCState(.5,1.1,.5,0,0,0)),("plus_lower_boundary",OCState(.5,.9,.5,0,0,0)),
        ("minus_upper_boundary",OCState(.5,-.9,.5,0,0,0)),("minus_lower_boundary",OCState(.5,-1.1,.5,0,0,0)),
        ("midpoint",OCState(.5,0,.5,0,0,0)),("far_positive_U",OCState(.5,10,.5,0,0,0)),
        ("far_negative_U",OCState(.5,-10,.5,0,0,0)),("large_E",OCState(100,0,.5,0,0,0)),
        ("large_S_positive",OCState(.5,0,.5,10,0,0)),("large_S_negative",OCState(.5,0,.5,-10,0,0)),
        ("large_B",OCState(.5,0,.5,0,100,0)),("large_Bdot",OCState(.5,0,.5,0,0,100)),
    ]
    out=[]
    for i,(name,s) in enumerate(specs):
        c=EvidenceCase(i,s,_ev_param_copy(p)); setattr(c,"name",name); out.append(c)
    return out


def _ev_adversarial_noise_stiffness_residual_suite(cfg: EvidenceSuiteConfig, out: Path) -> Dict[str,Any]:
    adv=[]
    for c in _ev_adversarial_cases():
        for mode in ["adaptive","fixed","off"]:
            tr=_ev_simulate_case(c,regulation_mode=mode); d=tr.to_dict(); d["case_name"]=getattr(c,"name",str(c.case_id)); adv.append(d)
    _ev_write_csv(out/"ADVERSARIAL_BOUNDARY_CASES.csv",adv)
    cases=_ev_draw_cases(cfg.seed+707,cfg.noise_cases); noise_rows=[]
    # -------------------------------------------------------------------------
    # AUDIT FIX A1a - THE NOISE GRID SKIPPED THE KNEE
    # -------------------------------------------------------------------------
    # DEFECT (prior builds): the Gaussian grid jumped 0.001 -> 0.01 -> 0.05.
    # Certification was 100% at 0.01 and 13.3% at 0.05, so the entire transition
    # - the only part of the curve an operator needs - fell in an untested gap.
    # The grid is now refined across the knee so the measured curve can be shown
    # tracking the closed form in cert10_noise_budget(). Higher sigmas are added
    # so the far tail is bounded rather than extrapolated.
    # -------------------------------------------------------------------------
    scenarios=[("clean",0,0,0,0,0),
               ("gaussian_0.001",.001,0,0,0,0),
               ("gaussian_0.005",.005,0,0,0,0),
               ("gaussian_0.01",.01,0,0,0,0),
               ("gaussian_0.015",.015,0,0,0,0),
               ("gaussian_0.02",.02,0,0,0,0),
               ("gaussian_0.0225",.0225,0,0,0,0),
               ("gaussian_0.025",.025,0,0,0,0),
               ("gaussian_0.0275",.0275,0,0,0,0),
               ("gaussian_0.03",.03,0,0,0,0),
               ("gaussian_0.04",.04,0,0,0,0),
               ("gaussian_0.05",.05,0,0,0,0),
               ("gaussian_0.06",.06,0,0,0,0),
               ("gaussian_0.08",.08,0,0,0,0),
               ("impulse_0.25",0,.25,0,0,0),
               ("dropout_10pct",0,0,.1,0,0),
               ("delay_5_micro",0,0,0,5,0),
               ("parameter_drift_20pct",0,0,0,0,.2)]
    for si,(name,ns,imp,drop,delay,drift) in enumerate(scenarios):
        trs=[_ev_simulate_case(c,noise_std=ns,impulse=imp,dropout_prob=drop,regulation_delay_microsteps=delay,parameter_drift=drift,rng=np.random.default_rng(cfg.seed+8000+si*1000+c.case_id)) for c in cases]
        s=_ev_trajectory_summary(trs); s["scenario"]=name; noise_rows.append(s)
    # The Gaussian arms above are PROCESS/STATE noise: U is perturbed after every
    # microstep and the perturbation therefore changes subsequent control and dynamics.
    for _r in noise_rows:
        _nm=str(_r.get("scenario",""))
        if _nm.startswith("gaussian_"):
            _r["noise_injection_scope"]="U_STATE_AFTER_EACH_MICROSTEP"
            _r["closed_form_measurement_noise_probability"]="NOT_APPLICABLE_DIFFERENT_NOISE_MODEL"
    _ev_write_csv(out/"DISTURBANCE_ROBUSTNESS.csv",noise_rows)

    # Empirical process-noise qualification envelope, now based on n=500 per arm
    # in the full profile and a 95% lower confidence bound rather than 30/30 rhetoric.
    _process_budget=cert10_process_noise_empirical_budget(noise_rows,target_probability=0.95)
    (out/"CERT10_PROCESS_NOISE_EMPIRICAL_BUDGET.json").write_text(json.dumps(_process_budget,indent=2,default=str),encoding="utf-8")
    _ev_write_csv(out/"CERT10_PROCESS_NOISE_EMPIRICAL_BUDGET.csv",_process_budget.get("rows",[]))

    # Separate MEASUREMENT-noise experiment. Dynamics remain clean; only the
    # observed U_history used by the qualification predicate is corrupted. This
    # is the experiment that can be compared to cert10_noise_budget().
    try:
        _measurement_model=cert10_noise_budget()
        _measurement_sigmas=[float(x["sigma"]) for x in _measurement_model.get("curve",[])]
        _clean_trs=[_ev_simulate_case(c,regulation_mode="adaptive") for c in cases]
        _mrows=[]
        _pred_map={round(float(x["sigma"]),8):x for x in _measurement_model.get("curve",[])}
        for _si,_sig in enumerate(_measurement_sigmas):
            _cert=_conv=0
            for _tr in _clean_trs:
                _rr=np.random.default_rng(cfg.seed+180000+_si*100000+int(_tr.case_id))
                _obs=[float(u)+float(_rr.normal(0.0,_sig)) for u in _tr.U_history]
                _cls=_ev_classify_history(_obs,BASIN_TOL,STABILITY_WINDOW,CERTIFICATION_STEPS)
                _conv+=int(bool(_cls["conveyed"])); _cert+=int(bool(_cls["certified"]))
            _n=len(_clean_trs); _clo,_chi=_ev_wilson_interval(_cert,_n); _vlo,_vhi=_ev_wilson_interval(_conv,_n)
            _pred=_pred_map.get(round(_sig,8),{})
            _mrows.append({"sigma":_sig,"n":_n,"conveyed":_conv,"conveyed_rate":_conv/max(_n,1),"conveyed_wilson95_low":_vlo,"conveyed_wilson95_high":_vhi,
                           "certified":_cert,"certified_rate":_cert/max(_n,1),"certified_wilson95_low":_clo,"certified_wilson95_high":_chi,
                           "predicted_finite_horizon_cert10_probability":_pred.get("finite_horizon_cert10_probability_iid_measurement_model"),
                           "noise_injection_scope":"OBSERVATION_ONLY_AT_RECORDED_MACRO_STEPS"})
        _ev_write_csv(out/"MEASUREMENT_NOISE_ROBUSTNESS.csv",_mrows)
        (out/"CERT10_MEASUREMENT_NOISE_MODEL.json").write_text(json.dumps(_measurement_model,indent=2,default=str),encoding="utf-8")
        _ev_write_csv(out/"CERT10_MEASUREMENT_NOISE_MODEL.csv",_measurement_model.get("curve",[]))
    except Exception as _nb_err:
        print(f"[WARN] measurement-noise qualification suite failed: {_nb_err}")
    # Jacobian stiffness diagnostics.
    stiff=[]
    for c in cases[:min(30,len(cases))]:
        tr=_ev_simulate_case(c)
        for label,st in [("initial",tr.state_history[0]),("mid",tr.state_history[len(tr.state_history)//2]),("final",tr.state_history[-1])]:
            y=state_to_vec(st); J=np.zeros((6,6)); h=1e-6
            for j in range(6):
                dy=np.zeros(6); dy[j]=h*max(1.0,abs(y[j])); fp=state_to_vec(oc_derivatives(vec_to_state(y+dy),c.params,0)); fm=state_to_vec(oc_derivatives(vec_to_state(y-dy),c.params,0)); J[:,j]=(fp-fm)/(2*dy[j])
            eig=np.linalg.eigvals(J); mags=np.abs(eig); nz=mags[mags>1e-12]; ratio=float(np.max(nz)/np.min(nz)) if nz.size else 0.0; stability_metric=float(np.max(np.abs(eig))*MICRO_DT)
            stiff.append({"case_id":c.case_id,"state":label,"stiffness_ratio":ratio,"max_abs_eigenvalue":float(np.max(mags)),"rk4_linear_stability_metric_h_lambda":stability_metric,"negative_real_axis_reference_limit":2.785,"warning":stability_metric>2.785,"eigenvalues":[str(x) for x in eig]})
    _ev_write_csv(out/"STIFFNESS_DIAGNOSTICS.csv",stiff)
    # Differential equation residual on unregulated fine trajectories.
    residual=[]
    for c in cases[:min(30,len(cases))]:
        tr=_ev_simulate_case(c,micro_steps=80,regulation_mode="off")
        H=tr.state_history
        for i in range(1,len(H)-1):
            fd=(state_to_vec(H[i+1])-state_to_vec(H[i-1]))/(2*MACRO_DT); rhs=state_to_vec(oc_derivatives(H[i],c.params,i*MACRO_DT)); e=fd-rhs
            residual.append({"case_id":c.case_id,"macro_step":i,"residual_l2":float(np.linalg.norm(e)),"residual_linf":float(np.max(np.abs(e))),"E":float(e[0]),"U":float(e[1]),"I_U":float(e[2]),"S":float(e[3]),"B":float(e[4]),"B_dot":float(e[5])})
    _ev_write_csv(out/"DIFFERENTIAL_EQUATION_RESIDUAL_AUDIT.csv",residual)
    bath_rows=[]
    for c in cases[:min(30,len(cases))]:
        tr=_ev_simulate_case(c,micro_steps=80,regulation_mode="off")
        H=tr.state_history
        h=MACRO_DT
        for i in range(1,len(H)-1):
            rb=bath_discrete_residual(H[i-1],H[i],H[i+1],c.params,h)
            bath_rows.append({"case_id":c.case_id,"macro_step":i,"bath_discrete_residual":float(rb),"abs_residual":abs(float(rb))})
    _ev_write_csv(out/"BATH_DISCRETE_RESIDUAL_AUDIT.csv",bath_rows)
    bath_summary={
        "count":len(bath_rows),
        "mean_abs":float(np.mean([r["abs_residual"] for r in bath_rows])) if bath_rows else None,
        "rms":float(math.sqrt(np.mean([r["bath_discrete_residual"]**2 for r in bath_rows]))) if bath_rows else None,
        "max_abs":float(max([r["abs_residual"] for r in bath_rows],default=0.0)),
    }
    return {"adversarial_count":len(adv),"disturbance_rows":noise_rows,"stiffness_summary":{"max_ratio":float(max([r["stiffness_ratio"] for r in stiff],default=0)),"warnings":sum(bool(r["warning"]) for r in stiff),"acceptance_criterion":"RK4 linear absolute-stability limit on the negative real axis: |h*lambda| <= 2.785","acceptance_threshold_h_lambda":2.785,"max_observed_h_lambda":float(max([r["rk4_linear_stability_metric_h_lambda"] for r in stiff],default=0.0)),"criterion_note":"The eigenvalue condition-number RATIO is reported as a diagnostic of problem conditioning and is NOT the acceptance criterion. Acceptance is decided by the dimensionless product of the integration step and the dominant eigenvalue magnitude against the classical RK4 stability limit, which is the quantity that governs whether an explicit fixed-step integrator remains stable."},"residual_summary":{"mean_l2":float(np.mean([r["residual_l2"] for r in residual])) if residual else None,"max_linf":float(max([r["residual_linf"] for r in residual],default=0)),"bath_discrete":bath_summary}}


def _ev_self_tests(cfg: EvidenceSuiteConfig, out: Path) -> Dict[str,Any]:
    tests=[]
    def record(name,ok,detail=""):
        tests.append({"test":name,"passed":bool(ok),"detail":str(detail)})
    # Generic RK4 known ODE y'=y, fourth-order behavior.
    def scalar_rk4(y,h):
        k1=y; k2=y+.5*h*k1; k3=y+.5*h*k2; k4=y+h*k3; return y+h*(k1+2*k2+2*k3+k4)/6
    def integrate(h):
        y=1.; n=round(1/h)
        for _ in range(n): y=scalar_rk4(y,h)
        return y
    e1=abs(integrate(.1)-math.e); e2=abs(integrate(.05)-math.e); order=math.log(e1/e2,2) if e2>0 else 99
    record("RK4 known ODE fourth-order sanity",order>3.5,f"observed order={order:.6f}")
    # Deterministic replay and canonical equivalence.
    seed=cfg.seed+909; cases=_ev_draw_cases(seed,20); a=[_ev_simulate_case(c) for c in cases]; b=[_ev_simulate_case(c) for c in cases]
    exact=all(np.array_equal(_ev_final_vector(x),_ev_final_vector(y)) and x.to_dict()==y.to_dict() for x,y in zip(a,b)); record("deterministic replay",exact)
    rcfg=RuntimeConfig(mc_runs=20); rr,_=_ev_run_canonical_silent(rcfg,seed)
    diffs=[]; class_ok=True
    for x,y in zip(a,rr):
        diffs.append(float(np.max(np.abs(_ev_final_vector(x)-np.array([y.final_E,y.final_U,y.final_IU,y.final_S,y.final_B,y.final_Bdot])))))
        class_ok=class_ok and x.conveyed==y.conveyed and x.certified==y.certified_primary
    record("generalized verifier matches canonical 10-microstep engine",max(diffs,default=0)<1e-12 and class_ok,f"max state difference={max(diffs,default=0):.3e}")
    record("born and rescued categories disjoint",all(not(r.born_stable and r.rescued) for r in rr))
    record("certification implies qualifying streak",all((not r.certified_primary) or r.max_consecutive_same_basin>=CERTIFICATION_STEPS for r in rr))
    record("conveyance event timing internally consistent",all((not r.conveyed) or (r.conveyed_step is not None and r.conveyance_confirmed_step-r.conveyed_step+1==STABILITY_WINDOW) for r in rr))
    record("nonfinite trajectories not conveyed",all(not((not np.all(np.isfinite([r.final_E,r.final_U,r.final_IU,r.final_S,r.final_B,r.final_Bdot]))) and r.conveyed) for r in rr))
    record("result totals reconcile",len(rr)==sum(1 for _ in rr))
    _p_mid=OCParameters(**{k:(lo+hi)/2 for k,(lo,hi) in PARAMETER_RANGES.items()})
    _omega=max(_p_mid.omega_B,EPS)
    record("spinor factor 0/360/720 periodicity",
           all(math.isclose(spinor_closure_factor(t,_p_mid),expected,rel_tol=0.0,abs_tol=1e-12)
               for t,expected in ((0.0,1.0),(2*math.pi/_omega,-1.0),(4*math.pi/_omega,1.0))))
    record("canonical bath discrete residual emitted",
           all(r.bath_discrete_residual_count>0 and math.isfinite(r.bath_discrete_residual_peak) for r in rr))
    _ev_write_csv(out/"AUTOMATED_VERIFICATION_TESTS.csv",tests)
    return {"passed":sum(t["passed"] for t in tests),"failed":sum(not t["passed"] for t in tests),"tests":tests}


def _ev_environment_fingerprint(seed: int, out: Path) -> Dict[str,Any]:
    cases=_ev_draw_cases(seed,12); trs=[_ev_simulate_case(c) for c in cases]
    payload={"engine_sha256":_oc_engine_sha256(),"python":sys.version,"platform":platform.platform(),"numpy":np.__version__,"seed":seed,"trajectory_digest_input":[{"case_id":t.case_id,"final":[float(x) for x in _ev_final_vector(t)],"conveyed":t.conveyed,"certified":t.certified,"basin":t.final_basin_sign} for t in trs]}
    payload["trajectory_sha256"]=hashlib.sha256(json.dumps(payload["trajectory_digest_input"],sort_keys=True,separators=(",",":")).encode()).hexdigest()
    (out/"EVIDENCE_PLATFORM_FINGERPRINT.json").write_text(json.dumps(payload,indent=2),encoding="utf-8")
    return payload


