    """Fixed compute-benchmark visual grammar: architecture, signed matrix,
    baseline-normalized dumbbells, protected-service dot plot, and seed rates."""
    outdir.mkdir(parents=True,exist_ok=True); summaries=payload.get("summaries",{}); modes=payload.get("modes",[]); paths={}
    import matplotlib.pyplot as _plt
    note=f"{OC_VISUAL_SYSTEM_ID}; deterministic matched-workload simulator. Values are model outputs, not live hardware measurements."
    # Architecture: layered, rounded, semantic nodes.
    fig,ax=_plt.subplots(figsize=(10.50,6.84)); ax.set_xlim(0,1); ax.set_ylim(0,1); ax.axis("off")
