    arch=output_dir/"FRAGMENTED_STACK_GOVERNANCE_ARCHITECTURE.png"; fig,ax=plt.subplots(figsize=(10.50,7.20)); ax.set_xlim(0,1); ax.set_ylim(0,1); ax.axis("off")
    _oc_node(ax,(.35,.78),.30,.15,"OMNI-COMPASS","governing convergence control core",color=OC_VISUAL_PALETTE["blue"])
