                policies=["fragmented_managers","conventional_broker","omni-compass"]; representative=[r for r in rr if r.get("selection_label")=="representative_median"]; use=representative or rr
                for i,policy in enumerate(policies):
                    part=[r for r in use if r["policy"]==policy]; t=[float(r["minute"]) for r in part]; col=OC_VISUAL_SERIES[i]
