                    axes[1].plot(t,[float(r["nodes"]) for r in part],color=col,linestyle=OC_VISUAL_LINESTYLES[i])
                    axes[2].plot(t,[float(r["unresolved_conflicts"]) for r in part],color=col,linestyle=OC_VISUAL_LINESTYLES[i])
