def _ep_write_csv(path: Path, rows: List[Dict[str,Any]]) -> None:
    _ci_write_csv(path, rows)


def run_enterprise_proof_suite(profile: str, seed_base: int, output_dir: str,
                               manager_payload: Optional[Dict[str,Any]],
                               compute_payload: Optional[Dict[str,Any]],
                               trace_path: Optional[str] = None) -> Dict[str,Any]:
    profile=str(profile).lower().strip(); cfg=EnterpriseProofConfig(profile=profile)
    if profile=="quick":
        cfg.causal_scenarios=80; cfg.failure_scenarios=90; cfg.security_scenarios=120; cfg.direct_muscle_trials=18; cfg.dual_basin_runs=200; cfg.scale_repeats=20
    outdir=Path(output_dir).expanduser(); outdir.mkdir(parents=True,exist_ok=True)
    payload={"profile":profile,"generated_utc":datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00","Z"),"seed_base":int(seed_base),"config":asdict(cfg),"engine_sha256":_oc_engine_sha256(),
             "claim_boundary":"Integrated synthetic and current-environment execution evidence. Real production, physical safety, customer economics, and independent certification require environment-specific validation."}
    print("[RUN] enterprise evidence: state-coupling and command-dependency audit")
    payload["state_coupling"]=_ep_state_coupling_audit()
    print("[RUN] enterprise evidence: causal contribution and decision replay")
    payload["causal"]=_ep_causal_contribution(cfg,seed_base+10001)
    print("[RUN] enterprise evidence: governor failure, fallback and recovery")
    payload["failure"]=_ep_governor_failure(cfg,seed_base+20001)
    print("[RUN] enterprise evidence: scale and saturation")
    payload["scale"]=_ep_scale_saturation(cfg,seed_base+30001)
    print("[RUN] enterprise evidence: direct operational muscle plants")
    payload["direct_muscle"]=_ep_direct_muscle(cfg,seed_base+40001)
    print("[RUN] enterprise evidence: dual-basin symmetry")
    payload["dual_basin"]=_ep_dual_basin(cfg,seed_base+50001)
    payload["governance_compression"]=_ep_governance_compression(manager_payload)
    payload["slo_error_budget"]=_ep_slo_error_budget(manager_payload,compute_payload)
    print("[RUN] enterprise evidence: security and adversarial governance")
    payload["security"]=_ep_security(cfg,seed_base+60001)
    print("[RUN] enterprise evidence: long-duration drift")
    payload["long_duration"]=_ep_long_duration(cfg,seed_base+70001)
    payload["trace_replay"]=_ep_trace_replay(cfg,seed_base+80001,trace_path,outdir)
    payload["cfo"]=_ep_cfo(compute_payload,manager_payload,outdir)
    artifacts={}
    mapping={
        "causal_runs.csv":payload["causal"]["rows"],"decision_ledger.csv":payload["causal"]["decision_ledger"],
        "governor_failure_runs.csv":payload["failure"]["rows"],"scale_saturation.csv":payload["scale"]["rows"],
        "direct_muscle_runs.csv":payload["direct_muscle"]["rows"],"dual_basin_runs.csv":payload["dual_basin"]["rows"],
        "security_adversarial_runs.csv":payload["security"]["rows"],"long_duration_runs.csv":payload["long_duration"]["rows"],
        "state_coupling_jacobian.csv":payload["state_coupling"]["rows"],
    }
    for name,rows in mapping.items():
        p=outdir/name.upper(); _ep_write_csv(p,rows); artifacts[name]=str(p)
    summary_path=outdir/"ENTERPRISE_PROOF_SUMMARY.json"
    summary_path.write_text(json.dumps({k:v for k,v in payload.items() if k not in ("causal","failure","direct_muscle","security")},indent=2,default=str),encoding="utf-8")
    artifacts["summary_json"]=str(summary_path); artifacts["trace_csv"]=payload["trace_replay"]["trace_csv"]; artifacts["cfo_template"]=payload["cfo"]["template"]
    payload["artifacts"]=artifacts; payload["figures"]=_ep_generate_charts(payload,outdir)
    return payload


def _ep_status_rows(payload: Dict[str,Any]) -> List[List[str]]:
    causal=payload.get("causal",{}).get("summary",{}).get("adapter_only__mean_unresolved_conflict",{})
    fail=payload.get("failure",{}).get("summary",{}).get("omni_fail_safe",{})
    scale=(payload.get("scale",{}).get("rows",[]) or [{}])[-1]
    muscle=payload.get("direct_muscle",{})
    gc=payload.get("governance_compression",{})
    sec=payload.get("security",{}).get("summaries",{})
    replay=payload.get("causal",{}).get("decision_replay",{})
    dual=payload.get("dual_basin",{}).get("summary",{})
    coupling=payload.get("state_coupling",{})
    return [
        ["State-coupling audit", f"Local Jacobian rank {coupling.get('jacobian_rank','n/a')}/6; command-active: {', '.join(coupling.get('command_active_states',[]))}", "EXECUTED"],
        ["Causal contribution", f"Full Omni vs adapter-only unresolved conflict: {_ci_fmt(causal.get('mean_percent_change'),2,True)}. INTERPRETATION: this is the change in UNRESOLVED CONFLICT, so a NEGATIVE value is the FAVOURABLE direction - it denotes fewer unresolved conflicts under full governance than under an adapter-only configuration. The magnitude is a scoped synthetic measurement of supervisory contribution and is not a claim of production conflict reduction.", "EXECUTED"],
        ["Governor failure safety", f"Fail-safe bounded steps: {_ci_fmt(100*float(fail.get('bounded_fraction',0)),2,True)}", "EXECUTED"],
        ["Local scaling microbenchmark", f"{scale.get('nodes','n/a')} nodes; P95 decision {_ci_fmt(scale.get('p95_decision_ms'),4)} ms", "EXECUTED"],
        ["Direct muscle control", f"Omni best-metric win rate: {_ci_fmt(100*float(muscle.get('omni_metric_win_rate',0)),1,True)}. INTERPRETATION: this figure is deliberately reported even though it is unfavourable. It measures how often the general-purpose supervisory operator beat a SPECIALIZED per-plant controller on that plant's own best metric. A general supervisor is not expected to outperform purpose-built controllers on their own optimization target; the claim established by this surface is EXECUTABLE DIRECT-ACTUATOR INTEGRATION across the synthetic plants, not per-plant superiority. No universal superiority over specialized plant controllers is claimed or implied.", "EXECUTED"],
        ["Governance outcome / overhead balance", f"Event change vs broker: {_ci_fmt(gc.get('governance_event_change_percent'),2,True) if gc.get('executed') else 'not executed'}", "EXECUTED" if gc.get('executed') else "NOT EXECUTED"],
        ["Adversarial-input behavioral simulation", f"Unsafe execution: broker {_ci_fmt(100*sec.get('conventional_broker',{}).get('unsafe_execution_rate',0),2,True)}; Omni {_ci_fmt(100*sec.get('omni_bounded_governor',{}).get('unsafe_execution_rate',0),2,True)}", "EXECUTED"],
        ["Decision replay", f"{replay.get('decisions_checked',0)} decisions; {replay.get('mismatches',0)} mismatches", "PASS" if replay.get('pass') else "FAIL"],
        ["Direct signed dual-basin dynamics", f"Conveyance symmetry gap: {_ci_fmt(dual.get('symmetry_gap_conveyance_pp'),2)} percentage points", "EXECUTED"],
    ]

