def _ms_catalog_hash() -> str:
    return hashlib.sha256(json.dumps(MS_MUSCLE_CATALOG, sort_keys=True).encode("utf-8")).hexdigest().upper()


def _ms_clamp(x: float, lo: float, hi: float) -> float:
    return float(max(lo, min(hi, x)))


def _ms_num(row: Dict[str, Any], key: str, default: float = 0.0) -> float:
    try:
        value = row.get(key, default)
        if value is None:
            return float(default)
        return float(value)
    except Exception:
        return float(default)


def _ms_percentile(values: List[float], q: float) -> float:
    if not values:
        return 0.0
    return float(np.percentile(np.asarray(values, dtype=float), q))


def _ms_stats(values: List[float]) -> Dict[str, float]:
    if not values:
        return {"n":0,"mean":0.0,"median":0.0,"stdev":0.0,"p05":0.0,"p95":0.0,"ci95_low":0.0,"ci95_high":0.0}
    a = np.asarray(values, dtype=float)
    n = int(a.size)
    mean = float(np.mean(a))
    stdev = float(np.std(a, ddof=1)) if n > 1 else 0.0
    half = 1.959963984540054 * stdev / math.sqrt(max(1, n))
    return {
        "n":n,
        "mean":mean,
        "median":float(np.median(a)),
        "stdev":stdev,
        "p05":float(np.percentile(a,5)),
        "p95":float(np.percentile(a,95)),
        "ci95_low":mean-half,
        "ci95_high":mean+half,
    }


def _ms_mode_label(mode: str) -> str:
    return {
        "no_orchestrator":"Unmanaged Stack / No Orchestration",
        "kubernetes":"Kubernetes Baseline",
        "kubernetes_plus_omnicompass":"Kubernetes + Omni-Compass",
        "omnicompass_direct":"Omni-Compass Direct Orchestration",
        "alternative_nomad_slurm":"Representative Alternative (Nomad/Slurm Style)",
    }.get(mode, mode.replace("_"," ").title())


def _ms_environment_label(env: str) -> str:
    return {
        "bare_metal":"Bare Metal",
        "on_premises":"On-Premises Datacenter",
        "private_cloud":"Private Cloud",
        "public_cloud":"Public Cloud",
        "hybrid_cloud":"Hybrid Cloud",
        "edge_distributed":"Edge / Distributed",
    }.get(env, env.replace("_"," ").title())


def _ms_run_one(canonical: Dict[str, Any], environment: str, mode: str, stacks: int, seed_base: int) -> Dict[str, Any]:
    """Execute one matched scenario using one complete stack as the unit baseline.

    Every reported cluster is an exact duplication of the same fully populated
    one-stack unit. Per-stack utilization, latency, availability, cost mix, and
    savings percentages therefore remain invariant at 1, 10, 100, and 1,000
    stacks. Aggregate throughput, incident counts, resource quantities, and
    dollar totals scale linearly with stack count. This is the controlling
    normalized financial comparison. Company-specific engineers may replace the
    one-stack resource vector or remove/weight muscles in the exported ledger.
    """
    env = MS_ENVIRONMENT_MODEL[environment]
    policy = MS_MODE_MODEL[mode]
    stacks = int(stacks)
    if stacks not in MS_CLUSTER_SCALES:
        raise ValueError(f"Unsupported normalized stack scale: {stacks}")
    run_id = int(_ms_num(canonical, "run_id", 0))

    # The common disturbance intentionally excludes governance mode AND stack
    # count. The identical one-stack disturbance is duplicated across each
    # cluster scale, guaranteeing a matched unit comparison and exact financial
    # percentage invariance across 1, 10, 100, and 1,000 stacks.
    common_seed = _stable_seed("megastack-one-stack-common-disturbance", seed_base, environment, run_id)
    rng = np.random.default_rng(common_seed)
    common_draw_id = hashlib.sha256(f"{seed_base}|{environment}|ONE_STACK|{run_id}".encode("utf-8")).hexdigest().upper()[:20]

    initial_distance = _ms_num(canonical, "initial_distance_to_basin", 0.5)
    final_error = abs(_ms_num(canonical, "final_E", 0.0))
    final_u = abs(_ms_num(canonical, "final_U", 1.0))
    confirm_step = _ms_num(canonical, "conveyance_confirmed_step", 20.0)
    regulation = _ms_num(canonical, "basin_regulation_abs_total", 0.0)
    residual = _ms_num(canonical, "bath_discrete_residual_rms", 0.0)

    workload_noise = float(rng.lognormal(mean=0.0, sigma=0.10))
    criticality_noise = float(rng.normal(0,0.04))
    util_noise = [float(rng.normal(0,s)) for s in (0.025,0.035,0.025,0.020,0.025)]
    p95_noise = float(rng.uniform(0.0,0.10))
    p99_noise = float(rng.uniform(0.0,0.12))
    failure_noise = float(rng.normal(0,0.03))
    security_exposure_noise = float(rng.lognormal(mean=0.0,sigma=0.12))

    demand = workload_noise * (0.84 + 0.22 * initial_distance + 0.04 * min(2.0, final_error) + 0.025 * min(5.0, residual))
    criticality = _ms_clamp(0.55 + 0.35 * initial_distance + criticality_noise, 0.35, 1.0)

    oc_readiness = _ms_clamp(0.72 + 0.18 * final_u + 0.10 * (1.0 - confirm_step / 20.0), 0.65, 1.0)
    oc_effort = _ms_clamp(math.tanh(max(0.0, regulation) / 5.0), 0.0, 1.0)
    if mode in ("kubernetes_plus_omnicompass", "omnicompass_direct"):
        adaptive_quality = 0.035 * oc_readiness + 0.012 * oc_effort
        adaptive_recovery = 1.0 - 0.18 * oc_readiness
        adaptive_prevention = 1.0 - 0.12 * oc_readiness
    else:
        adaptive_quality = 0.0
        adaptive_recovery = 1.0
        adaptive_prevention = 1.0

    # Unit-stack physics and economics. No scale-dependent degradation is mixed
    # into the primary financial model. Scale effects belong in a separate
    # optional stress study, not in the controlling normalized comparison.
    unit_scale_log = math.log2(2.0)
    coordination_loss = policy["coordination"] * unit_scale_log / 10.0
    network_complexity = 1.0 + 0.034 * unit_scale_log + (0.055 if environment in ("hybrid_cloud","edge_distributed") else 0.0)
    effective_quality = _ms_clamp(policy["quality"] + adaptive_quality - coordination_loss, 0.45, 0.985)
    overhead = _ms_clamp(policy["overhead"] + 0.0045 * unit_scale_log, 0.005, 0.22)
    capacity = env["capacity"] * effective_quality * (1.0 - overhead)

    base_rho = demand / max(0.25, capacity * 1.08)
    cpu_util = _ms_clamp(0.52 + 0.23 * base_rho + util_noise[0], 0.15, 0.985)
    gpu_util = _ms_clamp(0.47 + 0.28 * base_rho + util_noise[1], 0.10, 0.985)
    memory_util = _ms_clamp(0.55 + 0.20 * base_rho + util_noise[2], 0.20, 0.985)
    network_util = _ms_clamp((0.44 + 0.25 * base_rho) * network_complexity + util_noise[3], 0.10, 0.995)
    storage_util = _ms_clamp(0.48 + 0.23 * base_rho + 0.018 * unit_scale_log + util_noise[4], 0.10, 0.995)
    max_util = max(cpu_util, gpu_util, memory_util, network_util, storage_util)
    queue_multiplier = 1.0 / max(0.08, 1.0 - 0.88 * max_util)

    p50_latency_ms = env["base_latency_ms"] * network_complexity * (1.0 + overhead * 3.0) * (1.0 + 0.16 * queue_multiplier)
    p95_latency_ms = p50_latency_ms * (1.55 + 0.36 * queue_multiplier) * (1.0 + p95_noise)
    p99_latency_ms = p95_latency_ms * (1.30 + p99_noise)

    unit_throughput = 100000.0 * effective_quality * env["capacity"] / max(0.65, demand) / network_complexity
    unit_throughput *= (1.0 - 0.55 * overhead)
    throughput = unit_throughput * stacks

    unit_base_failures = max(0.0, env["failure"] * (0.035 + 0.03 * initial_distance) * demand + failure_noise)
    unit_failure_events = unit_base_failures * policy["technical_failure_frequency"] * adaptive_prevention
    recovery_seconds = max(0.5, 50.0 * policy["recovery"] * adaptive_recovery * network_complexity / max(0.45,effective_quality) * (1.0 + 0.35 * initial_distance))
    unit_downtime_seconds = unit_failure_events * recovery_seconds
    failure_events = unit_failure_events * stacks
    aggregate_downtime_seconds = unit_downtime_seconds * stacks
    availability = _ms_clamp(1.0 - unit_downtime_seconds / 86400.0, 0.90, 0.9999999)
    dropped_work_pct = _ms_clamp(100.0 * unit_downtime_seconds / 86400.0 * (1.15 - effective_quality), 0.0, 15.0)

    provision_factor = 1.0 + max(0.0, 0.90 - effective_quality) * 1.9 + coordination_loss + overhead
    unit_cpu_core_hours = MS_RESOURCE_VECTOR["cpu_core_equiv"] * 24.0 * provision_factor * (0.42 + 0.58 * cpu_util)
    unit_gpu_hours = MS_RESOURCE_VECTOR["gpu_equiv"] * 24.0 * provision_factor * (0.30 + 0.70 * gpu_util)
    unit_storage_gb_month = MS_RESOURCE_VECTOR["storage_tb"] * 1024.0 * (0.72 + 0.28 * storage_util)
    unit_network_gb_day = MS_RESOURCE_VECTOR["network_gbps"] * 10800.0 * network_util * env["egress_fraction"]

    unit_it_power_kw = 0.035 * MS_RESOURCE_VECTOR["cpu_core_equiv"] * cpu_util + 0.42 * MS_RESOURCE_VECTOR["gpu_equiv"] * gpu_util + 0.00055 * MS_RESOURCE_VECTOR["memory_gb"] * memory_util + 0.25
    unit_energy_kwh_day = unit_it_power_kw * 24.0 * env["pue"]
    unit_compute_cost_day = unit_cpu_core_hours * env["cpu_core_hour"] + unit_gpu_hours * env["gpu_hour"]
    unit_storage_cost_day = unit_storage_gb_month * env["storage_gb_month"] / 30.4375
    unit_network_cost_day = unit_network_gb_day * env["network_gb"]
    unit_energy_cost_day = unit_energy_kwh_day * env["power_kwh"]

    unit_base_fte = 1.35 + 0.22 + 0.15 * math.log10(2.0)
    unit_engineer_fte = unit_base_fte * policy["engineers"] * (1.0 + 0.22 * coordination_loss) * (1.0 + 0.08 * (network_complexity - 1.0))
    loaded_engineer_cost_year = 133080.0 * 1.45
    unit_engineering_cost_day = unit_engineer_fte * loaded_engineer_cost_year / 365.25

    unit_observed_hosts = 1.0 + 0.05 * unit_scale_log
    unit_observability_cost_day = unit_observed_hosts * (18.0 / 30.4375) * (0.85 + 0.25 * network_util)
    unit_control_plane_cost_day = policy["control_plane_hour"] * 24.0
    unit_software_cost_day = unit_observability_cost_day + unit_control_plane_cost_day

    unit_business_value_per_minute = 75.0 + 175.0 * criticality
    unit_service_interruption_loss_day = unit_downtime_seconds / 60.0 * unit_business_value_per_minute

    unit_base_material_outage_rate_year = (0.03 + 0.040) * env["failure"] * demand
    unit_material_outage_rate_year = unit_base_material_outage_rate_year * policy["material_incident_frequency"] * adaptive_prevention
    outage_reference_cost = sum(float(b["probability"]) * float(b["representative_cost_usd"]) for b in MS_INCIDENT_COST_MODEL["major_outage_cost_bands"])
    outage_reference_cost *= (0.75 + 0.50 * criticality) * policy["severity_containment"]
    unit_major_outage_expected_loss_day = unit_material_outage_rate_year * outage_reference_cost / 365.25

    security_environment_factor = {
        "bare_metal":0.90,"on_premises":0.96,"private_cloud":1.00,
        "public_cloud":1.10,"hybrid_cloud":1.16,"edge_distributed":1.22,
    }[environment]
    unit_base_security_incident_rate_year = (0.015 + 0.0065) * criticality * security_environment_factor * security_exposure_noise
    unit_security_incident_rate_year = unit_base_security_incident_rate_year * policy["security_incident_frequency"] * adaptive_prevention / max(0.85,policy["security"])
    unit_security_incident_expected_loss_day = unit_security_incident_rate_year * MS_INCIDENT_COST_MODEL["reference_security_breach_cost_usd"] * policy["severity_containment"] / 365.25

    unit_response_hours_day = unit_failure_events * (0.35 + recovery_seconds / 3600.0) + unit_material_outage_rate_year * 18.0 / 365.25
    unit_incident_response_cost_day = unit_response_hours_day * MS_INCIDENT_COST_MODEL["loaded_incident_engineer_hour_usd"]
    unit_sla_customer_impact_cost_day = unit_material_outage_rate_year * MS_INCIDENT_COST_MODEL["minimum_sla_and_customer_impact_per_material_incident_usd"] * policy["severity_containment"] / 365.25

    unit_operational_outage_loss_day = max(unit_service_interruption_loss_day, unit_major_outage_expected_loss_day)
    unit_risk_adjusted_incident_loss_day = unit_operational_outage_loss_day + unit_security_incident_expected_loss_day + unit_incident_response_cost_day + unit_sla_customer_impact_cost_day
    unit_non_incident_cost_day = unit_compute_cost_day + unit_storage_cost_day + unit_network_cost_day + unit_energy_cost_day + unit_engineering_cost_day + unit_software_cost_day
    unit_total_cost_day = unit_non_incident_cost_day + unit_risk_adjusted_incident_loss_day

    compute_cost_day = unit_compute_cost_day * stacks
    storage_cost_day = unit_storage_cost_day * stacks
    network_cost_day = unit_network_cost_day * stacks
    energy_cost_day = unit_energy_cost_day * stacks
    engineering_cost_day = unit_engineering_cost_day * stacks
    software_cost_day = unit_software_cost_day * stacks
    service_interruption_loss_day = unit_service_interruption_loss_day * stacks
    major_outage_expected_loss_day = unit_major_outage_expected_loss_day * stacks
    security_incident_expected_loss_day = unit_security_incident_expected_loss_day * stacks
    incident_response_cost_day = unit_incident_response_cost_day * stacks
    sla_customer_impact_cost_day = unit_sla_customer_impact_cost_day * stacks
    risk_adjusted_incident_loss_day = unit_risk_adjusted_incident_loss_day * stacks
    non_incident_cost_day = unit_non_incident_cost_day * stacks
    total_cost_day = unit_total_cost_day * stacks

    material_outage_rate_year = unit_material_outage_rate_year * stacks
    security_incident_rate_year = unit_security_incident_rate_year * stacks
    energy_kwh_day = unit_energy_kwh_day * stacks
    engineer_fte = unit_engineer_fte * stacks
    containers = int(round(stacks * MS_RESOURCE_VECTOR["containers"] * provision_factor))
    db_ops = stacks * MS_RESOURCE_VECTOR["database_ops_per_second"] * effective_quality * availability
    ai_units = stacks * MS_RESOURCE_VECTOR["ai_inference_units_per_second"] * effective_quality * gpu_util
    ros2_msgs = stacks * MS_RESOURCE_VECTOR["ros2_messages_per_second"] * effective_quality / network_complexity
    hpc_jobs = stacks * MS_RESOURCE_VECTOR["hpc_jobs_per_hour"] * effective_quality * (0.45 + gpu_util)
    aerospace_cycles = stacks * MS_RESOURCE_VECTOR["aerospace_control_cycles_per_second"] * effective_quality / max(1.0,p95_latency_ms/2.0)
    logistics_orders = stacks * MS_RESOURCE_VECTOR["logistics_orders_per_hour"] * effective_quality * availability
    search_qps = stacks * MS_RESOURCE_VECTOR["search_queries_per_second"] * effective_quality / max(1.0,p50_latency_ms)

    return {
        "benchmark_schema":MS_BENCHMARK_SCHEMA,
        "canonical_run_id":run_id,
        "common_disturbance_draw_id":common_draw_id,
        "common_disturbance_seed":int(common_seed),
        "environment":environment,
        "environment_label":_ms_environment_label(environment),
        "mode":mode,
        "mode_label":_ms_mode_label(mode),
        "stack_count":stacks,
        "reference_stack_count":MS_REFERENCE_STACK_COUNT,
        "normalized_scale_multiple":stacks,
        "one_stack_normalization":True,
        "scale_projection_rule":"aggregate totals = one-stack value x stack_count; per-stack metrics and savings percentages remain invariant",
        "muscle_count":len(MS_MUSCLE_CATALOG),
        "muscle_catalog_sha256":_ms_catalog_hash(),
        "initial_distance_to_basin":initial_distance,
        "omnicompass_readiness":oc_readiness,
        "omnicompass_effort_index":oc_effort,
        "effective_scheduling_quality":effective_quality,
        "orchestration_overhead_pct":100.0*overhead,
        "cpu_utilization_pct":100.0*cpu_util,
        "gpu_utilization_pct":100.0*gpu_util,
        "memory_utilization_pct":100.0*memory_util,
        "network_utilization_pct":100.0*network_util,
        "storage_utilization_pct":100.0*storage_util,
        "throughput_work_units_per_second":throughput,
        "latency_p50_ms":p50_latency_ms,
        "latency_p95_ms":p95_latency_ms,
        "latency_p99_ms":p99_latency_ms,
        "failure_events_per_day":failure_events,
        "material_outage_events_per_year":material_outage_rate_year,
        "security_incidents_per_year":security_incident_rate_year,
        "mean_recovery_seconds":recovery_seconds,
        "downtime_seconds_per_day":aggregate_downtime_seconds,
        "downtime_seconds_per_stack_per_day":unit_downtime_seconds,
        "availability_pct":100.0*availability,
        "dropped_work_pct":dropped_work_pct,
        "energy_kwh_per_day":energy_kwh_day,
        "engineer_fte":engineer_fte,
        "containers_equivalent":containers,
        "database_ops_per_second":db_ops,
        "ai_inference_units_per_second":ai_units,
        "ros2_messages_per_second":ros2_msgs,
        "hpc_jobs_per_hour":hpc_jobs,
        "aerospace_control_cycles_per_second":aerospace_cycles,
        "logistics_orders_per_hour":logistics_orders,
        "search_queries_per_second":search_qps,
        "compute_cost_usd_per_day":compute_cost_day,
        "storage_cost_usd_per_day":storage_cost_day,
        "network_cost_usd_per_day":network_cost_day,
        "energy_cost_usd_per_day":energy_cost_day,
        "engineering_cost_usd_per_day":engineering_cost_day,
        "software_observability_cost_usd_per_day":software_cost_day,
        "service_interruption_loss_usd_per_day":service_interruption_loss_day,
        "major_outage_expected_loss_usd_per_day":major_outage_expected_loss_day,
        "security_incident_expected_loss_usd_per_day":security_incident_expected_loss_day,
        "incident_response_cost_usd_per_day":incident_response_cost_day,
        "sla_customer_impact_cost_usd_per_day":sla_customer_impact_cost_day,
        "risk_adjusted_incident_loss_usd_per_day":risk_adjusted_incident_loss_day,
        "risk_adjusted_incident_loss_usd_per_year":risk_adjusted_incident_loss_day*365.25,
        "downtime_cost_usd_per_day":service_interruption_loss_day,
        "non_incident_operating_cost_usd_per_day":non_incident_cost_day,
        "total_cost_usd_per_day":total_cost_day,
        "total_cost_usd_per_year":total_cost_day*365.25,
        "total_cost_usd_per_stack_per_year":unit_total_cost_day*365.25,
        "statistical_scope":"one canonical Monte Carlo variable pushed through one normalized complete-stack unit, then duplicated by the declared scale multiple",
        "evidence_class":"executed synthetic digital-twin result; not a production invoice or hardware meter",
    }


MS_SUMMARY_METRICS = (
    "cpu_utilization_pct","gpu_utilization_pct","memory_utilization_pct","network_utilization_pct","storage_utilization_pct",
    "throughput_work_units_per_second","latency_p50_ms","latency_p95_ms","latency_p99_ms","failure_events_per_day",
    "material_outage_events_per_year","security_incidents_per_year","mean_recovery_seconds","downtime_seconds_per_day",
    "availability_pct","dropped_work_pct","energy_kwh_per_day","engineer_fte",
    "database_ops_per_second","ai_inference_units_per_second","ros2_messages_per_second","hpc_jobs_per_hour",
    "aerospace_control_cycles_per_second","logistics_orders_per_hour","search_queries_per_second",
    "compute_cost_usd_per_day","storage_cost_usd_per_day","network_cost_usd_per_day","energy_cost_usd_per_day",
    "engineering_cost_usd_per_day","software_observability_cost_usd_per_day",
    "service_interruption_loss_usd_per_day","major_outage_expected_loss_usd_per_day","security_incident_expected_loss_usd_per_day",
    "incident_response_cost_usd_per_day","sla_customer_impact_cost_usd_per_day","risk_adjusted_incident_loss_usd_per_day",
    "risk_adjusted_incident_loss_usd_per_year","downtime_cost_usd_per_day","non_incident_operating_cost_usd_per_day",
    "total_cost_usd_per_day","total_cost_usd_per_year","total_cost_usd_per_stack_per_year",
)


def _ms_summarize(raw_rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    groups: Dict[Tuple[str,str,int], List[Dict[str,Any]]] = {}
    for row in raw_rows:
        groups.setdefault((row["environment"],row["mode"],int(row["stack_count"])),[]).append(row)
    out=[]
    for (environment,mode,stacks), group in sorted(groups.items(), key=lambda x:(MS_ENVIRONMENTS.index(x[0][0]),MS_MODES.index(x[0][1]),MS_CLUSTER_SCALES.index(x[0][2]))):
        record={
            "environment":environment,"environment_label":_ms_environment_label(environment),
            "mode":mode,"mode_label":_ms_mode_label(mode),"stack_count":stacks,
            "run_count":len(group),"muscle_count":len(MS_MUSCLE_CATALOG),"muscle_catalog_sha256":_ms_catalog_hash(),
            "common_disturbance_matching":"mode excluded from common disturbance seed; same run/environment one-stack shock duplicated across governance modes and scales",
        }
        for metric in MS_SUMMARY_METRICS:
            record[metric]=_ms_stats([float(r[metric]) for r in group])
        out.append(record)
    index={(r["environment"],r["mode"],r["stack_count"]):r for r in out}
    for r in out:
        baseline=index.get((r["environment"],"kubernetes",r["stack_count"]))
        unmanaged=index.get((r["environment"],"no_orchestrator",r["stack_count"]))
        if baseline:
            base_cost=baseline["total_cost_usd_per_day"]["mean"]
            cost=r["total_cost_usd_per_day"]["mean"]
            base_thr=baseline["throughput_work_units_per_second"]["mean"]
            thr=r["throughput_work_units_per_second"]["mean"]
            base_lat=baseline["latency_p95_ms"]["mean"]
            lat=r["latency_p95_ms"]["mean"]
            base_energy=baseline["energy_kwh_per_day"]["mean"]
            energy=r["energy_kwh_per_day"]["mean"]
            base_eng=baseline["engineer_fte"]["mean"]
            eng=r["engineer_fte"]["mean"]
            base_incident=baseline["risk_adjusted_incident_loss_usd_per_day"]["mean"]
            incident=r["risk_adjusted_incident_loss_usd_per_day"]["mean"]
            annual_impact=(base_cost-cost)*365.25
            r["versus_kubernetes"]={
                "financial_impact_usd_per_day":base_cost-cost,
                "financial_impact_usd_per_year":annual_impact,
                "financial_impact_interpretation":"positive = savings beyond Kubernetes; zero = Kubernetes baseline; negative = additional cost versus Kubernetes",
                "cost_savings_usd_per_day":base_cost-cost,
                "cost_savings_usd_per_year":annual_impact,
                "cost_savings_pct":100.0*(base_cost-cost)/base_cost if base_cost else 0.0,
                "incident_loss_reduction_usd_per_day":base_incident-incident,
                "incident_loss_reduction_usd_per_year":(base_incident-incident)*365.25,
                "incident_loss_reduction_pct":100.0*(base_incident-incident)/base_incident if base_incident else 0.0,
                "throughput_change_pct":100.0*(thr-base_thr)/base_thr if base_thr else 0.0,
                "p95_latency_reduction_pct":100.0*(base_lat-lat)/base_lat if base_lat else 0.0,
                "energy_savings_pct":100.0*(base_energy-energy)/base_energy if base_energy else 0.0,
                "engineering_fte_reduction_pct":100.0*(base_eng-eng)/base_eng if base_eng else 0.0,
            }
        if unmanaged:
            unmanaged_cost=unmanaged["total_cost_usd_per_day"]["mean"]
            unmanaged_incident=unmanaged["risk_adjusted_incident_loss_usd_per_day"]["mean"]
            r["versus_unmanaged"]={
                "total_savings_usd_per_day":unmanaged_cost-r["total_cost_usd_per_day"]["mean"],
                "total_savings_usd_per_year":(unmanaged_cost-r["total_cost_usd_per_day"]["mean"])*365.25,
                "incident_loss_reduction_usd_per_year":(unmanaged_incident-r["risk_adjusted_incident_loss_usd_per_day"]["mean"])*365.25,
            }
    return out


def _ms_write_csv(path: Path, rows: List[Dict[str,Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if not rows:
        path.write_text("",encoding="utf-8")
        return
    fields=[]
    seen=set()
    for row in rows:
        for key in row.keys():
            if key not in seen:
                seen.add(key); fields.append(key)
    with path.open("w",newline="",encoding="utf-8") as f:
        w=csv.DictWriter(f,fieldnames=fields)
        w.writeheader()
        for row in rows:
            w.writerow({k:(json.dumps(v,sort_keys=True,default=str) if isinstance(v,(dict,list,tuple)) else v) for k,v in row.items()})


def _ms_write_catalog(outdir: Path) -> Dict[str,str]:
    cat_path=outdir/"STACK_MUSCLE_CATALOG.csv"
    with cat_path.open("w",newline="",encoding="utf-8") as f:
        w=csv.writer(f); w.writerow(["index","family","muscle","description","catalog_sha256"])
        for i,(fam,name,desc) in enumerate(MS_MUSCLE_CATALOG,1):
            w.writerow([i,fam,name,desc,_ms_catalog_hash()])
    vector_path=outdir/"STACK_RESOURCE_VECTOR.json"
    vector_path.write_text(json.dumps({"reference_stack_count":MS_REFERENCE_STACK_COUNT,"scaling_rule":"N x one-stack value","per_stack_resource_vector":MS_RESOURCE_VECTOR,"muscle_count":len(MS_MUSCLE_CATALOG),"catalog_sha256":_ms_catalog_hash()},indent=2),encoding="utf-8")
    sources_path=outdir/"PUBLIC_SOURCE_REGISTRY.json"
    sources_path.write_text(json.dumps({"accessed":"2026-08-01","sources":MS_SOURCE_REGISTRY},indent=2),encoding="utf-8")
    assumptions_path=outdir/"COST_AND_PERFORMANCE_ASSUMPTIONS.json"
    assumptions_path.write_text(json.dumps({
        "benchmark_schema":MS_BENCHMARK_SCHEMA,
        "environment_model":MS_ENVIRONMENT_MODEL,
        "mode_model":MS_MODE_MODEL,
        "incident_cost_model":MS_INCIDENT_COST_MODEL,
        "primary_financial_baseline":"One complete stack is the controlling normalized cost unit. Kubernetes is the zero reference only in the incremental-impact view and is never represented as having zero operating cost. The 10-, 100-, and 1,000-stack primary financial values are exact multiples of the one-stack result.",
        "infrastructure_governance_distinction":"Bare metal is an infrastructure environment. No orchestration is a governance mode. They are orthogonal dimensions and are never treated as synonyms.",
        "loaded_engineer_cost_formula":"BLS May 2024 median software developer wage $133,080 x 1.45 loaded-cost factor",
        "electricity_reference":"EIA 2025 U.S. industrial average 8.62 cents/kWh; edge model uses 12 cents/kWh",
        "managed_kubernetes_reference":"AWS EKS and Google GKE public pages list a standard $0.10 per cluster-hour management fee; Azure pricing is calculator/offer dependent",
        "cost_basis_and_source_disclosure":MS_COST_BASIS_DISCLOSURE,
        "model_uncertainty":{"cost_pct":MS_MODEL_UNCERTAINTY_COST_PCT,"performance_pct":MS_MODEL_UNCERTAINTY_PERFORMANCE_PCT,"incident_pct":MS_MODEL_UNCERTAINTY_INCIDENT_PCT},
        "claim_boundary":"Cost coefficients are a transparent reference model, not a vendor quote, contract, invoice, or production measurement. Statistical intervals quantify simulated run variation only; model-form uncertainty is disclosed separately.",
    },indent=2),encoding="utf-8")
    cost_basis_path=outdir/"COST_BASIS_AND_SOURCE_DISCLOSURE.md"
    cost_basis_path.write_text("\n".join([
        "# Cost Basis and Public-Source Disclosure", "",
        MS_COST_BASIS_DISCLOSURE["method"], "",
        "## Declared cost-input basis", "",
        *[f"- **{k.replace('_',' ').title()}:** {v}" for k,v in MS_COST_BASIS_DISCLOSURE.items() if k not in ("method","comparison_formula","calibration_rule")],
        "", "## Matched comparison equation", "", MS_COST_BASIS_DISCLOSURE["comparison_formula"],
        "", "## Production calibration rule", "", MS_COST_BASIS_DISCLOSURE["calibration_rule"],
        "", "Exact URLs and source uses are in `PUBLIC_SOURCE_REGISTRY.json`; exact numerical coefficients are in `COST_AND_PERFORMANCE_ASSUMPTIONS.json`."
    ]),encoding="utf-8")
    muscle_adjust_path=outdir/"ONE_STACK_MUSCLE_ADJUSTMENT_TEMPLATE.csv"
    family_surface={
        "compute":"compute/accelerator","containers":"compute/engineering","network":"network/engineering",
        "storage":"storage/engineering","data":"compute/storage/network/engineering","observability":"observability/engineering",
        "security":"incident-loss/engineering/observability","automation":"engineering/compute","ai":"compute/accelerator/network",
        "hpc":"compute/accelerator/network","robotics":"compute/network/incident-loss","automotive":"compute/network/incident-loss",
        "aerospace":"compute/network/incident-loss","enterprise":"compute/storage/network/incident-loss","logistics":"compute/network",
        "edge":"compute/network/energy/incident-loss","resilience":"incident-loss/engineering","governance":"engineering/observability/incident-loss",
    }
    with muscle_adjust_path.open("w",newline="",encoding="utf-8") as f:
        w=csv.writer(f); w.writerow(["index","family","muscle","description","included_cost_surfaces","default_inclusion_factor","organization_adjustment_instruction"])
        for i,(fam,name,desc) in enumerate(MS_MUSCLE_CATALOG,1):
            w.writerow([i,fam,name,desc,family_surface.get(fam,"engineering"),1.0,"Set inclusion factor from 0.0 to 1.0 or replace with measured utilization; do not double count shared cost surfaces."])
    return {"catalog_csv":str(cat_path),"resource_vector_json":str(vector_path),"source_registry_json":str(sources_path),"assumptions_json":str(assumptions_path),"cost_basis_and_source_disclosure_md":str(cost_basis_path),"one_stack_muscle_adjustment_template_csv":str(muscle_adjust_path)}


def _ms_money_axis_label(value: float) -> str:
    value=float(value)
    sign="-" if value < 0 else ""
    v=abs(value)
    if v >= 1_000_000_000: return f"{sign}${v/1_000_000_000:.2f}B"
    if v >= 1_000_000: return f"{sign}${v/1_000_000:.2f}M"
    if v >= 1_000: return f"{sign}${v/1_000:.1f}K"
    return f"{sign}${v:.0f}"


def _ms_average_metric(summary_rows: List[Dict[str,Any]], mode: str, stacks: int, metric: str) -> float:
    vals=[float(r[metric]["mean"]) for r in summary_rows if r["mode"]==mode and int(r["stack_count"])==int(stacks)]
    return float(np.mean(vals)) if vals else 0.0


def _ms_primary_financial_table(summary_rows: List[Dict[str,Any]]) -> List[Dict[str,Any]]:
    rows=[]
    for stacks in MS_CLUSTER_SCALES:
        k8s=_ms_average_metric(summary_rows,"kubernetes",stacks,"total_cost_usd_per_year")
        for mode in MS_PRIMARY_REPORT_MODES:
            annual=_ms_average_metric(summary_rows,mode,stacks,"total_cost_usd_per_year")
            incident=_ms_average_metric(summary_rows,mode,stacks,"risk_adjusted_incident_loss_usd_per_year")
            impact=k8s-annual
            rows.append({
                "stack_count":int(stacks),"mode":mode,"mode_label":_ms_mode_label(mode),
                "annual_operating_cost_usd":annual,
                "annual_cost_per_stack_usd":annual/max(1,int(stacks)),
                "incremental_financial_impact_vs_kubernetes_usd":impact,
                "incremental_financial_impact_vs_kubernetes_pct":100.0*impact/k8s if k8s else 0.0,
                "risk_adjusted_incident_loss_usd":incident,
            })
    return rows


def _ms_one_stack_component_ledger(summary_rows: List[Dict[str,Any]]) -> List[Dict[str,Any]]:
    """Average one-stack annual cost components across declared environments."""
    components=[
        ("compute_cost_usd_per_day","Compute and accelerator"),
        ("storage_cost_usd_per_day","Storage"),
        ("network_cost_usd_per_day","Network and data movement"),
        ("energy_cost_usd_per_day","Energy and facilities"),
        ("engineering_cost_usd_per_day","Engineering and operations labor"),
        ("software_observability_cost_usd_per_day","Observability and control plane"),
        ("risk_adjusted_incident_loss_usd_per_day","Failure, outage, security and recovery loss"),
    ]
    out=[]
    for mode in MS_PRIMARY_REPORT_MODES:
        total=_ms_average_metric(summary_rows,mode,1,"total_cost_usd_per_year")
        for metric,label in components:
            annual=_ms_average_metric(summary_rows,mode,1,metric)*365.25
            out.append({"stack_count":1,"mode":mode,"mode_label":_ms_mode_label(mode),"component":label,
                        "annual_cost_usd":annual,"share_of_mode_total_pct":100.0*annual/total if total else 0.0})
    return out


def _ms_one_stack_scaling_guide(summary_rows: List[Dict[str,Any]]) -> List[Dict[str,Any]]:
    """Controlling one-stack baseline and exact integer scale projections."""
    primary=_ms_primary_financial_table(summary_rows)
    out=[]
    for mode in MS_PRIMARY_REPORT_MODES:
        unit=next(x for x in primary if x["stack_count"]==1 and x["mode"]==mode)
        for stacks in MS_CLUSTER_SCALES:
            out.append({
                "mode":mode,"mode_label":unit["mode_label"],"stack_count":stacks,
                "one_stack_annual_cost_usd":unit["annual_operating_cost_usd"],
                "projected_annual_cost_usd":unit["annual_operating_cost_usd"]*stacks,
                "one_stack_impact_vs_kubernetes_usd":unit["incremental_financial_impact_vs_kubernetes_usd"],
                "projected_impact_vs_kubernetes_usd":unit["incremental_financial_impact_vs_kubernetes_usd"]*stacks,
                "impact_vs_kubernetes_pct":unit["incremental_financial_impact_vs_kubernetes_pct"],
                "formula":"N x one-stack value",
            })
    return out


def _ms_generate_charts(summary_rows: List[Dict[str,Any]], outdir: Path, canonical_run_count: int, file_suffix: str) -> Dict[str,str]:
    """Global Megastack visuals using fixed signed dot, dumbbell, slope, and
    component-decomposition formats. Exact linear scale projections are labeled."""
    outdir.mkdir(parents=True,exist_ok=True); charts={}; canonical_run_count=int(canonical_run_count); suffix=str(file_suffix).strip().upper() or f"{canonical_run_count}_RUN"
    primary=_ms_primary_financial_table(summary_rows)
    _short_mode_labels={
        "no_orchestrator":"No orchestration",
        "kubernetes":"Kubernetes",
        "kubernetes_plus_omnicompass":"K8s + OC",
        "omnicompass_direct":"OC direct",
        "alternative_nomad_slurm":"Nomad/Slurm style",
    }
    labels=[_short_mode_labels.get(m,_ms_mode_label(m)) for m in MS_PRIMARY_REPORT_MODES]
    _mode_colors=[OC_VISUAL_SERIES[i % len(OC_VISUAL_SERIES)] for i,_ in enumerate(MS_PRIMARY_REPORT_MODES)]
    note=f"{OC_VISUAL_SYSTEM_ID}; modeled one-stack ledger and exact scale projections. Not production invoices or measured fleet scaling."

    # Signed impact small multiples: lollipop allows negative and positive values without block mass.
    fig,axes=plt.subplots(2,2,figsize=(12.00,9.44),dpi=180)
    for ax,stacks in zip(axes.ravel(),MS_CLUSTER_SCALES):
        vals=[next(x["incremental_financial_impact_vs_kubernetes_usd"] for x in primary if x["stack_count"]==stacks and x["mode"]==m) for m in MS_PRIMARY_REPORT_MODES]
        cols=[OC_SEMANTIC_COLORS["favorable"] if v>0 else OC_SEMANTIC_COLORS["adverse"] if v<0 else OC_SEMANTIC_COLORS["neutral"] for v in vals]
        _oc_lollipop(ax,labels,vals,horizontal=True,colors_list=cols,value_format="${:,.0f}"); ax.set_title(f"{stacks:,} complete stack(s)"); ax.set_xlabel("USD/year versus Kubernetes")
    fig.suptitle(f"{canonical_run_count}-run CFO view: incremental annual impact versus Kubernetes",fontsize=14,fontweight="semibold")
    pp=outdir/f"MEGASTACK_INCREMENTAL_IMPACT_VS_KUBERNETES_ALL_SCALES_{suffix}.png"; _oc_save_figure(fig,pp,note=note+" Kubernetes is the zero reference, not a zero-cost system."); plt.close(fig); charts["incremental_impact_vs_kubernetes"]=str(pp)

    fig,axes=plt.subplots(2,2,figsize=(12.00,9.44),dpi=180)
    for ax,stacks in zip(axes.ravel(),MS_CLUSTER_SCALES):
        vals=[next(x["annual_operating_cost_usd"] for x in primary if x["stack_count"]==stacks and x["mode"]==m) for m in MS_PRIMARY_REPORT_MODES]
        _oc_lollipop(ax,labels,vals,horizontal=True,colors_list=_mode_colors,value_format="${:,.0f}",zero_line=False); ax.set_title(f"{stacks:,} complete stack(s)"); ax.set_xlabel("Modeled USD/year")
    fig.suptitle(f"{canonical_run_count}-run supporting ledger: absolute annual operating cost",fontsize=14,fontweight="semibold")
    pp=outdir/f"MEGASTACK_ABSOLUTE_ANNUAL_COST_ALL_SCALES_{suffix}.png"; _oc_save_figure(fig,pp,note=note); plt.close(fig); charts["absolute_annual_cost"]=str(pp)

    fig,axes=plt.subplots(2,2,figsize=(12.00,9.44),dpi=180)
    for ax,stacks in zip(axes.ravel(),MS_CLUSTER_SCALES):
        vals=[next(x["risk_adjusted_incident_loss_usd"] for x in primary if x["stack_count"]==stacks and x["mode"]==m) for m in MS_PRIMARY_REPORT_MODES]
        _oc_lollipop(ax,labels,vals,horizontal=True,colors_list=_mode_colors,value_format="${:,.0f}",zero_line=False); ax.set_title(f"{stacks:,} complete stack(s)"); ax.set_xlabel("Risk-adjusted USD/year")
    fig.suptitle(f"{canonical_run_count}-run outage, security, and recovery-loss model",fontsize=14,fontweight="semibold")
    pp=outdir/f"MEGASTACK_RISK_ADJUSTED_INCIDENT_LOSS_ALL_SCALES_{suffix}.png"; _oc_save_figure(fig,pp,note=note); plt.close(fig); charts["incident_loss_by_scale"]=str(pp)

    components=[("compute_cost_usd_per_day","Compute"),("storage_cost_usd_per_day","Storage"),("network_cost_usd_per_day","Network"),("energy_cost_usd_per_day","Energy"),("engineering_cost_usd_per_day","Engineering"),("software_observability_cost_usd_per_day","Observability"),("risk_adjusted_incident_loss_usd_per_day","Incident loss")]
    k8=[]; direct=[]
    for key,_ in components:
        base=_ms_average_metric(summary_rows,"kubernetes",1,key); k8.append((base-_ms_average_metric(summary_rows,"kubernetes_plus_omnicompass",1,key))*365.25); direct.append((base-_ms_average_metric(summary_rows,"omnicompass_direct",1,key))*365.25)
    fig,ax=plt.subplots(figsize=(10.80,7.08)); _oc_dumbbell(ax,[lab for _,lab in components],k8,direct,baseline_label="K8s + Omni-Compass",contender_label="Omni-Compass direct",value_format="${:,.0f}")
    ax.axvline(0,color=OC_VISUAL_PALETTE["ink"],linewidth=.8); ax.set_xlabel("Additional annual savings versus Kubernetes (USD)"); ax.set_title(f"{canonical_run_count}-run one-stack savings decomposition")
    pp=outdir/f"MEGASTACK_SAVINGS_DECOMPOSITION_1_STACK_{suffix}.png"; _oc_save_figure(fig,pp,note=note); plt.close(fig); charts["savings_decomposition"]=str(pp)

    for metric,slug,ylabel in [("total_cost_usd_per_day","cost","USD per day"),("throughput_work_units_per_second","throughput","work units/s"),("latency_p95_ms","latency","p95 latency (ms)"),("energy_kwh_per_day","energy","kWh/day"),("engineer_fte","engineers","engineering FTE"),("availability_pct","availability","availability (%)"),("risk_adjusted_incident_loss_usd_per_day","incident_loss","incident loss USD/day")]:
        fig,axes=plt.subplots(2,3,figsize=(12.00,8.26),dpi=170)
        display_ylabel = "modeled downtime (minutes/year)" if metric=="availability_pct" else ylabel
        display_title = "service unavailability derived from availability" if metric=="availability_pct" else ylabel
        for ax,env in zip(axes.ravel(),MS_ENVIRONMENTS):
            subset=[r for r in summary_rows if r["environment"]==env and r["stack_count"]==1]
            raw_vals=[next((r[metric]["mean"] for r in subset if r["mode"]==m),0.0) for m in MS_MODES]
            vals=[(100.0-v)/100.0*365.25*24.0*60.0 for v in raw_vals] if metric=="availability_pct" else raw_vals
            value_fmt="{:.1f}" if metric=="availability_pct" else "{:.3g}"
            _oc_lollipop(ax,labels,vals,horizontal=False,colors_list=_mode_colors,value_format=value_fmt,zero_line=False)
            ax.set_title(_ms_environment_label(env),fontsize=11.0); ax.set_ylabel(display_ylabel,fontsize=11.0); ax.tick_params(axis="x",labelrotation=18,labelsize=11.0)
        fig.suptitle(f"Global Megastack: {canonical_run_count}-run one-stack consensus - {display_title}",fontsize=13,fontweight="semibold")
        pp=outdir/f"MEGASTACK_{slug.upper()}_1_STACK_{suffix}.png"; _oc_save_figure(fig,pp,note=note); plt.close(fig); charts[slug]=str(pp)
    return charts


def _ms_draw_architecture(mode: str, width: float=524, height: float=344) -> Drawing:
    """Collision-safe Megastack architecture plate at >=11 pt."""
    d=Drawing(width,height)
    d.add(String(8,height-17,"Matched global stack architecture",fontName="OCSans-Bold",fontSize=11.0))
    d.add(String(8,height-33,_ms_mode_label(mode),fontName="OCSans-Bold",fontSize=11.0))
    layers=[
        ("Infrastructure", ["Bare metal | On-prem | Private", "Public | Hybrid | Edge"]),
        ("Physical muscles", ["CPU | GPU | Memory | Network", "Storage | Containers | Databases"]),
        ("Domain workloads", ["AI | HPC | ROS 2 | Automotive", "Aerospace | Logistics | Search"]),
        ("Operations", ["Terraform | CI/CD | Security", "OpenTelemetry | Grafana | Datadog-style"]),
        ("Governance", [_ms_mode_label(mode)]),
    ]
    y=height-62; row_h=39; gap=10
    for i,(name,desc_lines) in enumerate(layers):
        d.add(Rect(18,y-row_h,width-36,row_h,strokeColor=colors.black,fillColor=colors.whitesmoke,strokeWidth=.8))
        d.add(String(28,y-16,name,fontName="OCSans-Bold",fontSize=11.0))
        if len(desc_lines)==1:
            d.add(String(155,y-16,desc_lines[0],fontName="OCSans",fontSize=11.0))
        else:
            d.add(String(155,y-12,desc_lines[0],fontName="OCSans",fontSize=11.0))
            d.add(String(155,y-27,desc_lines[1],fontName="OCSans",fontSize=11.0))
        if i < len(layers)-1:
            d.add(Line(width/2,y-row_h,width/2,y-row_h-gap+2,strokeWidth=1))
            d.add(Polygon([width/2-3,y-row_h-gap+5,width/2+3,y-row_h-gap+5,width/2,y-row_h-gap+1],fillColor=colors.black,strokeColor=colors.black))
        y-=row_h+gap
    return d

def _ms_metric_bar(title: str, labels: List[str], values: List[float], width: float=508, height: float=260) -> Drawing:
    d=Drawing(width,height)
    d.add(String(5,height-15,title,fontName="OCSans-Bold",fontSize=11.0))
    if not values:
        return d
    maxv=max(values) or 1.0
    left=130; barw=width-left-92; y=height-38
    for label,val in zip(labels,values):
        d.add(String(5,y+2,label,fontName="OCSans",fontSize=11.0))
        d.add(Rect(left,y,barw,10,strokeColor=colors.lightgrey,fillColor=colors.white,strokeWidth=.4))
        d.add(Rect(left,y,barw*max(0.0,val)/maxv,10,strokeColor=colors.black,fillColor=colors.lightgrey,strokeWidth=.4))
        d.add(String(width-10,y+1,f"{val:,.2f}",fontName="OCSans",fontSize=11.0,textAnchor="end"))
        y-=24
    return d


def _ms_report_footer(canvas, doc):
    canvas.setProducer(OC_PDF_PRODUCER)
    canvas.setCreator("Omni-Compass Python Report Engine")
    canvas.setAuthor("The Omni-Compass LLC")
    canvas.saveState()
    canvas.setFont("OCSans-BoldOblique",9)
    canvas.drawString(OC_PAGE_LEFT_MARGIN_PT,OC_FOOTER_BASELINE_PT,f"{doc.page}")
    canvas.setFont("OCSans",9)
    canvas.drawCentredString(LETTER[0]/2.0,OC_FOOTER_BASELINE_PT,"www.omni-compass.com")
    canvas.setFont("OCSans-BoldOblique",9)
    canvas.drawRightString(LETTER[0]-OC_PAGE_RIGHT_MARGIN_PT,OC_FOOTER_BASELINE_PT,f"{doc.page}")
    canvas.restoreState()


def _ms_breakable_cell_markup(value: Any) -> str:
    """Return escaped cell text with invisible breaks in paths, hashes, and IDs."""
    return _oc_soft_break_html(value)


def _ms_table(data, widths, font=11.0, repeat=1, leading=None):
    """Margin-safe report table with wrapping Paragraph cells and fixed typography."""
    font=max(11.0,float(font)); widths=_oc_scale_widths(widths, maximum=508.0)
    if leading is None or float(leading)<font+2.2: leading=font+2.2
    body_style=ParagraphStyle("MSTableBody",fontName="OCSans",fontSize=font,leading=leading,
        spaceAfter=0,spaceBefore=0,splitLongWords=False,wordWrap="LTR",allowWidows=0,allowOrphans=0)
    head_style=ParagraphStyle("MSTableHead",fontName="OCSans-Bold",fontSize=font,leading=leading,
        spaceAfter=0,spaceBefore=0,splitLongWords=False,wordWrap="LTR",allowWidows=0,allowOrphans=0)
    wrapped=[]
    for ridx,row in enumerate(data):
        style=head_style if ridx<int(repeat or 0) else body_style
        wrapped.append([cell if isinstance(cell,(Paragraph,Table,Image)) else Paragraph(_ms_breakable_cell_markup(cell),style) for cell in row])
    t=Table(wrapped,colWidths=widths,repeatRows=repeat,hAlign="LEFT",splitByRow=1)
    t.setStyle(TableStyle([
        ("BACKGROUND",(0,0),(-1,max(0,int(repeat)-1)),colors.lightgrey),
        ("GRID",(0,0),(-1,-1),.35,colors.grey),("VALIGN",(0,0),(-1,-1),"TOP"),
        ("LEFTPADDING",(0,0),(-1,-1),4),("RIGHTPADDING",(0,0),(-1,-1),4),
        ("TOPPADDING",(0,0),(-1,-1),4),("BOTTOMPADDING",(0,0),(-1,-1),4),
    ]))
    return t


def _ms_wrapped_table(data, widths, font=11.0, leading=None, repeat=1):
    """Compatibility wrapper; _ms_table now wraps every textual cell globally."""
    return _ms_table(data,widths,font=font,repeat=repeat,leading=leading)


def _ms_find_summary(payload: Dict[str,Any], env: str, mode: str, stacks: int) -> Dict[str,Any]:
    for r in payload.get("summary_rows",[]):
        if r["environment"]==env and r["mode"]==mode and int(r["stack_count"])==int(stacks):
            return r
    return {}


def _ms_signed_money(value: float) -> str:
    value=float(value)
    if abs(value) < 0.005:
        return "$0 (Kubernetes baseline)"
    return ("+" if value > 0 else "-") + _ms_money_axis_label(abs(value))


def _ms_build_100_page_report(payload: Dict[str,Any], mode: str, path: Path) -> None:
    styles=getSampleStyleSheet()
    title=ParagraphStyle("MSTitle",parent=styles["Title"],fontName="OCSans-Bold",fontSize=20,leading=24,spaceAfter=16)
