    story.append(Spacer(1,6)); story.append(_ms_wrapped_table(_oc_economic_benefit_independence_rows(),[100,195,195],font=11.0,leading=13.2))
    story.append(Spacer(1,6)); story.append(_ms_wrapped_table(_oc_economic_benefit_authority_rows(),[90,190,210],font=11.0,leading=13.2))
    story.append(Spacer(1,6)); story.append(_ms_wrapped_table(_oc_economic_benefit_technical_rows(),[115,185,190],font=11.0,leading=13.2))
    story.append(Spacer(1,6)); story.append(_ms_wrapped_table(_oc_economic_benefit_cost_rows(),[115,195,180],font=11.0,leading=13.2))
    story.append(Spacer(1,6)); story.append(_ms_wrapped_table(_oc_economic_benefit_formula_rows({"global_stack_payload": payload}),[140,350],font=11.0,leading=13.2))
    story.append(Spacer(1,6)); story.append(_ms_wrapped_table(_oc_economic_benefit_risk_rows(),[120,175,195],font=11.0,leading=13.2)); story.append(PageBreak())
