def run_public_enterprise_manager_benchmark(canonical_rows: List[Dict[str,Any]], seed_base: int, output_dir: str, selection_seed: int) -> Dict[str,Any]:
    outdir=Path(output_dir).expanduser(); outdir.mkdir(parents=True,exist_ok=True)
    if not canonical_rows: raise RuntimeError("Public manager benchmark requires canonical Monte Carlo rows")
    canonical_100=_ms_select_report_rows(canonical_rows,min(100,len(canonical_rows)),int(selection_seed)); _full_n=len(canonical_rows); _sample_n=len(canonical_100); _same_population=(_full_n==_sample_n); ids100={int(_ms_num(r,"run_id",0)) for r in canonical_100}
    raw=[]
    for env in MS_ENVIRONMENTS:
        for mid in PM_MANAGER_ORDER:
            for var in PM_VARIANTS:
                for stacks in PM_CLUSTER_SCALES:
                    for canonical in canonical_rows:
                        raw.append(_pm_run_one(canonical,env,mid,var,stacks,seed_base))
    raw100=raw if _same_population else [r for r in raw if int(r["canonical_run_id"]) in ids100]
