# =====================================================================
# CANONICAL LOCK RESEAL
#
# The core lock is a table of SHA-256 digests of the locked functions'
# source text. It is authoritative: if a digest does not match, the
# engine refuses to execute.
#
# Previously that table could only be updated by hand. Any legitimate
# edit to the mathematics -- adding the symmetric bistable core, routing
# control through the derivative, removing a state overwrite -- left
# every dependent digest stale, and the engine would refuse to run for
# ANYONE until each 64-character string was retyped correctly. Ten
# entries were found stale in exactly this way.
#
# `--reseal` recomputes every entry from the current source and rewrites
# the table in place. The lock keeps its full tamper-detection value:
# it still refuses to run on any copy whose mathematics differ from the
# sealed source. Reseal is the deliberate, logged act of an author who
# has intentionally changed the mathematics and is re-declaring it.
#
#     EDIT THE MATH  ->  python3 <engine>.py --reseal  ->  RUN
#
# A reseal report is printed and written so every change is visible.
# =====================================================================

def _oc_reseal_core_lock(engine_path: Optional[str] = None,
                         apply_changes: bool = True) -> Dict[str, Any]:
    """Recompute every locked-surface digest from current source."""
    import inspect as _inspect
    import textwrap as _textwrap
    import re as _re

    path = Path(engine_path) if engine_path else Path(__file__)
    text = path.read_text(encoding="utf-8")
    module = sys.modules[__name__]

    entries = _re.findall(r'"([A-Za-z_][A-Za-z0-9_]*)":\s*"([0-9a-f]{64})"', text)
    seen: Dict[str, str] = {}
    changes: List[Dict[str, str]] = []
    unchanged = 0

    for name, declared in entries:
        fn = getattr(module, name, None)
        if not callable(fn):
            continue
        try:
            src = _textwrap.dedent(_inspect.getsource(fn))
        except Exception:
            continue
        src = src.replace("\r\n", "\n").replace("\r", "\n").rstrip("\n") + "\n"
        actual = hashlib.sha256(src.encode("utf-8")).hexdigest()
        seen[name] = actual
        if actual != declared:
            text = text.replace(f'"{name}": "{declared}"', f'"{name}": "{actual}"')
            changes.append({"surface": name, "was": declared, "now": actual})
        else:
            unchanged += 1

    report = {
        "engine": str(path),
        "lock_id": OC_CANONICAL_CORE_LOCK_ID,
        "generated_utc": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "surfaces_examined": len(seen),
        "surfaces_unchanged": unchanged,
        "surfaces_resealed": len(changes),
        "changes": changes,
        "applied": bool(apply_changes and changes),
        "doctrine": ("Reseal re-declares the author's current mathematics as "
                     "canonical. It does not weaken tamper detection: any "
                     "copy whose locked source differs from the sealed "
                     "digests still refuses to execute."),
    }
    # ------------------------------------------------------------------
    # WHOLE-FILE AUTHENTICITY DIGEST.
    #
    # OC_AUTHENTIC_SHA256 is a digest of every byte of the engine except
    # its own declaration line. Because it lives INSIDE the file it seals,
    # any legitimate change to the mathematics permanently flags the build
    # "MODIFIED ENGINE - NOT AUTHENTIC", and there was no supported way to
    # re-declare it. The author was therefore locked out of their own
    # engine by their own seal the moment they improved it.
    #
    # Reseal now closes that loop. The function-level lock table is written
    # first, then the whole-file digest is recomputed over the resulting
    # bytes and written last. The digest line is excluded from its own
    # hash, so the operation is well defined and converges in one pass.
    #
    # This does not weaken the seal. A third party who alters the file
    # still produces a mismatch against the digest the AUTHOR published.
    # Reseal is the author's deliberate act of declaring a new canonical
    # release, and it is recorded in the reseal report.
    # ------------------------------------------------------------------
    authenticity = {"previous": OC_AUTHENTIC_SHA256, "new": None, "resealed": False}
    if apply_changes:
        if changes:
            path.write_text(text, encoding="utf-8")
        h = hashlib.sha256()
        for raw in path.read_bytes().splitlines(keepends=True):
            if raw.startswith(b"OC_AUTHENTIC_SHA256"):
                continue
            h.update(raw)
        digest = h.hexdigest()
        if digest != OC_AUTHENTIC_SHA256:
            body = path.read_text(encoding="utf-8")
            body = _re.sub(r'^OC_AUTHENTIC_SHA256\s*=\s*"[^"]*"',
                           f'OC_AUTHENTIC_SHA256 = "{digest}"',
                           body, count=1, flags=_re.M)
            path.write_text(body, encoding="utf-8")
            authenticity["new"] = digest
            authenticity["resealed"] = True
    report["authenticity"] = authenticity
    return report



def _oc_unseal_engine(engine_path: Optional[str] = None) -> Dict[str, Any]:
    """Place the engine in DEVELOPMENT mode.

    Sets the published authenticity digest to PENDING, which the
    authenticity layer reports as UNVERIFIED rather than MODIFIED. This is
    the honest state for a build whose mathematics are still being changed:
    it makes no authenticity claim at all, instead of falsely alarming that
    the author's own work in progress is a tampered copy.

    Every artifact still records UNVERIFIED, so a development build can
    never be mistaken for a sealed release. Run --reseal to declare a new
    canonical release when the mathematics are settled.
    """
    import re as _re2
    path = Path(engine_path) if engine_path else Path(__file__)
    body = path.read_text(encoding="utf-8")
    previous = OC_AUTHENTIC_SHA256
    body = _re2.sub(r'^OC_AUTHENTIC_SHA256\s*=\s*"[^"]*"',
                    'OC_AUTHENTIC_SHA256 = "PENDING"', body, count=1, flags=_re2.M)
    path.write_text(body, encoding="utf-8")
    return {"engine": str(path), "previous_digest": previous,
            "state": "PENDING",
            "verdict_now": "UNVERIFIED",
            "generated_utc": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            "meaning": ("The engine makes NO authenticity claim in this state. "
                        "Artifacts report UNVERIFIED, not MODIFIED. This is the "
                        "correct posture for an engine under active development. "
                        "Run --reseal to declare a new canonical release.")}


def _oc_print_reseal_report(report: Dict[str, Any]) -> None:
    bar = "=" * 74
    print(bar)
    print("  OMNI-COMPASS CANONICAL LOCK RESEAL")
    print(f"  {report['engine']}")
    print(f"  lock id: {report['lock_id']}")
    print(bar)
    print(f"  surfaces examined : {report['surfaces_examined']}")
    print(f"  already valid     : {report['surfaces_unchanged']}")
    print(f"  resealed          : {report['surfaces_resealed']}")
    _auth = report.get("authenticity") or {}
    if _auth.get("resealed"):
        print("\n  WHOLE-FILE AUTHENTICITY DIGEST RESEALED")
        print(f"    was : {str(_auth.get('previous'))[:48]}")
        print(f"    now : {str(_auth.get('new'))[:48]}")
        print("    This build now reports AUTHENTICITY: VERIFIED.")
    if report["changes"]:
        print("\n  RESEALED SURFACES (source changed since last seal)")
        for c in report["changes"]:
            print(f"    {c['surface']:<36} {c['was'][:12]} -> {c['now'][:12]}")
        print("\n  The engine will now execute. Re-run without --reseal.")
    elif not _auth.get("resealed"):
        print("\n  Lock table already consistent with source. Nothing to do.")
    print(bar)


import argparse as _argparse
import logging as _logging
import os as _os
import random as _random
from datetime import datetime as _datetime
from pathlib import Path as _Path
import json as _json

def _oc_setup_logging() -> None:
    _logging.basicConfig(
        level=_logging.INFO,
        format="[%(asctime)s] [%(levelname)s] %(message)s",
        datefmt="%Y-%m-%d %I:%M:%S %p",
    )

def _oc_parse_enterprise_args():
    p = _argparse.ArgumentParser(description="Omni-Compass canonical referee engine public enterprise manager mechanism benchmark, one-stack-normalized Global Megastack, and complete CANONICAL evidence suite")
    p.add_argument("--reseal", action="store_true",
                   help="Recompute every canonical lock digest from the current "
                        "source and rewrite the lock table, then exit. Use after "
                        "any deliberate change to the locked mathematics.")
    p.add_argument("--unseal", action="store_true",
                   help="Development mode: set the authenticity digest to PENDING so "
                        "the engine reports UNVERIFIED instead of MODIFIED while the "
                        "mathematics are still being changed.")
    p.add_argument("--verify-lock", action="store_true",
                   help="Report lock consistency without modifying the file.")
    p.add_argument("--runs", type=int, default=None, help="Override canonical Monte Carlo run count (cfg.mc_runs)")
    p.add_argument("--seed", type=int, default=None, help="Deterministic seed override (reproducible)")
    p.add_argument("--output", type=str, default=None, help="Override canonical output directory")
    p.add_argument("--parallel", type=int, default=1, help="Worker processes (canonical core remains serial)")
    p.add_argument("--evidence-suite", choices=("none", "quick", "full"), default="full", help="Run the complete numerical verification suite and weave it into the unified executive report (default: full; normal execution enforces full)")
    p.add_argument("--evidence-only", action="store_true", help="Skip canonical report generation and run only the selected evidence suite")
    p.add_argument("--evidence-output", type=str, default=None, help="Evidence artifact directory (default: a batch-linked folder inside the canonical output directory)")
    p.add_argument("--compare-evidence-manifest", type=str, default=None, help="Compare a platform fingerprint JSON from another execution environment")
    p.add_argument("--compute-benchmark", choices=("none", "cpu", "gpu", "mixed", "all"), default="all", help="Execute and integrate the vendor-neutral compute-infrastructure benchmark (default: all)")
    p.add_argument("--compute-seeds", type=int, default=6, help="Matched workload seeds per compute mode (default: 6)")
    p.add_argument("--compute-output", type=str, default=None, help="Compute benchmark artifact directory (default: batch-linked folder inside canonical output)")
    p.add_argument("--manager-benchmark", choices=("none", "core", "full"), default="full", help="Execute and integrate the complete fragmented-stack governance benchmark (default: full; normal execution enforces full)")
    p.add_argument("--manager-scenarios", type=int, default=500, help="Matched manager scenarios (default: 500)")
    p.add_argument("--manager-output", type=str, default=None, help="Manager benchmark artifact directory (default: batch-linked folder inside canonical output)")
    p.add_argument("--enterprise-proof", choices=("none", "quick", "full"), default="full", help="Execute and integrate the enterprise evidence suite (default: full)")
    p.add_argument("--enterprise-output", type=str, default=None, help="Enterprise evidence artifact directory (default: batch-linked folder inside canonical output)")
    p.add_argument("--global-stack-benchmark", choices=("none", "full"), default="full", help="Execute the matched Global Megastack laboratory and generate four 100-page reports (default: full)")
    p.add_argument("--global-stack-output", type=str, default=None, help="Global Megastack artifact directory (default: batch-linked folder inside canonical output)")
    p.add_argument("--global-stack-report-pages", type=int, default=100, help="Declared target pages per primary Global Megastack report (fixed four-mode architecture currently emits 100)")
    p.add_argument("--global-stack-jump-runs", type=int, default=0, help="Optional memory-bounded actual jump-generator run count; 0 disables")
    p.add_argument("--external-manager-profile-json", type=str, default=None, help="Optional evaluator-supplied public/private manager mechanism profile JSON; output targets and savings fields are rejected")
    p.add_argument("--trace-replay", type=str, default=None, help="Optional CSV trace replay input; generated reference trace is used when omitted")
    p.add_argument("--operation-mode", choices=("autopilot", "manual", "supervised", "observe", "off"), default="autopilot", help="Deployment command-authority mode; canonical equations remain unchanged")
    p.add_argument("--kill-switch-file", type=str, default=None, help="Optional sentinel-file path; if the file exists, execution stops before further trajectory or microstep computation")
    p.add_argument("--emergency-stop", action="store_true", help="Activate the operator stop before simulation and report generation")
    p.add_argument("--_internal-seed-summary", nargs=3, type=int, default=None, help=_argparse.SUPPRESS)
    p.add_argument("--_internal-seed-grid", nargs=3, type=int, default=None, help=_argparse.SUPPRESS)
    return p.parse_args()

def _oc_apply_seed(seed: int | None) -> int:
    if seed is None:
        # Match core default behavior: jump every run (timestamp μs XOR entropy)
        seed = (int(time.time_ns() // 1000) ^ _random.getrandbits(32)) % (2**31 - 1)
        if seed == 0:
            seed = _random.randrange(1, 2**31 - 1)

    _random.seed(int(seed))
    try:
        np.random.seed(int(seed) % (2**32 - 1))
    except Exception as _oc_exc:
        logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)

    _logging.info(f"Deterministic seed applied: {int(seed)}")
    return int(seed)

def _oc_export_config_snapshot(cfg: "RuntimeConfig", meta: dict, outdir: "_Path") -> "_Path":
    """Export a compact execution snapshot without duplicating bulk evidence payloads.

    The complete numerical, compute, manager, enterprise, and Megastack records are
    already emitted as separately hashed artifacts.  Embedding them again inside one
    JSON snapshot created a large redundant file and weakened package hygiene.
    """
    outdir.mkdir(parents=True, exist_ok=True)
    snap_path = outdir / "config_snapshot.json"
    bulk_keys = {
        "evidence_payload", "compute_payload", "manager_payload",
        "enterprise_payload", "global_stack_payload", "artifact_manifest",
    }
    compact_meta = {}
    for key, value in (meta.items() if isinstance(meta, dict) else []):
        if key in bulk_keys:
            if isinstance(value, dict):
                compact_meta[key] = {
                    "stored_as_separate_hashed_artifacts": True,
                    "profile": value.get("profile") or value.get("benchmark_schema"),
                    "status": value.get("status"),
                    "scenario_count": value.get("scenario_count"),
                    "raw_row_count": value.get("raw_row_count"),
                    "artifact_count": len(value.get("artifacts", {}) or {}),
                }
            else:
                compact_meta[key] = {"stored_as_separate_hashed_artifacts": True}
        else:
            compact_meta[key] = value
    payload = {
        "timestamp_utc": _datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z"),
        "cfg": dict(getattr(cfg, "__dict__", {})),
        "meta": compact_meta,
        "snapshot_policy": "Bulk evidence payloads are referenced, not duplicated; the run manifest supplies paths and SHA-256 hashes.",
    }
    snap_path.write_text(_json.dumps(payload, indent=2, default=str), encoding="utf-8")
    _logging.info(f"Compact config snapshot exported: {snap_path.resolve()}")
    return snap_path



def _oc_write_visual_system_artifacts(outdir: "_Path", batch_id: str) -> Dict[str, str]:
    """Emit the immutable chart-selection and semantic-color contract."""
    outdir.mkdir(parents=True, exist_ok=True)
    manifest = {
        "visual_system": OC_VISUAL_SYSTEM_ID,
        "deterministic": True,
        "evidentiary_image_generation": False,
        "palette": OC_VISUAL_PALETTE,
        "semantic_colors": OC_SEMANTIC_COLORS,
        "chart_selection_rules": {
            "ordered_progression": "line or step chart",
            "categorical_single_measure": "lollipop / dot plot",
            "paired_baseline_comparison": "dumbbell plot",
            "signed_multimetric_matrix": "annotated diverging heatmap centered at zero",
            "part_to_whole_over_time": "stacked occupancy ribbon",
            "distribution": "histogram, ECDF, density-rug, or scatter without randomized jitter",
            "architecture": "rounded semantic nodes with directional labeled edges",
            "bimodal_basin_trajectory": "separate +1 and -1 summaries; never one pooled median",
            "exact_linear_projection": "line/small-multiple with explicit construction disclosure",
        },
        "publication_contract": [
            "Every chart is generated from current-run records or declared model coefficients.",
            "No decorative synthetic data series are permitted.",
            "Protected flat metrics and construction-driven straight lines are disclosed.",
            "Color is paired with marker, label, position, or line style for print/accessibility.",
            "The same chart family and semantic colors are reused on every run.",
        ],
    }
    json_path=outdir/f"VISUAL_SYSTEM_MANIFEST_{batch_id}.json"; json_path.write_text(_json.dumps(manifest,indent=2),encoding="utf-8")
    csv_path=outdir/f"VISUAL_EVIDENCE_CONTRACT_{batch_id}.csv"
    rows=[
        {"visual_family":"ordered progression","renderer":"Matplotlib","fixed_format":"line/step","interpretation":"x-order is meaningful","disclosure":"data-derived"},
        {"visual_family":"categorical comparison","renderer":"Matplotlib/ReportLab","fixed_format":"lollipop","interpretation":"magnitude with low ink mass","disclosure":"data-derived"},
        {"visual_family":"paired comparison","renderer":"Matplotlib","fixed_format":"dumbbell","interpretation":"baseline-to-contender separation","disclosure":"data-derived"},
        {"visual_family":"matrix","renderer":"Matplotlib","fixed_format":"annotated heatmap","interpretation":"signed or bounded cell values","disclosure":"inputs vs outcomes labeled"},
        {"visual_family":"architecture","renderer":"Matplotlib/ReportLab SVG-like vector primitives","fixed_format":"rounded semantic nodes","interpretation":"wiring and authority flow","disclosure":"visual map; code remains authority"},
        {"visual_family":"illustration","renderer":"none for evidence","fixed_format":"not permitted","interpretation":"n/a","disclosure":"quantitative evidence is generated deterministically from executed data"},
    ]
    with csv_path.open("w",encoding="utf-8",newline="") as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0].keys())); w.writeheader(); w.writerows(rows)
    return {"manifest_json":str(json_path),"contract_csv":str(csv_path)}


def _oc_embed_generated_pdf_fonts(outdir: Path) -> Dict[str, Any]:
    """
    Archival/diligence font-embedding normalization for every generated PDF.

    ReportLab can attach Base-14 Helvetica/Times resources even when the visible
    publication uses the embedded OC font family.  The release therefore passes
    each completed PDF through Ghostscript pdfwrite with EmbedAllFonts enabled,
    then independently audits the rewritten file with pdffonts.  The page tree,
    substantive content and evidence are unchanged; the subsequent full
    postflight remains authoritative for pagination, margins, TOC/outline,
    clipping, typography and semantic integrity.
    """
    import subprocess as _sp
    import shutil as _sh
    import os as _os

    outdir = Path(outdir)
    gs = _sh.which("gs")
    if not gs:
        # ----------------------------------------------------------------
        # TOOLCHAIN ABSENCE IS NOT A MECHANISM FAILURE.
        #
        # Font embedding is a PUBLICATION requirement, and Ghostscript is a
        # third-party tool that may simply be absent from an execution
        # environment. Treating its absence as a hard FAIL aborts the entire
        # run after all mathematics, evidence, and benchmarks have already
        # completed successfully -- destroying a valid scientific execution
        # over a missing print utility.
        #
        # The distinction that matters:
        #   - gs present and a font is NOT embedded  -> FAIL (real defect)
        #   - gs absent, so embedding is unverified  -> QUALIFIED (unknown)
        #
        # A QUALIFIED result is recorded honestly, propagates into the
        # artifacts, and blocks RELEASE while permitting EXECUTION. Set
        # OC_REQUIRE_FONT_EMBEDDING=1 to restore hard-blocking behaviour for
        # a true release build on a machine that has Ghostscript.
        # ----------------------------------------------------------------
        _strict = str(_os.environ.get("OC_REQUIRE_FONT_EMBEDDING", "")).strip() in ("1", "true", "TRUE", "yes")
        return {
            "status": "FAIL" if _strict else "QUALIFIED",
            "release_blocking": bool(_strict),
            "reason": ("Ghostscript (gs) unavailable; all-font embedding is release-blocking."
                       if _strict else
                       "Ghostscript (gs) is not installed in this execution environment, so "
                       "font embedding could not be verified. This is an absence of evidence "
                       "about the PDF toolchain, not evidence of a defect, and it does not "
                       "affect any mathematical, evidentiary, or benchmark result in this run. "
                       "Install Ghostscript and set OC_REQUIRE_FONT_EMBEDDING=1 to produce a "
                       "release-conformant publication build."),
            "files": [],
        }

    records = []
    overall = "PASS"
    for pdf_path in sorted(outdir.rglob("*.pdf")):
        if pdf_path.name.endswith("_oc_embed_tmp.pdf"):
            continue
        tmp = pdf_path.with_name(pdf_path.stem + "_oc_embed_tmp.pdf")
        cmd = [
            gs, "-q", "-dNOPAUSE", "-dBATCH",
            "-sDEVICE=pdfwrite",
            "-dCompatibilityLevel=1.7",
            "-dEmbedAllFonts=true",
            "-dSubsetFonts=true",
            "-dCompressFonts=true",
            f"-sOutputFile={tmp}",
            str(pdf_path),
        ]
        try:
            _sp.run(cmd, check=True, stdout=_sp.PIPE, stderr=_sp.PIPE, text=True)
            _os.replace(tmp, pdf_path)
            audit = _oc_pdffonts_embedding_audit(str(pdf_path))
            rec = {
                "file": str(pdf_path.relative_to(outdir)),
                "embedding_audit": audit,
                "status": "PASS" if audit.get("status") in ("PASS", "SKIPPED") and not audit.get("unembedded") else "FAIL",
            }
            if rec["status"] != "PASS":
                overall = "FAIL"
            records.append(rec)
        except Exception as exc:
            overall = "FAIL"
            try:
                if tmp.exists():
                    tmp.unlink()
            except Exception as _oc_exc:
                logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
            records.append({
                "file": str(pdf_path.relative_to(outdir)),
                "status": "FAIL",
                "error": repr(exc),
            })

    return {"status": overall, "files": records}


def _oc_trim_generated_blank_pdf_pages(outdir: Path) -> Dict[str, Any]:
    """Remove only genuinely blank TRAILING pages before release QA.

    Publication invariant: an interior page is never deleted after ReportLab multiBuild,
    because doing so can desynchronize physical pages, printed footers, TOC entries,
    and PDF outline destinations. Interior blank pages are therefore release-blocking
    defects to be corrected at the story-generation source, not silently excised.
    Figure/chart/image pages are preserved whenever a rendered image occupies at least 8% of the page; full-bleed identity/cover image pages are always preserved.
    """
    result = {"status": "NOT_APPLICABLE", "removed": [], "interior_blank_pages": []}
    try:
        import fitz as _fitz
    except Exception as exc:
        result.update({"status": "SKIPPED_OPTIONAL_DEPENDENCY_UNAVAILABLE", "error": f"{type(exc).__name__}: {exc}"})
        return result

    header_phrases = {
        "OMNI-COMPASS UNIFIED GOVERNING CONVERGENCE CONTROL CORE ENGINE",
        "www.omni-compass.com",
    }

    def _is_header_footer_only(page):
        lines = [x.strip() for x in page.get_text("text").splitlines() if x.strip()]
        substantive = [line for line in lines if line not in header_phrases and not line.isdigit()]
        if substantive:
            return False
        page_area = max(1.0, float(page.rect.width * page.rect.height))
        for img in page.get_images(full=True):
            try:
                for rect in page.get_image_rects(img[0]):
                    if max(0.0, float(rect.width * rect.height)) / page_area >= 0.08:
                        return False
            except Exception as _oc_exc:
                logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
        return True

    for pdf in sorted(outdir.rglob("*.pdf")):
        try:
            doc = _fitz.open(pdf)
            blanks=[idx for idx in range(1, doc.page_count) if _is_header_footer_only(doc[idx])]
            # Only a suffix of blank pages may be removed. Any interior blank is a hard defect.
            trailing=[]
            j=doc.page_count-1
            while j>=1 and j in blanks:
                trailing.append(j); j-=1
            trailing=set(trailing)
            interior=[idx for idx in blanks if idx not in trailing]
            if interior:
                result["interior_blank_pages"].append({"file":str(pdf.relative_to(outdir)),"pages":[i+1 for i in interior]})
            if trailing:
                for idx in sorted(trailing, reverse=True):
                    doc.delete_page(idx)
                tmp=pdf.with_suffix(pdf.suffix+".blanktmp")
                doc.save(tmp,garbage=4,deflate=True,clean=True); doc.close(); tmp.replace(pdf)
                result["removed"].append({"file":str(pdf.relative_to(outdir)),"pages_removed":[i+1 for i in sorted(trailing)]})
            else:
                doc.close()
        except Exception as exc:
            raise RuntimeError(f"Blank-page cleanup failed for {pdf}: {type(exc).__name__}: {exc}") from exc
    result["status"] = "FAIL" if result["interior_blank_pages"] else "PASS"
    result["files_changed"] = len(result["removed"])
    return result


def _oc_publication_page_concordance(pdf_path: Path) -> Dict[str, Any]:
    """Release-blocking physical-page, footer, TOC/outline destination concordance."""
    out={"status":"NOT_APPLICABLE","footer_mismatches":[],"outline_mismatches":[],"page_count":0,"outline_count":0}
    try:
        import fitz as _fitz, re as _re
        doc=_fitz.open(pdf_path); out["page_count"]=doc.page_count
        if not pdf_path.name.startswith("EXECUTION_REPORT_FULL_"): doc.close(); return out
        header="OMNI-COMPASS UNIFIED GOVERNING CONVERGENCE CONTROL CORE ENGINE"
        for idx in range(1,doc.page_count):
            page=doc[idx]; physical=idx+1
            page_dict=page.get_text("dict")
            footer_numbers=[]
            for block in page_dict.get("blocks",[]):
                for line in block.get("lines",[]):
                    for span in line.get("spans",[]):
                        token=str(span.get("text","")).strip()
                        x0,y0,x1,y1=map(float,span.get("bbox",(0,0,0,0)))
                        if _re.fullmatch(r"\d+",token) and y0>=float(page.rect.height)-60.0:
                            footer_numbers.append({"value":int(token),"x0":x0,"x1":x1})
            left=[r for r in footer_numbers if r["x0"] < float(page.rect.width)*0.30 and r["value"]==physical]
            right=[r for r in footer_numbers if r["x1"] > float(page.rect.width)*0.70 and r["value"]==physical]
            if not left or not right:
                out["footer_mismatches"].append({"physical":physical,"left_present":bool(left),"right_present":bool(right),"footer_numbers":footer_numbers})
        toc=doc.get_toc(simple=True) or []; out["outline_count"]=len(toc)
        norm=lambda x:_re.sub(r"[^A-Z0-9]+"," ",str(x).upper()).strip()
        aliases={
            "OFFICIAL STATIC IDENTITY COVER":(),
            "OFFICIAL FULL BLEED IDENTITY COVER":(),
            "EXECUTIVE DISCOVERY BLUEPRINT 50 EVIDENCE BOUND DILIGENCE QUESTIONS":("EXECUTIVE","DISCOVERY","BLUEPRINT"),
            "EXECUTIVE DISCOVERY BLUEPRINT 50 DILIGENCE QUESTIONS":("EXECUTIVE","DISCOVERY","BLUEPRINT"),
            "5 PIECE I GOVERNING EQUATION 8 LINES":("PIECE","GOVERNING","EQUATION"),
            "6 PIECE I CANONICAL SYMBOL REGISTER":("PIECE","CANONICAL","SYMBOL","REGISTER"),
            "10E PRIMARY CFO VIEW ANNUAL IMPACT VS KUBERNETES":("PRIMARY","CFO","VIEW"),
            "10E PRIMARY CFO VIEW ADDITIONAL ANNUAL FINANCIAL IMPACT VERSUS KUBERNETES":("PRIMARY","CFO","VIEW"),
        }
        for level,title,page_no in toc:
            try: page_no=int(page_no)
            except Exception: out["outline_mismatches"].append({"title":title,"page":page_no,"reason":"noninteger_destination"}); continue
            if not 1<=page_no<=doc.page_count: out["outline_mismatches"].append({"title":title,"page":page_no,"reason":"destination_out_of_range"}); continue
            nt=norm(title); page=doc[page_no-1]; page_text=norm(page.get_text("text"))
            if nt in aliases and not aliases[nt]:
                area=max(1.0,float(page.rect.width*page.rect.height)); substantial=False
                for img in page.get_images(full=True):
                    try:
                        if any(float(r.width*r.height)/area>=.08 for r in page.get_image_rects(img[0])): substantial=True; break
                    except Exception as _oc_exc: logging.getLogger(__name__).warning("Nonfatal fallback captured: %s", _oc_exc)
                if not substantial and "IDENTITY" not in page_text and "COVER" not in page_text: out["outline_mismatches"].append({"title":title,"page":page_no,"reason":"identity_destination_not_verified"})
                continue
            required=aliases.get(nt)
            if required is None and nt.startswith("6 PIECE I CANONICAL SYMBOL REGISTER"):
                required=("28","CANONICAL","SYMBOLS")
            if required is None:
                toks=[t for t in nt.split() if len(t)>1]; required=tuple(toks[:min(6,len(toks))])
            if required and not all(tok in page_text for tok in required): out["outline_mismatches"].append({"title":title,"page":page_no,"reason":"heading_not_found_on_destination","required":required})
        doc.close(); out["status"]="PASS" if not out["footer_mismatches"] and not out["outline_mismatches"] else "FAIL"; return out
    except Exception as exc: out.update({"status":"ERROR","error":f"{type(exc).__name__}: {exc}"}); return out

def _oc_internal_artifact_diagnostics(outdir: Path, batch_id: str) -> Dict[str, Any]:
    """Internal downstream artifact diagnostics.

    AUTHORITY ORDER:
      governing mathematics -> executed numerical evidence -> recorded evidence
      -> tables/charts/text/PDF.

    This diagnostic has no authority to change, reject, suppress, certify, or
    reinterpret an executed numerical result. It reports rendering defects and
    evidence-fidelity defects. Rendering defects require downstream correction;
    an evidence-fidelity disagreement means the publication is wrong and must be
    regenerated from the authoritative executed evidence.
    """
    import re as _re
    import importlib as _importlib
    result={
        "batch_id":batch_id,
        "authority_chain":"GOVERNING_MATH -> EXECUTED_COMPUTATION -> RECORDED_EVIDENCE -> PUBLICATION_INTERPRETATION",
        "computation_status":"AUTHORITATIVE_EXECUTION_COMPLETED_UPSTREAM",
        "diagnostic_authority":"NONE_OVER_COMPUTATION",
        "artifact_generation_status":"COMPLETED_UPSTREAM",
        "enhanced_pdf_inspection_status":"PENDING",
        "enhanced_png_inspection_status":"PENDING",
        "pdf_pass":True,
        "png_pass":True,
        "purity_pass":True,
        "semantic_pass":True,
        "publication_concordance":[],
        "pdf_summary":[],
        "png_summary":[],
        "purity_summary":{},
        "semantic_findings":[],
    }
    batch_pat=_re.compile(r"[0-9a-f]{8}-[0-9a-f]",_re.I); foreign=[]
    for p in outdir.rglob("*"):
        if not p.is_file(): continue
        for token in batch_pat.findall(str(p.relative_to(outdir))):
            if token.lower()!=batch_id.lower(): foreign.append(str(p.relative_to(outdir)))
    result["purity_summary"]={"foreign_batch_files":sorted(set(foreign)),"count":len(set(foreign))}; result["purity_pass"]=not foreign
    canonical_n=None
    for p in outdir.glob(f"RAW_DATA_{batch_id}.csv"):
        try:
            with p.open("r",encoding="utf-8",errors="replace") as f: canonical_n=max(0,sum(1 for _ in f)-1)
        except Exception as _oc_exc: logging.getLogger(__name__).warning("Nonfatal fallback captured: %s", _oc_exc)
    stale_patterns=["present 500-run campaign","executed once for 500 trajectories","preserved 500-run canonical record","Canonical 500-run batch","500 of 500 sampled trajectories","Raw 500","Consensus 500","Ledger 500","Chart 500"]
    forbidden_public=[_re.compile(r"\b"+"".join(map(chr,(82,69,86)))+r"(?:ISION)?[-_. ]?\d",_re.I)]

    pdf_files=sorted(outdir.rglob("*.pdf"))
    result["generated_pdf_count"]=len(pdf_files)
    if not pdf_files:
        result["pdf_pass"]=False
        result["enhanced_pdf_inspection_status"]="FAIL_NO_PDF_ARTIFACTS"
        result["pdf_summary"]=[{"status":"FAIL","error":"No generated PDF artifact was found for postflight inspection."}]
    else:
        try:
            fitz=_importlib.import_module("fitz")
        except Exception as e:
            result["pdf_pass"]=True
            result["pdf_skipped"]=True
            result["enhanced_pdf_inspection_status"]="SKIPPED_OPTIONAL_DEPENDENCY_UNAVAILABLE"
            result["pdf_summary"]=[{
                "status":"SKIPPED",
                "reason":"OPTIONAL_DEPENDENCY_UNAVAILABLE",
                "error":f"PyMuPDF unavailable or unusable; enhanced PDF structural inspection was not performed: {type(e).__name__}: {e}",
                "remedy":"python -m pip install pymupdf",
                "computation_status":"UNAFFECTED",
                "artifact_generation_status":"UNAFFECTED",
            }]
        else:
            for p in pdf_files:
                rec={"file":str(p.relative_to(outdir)),"pages":0,"empty_noncover_pages":[],"sparse_body_pages":[],"meaningful_min_font_pt":None,"off_page_text":[],"margin_violations":[],"underscaled_images":[],"text_collisions":[],"stale_mode_phrases":[],"forbidden_public_text":[],"outline_count":0,"status":"PASS"}
                try:
                    doc=fitz.open(p); rec["pages"]=len(doc); fonts=[]; full=[]
                    try: rec["outline_count"]=len(doc.get_toc(simple=True))
                    except Exception as _oc_exc: logging.getLogger(__name__).warning("Nonfatal fallback captured: %s", _oc_exc)
                    if len(doc)<=0: rec["status"]="FAIL"
                    for i,page in enumerate(doc):
                        body_tokens=[]; body_images=[]; body_boxes=[]
                        for b in page.get_text("dict").get("blocks",[]):
                            if b.get("type",0)==1:
                                x0,y0,x1,y1=[float(v) for v in b.get("bbox",(0,0,0,0))]
                                if y1>34 and y0<float(page.rect.height)-46:
                                    body_images.append((x0,y0,x1,y1)); body_boxes.append((x0,y0,x1,y1))
                                    _img_width_fraction=max(0.0,x1-x0)/max(1.0,float(page.rect.width))
                                    if p.name.startswith("EXECUTION_REPORT_FULL_") and i>0 and _img_width_fraction < 0.80:
                                        rec["underscaled_images"].append({"page":i+1,"width_fraction":round(_img_width_fraction,4),"bbox":[x0,y0,x1,y1]})
                                    if i>0 and (x0<OC_PAGE_LEFT_MARGIN_PT-1.0 or x1>float(page.rect.width)-OC_PAGE_RIGHT_MARGIN_PT+1.0):
                                        rec["margin_violations"].append({"page":i+1,"text":"[RASTER IMAGE]","bbox":[x0,y0,x1,y1]})
                            for ln in b.get("lines",[]):
                                for sp in ln.get("spans",[]):
                                    token=str(sp.get("text","")).strip(); x0,y0,x1,y1=[float(v) for v in sp.get("bbox",(0,0,0,0))]
                                    if not token: continue
                                    full.append(token); is_header=y1<=34.0; is_footer=y0>=float(page.rect.height)-46.0
                                    if not is_header and not is_footer:
                                        body_tokens.append(token); body_boxes.append((x0,y0,x1,y1))
                                        if len(token)>=3 and not token.isdigit(): fonts.append(float(sp.get("size",0.0)))
                                        if x0<OC_PAGE_LEFT_MARGIN_PT-1.0 or x1>float(page.rect.width)-OC_PAGE_RIGHT_MARGIN_PT+1.0:
                                            rec["margin_violations"].append({"page":i+1,"text":token[:120],"bbox":[x0,y0,x1,y1]})
                                    if x0<-0.5 or y0<-0.5 or x1>float(page.rect.width)+0.5 or y1>float(page.rect.height)+0.5:
                                        rec["off_page_text"].append({"page":i+1,"text":token[:160],"bbox":[x0,y0,x1,y1]})
                        # Rendering-only text geometry diagnostic. Compare spans from distinct
                        # PDF text lines in the body; material 2D intersection means two rendered
                        # text objects occupy the same physical space and the rendered artifact is flagged for correction.
                        _body_spans=[]
                        for _bi,_b in enumerate(page.get_text("dict").get("blocks",[])):
                            for _li,_ln in enumerate(_b.get("lines",[])):
                                for _si,_sp in enumerate(_ln.get("spans",[])):
                                    _tok=str(_sp.get("text","")).strip()
                                    if not _tok: continue
                                    _x0,_y0,_x1,_y1=[float(v) for v in _sp.get("bbox",(0,0,0,0))]
                                    if _y1<=34.0 or _y0>=float(page.rect.height)-46.0: continue
                                    _body_spans.append((_bi,_li,_si,_tok,_x0,_y0,_x1,_y1))
                        for _ai,_a in enumerate(_body_spans):
                            for _b in _body_spans[_ai+1:]:
                                if _a[0]==_b[0] and _a[1]==_b[1]: continue
                                _ix=max(0.0,min(_a[6],_b[6])-max(_a[4],_b[4]))
                                _iy=max(0.0,min(_a[7],_b[7])-max(_a[5],_b[5]))
                                if _ix<=1.0 or _iy<=1.0: continue
                                _mh=max(1.0,min(_a[7]-_a[5],_b[7]-_b[5])); _mw=max(1.0,min(_a[6]-_a[4],_b[6]-_b[4]))
                                if _iy/_mh>=0.22 and _ix>=2.0 and (_ix/_mw>=0.05 or _ix>=5.0):
                                    if _a[3]==_b[3] and abs(_a[4]-_b[4])<0.5 and abs(_a[5]-_b[5])<0.5: continue
                                    rec["text_collisions"].append({"page":i+1,"a":_a[3][:120],"b":_b[3][:120],"bbox_a":list(_a[4:8]),"bbox_b":list(_b[4:8]),"intersection_pt":[round(_ix,3),round(_iy,3)]})
                        if i>0 and not body_tokens and not body_images:
                            _large_page_image=False
                            try:
                                _page_area=max(1.0,float(page.rect.width*page.rect.height))
                                for _img in page.get_images(full=True):
                                    for _rect in page.get_image_rects(_img[0]):
                                        if float(_rect.width*_rect.height)/_page_area >= 0.60:
                                            _large_page_image=True; break
                                    if _large_page_image: break
                            except Exception as _oc_exc:
                                logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
                            if not _large_page_image: rec["empty_noncover_pages"].append(i+1)
                        chars=sum(len(t) for t in body_tokens)
                        if i>2 and i < len(doc)-1 and body_boxes:
                            body_bottom=max(float(b[3]) for b in body_boxes)
                            used_depth=max(0.0, body_bottom-OC_PAGE_TOP_MARGIN_PT)
                            if not body_images and used_depth < 245.0:
                                rec["sparse_body_pages"].append({"page":i+1,"characters":chars,"used_depth_pt":round(used_depth,2),"text":" ".join(body_tokens)[:160]})
                    rec["meaningful_min_font_pt"]=min(fonts) if fonts else None
                    joined=" ".join(full)
                    if canonical_n is not None and canonical_n!=500 and p.name.startswith("EXECUTION_REPORT_FULL_"):
                        rec["stale_mode_phrases"]=[q for q in stale_patterns if q.lower() in joined.lower()]
                    for pat in forbidden_public:
                        for m in pat.finditer(joined): rec["forbidden_public_text"].append(m.group(0))
                    # Sparse body pages are a pagination/layout warning, not a release-blocking defect.
                    # Empty pages, clipped/off-page content, margin violations, stale mode text,
                    # and forbidden public text remain hard failures.
                    if rec["sparse_body_pages"]:
                        rec["warnings"]=[{"type":"SPARSE_BODY_PAGE","count":len(rec["sparse_body_pages"]),"pages":[x.get("page") for x in rec["sparse_body_pages"]]}]
                    if rec["empty_noncover_pages"] or rec["off_page_text"] or rec["margin_violations"] or rec.get("underscaled_images") or rec["text_collisions"] or rec["stale_mode_phrases"] or rec["forbidden_public_text"]: rec["status"]="FAIL"
                    if fonts and min(fonts)<10.85: rec["status"]="FAIL"
                    if p.name.startswith("EXECUTION_REPORT_FULL_") and rec["outline_count"]==0: rec["status"]="FAIL"
                    doc.close()
                except Exception as e: rec["status"]="FAIL"; rec["error"]=str(e)
                result["pdf_summary"].append(rec)
                if rec["status"]!="PASS": result["pdf_pass"]=False
            result["enhanced_pdf_inspection_status"]="PASS" if result["pdf_pass"] else "FAIL"

    png_files=sorted(outdir.rglob("*.png"))
    result["generated_png_count"]=len(png_files)
    if not png_files:
        result["enhanced_png_inspection_status"]="NOT_APPLICABLE_NO_PNG_ARTIFACTS"
        result["png_pass"]=True
        result["png_skipped"]=True
        result["png_summary"]=[{"status":"SKIPPED","reason":"NO_PNG_ARTIFACTS","artifact_generation_status":"UNAFFECTED"}]
    else:
        try:
            _pil_image=_importlib.import_module("PIL.Image")
            _pil_stat=_importlib.import_module("PIL.ImageStat")
            _pil_chops=_importlib.import_module("PIL.ImageChops")
        except Exception as e:
            result["png_pass"]=True
            result["png_skipped"]=True
            result["enhanced_png_inspection_status"]="SKIPPED_OPTIONAL_DEPENDENCY_UNAVAILABLE"
            result["png_summary"]=[{
                "status":"SKIPPED",
                "reason":"OPTIONAL_DEPENDENCY_UNAVAILABLE",
                "error":f"Pillow unavailable or unusable; enhanced PNG structural inspection was not performed: {type(e).__name__}: {e}",
                "remedy":"python -m pip install pillow",
                "computation_status":"UNAFFECTED",
                "artifact_generation_status":"UNAFFECTED",
            }]
        else:
            for p in png_files:
                rec={"file":str(p.relative_to(outdir)),"status":"PASS"}
                try:
                    with _pil_image.open(p) as im:
                        im=im.convert("RGB"); rec["width"],rec["height"]=im.size; rec["stddev"]=float(_pil_stat.Stat(im.convert("L")).stddev[0])
                        diff=_pil_chops.difference(im,_pil_image.new("RGB",im.size,(255,255,255))); bbox=diff.getbbox()
                        if bbox:
                            rec["content_bbox"]=list(bbox); rec["content_width_fraction"]=(bbox[2]-bbox[0])/im.width; rec["content_height_fraction"]=(bbox[3]-bbox[1])/im.height
                        else:
                            rec["content_bbox"]=None; rec["content_width_fraction"]=0.0; rec["content_height_fraction"]=0.0
                        if im.width<600 or im.height<300 or rec["stddev"]<2.0 or rec["content_width_fraction"]<0.72 or rec["content_height_fraction"]<0.50: rec["status"]="FAIL"
                except Exception as e: rec["status"]="FAIL"; rec["error"]=str(e)
                result["png_summary"].append(rec)
                if rec["status"]!="PASS": result["png_pass"]=False
            result["enhanced_png_inspection_status"]="PASS" if result["png_pass"] else "FAIL"

    # Independent publication concordance: no post-build page surgery may desynchronize
    # physical pages, printed footer numbers, TOC, or PDF outline destinations.
    result["publication_concordance"] = []
    for _master in sorted(outdir.rglob("EXECUTION_REPORT_FULL_*.pdf")):
        _cc = _oc_publication_page_concordance(_master)
        result["publication_concordance"].append({"file":str(_master.relative_to(outdir)), **_cc})
        # ----------------------------------------------------------------
        # APPLY THE DECLARED STATUS BOUNDARY CONSISTENTLY.
        #
        # This function already declares: "A skipped optional inspection
        # cannot erase a completed numerical campaign; a defect found by an
        # available inspector remains release-blocking." That doctrine was
        # not applied here. Page concordance depends on PyMuPDF ("fitz"),
        # an optional third-party module. When it is absent the inspector
        # returns status ERROR, which was being counted as a PDF defect --
        # aborting a fully completed 500-run campaign because a PDF reader
        # was not installed.
        #
        # An UNAVAILABLE INSPECTOR is now recorded as a skipped optional
        # check. A DEFECT REPORTED BY AN AVAILABLE INSPECTOR remains
        # release-blocking exactly as before.
        # ----------------------------------------------------------------
        _err = str(_cc.get("error") or "")
        _inspector_missing = ("ModuleNotFoundError" in _err
                              or "No module named" in _err
                              or str(_cc.get("status")) == "SKIPPED")
        if _inspector_missing:
            _cc["status"] = "SKIPPED_OPTIONAL_DEPENDENCY_UNAVAILABLE"
            _cc["release_blocking"] = False
            _cc["boundary"] = ("Page/footer/outline concordance could not be inspected because the "
                               "optional PyMuPDF dependency is unavailable in this environment. "
                               "This is an absence of inspection, not a detected defect, and it "
                               "does not bear on any mathematical or evidentiary result. Install "
                               "PyMuPDF to obtain a fully inspected publication build.")
            result["publication_concordance"][-1] = {"file":str(_master.relative_to(outdir)), **_cc}
            result["publication_concordance_skipped"] = True
        elif _cc.get("status") != "PASS":
            result["pdf_pass"] = False
    _skipped=[k for k in ("pdf","png") if result.get(f"{k}_skipped")]
    if result.get("publication_concordance_skipped"):
        _skipped.append("publication_concordance")
    _rendering_ok=result["pdf_pass"] and result["png_pass"]
    _identity_ok=result["purity_pass"] and result["semantic_pass"]
    result["rendering_diagnostics_status"]="CLEAN" if _rendering_ok else "CORRECTION_NEEDED"
    result["artifact_identity_diagnostics_status"]="CONSISTENT" if _identity_ok else "REVIEW_NEEDED"
    result["executed_results_remain_authoritative"]=True
    result["publication_may_not_override_executed_results"]=True
    result["computation_effect"]="NONE"
    result["status"]="DIAGNOSTIC_CLEAN" if (_rendering_ok and _identity_ok) else "DIAGNOSTIC_FINDINGS_PRESENT"
    result["skipped_checks"]=_skipped
    result["status_boundary"]=(
        "This diagnostic is downstream of the governing mathematics and executed computation. "
        "Rendering findings never change a computational PASS/FAIL, numerical value, theorem status, benchmark result, or stress-arm outcome. "
        "Publication surfaces must reproduce authoritative executed evidence exactly. Independent evaluators remain responsible for reproduction, benchmarking, scientific review, underwriting, production qualification, and validation."
    )
    json_path=outdir/f"INTERNAL_ARTIFACT_DIAGNOSTICS_{batch_id}.json"
    csv_path=outdir/f"INTERNAL_ARTIFACT_DIAGNOSTICS_{batch_id}.csv"
    json_path.write_text(json.dumps(result,indent=2,default=str),encoding="utf-8")
    rows=[{"artifact_type":"PDF",**r} for r in result["pdf_summary"]]+[{"artifact_type":"PNG",**r} for r in result["png_summary"]]
    _oc_write_csv_records(csv_path,rows)
    return result



# Compatibility alias only; this is not an independent certification authority.
_oc_a_plus_postflight_qa = _oc_internal_artifact_diagnostics

def _oc_write_manifest_release_package(outdir: Path, batch_id: str, manifest: Dict[str, Any]) -> str:
    """Create one release ZIP strictly from manifest records plus the executed engine."""
    import zipfile
    proof_runs=int(manifest.get("mc_runs",0) or 0)
    release_path=outdir.parent/f"OMNI-COMPASS_CANONICAL_{proof_runs}_RUN_OUTPUTS_{batch_id}.zip"
    engine_path=Path(__file__).resolve()
    with zipfile.ZipFile(release_path,"w",compression=zipfile.ZIP_DEFLATED,compresslevel=6) as zf:
        zf.write(engine_path,arcname=engine_path.name)
        for rec in manifest.get("artifacts",[]):
            rel=Path(str(rec["relative_path"])); src=outdir/rel
            if not src.is_file(): raise RuntimeError(f"Manifest package source missing: {rel}")
            if _oc_file_sha256(src)!=str(rec["sha256"]): raise RuntimeError(f"Manifest hash mismatch before packaging: {rel}")
            zf.write(src,arcname=f"outputs/{batch_id}/{rel.as_posix()}")
        for name in (f"RUN_MANIFEST_{batch_id}.json",f"RUN_MANIFEST_{batch_id}.csv","RUN_MANIFEST.json"):
            p=outdir/name
            if p.exists(): zf.write(p,arcname=f"outputs/{batch_id}/{name}")
    checksum=_oc_file_sha256(release_path)
    release_path.with_suffix(release_path.suffix+".sha256").write_text(f"{checksum}  {release_path.name}\n",encoding="utf-8")
    return str(release_path)



# =============================================================================
# GRANDMASTER DYNAMIC-OUTPUT / CURRENT-RUN PROVENANCE CONTRACT
# =============================================================================
# This layer does not prescribe favorable answers.  It binds every executive
# CPU/GPU/thermal/manager/canonical headline to the payload produced by the
# current execution seed and batch.  Adverse, neutral, failed, unavailable, and
# inconclusive results remain exactly that.  The report may interpret a result;
# it may not replace it with a static answer.
OC_DYNAMIC_OUTPUT_CONTRACT_ID = "OC-DYNAMIC-CURRENT-RUN-v1"


def _oc_dyn_finite_or_none(value: Any) -> Optional[float]:
    try:
        v=float(value)
        return v if math.isfinite(v) else None
    except Exception:
        return None


def _oc_dynamic_execution_snapshot(rows: List[Dict[str, Any]], meta: Dict[str, Any]) -> Dict[str, Any]:
    rows=list(rows or [])
    n=len(rows)
    def _b(r,*keys):
        for k in keys:
            if k in r:
                v=r.get(k)
                if isinstance(v,str): return v.strip().lower() in ("1","true","yes","y","pass")
                return bool(v)
        return False
    def _sign(r):
        for k in ("final_basin_sign","initial_nearest_basin","target_basin_sign","locked_basin_sign"):
            try:
                v=int(float(r.get(k,0)))
                if v in (-1,1): return v
            except Exception as _oc_exc: logging.getLogger(__name__).warning("Nonfatal fallback captured: %s", _oc_exc)
        return 0
    conveyed=sum(1 for r in rows if _b(r,"conveyed","conveyed_primary"))
    cert10=sum(1 for r in rows if _b(r,"certified_primary","certified","cert10","cert10_achieved","cert10_pass"))
    # Some canonical rows carry the certification step rather than a Boolean.
    if cert10==0 and rows:
        cert10=sum(1 for r in rows if r.get("certified_step", r.get("certification_step")) is not None or r.get("cert10_completed_step") is not None)
    plus=sum(1 for r in rows if _sign(r)==1)
    minus=sum(1 for r in rows if _sign(r)==-1)
    born=sum(1 for r in rows if _b(r,"born_stable","born_in_basin"))
    rescued=sum(1 for r in rows if _b(r,"rescued","self_tuning_applied"))
    snap={
        "contract_id":OC_DYNAMIC_OUTPUT_CONTRACT_ID,
        "batch_id":str(meta.get("batch_id","")),
        "seed":int(meta.get("random_seed",meta.get("rng_jump_seed",0)) or 0),
        "run_hash":str(meta.get("run_hash","")),
        "engine_sha256":str(meta.get("engine_sha256",_oc_engine_sha256())).upper(),
        "canonical":{
            "mechanism":"symmetric_double_well_plus_bounded_FF_P_ZOH",
            "state_assignment_after_rk4":False,
            "u_authority":float(U_AUTHORITY),
            "kp":float(KP),
            "run_count":n,
            "conveyed_count":conveyed,
            "conveyed_rate_percent":100.0*conveyed/n if n else None,
            "cert10_count":cert10,
            "cert10_rate_percent":100.0*cert10/n if n else None,
            "plus_basin_count":plus,
            "minus_basin_count":minus,
            "born_in_basin_count":born,
            "rescued_or_self_tuned_count":rescued,
            "source":"current canonical trajectory rows",
        },
        "compute":{}, "manager":{}, "enterprise":{}, "global_megastack":{},
        "claim_boundary":"Every value in this ledger is read or recomputed from the current execution's rows/payloads. No favorable outcome is supplied by this ledger; failure and adverse signs remain visible.",
    }
    cp=meta.get("compute_payload") if isinstance(meta.get("compute_payload"),dict) else {}
    for mode in cp.get("modes",[]) or []:
        comp=(((cp.get("summaries",{}) or {}).get(mode,{}) or {}).get("omni_vs_binpack",{}) or {})
        m={"matched_seeds":int(cp.get("seeds_per_mode",0) or 0),"metrics":{}}
        for metric in (
            "completed_jobs","facility_energy_kwh","peak_facility_power_kw",
            "powered_cpu_core_hours","powered_gpu_hours","allocated_cpu_core_hours",
            "allocated_gpu_hours","useful_cpu_core_hours","useful_gpu_hours",
            "urgent_sla_miss_rate","p95_urgent_queue_minutes","p95_flexible_queue_minutes",
            "thermal_excursion_hours","makespan_hours"):
            d=comp.get(metric,{}) or {}
            if d:
                m["metrics"][metric]={
                    "baseline_mean":_oc_dyn_finite_or_none(d.get("baseline_mean")),
                    "omni_mean":_oc_dyn_finite_or_none(d.get("contender_mean")),
                    "mean_percent_change":_oc_dyn_finite_or_none(d.get("mean_percent_change")),
                    "favorable_seeds":int(d.get("favorable_seeds",0) or 0),
                    "seeds":int(d.get("seeds",cp.get("seeds_per_mode",0)) or 0),
                    "source":f"compute_payload.summaries.{mode}.omni_vs_binpack.{metric}",
                }
        snap["compute"][str(mode)]=m
    mp=meta.get("manager_payload") if isinstance(meta.get("manager_payload"),dict) else {}
    if mp:
        snap["manager"]={
            "scenario_count":int(mp.get("scenario_count",0) or 0),
            "profile":str(mp.get("profile","")),
            "claim_boundary":str(mp.get("claim_boundary","")),
            "status_rows":[list(map(str,r)) for r in _mom_status_rows(mp)] if '_mom_status_rows' in globals() else [],
            "source":"current manager benchmark payload",
        }
    ep=meta.get("enterprise_payload") if isinstance(meta.get("enterprise_payload"),dict) else {}
    if ep:
        snap["enterprise"]={
            "profile":str(ep.get("profile","")),
            "seed_base":ep.get("seed_base"),
            "status_rows":[list(map(str,r)) for r in _ep_status_rows(ep)] if '_ep_status_rows' in globals() else [],
            "claim_boundary":str(ep.get("claim_boundary","")),
            "source":"current enterprise evidence payload",
        }
    gp=meta.get("global_stack_payload") if isinstance(meta.get("global_stack_payload"),dict) else {}
    if gp:
        snap["global_megastack"]={
            "scenario_count":int(gp.get("scenario_count",0) or 0),
            "raw_row_count":int(gp.get("raw_row_count",0) or 0),
            "environments":gp.get("environments"),
            "modes":gp.get("modes"),
            "cluster_scales":gp.get("cluster_scales"),
            "claim_boundary":str(gp.get("claim_boundary","")),
            "source":"current Global Megastack payload",
        }
    return snap


def _oc_dynamic_snapshot_rows(snapshot: Dict[str, Any]) -> List[List[str]]:
    out=[["Surface","Metric","Baseline","Omni/current","Change / result","Source"]]
    c=snapshot.get("canonical",{}) or {}
    out += [
        ["Canonical","Mechanism","",str(c.get("mechanism")),"executed","current engine"],
        ["Canonical","Bounded U authority","",str(c.get("u_authority")),"|u| limit","current engine"],
        ["Canonical","Post-RK4 state assignment","",str(c.get("state_assignment_after_rk4")),"must remain False","current engine"],
        ["Canonical","Runs","",str(c.get("run_count")),"current seed",str(c.get("source",""))],
        ["Canonical","CONVEY-5","",str(c.get("conveyed_count")),_ci_fmt(c.get("conveyed_rate_percent"),2,True),str(c.get("source",""))],
        ["Canonical","CERT-10","",str(c.get("cert10_count")),_ci_fmt(c.get("cert10_rate_percent"),2,True),str(c.get("source",""))],
        ["Canonical","Signed basin population","",f"+1={c.get('plus_basin_count')} / -1={c.get('minus_basin_count')}","observed",str(c.get("source",""))],
    ]
    labels={
        "completed_jobs":"Completed jobs","facility_energy_kwh":"Facility energy (kWh)",
        "peak_facility_power_kw":"Peak facility power (kW)","powered_cpu_core_hours":"Powered CPU core-hours",
        "powered_gpu_hours":"Powered GPU-hours","thermal_excursion_hours":"Thermal excursion hours",
        "urgent_sla_miss_rate":"Urgent SLA miss rate","p95_urgent_queue_minutes":"P95 urgent queue (min)",
        "p95_flexible_queue_minutes":"P95 flexible queue (min)","makespan_hours":"Makespan (h)",
    }
    for mode,md in (snapshot.get("compute",{}) or {}).items():
        for metric in labels:
            d=((md.get("metrics",{}) or {}).get(metric) or {})
            if not d: continue
            out.append([str(mode).upper(),labels[metric],_ci_fmt(d.get("baseline_mean")),_ci_fmt(d.get("omni_mean")),_ci_fmt(d.get("mean_percent_change"),2,True),str(d.get("source",""))])
    return out


def _oc_validate_dynamic_execution_snapshot(snapshot: Dict[str, Any], rows: List[Dict[str, Any]], meta: Dict[str, Any]) -> List[Dict[str, Any]]:
    findings=[]
    c=snapshot.get("canonical",{}) or {}
    findings.append(_oc_finding("DYNAMIC-RUN-COUNT","PASS" if int(c.get("run_count",-1))==len(rows) else "ERROR","dynamic_output","Dynamic ledger run count must equal the current canonical population.",{"ledger":c.get("run_count"),"rows":len(rows)}))
    findings.append(_oc_finding("DYNAMIC-SEED-BINDING","PASS" if int(snapshot.get("seed",-1))==int(meta.get("random_seed",meta.get("rng_jump_seed",-2))) else "ERROR","dynamic_output","Dynamic ledger is bound to the current execution seed.",{"ledger":snapshot.get("seed"),"meta":meta.get("random_seed")}))
    findings.append(_oc_finding("DYNAMIC-BATCH-BINDING","PASS" if str(snapshot.get("batch_id"))==str(meta.get("batch_id")) and bool(snapshot.get("batch_id")) else "ERROR","dynamic_output","Dynamic ledger is bound to the current batch identity.",{"ledger":snapshot.get("batch_id"),"meta":meta.get("batch_id")}))
    cp=meta.get("compute_payload") if isinstance(meta.get("compute_payload"),dict) else {}
    required=set(cp.get("modes",[]) or [])
    observed=set((snapshot.get("compute",{}) or {}).keys())
    findings.append(_oc_finding("DYNAMIC-COMPUTE-MODES","PASS" if required==observed else "ERROR","dynamic_output","Every executed CPU/GPU/mixed mode must appear in the current-run dynamic ledger.",{"required":sorted(required),"observed":sorted(observed)}))
    return findings


def _oc_write_dynamic_execution_artifacts(outdir: Path, batch_id: str, snapshot: Dict[str, Any]) -> Dict[str,str]:
    outdir=Path(outdir); outdir.mkdir(parents=True,exist_ok=True)
    jp=outdir/f"DYNAMIC_EXECUTION_LEDGER_{batch_id}.json"
    cp=outdir/f"DYNAMIC_EXECUTION_LEDGER_{batch_id}.csv"
    tp=outdir/f"DYNAMIC_EXECUTION_LEDGER_{batch_id}.txt"
    jp.write_text(json.dumps(snapshot,indent=2,ensure_ascii=False,default=str),encoding="utf-8")
    rows=_oc_dynamic_snapshot_rows(snapshot)
    with cp.open("w",newline="",encoding="utf-8") as f: csv.writer(f).writerows(rows)
    with tp.open("w",encoding="utf-8") as f:
        f.write(f"{OC_DYNAMIC_OUTPUT_CONTRACT_ID}\nBatch: {snapshot.get('batch_id')}\nSeed: {snapshot.get('seed')}\nEngine SHA-256: {snapshot.get('engine_sha256')}\n\n")
        for r in rows: f.write(" | ".join(map(str,r))+"\n")
        f.write("\n"+str(snapshot.get("claim_boundary",""))+"\n")
    return {"json":str(jp),"csv":str(cp),"txt":str(tp)}

# =============================================================================
# END GRANDMASTER DYNAMIC-OUTPUT / CURRENT-RUN PROVENANCE CONTRACT
# =============================================================================


def enterprise_main() -> None:
    _oc_setup_logging()
    _oc_emit_authenticity_banner()
    args = _oc_parse_enterprise_args()

    # Lock maintenance runs BEFORE the pre-execution core-lock validation,
    # because its whole purpose is to repair the condition that validation
    # would otherwise refuse to run on.
    if getattr(args, "unseal", False):
        _u = _oc_unseal_engine()
        print("=" * 74)
        print("  OMNI-COMPASS ENGINE UNSEALED - DEVELOPMENT MODE")
        print("=" * 74)
        print(f"  previous digest : {str(_u['previous_digest'])[:48]}")
        print(f"  state           : {_u['state']}")
        print(f"  verdict now     : {_u['verdict_now']}  (not MODIFIED)")
        print("\n  " + _u["meaning"])
        print("=" * 74)
        return

    if getattr(args, "reseal", False) or getattr(args, "verify_lock", False):
        print("[DEV] Lock/reseal operations are disabled in DEVELOPMENT_UNLOCKED mode.")
        print("[DEV] Finish the engine first; sealing will be restored only when explicitly requested.")
        return

    if getattr(args, "_internal_seed_summary", None) is not None:
        _seed, _runs, _batch_index = [int(v) for v in args._internal_seed_summary]
        _payload = _ev_seed_batch_summary(_seed, _runs, _batch_index)
        print("__OC_SEED_BATCH_SUMMARY__=" + json.dumps(_payload, ensure_ascii=False, sort_keys=True, default=str))
        return
    if getattr(args, "_internal_seed_grid", None) is not None:
        _seed0, _runs, _batches = [int(v) for v in args._internal_seed_grid]
        import gc as _gc
        _rows=[]
        for _i in range(_batches):
            _rows.append(_ev_seed_batch_summary(_seed0+_i, _runs, _i))
            _gc.collect()
        print("__OC_SEED_GRID_SUMMARY__=" + json.dumps(_rows, ensure_ascii=False, sort_keys=True, default=str))
        return
    # DIAGNOSTIC / REFEREE EVIDENCE-ONLY MODE
    # ---------------------------------------
    # An explicitly requested --evidence-only execution is intentionally
    # permitted and does NOT constitute a canonical publication run. This
    # restores the documented quick/full verification workflow while leaving
    # the default no-argument canonical complete-execution contract unchanged.
    # Evidence-only artifacts must identify themselves as diagnostic evidence
    # and must not be represented as a completed canonical 500-run release.
    if bool(getattr(args, "evidence_only", False)):
        _logging.info("DIAGNOSTIC evidence-only profile active; canonical publication/report generation is not being claimed.")
    installed_external_manager_profiles = _pm_install_external_profiles(args.external_manager_profile_json)
    if installed_external_manager_profiles:
        _logging.info("Installed external manager profile(s): " + ", ".join(installed_external_manager_profiles))

    # CANONICAL COMPLETE-EXECUTION CONTRACT
    # -----------------------------------
    # A normal engine run is indivisible. The canonical Monte Carlo, full
    # numerical evidence suite, all compute modes, full public-manager
    # mechanism benchmark, full enterprise proof suite, and full Global
    # Megastack laboratory are mandatory inputs to the unified reports.
    # Command-line values that would suppress or reduce a suite are restored
    # before any simulation begins. This prevents shortened PDFs, missing
    # appendices, or presentation surfaces that are not backed by the complete
    # executed mechanism and its generated artifacts.
    if not args.evidence_only and not args.compare_evidence_manifest:
        _requested = {
            "evidence_suite": str(args.evidence_suite),
            "compute_benchmark": str(args.compute_benchmark),
            "manager_benchmark": str(args.manager_benchmark),
            "enterprise_proof": str(args.enterprise_proof),
            "global_stack_benchmark": str(args.global_stack_benchmark),
        }
        args.evidence_suite = "full"
        args.compute_benchmark = "all"
        args.manager_benchmark = "full"
        args.enterprise_proof = "full"
        args.global_stack_benchmark = "full"
        _complete = {
            "evidence_suite": args.evidence_suite,
            "compute_benchmark": args.compute_benchmark,
            "manager_benchmark": args.manager_benchmark,
            "enterprise_proof": args.enterprise_proof,
            "global_stack_benchmark": args.global_stack_benchmark,
        }
        _changed = [f"{k}: {_requested[k]} -> {_complete[k]}" for k in _complete if _requested[k].lower() != _complete[k].lower()]
        if _changed:
            _logging.warning("CANONICAL complete-execution contract restored reduced suite selections: " + "; ".join(_changed))
        _logging.info("CANONICAL complete-execution profile active: numerical=full; compute=all; manager=full; enterprise=full; global-stack=full")

    if args.compare_evidence_manifest:
        comparison = compare_evidence_manifest(args.compare_evidence_manifest)
        print(json.dumps(comparison, indent=2, default=str))
        return

    global _OC_KILL_SWITCH_FILE
    _OC_KILL_SWITCH_FILE = str(args.kill_switch_file or "").strip()
    if args.emergency_stop or str(args.operation_mode).lower() == "off":
        print("[STOP] Omni-Compass operator authority is OFF; no simulation or report was generated.")
        return
    try:
        _oc_assert_runtime_enabled()
    except OCOperatorStop as _stop:
        print(f"[STOP] {_stop}")
        return

    evidence_seed = int(args.seed) if args.seed is not None else 20260719
    if args.evidence_only:
        if args.evidence_suite == "none":
            args.evidence_suite = "quick"
        evidence_only_dir = args.evidence_output or "./omni-compass_evidence"
        run_numerical_evidence_suite(args.evidence_suite, evidence_seed, evidence_only_dir, emit_standalone_report=True)
        print(f"[OK] Numerical evidence artifacts: {Path(evidence_only_dir).expanduser().resolve()}")
        return

    # Build config from core as-is, then apply non-invasive overrides.
    cfg = RuntimeConfig()
    cfg.operation_mode = str(args.operation_mode)
    cfg.kill_switch_file = str(args.kill_switch_file or "")
    cfg.kill_switch_enabled = True

    if args.runs is not None:
        cfg.mc_runs = int(args.runs)
        _logging.info(f"Monte Carlo runs overridden: {cfg.mc_runs}")

    validation_findings = _oc_validate_runtime_contract(cfg)
    _canonical_core_integrity = _oc_canonical_core_integrity_registry()
    validation_findings.extend(_oc_validate_canonical_core_integrity(_canonical_core_integrity))
    # DEVELOPMENT_UNLOCKED: enforce runtime/configuration correctness, never source-hash locks.
    _runtime_only_findings = [
        f for f in validation_findings
        if str(f.get("surface","")) != "canonical_core_integrity"
        and not str(f.get("code","")).startswith("CORE-")
    ]
    _oc_raise_on_validation_errors(_runtime_only_findings, "pre-execution configuration")

    # Seed
    seed_used = _oc_apply_seed(args.seed)

    # Run core (serial in this v11 core build)
    if int(args.parallel or 1) > 1:
        _logging.info(f"Parallel requested ({int(args.parallel)}). Core v11 runs serial; continuing serial.")

    _perf_t0 = time.perf_counter()
    try:
        results, meta2 = run_monte_carlo(cfg, seed_used)
    except OCOperatorStop as _stop:
        print(f"[STOP] {_stop}")
        print("[STOP] No completed-run report or artifact package was generated from the interrupted execution.")
        return
    _perf_t1 = time.perf_counter()

    # Attach performance data (same shape as core main)
    perf_runtime_seconds = float(_perf_t1 - _perf_t0)
    try:
        _ru = resource.getrusage(resource.RUSAGE_SELF)
        _rss = float(getattr(_ru, 'ru_maxrss', 0.0))
        if sys.platform == 'darwin':
            perf_peak_rss_mb = _rss / (1024.0 * 1024.0)
        else:
            perf_peak_rss_mb = _rss / 1024.0
    except Exception:
        perf_peak_rss_mb = float('nan')

    perf_platform = platform.platform()
    perf_python = sys.version.split()[0]

    meta2 = dict(meta2) if isinstance(meta2, dict) else {}
    meta2['perf'] = {
        'runtime_seconds': perf_runtime_seconds,
        'peak_rss_mb': perf_peak_rss_mb,
        'platform': perf_platform,
        'python': perf_python,
    }

    meta = dict(meta2) if isinstance(meta2, dict) else {}
    meta["engine_equation_form"] = ENGINE_EQUATION_FORM
    meta["engine_equation_lines"] = EQUATION_LINE_COUNT
    meta["operation_mode"] = str(args.operation_mode)
    meta["kill_switch_enabled"] = True
    meta["external_manager_profiles_installed"] = list(installed_external_manager_profiles)
    meta["kill_switch_file"] = str(args.kill_switch_file or "")
    meta["operator_authority_contract"] = "autopilot|supervised|observe|off plus OC_KILL_SWITCH and optional sentinel-file stop"

    # Output dir override: match core by writing meta["output_dir"]
    if args.output is not None and str(args.output).strip() != "":
        meta["output_dir"] = str(args.output)
        _logging.info(f"Output directory overridden: {meta['output_dir']}")
    else:
        meta.setdefault("output_dir", "omni-compass_outputs")

    # Prepare rows + snapshots just like core main
    cfg_snapshot = dict(meta.get("cfg_snapshot")) if isinstance(meta.get("cfg_snapshot"), dict) else dict(getattr(cfg, "__dict__", {}))
    rows = _coerce_results_to_dicts(results)
    rows = [_augment_row_with_quadrants(dict(r)) for r in rows]
    if not rows:
        raise RuntimeError("Engine returned no run rows; cannot emit reports.")
    validation_findings.extend(_oc_validate_run_rows(rows, cfg))
    _oc_raise_on_validation_errors(validation_findings, "canonical Monte Carlo output")
    meta["canonical_population_sha256"] = _oc_canonical_population_sha256(rows)
    meta["canonical_population_identity"] = {
        "row_count": len(rows),
        "sha256": meta["canonical_population_sha256"],
        "meaning": "Identity of this executed stochastic population; expected to change on fresh-seed runs while the unchanged engine SHA remains constant.",
    }
    meta["cross_process_reproducibility"] = _oc_cross_process_reproducibility_check()
    validation_findings.extend(_oc_validate_reproducibility(meta))
    _oc_raise_on_validation_errors(validation_findings, "cross-process reproducibility")

    batch_id = str(uuid.uuid4())[:10]
    meta["batch_id"] = batch_id
    meta["timestamp_eastern"] = _timestamp_eastern()
    meta["timestamp_utc"] = _timestamp_utc()
    meta["random_seed"] = int(seed_used)
    global random_seed
    random_seed = int(seed_used)
    meta["mc_runs"] = int(cfg.mc_runs)
    _rng_record = meta2.get("rng", {}) if isinstance(meta2.get("rng", {}), dict) else {}
    meta["rng_fingerprint"] = str(_rng_record.get("fingerprint", meta.get("rng_fingerprint", "")))
    meta["rng_generator"] = str(_rng_record.get("generator", "np.random.default_rng()"))
    meta["rng_bit_generator"] = str(_rng_record.get("bit_generator", "PCG64"))
    meta["rng_jump_seed"] = int(seed_used)
    meta["rng_seed_mode"] = "JUMP-GENERATED" if args.seed is None else "EXPLICIT OVERRIDE"
    meta["rng_jump_id"] = f"RNG-JUMP-{int(seed_used)}-{meta['rng_fingerprint'][:12].upper()}"
    meta["engine_sha256"] = _oc_engine_sha256().upper()
    _identity_payload = {
        "engine_sha256": meta["engine_sha256"],
        "batch_id": meta["batch_id"],
        "timestamp_utc": meta["timestamp_utc"],
        "timestamp_eastern": meta["timestamp_eastern"],
        "rng_jump_seed": meta["rng_jump_seed"],
        "rng_seed_mode": meta["rng_seed_mode"],
        "rng_generator": meta["rng_generator"],
        "rng_bit_generator": meta["rng_bit_generator"],
        "rng_fingerprint": meta["rng_fingerprint"],
        "python": sys.version.split()[0],
    }
    meta["run_hash"] = hashlib.sha256(json.dumps(_identity_payload, sort_keys=True).encode("utf-8")).hexdigest().upper()
    global run_hash
    run_hash = meta["run_hash"]
    meta.setdefault("verified_by", "python")

    _output_root = _Path(meta["output_dir"]).expanduser()
    _output_root.mkdir(parents=True, exist_ok=True)
    outdir = _output_root / batch_id
    if outdir.exists():
        if any(outdir.iterdir()):
            raise RuntimeError(f"Batch output directory is not empty: {outdir}")
    else:
        outdir.mkdir(parents=True, exist_ok=False)
    meta["output_root"] = str(_output_root.resolve())
    meta["output_dir"] = str(outdir.resolve())
    meta["visual_system_id"] = OC_VISUAL_SYSTEM_ID
    meta["visual_system_artifacts"] = _oc_write_visual_system_artifacts(outdir, batch_id)
    meta["text_class_disclosure_artifacts"] = _oc_emit_authored_vs_computed_artifact(outdir, batch_id)
    if not isinstance(meta["text_class_disclosure_artifacts"], dict) or meta["text_class_disclosure_artifacts"].get("error"):
        raise RuntimeError("TEXT CLASS DISCLOSURE emission failed: " + json.dumps(meta.get("text_class_disclosure_artifacts",{}), default=str))

    # Release the object-rich canonical RunResult population after canonical rows,
    # metadata, and validation snapshots have been materialized. The numerical
    # evidence worker is independent and can otherwise suffer allocator pressure in
    # constrained review environments. Canonical rows and all report inputs remain.
    try:
        import gc as _oc_gc
        del results
        _oc_gc.collect()
    except Exception as _oc_exc:
        logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)

    # Numerical evidence is executed before report construction and woven into the
    # existing executive-report architecture. The canonical Monte Carlo rows above
    # are not altered by these verification executions.
    evidence_payload = None
    if args.evidence_suite != "none":
        evidence_dir = _Path(args.evidence_output).expanduser() if args.evidence_output else (outdir / f"NUMERICAL_EVIDENCE_ARTIFACTS_{batch_id}")
        evidence_payload = _oc_timed_stage("pipeline.numerical_evidence", lambda: run_numerical_evidence_suite(args.evidence_suite, int(seed_used), str(evidence_dir), emit_standalone_report=False))
        meta["evidence_payload"] = evidence_payload
        meta["evidence_output_dir"] = str(evidence_dir.resolve())
        meta["evidence_profile"] = args.evidence_suite

    # Vendor-neutral CPU/GPU/mixed domain benchmark. This is a separate matched-
    # workload execution layer that reuses Piece I and is woven into the same PDF.
    compute_payload = None
    if args.compute_benchmark != "none":
        compute_dir = _Path(args.compute_output).expanduser() if args.compute_output else (outdir / f"COMPUTE_INFRASTRUCTURE_ARTIFACTS_{batch_id}")
        compute_payload = _oc_timed_stage("pipeline.compute_benchmark", lambda: run_compute_infrastructure_benchmark(
            args.compute_benchmark,
            max(2, int(args.compute_seeds)),
            int(seed_used) + 730001,
            str(compute_dir),
        ))
        meta["compute_payload"] = compute_payload
        meta["compute_output_dir"] = str(compute_dir.resolve())
        meta["compute_profile"] = args.compute_benchmark
        meta["compute_seeds_per_mode"] = max(2, int(args.compute_seeds))
    else:
        meta["compute_profile"] = "not executed"

    manager_payload = None
    if args.manager_benchmark != "none":
        manager_dir = _Path(args.manager_output).expanduser() if args.manager_output else (outdir / f"FRAGMENTED_STACK_GOVERNANCE_ARTIFACTS_{batch_id}")
        manager_payload = _oc_timed_stage("pipeline.manager_benchmark", lambda: run_fragmented_stack_governance_benchmark(
            args.manager_benchmark,
            max(1, int(args.manager_scenarios)),
            int(seed_used) + 910001,
            str(manager_dir),
        ))
        meta["manager_payload"] = manager_payload
        meta["manager_output_dir"] = str(manager_dir.resolve())
        meta["manager_profile"] = args.manager_benchmark
        meta["manager_scenarios"] = max(1, int(args.manager_scenarios))
    else:
        meta["manager_profile"] = "not executed"

    enterprise_payload = None
    if args.enterprise_proof != "none":
        enterprise_dir = _Path(args.enterprise_output).expanduser() if args.enterprise_output else (outdir / f"ENTERPRISE_PROOF_ARTIFACTS_{batch_id}")
        enterprise_payload = _oc_timed_stage("pipeline.enterprise_proof", lambda: run_enterprise_proof_suite(
            args.enterprise_proof,
            int(seed_used) + 1230001,
            str(enterprise_dir),
            manager_payload,
            compute_payload,
            args.trace_replay,
        ))
        meta["enterprise_payload"] = enterprise_payload
        meta["enterprise_output_dir"] = str(enterprise_dir.resolve())
        meta["enterprise_profile"] = args.enterprise_proof
    else:
        meta["enterprise_profile"] = "not executed"

    global_stack_payload = None
    if args.global_stack_benchmark != "none":
        global_stack_dir = _Path(args.global_stack_output).expanduser() if args.global_stack_output else (outdir / f"GLOBAL_MEGASTACK_ARTIFACTS_{batch_id}")
        global_stack_payload = _oc_timed_stage("pipeline.global_megastack", lambda: run_global_megastack_benchmark(
            rows,
            int(seed_used) + 1700001,
            str(global_stack_dir),
            int(args.global_stack_report_pages),
            report_selection_seed=int(seed_used),
        ))
        if int(args.global_stack_jump_runs or 0) > 0:
            global_stack_payload["jump_generator"] = _ms_streaming_jump_generator(int(args.global_stack_jump_runs), int(seed_used) + 1800001)
            try:
                (_Path(global_stack_dir) / "GLOBAL_MEGASTACK_JUMP_GENERATOR.json").write_text(_json.dumps(global_stack_payload["jump_generator"], indent=2), encoding="utf-8")
            except Exception as _oc_exc:
                logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
        meta["global_stack_payload"] = global_stack_payload
        meta["global_stack_output_dir"] = str(global_stack_dir.resolve())
        meta["global_stack_profile"] = args.global_stack_benchmark
    else:
        meta["global_stack_profile"] = "not executed"

    # Canonical referee registry: one source of truth for validation, claims,
    # code bindings, complexity, benchmark scope, and independent verification.
    meta["canonical_core_integrity"] = _canonical_core_integrity
    validation_findings.extend(_oc_validate_benchmark_payloads(meta))
    meta["theorem_registry"] = _oc_hybrid_theorem_registry(rows, meta)
    validation_findings.extend(_oc_validate_theorem_registry(meta["theorem_registry"]))
    _oc_raise_on_validation_errors(validation_findings, "formal theorem and benchmark validation")
    meta["validation_registry"] = validation_findings
    meta["validation_counts"] = _oc_validation_counts(validation_findings)
    meta["traceability_rows"] = _oc_traceability_rows()
    meta["complexity_model"] = _oc_complexity_model(cfg, rows, meta)
    meta["benchmark_registry"] = _oc_benchmark_registry(meta)
    if global_stack_payload is not None:
        try:
            meta["benchmark_registry"].append({
                "benchmark_id":"GLOBAL-MEGASTACK-CANONICAL",
                "status":"EXECUTED",
                "scope":f"{global_stack_payload.get('scenario_count')} matched scenarios; {global_stack_payload.get('raw_row_count')} raw scenario-run rows",
                "environments":global_stack_payload.get("environments"),
                "modes":global_stack_payload.get("modes"),
                "cluster_scales":global_stack_payload.get("cluster_scales"),
                "claim_boundary":global_stack_payload.get("claim_boundary"),
            })
        except Exception as _oc_exc:
            logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
    meta["production_validation_ladder"] = _oc_production_validation_ladder(meta)
    meta["evaluator_proof"] = _oc_evaluator_proof_payload(cfg, rows, meta)
    validation_findings.extend(_oc_validate_evaluator_proof(meta["evaluator_proof"]))
    _oc_raise_on_validation_errors(validation_findings, "evaluator proof, claim ledger, and intervention accounting")
    meta["validation_registry"] = validation_findings
    meta["validation_counts"] = _oc_validation_counts(validation_findings)

    # Bind every principal headline to this seed/batch and validate the binding
    # before any human-readable report is allowed to render.
    meta["dynamic_execution_snapshot"] = _oc_dynamic_execution_snapshot(rows, meta)
    validation_findings.extend(_oc_validate_dynamic_execution_snapshot(meta["dynamic_execution_snapshot"], rows, meta))
    _oc_raise_on_validation_errors(validation_findings, "dynamic current-run output binding")
    meta["validation_registry"] = validation_findings
    meta["validation_counts"] = _oc_validation_counts(validation_findings)
    _canon_convey = sum(bool((r.to_dict() if hasattr(r,"to_dict") else r).get("conveyed_primary", (r.to_dict() if hasattr(r,"to_dict") else r).get("conveyed", False))) for r in rows)
    _canon_cert10 = sum(bool((r.to_dict() if hasattr(r,"to_dict") else r).get("certified_primary", False)) for r in rows)
    _dyn = meta.get("dynamic_execution_snapshot", {}) or {}
    _dyn_canon = _dyn.get("canonical", {}) if isinstance(_dyn.get("canonical", {}), dict) else {}
    _dyn_convey = int(_dyn_canon.get("conveyed_count", -1))
    _dyn_cert10 = int(_dyn_canon.get("cert10_count", -1))
    if _dyn_convey != _canon_convey or _dyn_cert10 != _canon_cert10:
        raise RuntimeError(
            "EVIDENCE-FIDELITY FAILURE: current-run ledger disagrees with canonical rows "
            f"(CONVEY ledger={_dyn_convey}, rows={_canon_convey}; CERT-10 ledger={_dyn_cert10}, rows={_canon_cert10})."
        )
    meta["dynamic_execution_artifacts"] = _oc_write_dynamic_execution_artifacts(outdir, batch_id, meta["dynamic_execution_snapshot"])
    _top10_summary = _summarize(rows, cfg_snapshot)
    meta["top10_engineering_financial_outcomes"] = _oc_top10_engineering_financial_outcomes(rows, _top10_summary, meta)
    meta["top10_engineering_financial_artifacts"] = _oc_write_top10_outcomes_artifacts(
        outdir, batch_id, meta["top10_engineering_financial_outcomes"])
    meta["release_id"] = OC_RELEASE_ID
    meta["visual_system_id"] = OC_VISUAL_SYSTEM_ID
    meta["cover_claim_execution_artifacts"] = _oc_write_cover_claim_execution_artifacts(outdir, batch_id, rows, meta)
    meta["referee_upgrade_artifacts"] = _oc_write_referee_upgrade_artifacts(outdir, batch_id, cfg, rows, meta)
    meta["evaluator_proof_artifacts"] = _oc_write_evaluator_proof_artifacts(outdir, batch_id, cfg, rows, meta)
    meta["report_conformity_artifacts"] = _oc_write_report_conformity_artifacts(outdir, batch_id, cfg, rows, meta)

    # One unified report ordered from enterprise proof to numerical, compute,
    # fragmented-stack, canonical mechanism, appendices, and raw data last.
    write_executive_report_full(outdir, batch_id, rows, cfg_snapshot, meta)
    summary = _summarize(rows, cfg_snapshot)
    drawings = _make_drawings(summary, cfg_snapshot, rows, meta)
    _write_raw_files(
        outdir,
        batch_id,
        rows,
        {"step_hist_png": None, "cum_png": None, "rms_png": None,
         "x_steps": drawings["x_steps"], "counts": drawings["counts"], "cum": drawings["cum"]},
        meta
    )

    # Enterprise JSON snapshot
    _oc_export_config_snapshot(cfg, meta, outdir)

    # Preserve the exact executed engine inside the isolated batch directory.
    _executed_engine_copy=outdir/Path(__file__).name
    shutil.copy2(Path(__file__).resolve(),_executed_engine_copy)

    # Remove only generator-created trailing header/footer-only pages before release inspection.
    meta["blank_pdf_cleanup"]=_oc_trim_generated_blank_pdf_pages(outdir)
    if meta["blank_pdf_cleanup"].get("status") == "FAIL":
        logging.getLogger(__name__).warning("Rendering diagnostic only: interior blank page(s) detected; executed computation remains authoritative. %s", json.dumps(meta["blank_pdf_cleanup"].get("interior_blank_pages",[]), default=str))

    # Normalize every generated PDF to embedded publication fonts before the
    # authoritative release inspection.  Any unembedded font is release-blocking.
    meta["pdf_font_embedding"]=_oc_embed_generated_pdf_fonts(outdir)
    if meta["pdf_font_embedding"].get("status") != "PASS":
        if str(meta["pdf_font_embedding"].get("status")) == "FAIL":
            logging.getLogger(__name__).warning("Rendering diagnostic only: PDF font embedding audit failed; executed computation remains authoritative. %s", json.dumps(meta["pdf_font_embedding"], default=str))

    # Postflight separates upstream computation/artifact completion from optional enhanced inspection; actual detected defects and batch impurity remain release-blocking.
    meta["internal_artifact_diagnostics"]=_oc_internal_artifact_diagnostics(outdir,batch_id)
    # Rewrite conformity artifacts so the final files include postflight status.
    meta["report_conformity_artifacts"]=_oc_write_report_conformity_artifacts(outdir,batch_id,cfg,rows,meta)
    if str(meta.get("report_conformity_status")) == "FAIL":
        raise RuntimeError("EVIDENCE-FIDELITY FAILURE: a downstream report/chart/text surface failed the declared source-to-executed-evidence conformity checks. The computation remains authoritative; regenerate the downstream artifact from executed evidence.")

    # -------------------------------------------------------------------------
    # AUDIT FIX B2 / P3 - EMISSION ORDER AND FAILURE SEMANTICS
    # -------------------------------------------------------------------------
    # DEFECT (prior builds): the artifact manifest and the release package were
    # sealed HERE, and the minimal proof object, the standalone external
    # verifier, the core isolation extract and the replication pack were emitted
    # AFTERWARDS.  Consequences, all observed in batch e706d5a8-8:
    #   * RUN_MANIFEST.json contained none of those four artifacts;
    #   * artifact_count under-reported the directory by two;
    #   * status="PASS" / missing_expected_artifacts=[] was VACUOUS for exactly
    #     the artifacts the report's VERIFICATION PROTOCOL depends on;
    #   * the engine's own release .zip shipped without the verifier that the
    #     report tells the reader to run.
    # The comment that used to sit here asserted "deliberately after every
    # writer".  That invariant was false.  It is now true: every writer runs
    # above this line.
    #
    # Failure semantics are also corrected.  These four emitters previously
    # degraded to a printed [WARN] and allowed the run to publish a report
    # asserting artifacts that were never written.  Silent degradation is not
    # survivable in the integrity layer.  Any failure here is release-blocking.
    # -------------------------------------------------------------------------
    _oc_minimal_proof = _oc_emit_minimal_proof_object(outdir, batch_id, rows, meta)
    meta["minimal_proof_object"] = _oc_minimal_proof
    print(f"[OK] minimal proof object: {_oc_minimal_proof.get('proof_module')}")

    _oc_integrity_files = _oc_emit_integrity_artifacts(outdir, batch_id, meta)
    meta["integrity_artifacts"] = _oc_integrity_files

    _oc_core_files = _oc_emit_core_isolation_module(outdir, batch_id, meta)
    meta["core_isolation_artifacts"] = _oc_core_files
    if _oc_core_files.get("core_extract"):
        print(f"[OK] core_extract: {_oc_core_files['core_extract']} "
              f"(surfaces={_oc_core_files.get('core_extract_surfaces')}, "
              f"compiles={_oc_core_files.get('core_extract_compiles')})")

    _oc_repl_files = _oc_emit_replication_pack(outdir, batch_id, meta, summary)
    meta["replication_pack_artifacts"] = _oc_repl_files
    for _oc_rk in ("replication_pack", "replication_attestation_form", "external_validation_register"):
        if _oc_repl_files.get(_oc_rk):
            print(f"[OK] {_oc_rk}: {_oc_repl_files[_oc_rk]}")
    for _oc_k in ("external_verifier", "integrity_record", "master_disclosure", "license"):
        if _oc_integrity_files.get(_oc_k):
            print(f"[OK] {_oc_k}: {_oc_integrity_files[_oc_k]}")

    _oc_integrity_emitter_errors = {
        name: payload.get("error")
        for name, payload in (
            ("integrity_artifacts", _oc_integrity_files),
            ("core_isolation_module", _oc_core_files),
            ("replication_pack", _oc_repl_files),
        )
        if isinstance(payload, dict) and payload.get("error")
    }
    if _oc_integrity_emitter_errors:
        raise RuntimeError(
            "Publication-conformity failure: integrity / verification artifact emission failed. "
            "The report's VERIFICATION PROTOCOL directs the reader to these files, so a run that "
            "cannot write them must not publish a report that claims they exist. "
            + json.dumps(_oc_integrity_emitter_errors, default=str))

    # The four verification artifacts above are now REQUIRED members of the
    # manifest's expected set, so their absence turns manifest status to FAIL
    # instead of passing unnoticed.
    meta["required_verification_artifacts"] = [
        str(_oc_minimal_proof.get("proof_module") or ""),
        str(_oc_integrity_files.get("external_verifier") or ""),
        str(_oc_integrity_files.get("integrity_record") or ""),
        str(_oc_core_files.get("core_extract") or ""),
        str(_oc_repl_files.get("replication_pack") or ""),
    ]
    _oc_missing_required_verification=[]
    for _oc_required_path in meta["required_verification_artifacts"]:
        if not _oc_required_path:
            _oc_missing_required_verification.append("<EMPTY PATH>")
            continue
        _oc_rp=Path(_oc_required_path)
        if not _oc_rp.is_file() or _oc_rp.stat().st_size <= 0:
            _oc_missing_required_verification.append(str(_oc_rp))
    if _oc_missing_required_verification:
        raise RuntimeError(
            "Release integrity gate failed before manifest: required verification artifacts are missing/empty: "
            + json.dumps(_oc_missing_required_verification))
    meta["required_disclosure_artifacts"] = [
        str((meta.get("text_class_disclosure_artifacts") or {}).get("text_class_disclosure_json") or ""),
        str((meta.get("text_class_disclosure_artifacts") or {}).get("text_class_disclosure_txt") or ""),
        str((meta.get("economic_benefit_artifacts") or {}).get("economic_benefit_json") or ""),
        str((meta.get("economic_benefit_artifacts") or {}).get("economic_benefit_txt") or ""),
        str((meta.get("top10_engineering_financial_artifacts") or {}).get("top10_json") or ""),
        str((meta.get("top10_engineering_financial_artifacts") or {}).get("top10_csv") or ""),
        str((meta.get("top10_engineering_financial_artifacts") or {}).get("top10_txt") or ""),
    ]
    _oc_missing_required_disclosures=[]
    for _p in meta["required_disclosure_artifacts"]:
        if not _p or not Path(_p).is_file() or Path(_p).stat().st_size <= 0:
            _oc_missing_required_disclosures.append(_p or "<EMPTY PATH>")
    if _oc_missing_required_disclosures:
        raise RuntimeError("Disclosure artifact gate failed before manifest: " + json.dumps(_oc_missing_required_disclosures))

    # Final integrity pass. Every writer, including the verification-artifact
    # emitters immediately above, has now run. The manifest hashes each artifact
    # and refuses to represent a partial package as a completed run.
    meta["artifact_manifest"] = _oc_write_artifact_manifest(outdir, batch_id, meta)
    _oc_manifest_relpaths={
        str(_r.get("relative_path","")).replace("\\","/")
        for _r in meta["artifact_manifest"].get("artifacts",[])
        if isinstance(_r,dict)
    }
    _oc_manifest_missing=[]
    for _oc_required_path in meta["required_verification_artifacts"]:
        _oc_rp=Path(_oc_required_path).resolve()
        try:
            _oc_rel=_oc_rp.relative_to(Path(outdir).resolve()).as_posix()
        except Exception:
            _oc_rel=_oc_rp.name
        if _oc_rel not in _oc_manifest_relpaths:
            _oc_manifest_missing.append(_oc_rel)
    if _oc_manifest_missing:
        raise RuntimeError(
            "Release integrity gate failed after manifest: required verification artifacts are not hash-bound in RUN_MANIFEST: "
            + json.dumps(_oc_manifest_missing))
    _oc_manifest_missing_disclosures=[]
    for _p in meta.get("required_disclosure_artifacts",[]):
        _rp=Path(_p).resolve()
        try: _rel=_rp.relative_to(Path(outdir).resolve()).as_posix()
        except Exception: _rel=_rp.name
        if _rel not in _oc_manifest_relpaths: _oc_manifest_missing_disclosures.append(_rel)
    if _oc_manifest_missing_disclosures:
        raise RuntimeError("Disclosure artifacts are not hash-bound in RUN_MANIFEST: " + json.dumps(_oc_manifest_missing_disclosures))
    meta["release_package"]=_oc_write_manifest_release_package(outdir,batch_id,meta["artifact_manifest"])

    # Keep the sandbox export behavior from core main
    try:
        export_dir = _Path("/mnt/data")
        export_dir.mkdir(parents=True, exist_ok=True)
        for p in outdir.glob(f"*{batch_id}*"):
            if p.is_file():
                shutil.copy2(p, export_dir / p.name)
        # also export config snapshot
        try:
            shutil.copy2(outdir / "config_snapshot.json", export_dir / f"config_snapshot_{batch_id}.json")
        except Exception as _oc_exc:
            logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
        for _manifest_name in (f"RUN_MANIFEST_{batch_id}.json", f"RUN_MANIFEST_{batch_id}.csv"):
            try:
                shutil.copy2(outdir / _manifest_name, export_dir / _manifest_name)
            except Exception as _oc_exc:
                logging.getLogger(__name__).warning("Nonfatal fallback captured at %s: %s", __name__, _oc_exc)
        try:
            if meta.get("compute_output_dir"):
                _src_compute = _Path(str(meta["compute_output_dir"]))
                _dst_compute = export_dir / f"COMPUTE_INFRASTRUCTURE_ARTIFACTS_{batch_id}"
                if _src_compute.exists():
                    if _dst_compute.exists():
                        shutil.rmtree(_dst_compute)
                    shutil.copytree(_src_compute, _dst_compute)
        except Exception as _compute_export_error:
            print(f"[WARN] Compute artifact export failed: {_compute_export_error}")
        try:
            if meta.get("manager_output_dir"):
                _src_manager = _Path(str(meta["manager_output_dir"]))
                _dst_manager = export_dir / f"FRAGMENTED_STACK_GOVERNANCE_ARTIFACTS_{batch_id}"
                if _src_manager.exists():
                    if _dst_manager.exists():
                        shutil.rmtree(_dst_manager)
                    shutil.copytree(_src_manager, _dst_manager)
        except Exception as _manager_export_error:
            print(f"[WARN] Manager artifact export failed: {_manager_export_error}")
        try:
            if meta.get("enterprise_output_dir"):
                _src_enterprise = _Path(str(meta["enterprise_output_dir"]))
                _dst_enterprise = export_dir / f"ENTERPRISE_PROOF_ARTIFACTS_{batch_id}"
                if _src_enterprise.exists():
                    if _dst_enterprise.exists():
                        shutil.rmtree(_dst_enterprise)
                    shutil.copytree(_src_enterprise, _dst_enterprise)
        except Exception as _enterprise_export_error:
            print(f"[WARN] Enterprise proof artifact export failed: {_enterprise_export_error}")
        try:
            if meta.get("global_stack_output_dir"):
                _src_stack = _Path(str(meta["global_stack_output_dir"]))
                _dst_stack = export_dir / f"GLOBAL_MEGASTACK_ARTIFACTS_{batch_id}"
                if _src_stack.exists():
                    if _dst_stack.exists():
                        shutil.rmtree(_dst_stack)
                    shutil.copytree(_src_stack, _dst_stack)
                _pkg = global_stack_payload.get("artifacts",{}).get("package_zip") if global_stack_payload else None
                if _pkg and _Path(str(_pkg)).exists():
                    shutil.copy2(_Path(str(_pkg)), export_dir / _Path(str(_pkg)).name)
        except Exception as _stack_export_error:
            print(f"[WARN] Global Megastack artifact export failed: {_stack_export_error}")
        print(f"[OK] Exported artifacts to {export_dir.resolve()}")
    except Exception as e:
        print(f"[WARN] Artifact export failed: {e}")

    print(f"[OK] EXECUTION_REPORT_TEXT_{batch_id}.txt")
    print(f"")
    print(f"")
    print(f"[OK] random_seed = {seed_used}")
    _dyn_meta = meta.get("dynamic_execution_snapshot", {}) or {}
    print(f"[OK] Dynamic current-run ledger: batch={_dyn_meta.get('batch_id')} seed={_dyn_meta.get('seed')} contract={_dyn_meta.get('contract_id')}")
    if compute_payload:
        print(f"[OK] Compute benchmark modes: {', '.join(compute_payload.get('modes', []))}")
        print(f"[OK] Compute seeds per mode: {compute_payload.get('seeds_per_mode')}")
        print(f"[OK] Compute artifact dir: {meta.get('compute_output_dir')}")
    if manager_payload:
        print(f"[OK] Manager benchmark scenarios: {manager_payload.get('scenario_count')}")
        print(f"[OK] Manager benchmark profile: {manager_payload.get('profile')}")
        print(f"[OK] Manager artifact dir: {meta.get('manager_output_dir')}")
    if enterprise_payload:
        print(f"[OK] Enterprise evidence profile: {enterprise_payload.get('profile')}")
        print(f"[OK] Enterprise evidence artifact dir: {meta.get('enterprise_output_dir')}")
        print(f"[OK] Decision replay pass: {enterprise_payload.get('causal',{}).get('decision_replay',{}).get('pass')}")
    if global_stack_payload:
        print(f"[OK] Global Megastack scenarios: {global_stack_payload.get('scenario_count')}")
        print(f"[OK] Global Megastack raw rows: {global_stack_payload.get('raw_row_count')}")
        print(f"[OK] Global Megastack artifact dir: {meta.get('global_stack_output_dir')}")
    # AUDIT FIX B2: the minimal proof object, integrity artifacts, core
    # isolation extract and replication pack are now emitted BEFORE the
    # manifest and the release package (see the AUDIT FIX B2 / P3 block above),
    # so they are inside both. Only the console summary remains here.
    print(f"[OK] Engine authenticity verdict: {_oc_authenticity_verdict()}")
    print(f"[OK] Verification artifacts sealed inside manifest and release package: "
          f"{sum(1 for _p in meta.get('required_verification_artifacts', []) if _p)} of 5")
    print(f"[OK] Output dir: {outdir.resolve()}")
    print(f"[OK] Output package: {meta.get('release_package')}")


if __name__ == "__main__":
    enterprise_main()
